import React from 'react';
import { Lead, Deal, Task, Meeting, Activity } from '../types';
import { IconUsers, IconKanban, IconZap, IconHistory, IconArrowUp } from './Icons';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from 'recharts';

interface StatCardProps {
  title: string;
  value: string | number;
  icon: React.ElementType;
  trend?: string;
  progress?: number;
  goalText?: string;
  color?: string;
}

const StatCard: React.FC<StatCardProps> = ({ title, value, icon: Icon, trend, progress, goalText, color = "purple" }) => {
  const colorClasses = {
      purple: "from-purple-500 to-indigo-500 text-purple-600 dark:text-purple-400 bg-purple-50 dark:bg-purple-900/20",
      blue: "from-blue-500 to-cyan-500 text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/20",
      emerald: "from-emerald-500 to-teal-500 text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20",
  };

  return (
    <div className="group p-6 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl hover:border-purple-500/30 hover:shadow-lg hover:shadow-purple-500/5 dark:hover:shadow-purple-900/10 transition-all duration-300 transform hover:-translate-y-1 relative overflow-hidden">
      {/* Background Gradient Blob */}
      <div className={`absolute -right-6 -top-6 w-24 h-24 bg-gradient-to-br ${color === 'purple' ? 'from-purple-500/10' : color === 'blue' ? 'from-blue-500/10' : 'from-emerald-500/10'} to-transparent rounded-full blur-2xl transition-all group-hover:scale-150`}></div>

      <div className="relative z-10">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-sm font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wide">{title}</h3>
            <div className={`p-2.5 rounded-xl ${colorClasses[color as keyof typeof colorClasses].split(' ').slice(2).join(' ')}`}>
              <Icon className="w-5 h-5" />
            </div>
          </div>
          <p className="text-3xl font-bold text-slate-900 dark:text-white mb-2">{value}</p>

          {progress !== undefined ? (
            <div className="mt-4">
              <div className="flex justify-between text-xs font-medium text-slate-500 dark:text-slate-400 mb-1.5">
                <span>{Math.round(progress)}% of Goal</span>
                <span className="text-slate-400 dark:text-slate-500">{goalText}</span>
              </div>
              <div className="w-full bg-slate-100 dark:bg-slate-800 rounded-full h-2 overflow-hidden">
                <div 
                  className={`h-full rounded-full bg-gradient-to-r ${colorClasses[color as keyof typeof colorClasses].split(' ').slice(0, 2).join(' ')} transition-all duration-1000 ease-out`} 
                  style={{ width: `${progress}%` }}
                ></div>
              </div>
            </div>
          ) : (
            trend && <div className="mt-2 flex items-center text-sm text-emerald-600 dark:text-emerald-400 font-medium bg-emerald-50 dark:bg-emerald-900/10 px-2 py-1 rounded-md w-fit"><IconArrowUp className="w-3 h-3 mr-1" />{trend}</div>
          )}
      </div>
    </div>
  );
};

const ActivityItem: React.FC<{ activity: Activity & { context: string }, isLast: boolean }> = ({ activity, isLast }) => {
    const formatDescription = (act: Activity & { context: string }) => {
        return <span dangerouslySetInnerHTML={{ __html: `${act.description} <span class="text-slate-400 mx-1">•</span> <span class="font-medium text-slate-700 dark:text-slate-300">${act.context}</span>` }} />
    }

    return (
        <div className="flex group">
            <div className="flex flex-col items-center mr-4">
                <div className="w-3 h-3 rounded-full bg-white dark:bg-slate-800 border-2 border-purple-500 group-hover:scale-125 transition-transform z-10"></div>
                {!isLast && <div className="w-0.5 flex-1 bg-slate-200 dark:bg-slate-800 my-1 group-hover:bg-purple-200 dark:group-hover:bg-purple-900/30 transition-colors"></div>}
            </div>
            <div className="pb-6">
                <p className="text-sm text-slate-600 dark:text-slate-400 mb-1">{formatDescription(activity)}</p>
                <p className="text-xs text-slate-400 dark:text-slate-500">{new Date(activity.timestamp).toLocaleString()}</p>
            </div>
        </div>
    );
};


interface DashboardProps {
  leads: Lead[];
  deals: Deal[];
  tasks: Task[];
  meetings: Meeting[];
  isDark?: boolean;
  pipelineGoal?: number;
}

const Dashboard: React.FC<DashboardProps> = ({ leads, deals, tasks, meetings, isDark = true, pipelineGoal = 5000000 }) => {

  const totalPipelineValue = deals.reduce((sum, deal) => sum + deal.value, 0);
  const activeLeadsCount = leads.length;
  const avgLeadScore = leads.length > 0 ? Math.round(leads.reduce((sum, lead) => sum + lead.score, 0) / leads.length) : 0;
  const goalProgress = pipelineGoal > 0 ? Math.min((totalPipelineValue / pipelineGoal) * 100, 100) : 0;

  const wonDeals = deals.filter(d => d.stage === 'Closed Won');
  const chartData = wonDeals.slice(0, 5).map(d => ({ name: d.title.split(' ')[0], value: d.value }));

  const allActivities = [
      ...leads.flatMap(lead => (lead.activities || []).map(act => ({ ...act, context: lead.name }))),
      ...deals.flatMap(deal => deal.activities.map(act => ({ ...act, context: deal.title })))
  ].sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()).slice(0, 10);

  return (
    <div className="space-y-8 animate-slide-up pb-10">
      <div className="flex items-center justify-between">
        <h1 className="text-3xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-slate-900 to-slate-600 dark:from-white dark:to-slate-300">Dashboard Overview</h1>
        <p className="text-sm text-slate-500 dark:text-slate-400 bg-white dark:bg-slate-900 px-3 py-1 rounded-full border border-slate-200 dark:border-slate-800 shadow-sm">
            Last updated: {new Date().toLocaleTimeString()}
        </p>
      </div>

      <div className="grid grid-cols-1 gap-6 md:grid-cols-3">
        <StatCard 
          title="Pipeline Value" 
          value={`$${(totalPipelineValue / 1000000).toFixed(1)}M`} 
          icon={IconKanban} 
          progress={goalProgress}
          goalText={`$${(pipelineGoal / 1000000).toFixed(1)}M`}
          color="purple"
        />
        <StatCard 
          title="Active Leads" 
          value={activeLeadsCount} 
          icon={IconUsers} 
          trend="+5 new today"
          color="blue"
        />
        <StatCard 
          title="Avg Lead AI Score" 
          value={avgLeadScore} 
          icon={IconZap} 
          trend="Top 10% Industry"
          color="emerald"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* Chart Section */}
        <div className="lg:col-span-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 shadow-sm dark:shadow-none hover:border-purple-500/20 transition-colors">
           <div className="flex items-center justify-between mb-6">
               <h3 className="text-lg font-bold text-slate-900 dark:text-white">Revenue Performance</h3>
               <select className="text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg px-2 py-1 focus:outline-none focus:ring-1 focus:ring-purple-500">
                   <option>This Month</option>
                   <option>Last Quarter</option>
               </select>
           </div>
           <div className="h-80 w-full">
             <ResponsiveContainer width="100%" height="100%">
               <BarChart data={chartData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                 <defs>
                    <linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#8b5cf6" stopOpacity={0.8}/>
                      <stop offset="95%" stopColor="#8b5cf6" stopOpacity={0}/>
                    </linearGradient>
                 </defs>
                 <XAxis 
                    dataKey="name" 
                    tick={{ fill: isDark ? '#94a3b8' : '#64748b', fontSize: 12 }} 
                    axisLine={false}
                    tickLine={false}
                    dy={10}
                 />
                 <YAxis 
                    tick={{ fill: isDark ? '#94a3b8' : '#64748b', fontSize: 12 }} 
                    tickFormatter={(value) => `$${Number(value)/1000}k`}
                    axisLine={false}
                    tickLine={false}
                    dx={-10}
                 />
                 <Tooltip 
                   cursor={{ fill: isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.02)' }}
                   contentStyle={{
                     background: isDark ? 'rgba(15, 23, 42, 0.9)' : 'rgba(255, 255, 255, 0.9)',
                     borderColor: isDark ? '#334155' : '#e2e8f0',
                     borderRadius: '12px',
                     boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)',
                     backdropFilter: 'blur(8px)',
                     padding: '12px'
                   }}
                   itemStyle={{ color: isDark ? '#fff' : '#0f172a', fontWeight: 600 }}
                 />
                 <Bar 
                    dataKey="value" 
                    fill="url(#colorValue)" 
                    radius={[6, 6, 0, 0]} 
                    barSize={40}
                 />
               </BarChart>
             </ResponsiveContainer>
           </div>
        </div>

        {/* Recent Activity Section */}
        <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 h-[460px] flex flex-col hover:border-purple-500/20 transition-colors">
            <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-6 flex items-center">
                <div className="p-1.5 bg-indigo-100 dark:bg-indigo-900/30 rounded-lg mr-2">
                    <IconHistory className="w-4 h-4 text-indigo-600 dark:text-indigo-400" />
                </div>
                Recent Activity
            </h3>
            <div className="overflow-y-auto flex-1 pr-2 -mr-2 custom-scrollbar pl-2">
                {allActivities.length > 0 ? allActivities.map((act, index) => (
                    <ActivityItem 
                        key={act.id} 
                        activity={act} 
                        isLast={index === allActivities.length - 1}
                    />
                )) : <p className="text-sm text-slate-500 italic text-center mt-10">No recent activity found.</p>}
            </div>
        </div>

      </div>
    </div>
  );
};

export default Dashboard;

