    { id: 'f8', label: 'Department', type: 'text', key: 'department', value: 'Single Line', required: false, isLocked: false },
    { id: 'f9', label: 'Phone', type: 'tel', key: 'phone', value: 'Phone', required: false, isLocked: false },
    { id: 'f10', label: 'Home Phone', type: 'tel', key: 'homePhone', value: 'Phone', required: false, isLocked: false },
    { id: 'f11', label: 'Other Phone', type: 'tel', key: 'otherPhone', value: 'Phone', required: false, isLocked: false },
    { id: 'f12', label: 'Fax', type: 'tel', key: 'fax', value: 'Phone', required: false, isLocked: false },
    { id: 'f13', label: 'Mobile', type: 'tel', key: 'mobile', value: 'Phone', required: false, isLocked: false },
    { id: 'f14', label: 'Date of Birth', type: 'date', key: 'dateOfBirth', value: 'Date', required: false, isLocked: false },
    { id: 'f15', label: 'Assistant', type: 'text', key: 'assistant', value: 'Single Line', required: false, isLocked: false },
    { id: 'f16', label: 'Asst Phone', type: 'tel', key: 'asstPhone', value: 'Phone', required: false, isLocked: false },
    { id: 'f17', label: 'Email Opt Out', type: 'checkbox', key: 'emailOptOut', value: 'Check', required: false, isLocked: false },
    { id: 'f18', label: 'Status', type: 'select', key: 'status', value: 'New', required: true, isLocked: false }
];

const CONTACT_STATUSES: ContactStatus[] = ['New', 'Active', 'Inactive'];

const LEAD_SOURCES = [
    'Advertisement',
    'Cold Call',
    'Employee Referral',
    'External Referral',
    'Online Store',
    'Partner',
    'Trade Show',
    'Web Download',
    'Web Search',
    'Chat'
];

const Contacts: React.FC<ContactsProps> = ({ contacts, onAddContact, onUpdateContact }) => {
  const [viewMode, setViewMode] = useState<'list' | 'kanban'>('list');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [layoutFields, setLayoutFields] = useState<LayoutField[]>(DEFAULT_LAYOUT);
  const [formData, setFormData] = useState<Partial<Contact>>({});
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isLayoutEditorOpen, setIsLayoutEditorOpen] = useState(false);

  // Drag and Drop State
  const [draggedContactId, setDraggedContactId] = useState<string | null>(null);
  const [dragOverColumn, setDragOverColumn] = useState<ContactStatus | null>(null);

  // If layout editor mode is active, show the editor instead of the list
  if (isLayoutEditorOpen) {
    return <ContactLayoutEditor 
      currentLayout={layoutFields}
      onSave={(newLayout) => {
        setLayoutFields(newLayout);
        setIsLayoutEditorOpen(false);
      }}
      onBack={() => setIsLayoutEditorOpen(false)} 
    />;
  }

  const handleOpenModal = () => {
    setFormData({ status: 'New', leadSource: 'Web Search' }); // Default Values
    setEditingId(null);
    setIsModalOpen(true);
  };

  const handleEditClick = (contact: Contact) => {
    setFormData({ ...contact });
    setEditingId(contact.id);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setEditingId(null);
  };

  const handleEditPageLayout = (e: React.MouseEvent) => {
      e.preventDefault();
      setIsModalOpen(false);
      setIsLayoutEditorOpen(true);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const checked = (e.target as HTMLInputElement).checked;

    setFormData(prev => ({ 
      ...prev, 
      [name]: type === 'checkbox' ? checked : value 
    }));
  };

  const saveContact = () => {
    // Dynamic Validation based on Layout
    const missingFields = layoutFields.filter(field => field.required && !formData[field.key as keyof Contact] && field.key !== 'owner');

    if (missingFields.length > 0) {
      alert(`Please fill in the required fields: ${missingFields.map(f => f.label).join(', ')}`);
      return false;
    }

    // Name Construction logic
    let fullName = formData.name;
    if (!fullName) {
        const firstName = formData.firstName || '';
        const lastName = formData.lastName || '';
        fullName = `${firstName} ${lastName}`.trim();
        if (!fullName && formData.company) fullName = formData.company; // Fallback
    }

    const contactData = {
      ...formData,
      name: fullName || 'Unknown',
      status: formData.status || 'New',
    } as Contact;

    if (editingId) {
      const originalContact = contacts.find(c => c.id === editingId);
      if (originalContact) {
        onUpdateContact({
          ...originalContact,
          ...contactData
        });
      }
    } else {
      onAddContact(contactData);
    }
    return true;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (saveContact()) {
      handleCloseModal();
    }
  };

  const handleSaveAndNew = (e: React.MouseEvent) => {
    e.preventDefault();
    if (saveContact()) {
      setFormData({ status: 'New' });
      setEditingId(null);
    }
  };

  // Drag and Drop Handlers (Kanban)
  const handleDragStart = (e: React.DragEvent, id: string) => {
    setDraggedContactId(id);
    e.dataTransfer.setData('contactId', id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragEnd = () => {
    setDraggedContactId(null);
    setDragOverColumn(null);
  };

  const handleDragOver = (e: React.DragEvent, status: ContactStatus) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    if (dragOverColumn !== status) {
        setDragOverColumn(status);
    }
  };

  const handleDrop = (e: React.DragEvent, status: ContactStatus) => {
    e.preventDefault();
    setDragOverColumn(null);
    const id = e.dataTransfer.getData('contactId');
    const contact = contacts.find(c => c.id === id);

    if (contact && contact.status !== status) {
      onUpdateContact({ ...contact, status });
    }
    setDraggedContactId(null);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Active': return 'bg-emerald-100 text-emerald-800 border-emerald-200 dark:bg-emerald-900/30 dark:text-emerald-300 dark:border-emerald-700/50';
      case 'Inactive': return 'bg-slate-100 text-slate-800 border-slate-200 dark:bg-slate-800/50 dark:text-slate-400 dark:border-slate-700';
      default: return 'bg-blue-100 text-blue-800 border-blue-200 dark:bg-blue-900/30 dark:text-blue-300 dark:border-blue-700/50';
    }
  };

  const renderField = (field: LayoutField) => {
      const isRequired = field.required;
      const commonClasses = `w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800/50 border ${isRequired && !formData[field.key as keyof Contact] ? 'border-red-300 dark:border-red-800' : 'border-slate-200 dark:border-slate-700'} rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500/50 text-slate-900 dark:text-white transition-all`;

      if (field.key === 'owner') {
          return (
            <div className="relative group">
                <input type="text" value="Bayas Ahamed" readOnly className={`${commonClasses} cursor-default`} />
                <IconUser className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 group-hover:text-purple-500 transition-colors" />
            </div>
          );
      }

      if (field.isComposite && field.key === 'firstName') {
          return (
            <div className="flex gap-2">
                <select className="w-24 px-2 py-2.5 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500/50 text-slate-900 dark:text-white text-sm">
                    <option>Mr.</option>
                    <option>Ms.</option>
                    <option>Dr.</option>
                </select>
                <input 
                    type="text" 
                    name={field.key} 
                    value={formData[field.key as keyof Contact] || ''} 
                    onChange={handleInputChange} 
                    className={commonClasses} 
                />
            </div>
          );
      }

      switch (field.type) {
          case 'select':
              let options = (
                 <>
                    <option value="">-None-</option>
                    <option value="Option 1">Option 1</option>
                    <option value="Option 2">Option 2</option>
                 </>
              );

              if (field.key === 'status') {
                  options = <>{CONTACT_STATUSES.map(s => <option key={s} value={s}>{s}</option>)}</>;
              } else if (field.key === 'leadSource') {
                  options = (
                    <>
                        <option value="">-None-</option>
                        {LEAD_SOURCES.map(s => <option key={s} value={s}>{s}</option>)}
                    </>
                  );
              }

              return (
                  <select name={field.key} value={formData[field.key as keyof Contact] || ''} onChange={handleInputChange} className={commonClasses}>
                      {options}
                  </select>
              );
          case 'checkbox':
              return (
                  <div className="flex items-center h-full">
                      <input type="checkbox" name={field.key} checked={!!formData[field.key as keyof Contact]} onChange={handleInputChange} className="w-5 h-5 text-purple-600 bg-slate-100 border-slate-300 rounded focus:ring-purple-500 dark:focus:ring-purple-600 dark:ring-offset-slate-800 focus:ring-2 dark:bg-slate-700 dark:border-slate-600 cursor-pointer" />
                  </div>
              );
          default:
              return (
                  <div className="relative group">
                    <input 
                        type={field.type} 
                        name={field.key} 
                        value={formData[field.key as keyof Contact] || ''} 
                        onChange={handleInputChange} 
                        className={commonClasses} 
                    />
                    {field.key === 'company' && <IconBuilding className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 group-hover:text-purple-500 transition-colors" />}
                  </div>
              );
      }
  };

  return (
    <>
      <div className="space-y-8 h-full flex flex-col animate-fade-in">
        {/* Header and Kanban/List Toggle */}
        <div className="flex justify-between items-center flex-shrink-0">
          <div className="flex items-center gap-4">
             <h1 className="text-3xl font-bold text-slate-900 dark:text-white">Contacts</h1>
             <div className="flex bg-slate-100 dark:bg-slate-800/50 p-1 rounded-xl border border-slate-200 dark:border-slate-700/50">
                <button onClick={() => setViewMode('list')} className={`p-2 rounded-lg transition-all duration-200 ${viewMode === 'list' ? 'bg-white dark:bg-slate-700 shadow-sm text-purple-600 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200'}`}><IconList className="w-4 h-4" /></button>
                <button onClick={() => setViewMode('kanban')} className={`p-2 rounded-lg transition-all duration-200 ${viewMode === 'kanban' ? 'bg-white dark:bg-slate-700 shadow-sm text-purple-600 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200'}`}><IconKanban className="w-4 h-4" /></button>
             </div>
          </div>
          <button onClick={handleOpenModal} className="px-5 py-2.5 text-sm font-medium text-white bg-purple-600 rounded-xl hover:bg-purple-500 shadow-lg shadow-purple-500/25 hover:shadow-purple-500/40 hover:-translate-y-0.5 transition-all duration-200">+ New Contact</button>
        </div>

        {/* Views Render (List or Kanban) */}
        {viewMode === 'list' ? (
          <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-sm dark:shadow-none overflow-hidden flex flex-col h-full">
            <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between bg-slate-50/50 dark:bg-slate-900/50">
              <div className="flex items-center space-x-2 bg-white dark:bg-slate-800 px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-700">
                  <IconFilter className="w-4 h-4 text-slate-400" />
                  <select className="bg-transparent text-sm font-medium text-slate-700 dark:text-slate-300 focus:outline-none cursor-pointer"><option>All Contacts</option></select>
              </div>
            </div>
            <div className="overflow-auto flex-1 custom-scrollbar">
                <table className="w-full text-left text-sm">
                <thead className="sticky top-0 z-20 bg-slate-50/90 dark:bg-slate-900/90 backdrop-blur-sm border-b border-slate-200 dark:border-slate-800">
                    <tr>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Name</th>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Title</th>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Account Name</th>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Email</th>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Phone</th>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Status</th>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Last Activity</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 dark:divide-slate-800/50">
                    {contacts.map((contact) => (
                    <tr key={contact.id} onClick={() => handleEditClick(contact)} className="hover:bg-slate-50/80 dark:hover:bg-slate-800/40 transition-colors cursor-pointer group">
                        <td className="px-6 py-4 text-base font-medium text-slate-900 dark:text-white flex items-center">
                            <div className="w-9 h-9 rounded-full bg-gradient-to-br from-purple-100 to-blue-100 dark:from-slate-700 dark:to-slate-600 flex items-center justify-center mr-3 text-sm font-bold text-slate-700 dark:text-slate-200 shadow-sm border border-white dark:border-slate-600">
                                {contact.name.charAt(0)}
                            </div>
                            <span className="group-hover:text-purple-600 dark:group-hover:text-purple-400 transition-colors">{contact.name}</span>
                        </td>
                        <td className="px-6 py-4 text-slate-600 dark:text-slate-400">{contact.title}</td>
                        <td className="px-6 py-4 text-slate-600 dark:text-slate-400">{contact.company}</td>
                        <td className="px-6 py-4 text-slate-600 dark:text-slate-400"><div className="flex items-center gap-2 group-hover:text-slate-900 dark:group-hover:text-slate-200 transition-colors"><IconMail className="w-3.5 h-3.5 opacity-50" />{contact.email}</div></td>
                        <td className="px-6 py-4 text-slate-600 dark:text-slate-400"><div className="flex items-center gap-2 group-hover:text-slate-900 dark:group-hover:text-slate-200 transition-colors"><IconPhone className="w-3.5 h-3.5 opacity-50" />{contact.phone}</div></td>
                        <td className="px-6 py-4"><span className={`px-2.5 py-1 text-xs font-semibold rounded-full border ${getStatusColor(contact.status || 'New')}`}>{contact.status || 'New'}</span></td>
                        <td className="px-6 py-4 text-slate-500 dark:text-slate-500">{contact.lastActivity}</td>
                    </tr>
                    ))}
                </tbody>
                </table>
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-x-auto overflow-y-hidden pb-4">
            <div className="flex h-full gap-6 min-w-full">
              {CONTACT_STATUSES.map(status => (
                <div 
                    key={status} 
                    onDragOver={(e) => handleDragOver(e, status)} 
                    onDrop={(e) => handleDrop(e, status)} 
                    className={`flex-1 min-w-[340px] flex flex-col border rounded-2xl h-full transition-all duration-300 ${
                        dragOverColumn === status 
                            ? 'bg-purple-50/50 dark:bg-purple-900/10 border-purple-300 dark:border-purple-500 shadow-inner' 
                            : 'bg-slate-100/50 dark:bg-slate-900/30 border-slate-200 dark:border-slate-800'
                    }`}
                >
                  <div className="p-4 border-b border-slate-200 dark:border-slate-800/50 flex justify-between items-center bg-white/40 dark:bg-slate-800/40 rounded-t-2xl backdrop-blur-md sticky top-0 z-10">
                    <h3 className="font-bold text-slate-700 dark:text-slate-200 flex items-center gap-2">
                        <span className={`w-3 h-3 rounded-full shadow-sm ${status === 'Active' ? 'bg-emerald-500' : status === 'Inactive' ? 'bg-slate-400' : 'bg-blue-500'}`}></span>
                        {status}
                    </h3>
                    <span className="bg-white dark:bg-slate-700 text-slate-600 dark:text-slate-300 text-xs font-bold px-2.5 py-1 rounded-full shadow-sm">{contacts.filter(c => (c.status || 'New') === status).length}</span>
                  </div>
                  <div className="p-4 space-y-3 overflow-y-auto flex-1 custom-scrollbar">
                     {contacts.filter(c => (c.status || 'New') === status).map(contact => (
                       <div 
                         key={contact.id} 
                         draggable 
                         onDragStart={(e) => handleDragStart(e, contact.id)} 
                         onDragEnd={handleDragEnd}
                         onClick={() => handleEditClick(contact)} 
                         className={`p-4 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl shadow-sm hover:shadow-lg hover:border-purple-300 dark:hover:border-purple-500/30 transition-all duration-200 cursor-move group select-none ${draggedContactId === contact.id ? 'opacity-40 scale-95' : 'hover:-translate-y-1'}`}
                       >
                         <div className="flex items-start justify-between mb-3">
                           <div className="flex items-center">
                                <div className="w-9 h-9 rounded-full bg-slate-50 dark:bg-slate-700 flex items-center justify-center text-xs font-bold text-slate-600 dark:text-slate-300 mr-3 border border-slate-100 dark:border-slate-600 shadow-sm">{contact.name.charAt(0)}</div>
                                <div>
                                    <h4 className="font-semibold text-slate-800 dark:text-slate-100 text-sm leading-tight group-hover:text-purple-600 dark:group-hover:text-purple-400 transition-colors">{contact.name}</h4>
                                    <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">{contact.title}</p>
                                </div>
                           </div>
                         </div>
                         <div className="pl-12 space-y-2">
                             <p className="text-sm text-slate-600 dark:text-slate-300 flex items-center">
                                 <IconBuilding className="w-3.5 h-3.5 mr-2 text-slate-400" />
                                 <span className="truncate">{contact.company}</span>
                             </p>
                             {(contact.email || contact.phone) && (
                                 <div className="flex items-center gap-3 pt-1">
                                    {contact.email && <div className="p-1.5 rounded-md bg-slate-50 dark:bg-slate-700/50 text-slate-500 dark:text-slate-400 hover:text-purple-600 dark:hover:text-purple-400 transition-colors"><IconMail className="w-3.5 h-3.5" /></div>}
                                    {contact.phone && <div className="p-1.5 rounded-md bg-slate-50 dark:bg-slate-700/50 text-slate-500 dark:text-slate-400 hover:text-purple-600 dark:hover:text-purple-400 transition-colors"><IconPhone className="w-3.5 h-3.5" /></div>}
                                 </div>
                             )}
                         </div>
                         <div className="flex justify-between items-center pt-3 mt-3 border-t border-slate-50 dark:border-slate-700/50 pl-12">
                             <span className="text-[10px] font-medium text-slate-400 uppercase tracking-wide">Last Activity</span>
                             <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">{contact.lastActivity}</span>
                         </div>
                       </div>
                     ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm transition-opacity duration-300">
          <div className="w-full max-w-5xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-scale-in">
            {/* Header */}
            <div className="p-5 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50/80 dark:bg-slate-950/80 backdrop-blur-md">
               <div className="flex items-center gap-3">
                  <h2 className="text-xl font-bold text-slate-900 dark:text-white">
                    {editingId ? 'Edit Contact' : 'Create Contact'}
                  </h2>
                  <button onClick={handleEditPageLayout} className="text-sm font-medium text-purple-600 hover:text-purple-700 dark:text-purple-400 hover:underline transition-colors">Edit Page Layout</button>
               </div>
               <div className="flex items-center gap-3">
                 <button onClick={handleCloseModal} className="px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">Cancel</button>
                 <button onClick={handleSaveAndNew} className="px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">Save and New</button>
                 <button onClick={handleSubmit} className="px-5 py-2 text-sm font-medium text-white bg-purple-600 rounded-lg hover:bg-purple-500 shadow-lg shadow-purple-500/20 transition-all">Save</button>
               </div>
            </div>

            {/* Dynamic Form Content */}
            <div className="overflow-y-auto p-8 bg-white dark:bg-slate-900 custom-scrollbar">
              <form onSubmit={handleSubmit}>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-8">
                    {layoutFields.map((field) => (
                        <div key={field.id} className="grid grid-cols-1 md:grid-cols-3 gap-4 items-center group">
                            <label className={`text-sm font-medium text-slate-600 dark:text-slate-400 md:text-right transition-colors group-focus-within:text-purple-600 dark:group-focus-within:text-purple-400 ${field.required ? 'after:content-["*"] after:text-red-500 after:ml-1' : ''}`}>
                                {field.label}
                            </label>
                            <div className="md:col-span-2">
                                {renderField(field)}
                            </div>
                        </div>
                    ))}
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default Contacts;

import React, { useState, useRef, useEffect } from 'react';
import { Message, Lead, Deal } from '../types';
import { chatWithCRM } from '../services/geminiService';
import { IconSparkles, IconSend, IconX, IconMessageSquare } from './Icons';

interface AIChatProps {
  leads: Lead[];
  deals: Deal[];
}

const AIChat: React.FC<AIChatProps> = ({ leads, deals }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { id: '1', role: 'model', text: 'Hello! I am Nova. Ask me about your pipeline, high-value leads, or revenue forecast.', timestamp: new Date() }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    try {
      const responseText = await chatWithCRM(input, { leads, deals });
      const aiMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: responseText,
        timestamp: new Date()
      };
      setMessages(prev => [...prev, aiMsg]);
    } catch (error) {
      console.error(error);
