      )}
    </>
  );
};

export default AIChat;

import React, { useState } from 'react';
import { LayoutField } from '../types';
import { 
    IconArrowLeft, 
    IconSettings, 
    IconGripVertical, 
    IconChevronDown, 
    IconChevronRight, 
    IconUser, 
    IconToggleLeft, 
    IconPlus, 
    IconTrash, 
    IconCheckSquare
} from './Icons';

interface ContactLayoutEditorProps {
    currentLayout: LayoutField[];
    onSave: (layout: LayoutField[]) => void;
    onBack: () => void;
}

const SidebarItem = ({ label, type }: { label: string, type: string }) => {
    const handleDragStart = (e: React.DragEvent) => {
        // Create a template for the new field. 
        const fieldKey = `custom_${type.toLowerCase().replace(/[^a-z0-9]/g, '_')}_${Date.now()}`;
        const newFieldData: LayoutField = {
            id: `new_template_${Date.now()}`, 
            label: label,
            type: type,
            key: fieldKey,
            required: false,
            isLocked: false,
            value: `[${label}]`
        };
        e.dataTransfer.setData('application/new-field', JSON.stringify(newFieldData));
        e.dataTransfer.effectAllowed = 'copy';
    };

    return (
        <div 
            draggable 
            onDragStart={handleDragStart}
            className="flex items-center px-4 py-3.5 bg-slate-800 border border-slate-700/50 rounded-xl mb-3 cursor-grab hover:bg-slate-750 hover:border-purple-500/50 hover:shadow-lg hover:shadow-purple-900/20 transition-all duration-200 active:cursor-grabbing group select-none"
        >
            <div className="p-1.5 bg-slate-700 rounded-lg mr-3 group-hover:bg-purple-500/20 transition-colors">
                <IconGripVertical className="w-5 h-5 text-slate-500 group-hover:text-purple-400" />
            </div>
            <span className="text-base font-medium text-slate-200 group-hover:text-white">{label}</span>
        </div>
    );
};

const ContactLayoutEditor: React.FC<ContactLayoutEditorProps> = ({ currentLayout, onSave, onBack }) => {
    const [fields, setFields] = useState<LayoutField[]>(currentLayout);
    const [activeFieldId, setActiveFieldId] = useState<string | null>(null);
    const [dragOverIndex, setDragOverIndex] = useState<number | null>(null);
    const [isDraggingOverContainer, setIsDraggingOverContainer] = useState(false);

    // Close context menu when clicking outside
    React.useEffect(() => {
        const handleClickOutside = () => setActiveFieldId(null);
        window.addEventListener('click', handleClickOutside);
        return () => window.removeEventListener('click', handleClickOutside);
    }, []);

    const handleFieldClick = (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        setActiveFieldId(activeFieldId === id ? null : id);
    };

    const handleRemoveField = (id: string) => {
        setFields(prev => prev.filter(f => f.id !== id));
        setActiveFieldId(null);
    };

    const handleToggleRequired = (id: string) => {
        setFields(prev => prev.map(f => f.id === id ? { ...f, required: !f.required } : f));
        setActiveFieldId(null);
    };

    const handleSaveLayout = () => {
        onSave(fields);
    };

    // Helper to check for type existence in DataTransferItemList or array
    const hasType = (types: any, type: string) => {
        if (!types) return false;
        if (types.includes) return types.includes(type);
        if (types.contains) return types.contains(type); // For DOMStringList
        for (let i = 0; i < types.length; i++) {
            if (types[i] === type) return true;
        }
        return false;
    };

    // Drag and Drop Handlers
    const handleDragStart = (e: React.DragEvent, index: number) => {
        e.dataTransfer.setData('application/field-index', index.toString());
        e.dataTransfer.effectAllowed = 'move';
        setActiveFieldId(null);
    };

    const handleDragOver = (e: React.DragEvent, index: number) => {
        e.preventDefault(); 
        e.stopPropagation();

        if (hasType(e.dataTransfer.types, 'application/new-field')) {
            e.dataTransfer.dropEffect = 'copy';
        } else {
            e.dataTransfer.dropEffect = 'move';
        }

        setDragOverIndex(index);
        setIsDraggingOverContainer(true);
    };

    const handleContainerDragOver = (e: React.DragEvent) => {
        e.preventDefault();

        if (hasType(e.dataTransfer.types, 'application/new-field')) {
            e.dataTransfer.dropEffect = 'copy';
        } else {
            e.dataTransfer.dropEffect = 'move';
        }

        setIsDraggingOverContainer(true);
    };

    const handleContainerDragLeave = (e: React.DragEvent) => {
        // Only clear if leaving the main container, not entering a child
        if (e.currentTarget.contains(e.relatedTarget as Node)) return;
        setIsDraggingOverContainer(false);
        setDragOverIndex(null);
    };

    // Helper to create a unique field from template
    const createFieldFromTemplate = (template: LayoutField): LayoutField => {
        const timestamp = Date.now();
        const randomStr = Math.random().toString(36).substring(2, 9);
        return {
            ...template,
            id: `field_${timestamp}_${randomStr}`,
            key: `custom_${template.type}_${timestamp}_${randomStr}`,
        };
    };

    const handleDrop = (e: React.DragEvent, dropIndex: number) => {
        e.preventDefault();
        e.stopPropagation();
        setDragOverIndex(null);
        setIsDraggingOverContainer(false);

        const newFieldJson = e.dataTransfer.getData('application/new-field');
        const draggedIndexStr = e.dataTransfer.getData('application/field-index');

        if (newFieldJson) {
            // Adding a new field from sidebar
            try {
                const template = JSON.parse(newFieldJson) as LayoutField;
                const newField = createFieldFromTemplate(template);

                setFields(prev => {
                    const newFields = [...prev];
                    newFields.splice(dropIndex, 0, newField);
                    return newFields;
                });
            } catch (err) {
                console.error("Error parsing new field data:", err);
            }
        } else if (draggedIndexStr) {
            // Reordering existing field
            const draggedIndex = parseInt(draggedIndexStr, 10);
            if (!isNaN(draggedIndex) && draggedIndex !== dropIndex) {
                setFields(prev => {
                    const newFields = [...prev];
                    const [movedField] = newFields.splice(draggedIndex, 1);
                    // Adjust drop index if dragging from above
                    const adjustedDropIndex = draggedIndex < dropIndex ? dropIndex - 1 : dropIndex;
                    newFields.splice(adjustedDropIndex, 0, movedField);
                    return newFields;
                });
            }
        }
    };

    const handleDropContainer = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setIsDraggingOverContainer(false);
        setDragOverIndex(null);

        // If dropping directly on container (not on a specific item), we append to the end.
        // Or if it bubbled up (though we stop propagation in handleDrop item, so this catches drops on empty space)

        const newFieldJson = e.dataTransfer.getData('application/new-field');
        const draggedIndexStr = e.dataTransfer.getData('application/field-index');

        if (newFieldJson) {
             try {
                const template = JSON.parse(newFieldJson) as LayoutField;
                const newField = createFieldFromTemplate(template);
                setFields(prev => [...prev, newField]);
             } catch (err) {
                 console.error("Error parsing new field data:", err);
             }
        } else if (draggedIndexStr) {
             // If dragging an existing field to the container background (effectively moving to end)
             const draggedIndex = parseInt(draggedIndexStr, 10);
             if (!isNaN(draggedIndex)) {
                 setFields(prev => {
                    const newFields = [...prev];
                    const [movedField] = newFields.splice(draggedIndex, 1);
                    newFields.push(movedField);
                    return newFields;
                });
             }
        }
    };

    return (
        <div className="flex h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-white overflow-hidden font-sans">
            {/* Sidebar */}
            <div className="w-80 bg-slate-900 border-r border-slate-800 flex flex-col flex-shrink-0 z-20 shadow-2xl">
                <div className="p-6 border-b border-slate-800">
                    <button onClick={onBack} className="flex items-center text-sm font-semibold text-slate-400 hover:text-white transition-colors mb-6 bg-slate-800/50 hover:bg-slate-700 px-4 py-2 rounded-lg w-fit transition-all group">
                        <IconArrowLeft className="w-4 h-4 mr-2 group-hover:-translate-x-1 transition-transform" />
                        Back to Contact List
                    </button>
                    <div className="flex items-center justify-between text-white font-bold text-lg">
                        <span>New Fields</span>
                        <div className="bg-slate-800 p-1.5 rounded-md">
                            <IconChevronDown className="w-5 h-5 text-slate-400" />
                        </div>
                    </div>
                    <p className="text-slate-500 text-sm mt-2">Drag fields to the canvas</p>
                </div>

                <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">
                    <div className="grid grid-cols-1 gap-1">
                        <SidebarItem label="Single Line Text" type="text" />
                        <SidebarItem label="Phone Number" type="tel" />
                        <SidebarItem label="Email Address" type="email" />
                        <SidebarItem label="Date Picker" type="date" />
                        <SidebarItem label="Number Input" type="number" />
                        <SidebarItem label="Dropdown (Pick List)" type="select" />
                        <SidebarItem label="Checkbox Toggle" type="checkbox" />
                        <SidebarItem label="Website URL" type="url" />
                    </div>

                    <div className="mt-8">
                        <div className="flex items-center justify-center p-4 border-2 border-dashed border-slate-700 rounded-xl text-slate-400 hover:text-white hover:border-purple-500/50 hover:bg-slate-800/50 cursor-pointer transition-all group">
                            <IconPlus className="w-5 h-5 mr-2 group-hover:text-purple-500" />
                            <span className="text-base font-semibold uppercase tracking-wide">New Section</span>
                        </div>
                    </div>
                </div>
            </div>

            {/* Main Content */}
            <div className="flex-1 flex flex-col min-w-0 bg-slate-100 dark:bg-slate-950">
                {/* Header */}
                <div className="h-20 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 px-8 flex justify-between items-center flex-shrink-0 shadow-sm z-10">
                    <div className="flex items-center">
                        <h1 className="text-2xl font-bold text-slate-800 dark:text-white mr-3">Contact Page Layout</h1>
                        <span className="text-slate-300 dark:text-slate-600 mx-2 text-2xl font-light">/</span>
                        <span className="text-slate-500 dark:text-slate-400 font-medium text-lg bg-slate-100 dark:bg-slate-800 px-3 py-1 rounded-lg">Standard Layout</span>
                    </div>
                    <div className="flex items-center space-x-4">
                         <button onClick={onBack} className="px-5 py-2.5 text-base font-medium text-slate-700 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-xl hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">
                           Cancel
                         </button>
                         <button onClick={handleSaveLayout} className="px-6 py-2.5 text-base font-semibold text-white bg-purple-600 rounded-xl hover:bg-purple-500 transition-all shadow-lg shadow-purple-500/20 hover:shadow-purple-500/40 hover:-translate-y-0.5">
                           Save Layout
                         </button>
                    </div>
                </div>

                {/* Form Editor Canvas */}
                <div className="flex-1 overflow-y-auto p-10 custom-scrollbar bg-slate-50 dark:bg-[#0b1120]">
                    <div className="max-w-6xl mx-auto bg-white dark:bg-slate-900 rounded-2xl shadow-xl border border-slate-200 dark:border-slate-800 min-h-[900px]">
                        <div className="p-10">
                             {/* Top Section / Branding Placeholder */}
                             <div className="flex items-center mb-10 p-6 bg-gradient-to-r from-slate-50 to-white dark:from-slate-800/50 dark:to-slate-900 border border-slate-100 dark:border-slate-800 rounded-xl">
                                <div className="w-16 h-16 bg-white dark:bg-slate-800 rounded-full flex items-center justify-center border-2 border-slate-100 dark:border-slate-700 shadow-sm mr-6 relative">
                                    <IconUser className="w-8 h-8 text-slate-400" />
                                    <div className="absolute -bottom-1 -right-1 w-6 h-6 bg-purple-500 rounded-full flex items-center justify-center border-2 border-white dark:border-slate-800">
                                        <IconSettings className="w-3 h-3 text-white" />
                                    </div>
                                </div>
                                <div>
                                    <h2 className="text-xl font-bold text-slate-800 dark:text-white">Profile Preview</h2>
                                    <div className="flex items-center mt-1 text-slate-500 dark:text-slate-400">
                                        <span className="text-sm font-medium">Visible to all users</span>
                                        <IconToggleLeft className="w-6 h-6 text-emerald-500 ml-3 cursor-pointer" />
                                    </div>
                                </div>
                             </div>

                             <div 
                                className={`border-2 rounded-2xl p-2 min-h-[600px] transition-all duration-300 
                                    ${isDraggingOverContainer 
                                        ? 'border-purple-500 bg-purple-50 dark:bg-purple-900/10 dark:border-purple-500 ring-4 ring-purple-500/10' 
                                        : 'border-dashed border-slate-300 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-900/30'
                                    }`}
                                onDragOver={handleContainerDragOver}
                                onDragLeave={handleContainerDragLeave}
                                onDrop={handleDropContainer}
                             >
                                 {/* Section Header */}
                                 <div className="flex justify-between items-center px-6 py-4 bg-slate-100 dark:bg-slate-800 rounded-xl mb-6 cursor-move border border-slate-200 dark:border-slate-700 shadow-sm group hover:border-purple-300 dark:hover:border-purple-500/30 transition-colors">
                                     <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100 flex items-center">
                                         <IconChevronDown className="w-5 h-5 mr-2 text-slate-400" />
                                         Contact Information
                                     </h3>
                                     <div className="flex items-center space-x-2 opacity-50 group-hover:opacity-100 transition-opacity">
                                         <button className="p-2 hover:bg-white dark:hover:bg-slate-700 rounded-lg text-slate-500 hover:text-purple-600 transition-colors">
                                            <IconSettings className="w-5 h-5" />
                                         </button>
                                     </div>
                                 </div>

                                 <div className="grid grid-cols-2 gap-x-8 gap-y-6 px-4 pb-4">
                                     {fields.map((field, index) => (
                                         <div 
                                            key={field.id}
                                            draggable={!field.isLocked}
                                            onDragStart={(e) => handleDragStart(e, index)}
                                            onDragOver={(e) => handleDragOver(e, index)}
                                            onDrop={(e) => handleDrop(e, index)}
                                            className={`relative transition-all duration-300 ease-out ${dragOverIndex === index ? 'pt-16' : ''}`}
                                         >
                                             {dragOverIndex === index && (
                                                <div className="absolute top-0 left-0 right-0 h-12 bg-purple-100 dark:bg-purple-900/30 border-2 border-purple-400 dark:border-purple-500 border-dashed rounded-xl flex items-center justify-center mb-4 animate-pulse">
                                                    <span className="text-sm text-purple-700 dark:text-purple-300 font-bold uppercase tracking-wider">Drop Field Here</span>
                                                </div>
                                             )}

                                             <div 
                                                className={`relative p-5 border rounded-xl group cursor-pointer transition-all duration-200 shadow-sm
                                                    ${activeFieldId === field.id 
                                                        ? 'bg-purple-50 border-purple-400 dark:bg-purple-900/20 dark:border-purple-500 ring-4 ring-purple-500/10 z-10 scale-[1.02]' 
                                                        : 'bg-white border-slate-200 dark:bg-slate-800 dark:border-slate-700 hover:border-purple-300 dark:hover:border-purple-500/50 hover:shadow-md'
                                                    }
                                                `}
                                                onClick={(e) => handleFieldClick(e, field.id)}
                                             >
                                                <div className="flex justify-between items-start mb-3 pointer-events-none">
                                                    <div className="flex items-center">
                                                        {field.required && (
                                                            <div className="flex items-center justify-center w-5 h-5 bg-red-100 dark:bg-red-900/30 rounded text-red-600 dark:text-red-400 text-xs font-bold mr-2" title="Required">*</div>
                                                        )}
                                                        <span className="text-base font-semibold text-slate-700 dark:text-slate-200">{field.label}</span>
                                                    </div>
                                                    <button className="text-slate-300 group-hover:text-slate-500 dark:text-slate-600 dark:group-hover:text-slate-400 transition-colors">
                                                        <IconSettings className="w-5 h-5" />
                                                    </button>
                                                </div>

                                                <div className="flex items-center justify-between pointer-events-none">
                                                    {field.isComposite ? (
                                                        <div className="flex gap-3 w-full items-center bg-slate-50 dark:bg-slate-900/50 p-2 rounded-lg border border-slate-100 dark:border-slate-700/50">
                                                            <div className="w-1/3 border-r border-slate-200 dark:border-slate-700 pr-3 text-right">
                                                                <span className="text-xs font-medium text-slate-400 uppercase tracking-wide">Salutation</span>
                                                            </div>
                                                            <div className="flex-1 pl-1">
                                                                <span className="text-base text-blue-600 dark:text-blue-400 font-medium">{field.value}</span>
                                                            </div>
                                                        </div>
                                                    ) : (
                                                        <div className="w-full bg-slate-50 dark:bg-slate-900/50 p-2.5 rounded-lg border border-slate-100 dark:border-slate-700/50 flex items-center justify-between">
                                                            <span className={`text-base font-medium ${field.value ? 'text-blue-600 dark:text-blue-400' : 'text-slate-400 italic'}`}>
                                                                {field.value || `Enter ${field.label}...`}
                                                            </span>
                                                            {field.isLocked && <span className="text-xs text-slate-400 bg-slate-200 dark:bg-slate-700 px-1.5 py-0.5 rounded">Locked</span>}
                                                        </div>
                                                    )}
                                                </div>

                                                {/* Context Menu */}
                                                {activeFieldId === field.id && (
                                                    <div className="absolute top-full right-0 mt-2 w-56 bg-white dark:bg-slate-800 rounded-xl shadow-2xl border border-slate-200 dark:border-slate-700 z-50 overflow-hidden animate-fade-in-down cursor-default ring-1 ring-black/5">
                                                        <div className="p-1.5">
                                                            <button 
                                                                onClick={(e) => { e.stopPropagation(); handleToggleRequired(field.id); }}
                                                                className="w-full text-left px-4 py-2.5 text-sm font-medium text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700 flex items-center rounded-lg transition-colors"
                                                            >
