import React, { useState, useMemo, useEffect } from 'react';
import { Lead, EmailTemplate, NurtureEmail, LeadStatus } from '../types';
import { MOCK_TEMPLATES } from '../constants';
import LeadForm from './LeadForm'; 
import LeadDetail from './LeadDetail';
import { 
  IconSearch, 
  IconChevronDown, 
  IconChevronRight, 
  IconSparkles, 
  IconMail,
  IconSend,
  IconX,
  IconTrash,
  IconBot,
  IconClock,
  IconArrowUp,
  IconArrowDown,
  IconFunnel
} from './Icons';
import { generateSmartFilterCriteria, batchAnalyzeLeads, generateAIBulkEmail, generateNurtureSequence } from '../services/geminiService';

interface LeadsProps {
  leads: Lead[];
  onAddLead: (leadData: Omit<Lead, 'id'>) => void;
  onUpdateLead: (lead: Lead) => void;
  onDeleteLeads: (leadIds: string[]) => void;
}

type ViewMode = 'list' | 'create' | 'edit' | 'detail';
type SortKey = keyof Lead;
type SortDirection = 'asc' | 'desc';

const FilterCheckbox: React.FC<{ label: string; count?: number; filterKey?: string; checked: boolean; onChange: (checked: boolean) => void; }> = ({ label, count, filterKey, checked, onChange }) => {
  const checkboxId = `filter-${filterKey || label}`;
  return (
    <div className="flex items-center group cursor-pointer">
      <input type="checkbox" id={checkboxId} className="w-4 h-4 rounded border-slate-300 text-purple-600 focus:ring-purple-500 bg-white dark:bg-slate-800 dark:border-slate-700 cursor-pointer" onChange={(e) => onChange(e.target.checked)} checked={checked} />
      <label htmlFor={checkboxId} className="ml-2 text-base text-slate-600 dark:text-slate-300 group-hover:text-purple-600 dark:group-hover:text-purple-400 transition-colors cursor-pointer">{label}</label>
      {count !== undefined && <span className="ml-auto text-sm text-slate-400">({count})</span>}
    </div>
  );
};


const Leads: React.FC<LeadsProps> = ({ leads, onAddLead, onUpdateLead, onDeleteLeads }) => {
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [selectedLead, setSelectedLead] = useState<Lead | null>(null);
  const [expandedSections, setExpandedSections] = useState<Record<string, boolean>>({'source': true, 'status': true});

  // Filtering, Sorting, and Pagination State
  const [searchQuery, setSearchQuery] = useState('');
  const [smartFilterQuery, setSmartFilterQuery] = useState('');
  const [isProcessingAI, setIsProcessingAI] = useState(false);
  const [selectedFilters, setSelectedFilters] = useState<Record<string, boolean>>({});
  const [aiFilters, setAiFilters] = useState<any[]>([]);
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: SortDirection } | null>({ key: 'score', direction: 'desc' });
  const [currentPage, setCurrentPage] = useState(1);
  const [recordsPerPage, setRecordsPerPage] = useState(10);

  const [selectedLeadIds, setSelectedLeadIds] = useState<Set<string>>(new Set());
  const [batchAnalysisResult, setBatchAnalysisResult] = useState<string | null>(null);
  const [isEmailModalOpen, setIsEmailModalOpen] = useState(false);
  const [emailSubject, setEmailSubject] = useState('');
  const [emailBody, setEmailBody] = useState('');
  const [emailTone, setEmailTone] = useState<'formal' | 'casual' | 'persuasive'>('persuasive');
  const [isDraftingAI, setIsDraftingAI] = useState(false);
  const [previewLeadName, setPreviewLeadName] = useState<string | null>(null);
  const [isSchedulingEmail, setIsSchedulingEmail] = useState(false);
  const [scheduleDateTime, setScheduleDateTime] = useState('');
  const [isNurtureModalOpen, setIsNurtureModalOpen] = useState(false);
  const [nurtureSequence, setNurtureSequence] = useState<NurtureEmail[] | null>(null);
  const [isNurturing, setIsNurturing] = useState(false);
  const [activeNurtureAccordion, setActiveNurtureAccordion] = useState<number | null>(0);

  // Move useMemo hooks to the top level, before any conditional returns
  const uniqueLeadSources = useMemo(() => Array.from(new Set(leads.map(l => l.leadSource).filter(Boolean))).sort(), [leads]);
  const uniqueStatuses = useMemo(() => Object.values(LeadStatus), []);
  const uniqueIndustries = useMemo(() => Array.from(new Set(leads.map(l => l.industry).filter(Boolean))).sort(), [leads]);
  const uniqueRatings = useMemo(() => Array.from(new Set(leads.map(l => l.rating).filter(Boolean))).sort(), [leads]);

  const applyAIFilters = (lead: Lead, filters: any[]) => {
      if (!filters || filters.length === 0) return true;
      return filters.every(filter => {
          const leadValue = lead[filter.field as keyof Lead] as any;
          if (leadValue === undefined) return false;
          const filterValue = isNaN(Number(filter.value)) ? filter.value : Number(filter.value);
          const leadValueNormalized = typeof leadValue === 'string' ? leadValue.toLowerCase() : leadValue;
          const filterValueNormalized = typeof filterValue === 'string' ? filterValue.toLowerCase() : filterValue;

          switch (filter.operator) {
              case '$gt': return leadValueNormalized > filterValueNormalized;
              case '$lt': return leadValueNormalized < filterValueNormalized;
              case '$eq': return leadValueNormalized == filterValueNormalized;
              case '$contains': return typeof leadValueNormalized === 'string' && leadValueNormalized.includes(filterValueNormalized as string);
              default: return true;
          }
      });
  };

  const filteredLeads = useMemo(() => {
    const query = searchQuery.toLowerCase();
    const activeSourceFilters = uniqueLeadSources.filter(source => selectedFilters[`Source: ${source}`]);
    const activeStatusFilters = uniqueStatuses.filter(status => selectedFilters[`Status: ${status}`]);
    const activeIndustryFilters = uniqueIndustries.filter(industry => selectedFilters[`Industry: ${industry}`]);
    const activeRatingFilters = uniqueRatings.filter(rating => selectedFilters[`Rating: ${rating}`]);

    return leads.filter(lead => {
      const matchesSearch = !query || ['name', 'company', 'email', 'leadSource', 'city'].some(field => lead[field as keyof Lead]?.toString().toLowerCase().includes(query));

      const matchesSource = activeSourceFilters.length === 0 || (lead.leadSource && activeSourceFilters.includes(lead.leadSource));
      const matchesStatus = activeStatusFilters.length === 0 || (lead.status && activeStatusFilters.includes(lead.status));
      const matchesIndustry = activeIndustryFilters.length === 0 || (lead.industry && activeIndustryFilters.includes(lead.industry));
      const matchesRating = activeRatingFilters.length === 0 || (lead.rating && activeRatingFilters.includes(lead.rating));

      const matchesAI = applyAIFilters(lead, aiFilters);

      return matchesSearch && matchesSource && matchesStatus && matchesIndustry && matchesRating && matchesAI;
    });
  }, [leads, searchQuery, selectedFilters, uniqueLeadSources, uniqueStatuses, uniqueIndustries, uniqueRatings, aiFilters]);


  const sortedLeads = useMemo(() => {
    let sortableItems = [...filteredLeads];
    if (sortConfig !== null) {
      sortableItems.sort((a, b) => {
        const aValue = a[sortConfig.key];
        const bValue = b[sortConfig.key];
        if (aValue === undefined || aValue < bValue) return sortConfig.direction === 'asc' ? -1 : 1;
        if (bValue === undefined || aValue > bValue) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
      });
    }
    return sortableItems;
  }, [filteredLeads, sortConfig]);

  const handleViewLeadDetail = (lead: Lead) => { setSelectedLead(lead); setViewMode('detail'); };
  const handleCreateNewLead = () => { setSelectedLead(null); setViewMode('create'); };
  const handleEditLead = (lead: Lead) => { setSelectedLead(lead); setViewMode('edit'); };
  const handleCancelForm = () => { setSelectedLead(null); setViewMode('list'); };
  const handleBackToList = () => { setSelectedLead(null); setViewMode('list'); };

  useEffect(() => {
    setSelectedLeadIds(new Set()); // Reset selection when filters or page change
  }, [searchQuery, selectedFilters, aiFilters, currentPage, recordsPerPage]);


  const handleSaveLead = (leadData: Lead) => {
    if (viewMode === 'edit' && selectedLead) {
      onUpdateLead({ ...selectedLead, ...leadData });
    } else {
      onAddLead(leadData);
    }
    setViewMode('list');
    setSelectedLead(null);
  };

  const handleDeleteSelected = () => {
    if (selectedLeadIds.size === 0) return;
    if (window.confirm(`Are you sure you want to delete ${selectedLeadIds.size} selected lead(s)?`)) {
      onDeleteLeads(Array.from(selectedLeadIds));
      setSelectedLeadIds(new Set());
    }
  };

  const handleDeleteFromDetail = (leadId: string) => {
     if (window.confirm(`Are you sure you want to delete this lead?`)) {
      onDeleteLeads([leadId]);
      setViewMode('list');
      setSelectedLead(null);
    }
  };

  const handleNurtureLead = async (lead: Lead) => {
    setIsNurturing(true);
    setNurtureSequence(null);
    setActiveNurtureAccordion(0);
    setIsNurtureModalOpen(true);
    const sequence = await generateNurtureSequence(lead);
    setNurtureSequence(sequence);
    setIsNurturing(false);
  };

  const closeNurtureModal = () => {
    setIsNurtureModalOpen(false);
    setNurtureSequence(null);
  };

  const toggleSection = (section: string) => setExpandedSections(prev => ({ ...prev, [section]: !prev[section] }));
  const toggleSelection = (id: string) => {
    const newSelected = new Set(selectedLeadIds);
    newSelected.has(id) ? newSelected.delete(id) : newSelected.add(id);
    setSelectedLeadIds(newSelected);
  };

  const handleSmartFilter = async () => {
    if (!smartFilterQuery.trim()) { setAiFilters([]); return; }
    setIsProcessingAI(true);
    setSearchQuery('');
    const criteria = await generateSmartFilterCriteria(smartFilterQuery);
    setAiFilters(criteria.filters || []);
    setIsProcessingAI(false);
    setCurrentPage(1);
  };

  const handleBatchAnalyze = async () => {
    if (selectedLeadIds.size === 0) return;
    setIsProcessingAI(true);
    const selectedLeads = leads.filter(l => selectedLeadIds.has(l.id));
    const result = await batchAnalyzeLeads(selectedLeads);
    setBatchAnalysisResult(result);
    setIsProcessingAI(false);
  };

  const handleOpenEmailModal = () => { if (selectedLeadIds.size > 0) setIsEmailModalOpen(true); };
  const closeEmailModal = () => { setIsEmailModalOpen(false); setEmailSubject(''); setEmailBody(''); setPreviewLeadName(null); setIsSchedulingEmail(false); setScheduleDateTime(''); };

  const handleTemplateChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const templateId = e.target.value;
    if (!templateId) { setEmailSubject(''); setEmailBody(''); setPreviewLeadName(null); return; }
    const template = MOCK_TEMPLATES.find(t => t.id === templateId);
    if (!template) return;
    const previewLead = leads.find(l => l.id === Array.from(selectedLeadIds)[0]);
    if (previewLead) {
      setPreviewLeadName(previewLead.name);
      setEmailSubject(template.subject.replace(/{{name}}/g, previewLead.name).replace(/{{company}}/g, previewLead.company));
      setEmailBody(template.body.replace(/{{name}}/g, previewLead.name).replace(/{{company}}/g, previewLead.company));
    } else {
      setPreviewLeadName(null);
      setEmailSubject(template.subject.replace(/{{.+?}}/g, '[Variable]'));
      setEmailBody(template.body.replace(/{{name}}/g, '[Lead Name]').replace(/{{company}}/g, '[Company Name]'));
    }
  };

  const handleAIDraft = async () => {
    if (selectedLeadIds.size === 0) return;
    setIsDraftingAI(true);
    const selectedLeads = leads.filter(l => selectedLeadIds.has(l.id));
    const result = await generateAIBulkEmail(selectedLeads, emailTone, emailBody);
    setEmailBody(result);
    setIsDraftingAI(false);
  };

  const handleSendEmail = () => {
    const message = isSchedulingEmail ? `Email scheduled for ${new Date(scheduleDateTime).toLocaleString()}` : `Email successfully sent`;
    alert(`${message} to ${selectedLeadIds.size} selected leads!`);
    closeEmailModal();
  };

  const paginatedLeads = sortedLeads.slice((currentPage - 1) * recordsPerPage, currentPage * recordsPerPage);
  const totalPages = Math.ceil(sortedLeads.length / recordsPerPage);

  const toggleSelectAll = () => {
    if (selectedLeadIds.size === paginatedLeads.length) setSelectedLeadIds(new Set());
    else setSelectedLeadIds(new Set(paginatedLeads.map(l => l.id)));
  };

  const requestSort = (key: SortKey) => {
    let direction: SortDirection = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') direction = 'desc';
    setSortConfig({ key, direction });
  };

  const getSortIcon = (key: SortKey) => {
    if (!sortConfig || sortConfig.key !== key) return <span className="w-3 h-3 opacity-0 group-hover:opacity-50 transition-opacity">↕️</span>;
    if (sortConfig.direction === 'asc') return <IconArrowUp className="w-3 h-3 text-purple-500" />;
    return <IconArrowDown className="w-3 h-3 text-purple-500" />;
  };

  // Conditional rendering at the end to avoid Hook error #300
  if (viewMode === 'create' || viewMode === 'edit') return <LeadForm onCancel={handleCancelForm} onSave={handleSaveLead} initialData={selectedLead} />;
  if (viewMode === 'detail' && selectedLead) return <LeadDetail lead={selectedLead} onBack={handleBackToList} onEdit={() => handleEditLead(selectedLead)} onDelete={() => handleDeleteFromDetail(selectedLead.id)} onNurture={() => handleNurtureLead(selectedLead)} isNurturing={isNurturing} leads={leads} />;

  return (
    <>
      <div className="flex flex-col md:flex-row h-full gap-4 md:gap-6">
        <div className="w-full md:w-64 flex-shrink-0 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden flex flex-col h-full">
          <div className="p-4 border-b border-slate-100 dark:border-slate-800 flex items-center gap-2">
            <IconFunnel className="w-4 h-4 text-slate-500" />
            <h2 className="text-base font-bold text-slate-900 dark:text-white uppercase tracking-wider">Filters</h2>
          </div>
          <div className="flex-1 overflow-y-auto p-4 custom-scrollbar space-y-4">
            {/* Lead Source Section */}
            <div>
              <button onClick={() => toggleSection('source')} className="flex items-center justify-between w-full text-left mb-2 group">
                <span className="text-base font-bold text-slate-800 dark:text-slate-200 group-hover:text-purple-600 transition-colors">Lead Source</span>
                {expandedSections['source'] ? <IconChevronDown className="w-4 h-4 text-slate-400" /> : <IconChevronRight className="w-4 h-4 text-slate-400" />}
              </button>
              {expandedSections['source'] && <div className="space-y-1 animate-fade-in pl-2 border-l border-slate-200 dark:border-slate-800">{uniqueLeadSources.map(source => <FilterCheckbox key={source} label={source || 'Unknown'} filterKey={`Source: ${source}`} checked={!!selectedFilters[`Source: ${source}`]} onChange={(checked) => setSelectedFilters(prev => ({ ...prev, [`Source: ${source}`]: checked }))} count={leads.filter(l => l.leadSource === source).length} />)}</div>}
            </div>

            {/* Status Section */}
            <div>
              <button onClick={() => toggleSection('status')} className="flex items-center justify-between w-full text-left mb-2 group">
                <span className="text-base font-bold text-slate-800 dark:text-slate-200 group-hover:text-purple-600 transition-colors">Status</span>
                {expandedSections['status'] ? <IconChevronDown className="w-4 h-4 text-slate-400" /> : <IconChevronRight className="w-4 h-4 text-slate-400" />}
              </button>
              {expandedSections['status'] && <div className="space-y-1 animate-fade-in pl-2 border-l border-slate-200 dark:border-slate-800">{uniqueStatuses.map(status => <FilterCheckbox key={status} label={status} filterKey={`Status: ${status}`} checked={!!selectedFilters[`Status: ${status}`]} onChange={(checked) => setSelectedFilters(prev => ({ ...prev, [`Status: ${status}`]: checked }))} count={leads.filter(l => l.status === status).length} />)}</div>}
            </div>

            {/* Industry Section */}
            <div>
              <button onClick={() => toggleSection('industry')} className="flex items-center justify-between w-full text-left mb-2 group">
                <span className="text-base font-bold text-slate-800 dark:text-slate-200 group-hover:text-purple-600 transition-colors">Industry</span>
                {expandedSections['industry'] ? <IconChevronDown className="w-4 h-4 text-slate-400" /> : <IconChevronRight className="w-4 h-4 text-slate-400" />}
              </button>
              {expandedSections['industry'] && <div className="space-y-1 animate-fade-in pl-2 border-l border-slate-200 dark:border-slate-800">{uniqueIndustries.map(industry => <FilterCheckbox key={industry} label={industry} filterKey={`Industry: ${industry}`} checked={!!selectedFilters[`Industry: ${industry}`]} onChange={(checked) => setSelectedFilters(prev => ({ ...prev, [`Industry: ${industry}`]: checked }))} count={leads.filter(l => l.industry === industry).length} />)}</div>}
            </div>

            {/* Rating Section */}
            <div>
              <button onClick={() => toggleSection('rating')} className="flex items-center justify-between w-full text-left mb-2 group">
                <span className="text-base font-bold text-slate-800 dark:text-slate-200 group-hover:text-purple-600 transition-colors">Rating</span>
                {expandedSections['rating'] ? <IconChevronDown className="w-4 h-4 text-slate-400" /> : <IconChevronRight className="w-4 h-4 text-slate-400" />}
              </button>
              {expandedSections['rating'] && <div className="space-y-1 animate-fade-in pl-2 border-l border-slate-200 dark:border-slate-800">{uniqueRatings.map(rating => <FilterCheckbox key={rating} label={rating} filterKey={`Rating: ${rating}`} checked={!!selectedFilters[`Rating: ${rating}`]} onChange={(checked) => setSelectedFilters(prev => ({ ...prev, [`Rating: ${rating}`]: checked }))} count={leads.filter(l => l.rating === rating).length} />)}</div>}
            </div>
          </div>
        </div>


        <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden h-full">
          <div className="p-4 md:p-6 pb-2">
            <div className="flex flex-col md:flex-row md:justify-between md:items-center gap-4 mb-4">
              <div className="flex items-center gap-4">
                <h1 className="text-2xl font-bold text-slate-800 dark:text-slate-100">Leads ({sortedLeads.length})</h1>
                <button onClick={handleCreateNewLead} className="px-4 py-2 text-sm font-medium text-white bg-purple-600 rounded-lg hover:bg-purple-50 shadow-lg shadow-purple-500/20 transition-all">+ New Lead</button>
              </div>
              <div className="flex items-center space-x-3"><div className="relative"><IconSearch className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" /><input type="text" placeholder="Search leads..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="w-full md:w-64 pl-9 pr-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-1 focus:ring-purple-500" /></div></div>
            </div>

            <div className="flex items-center gap-2 p-1.5 rounded-lg border border-purple-200 dark:border-purple-500/30 bg-purple-50 dark:bg-purple-900/10 mb-2">
               <div className="relative flex-1"><IconSparkles className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-purple-600 dark:text-purple-400" /><input type="text" value={smartFilterQuery} onChange={(e) => setSmartFilterQuery(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSmartFilter()} placeholder="Ask AI to filter (e.g., 'hot tech leads in New York')..." className="w-full pl-9 pr-3 py-2 text-sm bg-white dark:bg-slate-800 border border-purple-100 dark:border-slate-700 rounded-md focus:outline-none focus:ring-2 focus:ring-purple-500/50 text-slate-900 dark:text-white placeholder-slate-400" /></div>
               <button onClick={handleSmartFilter} disabled={isProcessingAI} className="px-4 py-2 bg-purple-600 text-white text-sm font-medium rounded-md hover:bg-purple-500 transition-colors disabled:opacity-50 shadow-sm">{isProcessingAI ? 'Thinking...' : 'Filter'}</button>
                {aiFilters.length > 0 && (
                  <button onClick={() => { setAiFilters([]); setSmartFilterQuery(''); }} className="px-3 py-2 bg-slate-200 text-slate-700 text-xs font-medium rounded-md hover:bg-slate-300 transition-colors dark:bg-slate-700 dark:text-slate-200 dark:hover:bg-slate-600">
                    Clear
                  </button>
                )}
               {selectedLeadIds.size > 0 && (<><button onClick={handleBatchAnalyze} className="px-4 py-2 bg-indigo-600 text-white text-sm font-medium rounded-md hover:bg-indigo-500 transition-colors flex items-center shadow-sm"><IconSparkles className="w-4 h-4 mr-1.5" />Analyze</button><button onClick={handleOpenEmailModal} className="px-4 py-2 bg-emerald-600 text-white text-sm font-medium rounded-md hover:bg-emerald-500 transition-colors flex items-center shadow-sm"><IconMail className="w-4 h-4 mr-1.5" />Email</button><button onClick={handleDeleteSelected} className="px-4 py-2 bg-red-600 text-white text-sm font-medium rounded-md hover:bg-red-500 transition-colors flex items-center shadow-sm"><IconTrash className="w-4 h-4 mr-1.5" />Delete</button></>)}
            </div>

            {batchAnalysisResult && (<div className="mb-4 p-4 bg-indigo-50 dark:bg-slate-800 border border-indigo-200 dark:border-slate-700 rounded-lg animate-slide-up relative"><button onClick={() => setBatchAnalysisResult(null)} className="absolute top-2 right-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200"><IconX className="w-4 h-4" /></button><h3 className="text-sm font-bold text-indigo-700 dark:text-indigo-400 mb-2 flex items-center"><IconSparkles className="w-4 h-4 mr-2" /> AI Bulk Analysis</h3><div className="prose prose-sm dark:prose-invert max-w-none text-slate-700 dark:text-slate-300">{batchAnalysisResult.split('\n').map((line, i) => <p key={i} className="my-1">{line}</p>)}</div></div>)}
          </div>

          <div className="flex-1 overflow-auto bg-white dark:bg-slate-900 custom-scrollbar">
            <table className="w-full text-left text-sm border-collapse">
              <thead className="bg-slate-50 dark:bg-slate-950/50 sticky top-0 z-10 border-b border-slate-200 dark:border-slate-800">
                <tr>
                  <th className="px-4 py-3 w-10 text-center"><input type="checkbox" checked={selectedLeadIds.size === paginatedLeads.length && paginatedLeads.length > 0} onChange={toggleSelectAll} className="w-4 h-4 rounded border-slate-300 text-purple-600 focus:ring-purple-500 bg-white dark:bg-slate-800 cursor-pointer" /></th>
                  <th className="px-4 py-3"><button onClick={() => requestSort('name')} className="text-sm font-semibold text-slate-600 dark:text-slate-400 whitespace-nowrap group flex items-center gap-2 hover:text-purple-600 transition-colors">Lead Name {getSortIcon('name')}</button></th>
                  <th className="px-4 py-3"><button onClick={() => requestSort('company')} className="text-sm font-semibold text-slate-600 dark:text-slate-400 whitespace-nowrap group flex items-center gap-2 hover:text-purple-600 transition-colors">Company {getSortIcon('company')}</button></th>
                  <th className="px-4 py-3"><button onClick={() => requestSort('score')} className="text-sm font-semibold text-slate-600 dark:text-slate-400 whitespace-nowrap group flex items-center gap-2 hover:text-purple-600 transition-colors">AI Score {getSortIcon('score')}</button></th>
                  <th className="px-4 py-3"><button onClick={() => requestSort('leadSource')} className="text-sm font-semibold text-slate-600 dark:text-slate-400 whitespace-nowrap group flex items-center gap-2 hover:text-purple-600 transition-colors">Lead Source {getSortIcon('leadSource')}</button></th>
                  <th className="px-4 py-3"><button onClick={() => requestSort('lastContact')} className="text-sm font-semibold text-slate-600 dark:text-slate-400 whitespace-nowrap group flex items-center gap-2 hover:text-purple-600 transition-colors">Last Contact {getSortIcon('lastContact')}</button></th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                {paginatedLeads.map((lead) => (
                  <tr key={lead.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors group">
                    <td className="px-4 py-4 text-center"><input type="checkbox" checked={selectedLeadIds.has(lead.id)} onChange={() => toggleSelection(lead.id)} className="w-4 h-4 rounded border-slate-300 text-purple-600 focus:ring-purple-500 bg-white dark:bg-slate-800 cursor-pointer" /></td>
                    <td className="px-4 py-4"><span onClick={() => handleViewLeadDetail(lead)} className="text-base font-medium text-slate-900 dark:text-slate-100 hover:text-purple-600 cursor-pointer">{lead.name}</span></td>
                    <td className="px-4 py-4 text-sm text-slate-600 dark:text-slate-400">{lead.company}</td>
                    <td className="px-4 py-4 text-sm text-slate-600 dark:text-slate-400"><div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full" style={{ backgroundColor: `hsl(${lead.score}, 70%, 50%)`}}></div>{lead.score}</div></td>
                    <td className="px-4 py-4 text-sm text-slate-600 dark:text-slate-400">{lead.leadSource}</td>
                    <td className="px-4 py-4 text-sm text-slate-600 dark:text-slate-400">{lead.lastContact}</td>
                  </tr>
                ))}
                {paginatedLeads.length === 0 && (<tr><td colSpan={6} className="px-6 py-12 text-center text-slate-500 dark:text-slate-400">No leads found matching your criteria.</td></tr>)}
              </tbody>
            </table>
          </div>
          {totalPages > 1 && (<div className="p-4 border-t border-slate-200 dark:border-slate-800 flex justify-between items-center text-sm"><div className="text-slate-600 dark:text-slate-400">Showing {paginatedLeads.length} of {sortedLeads.length} results</div><div className="flex items-center gap-2"><button disabled={currentPage === 1} onClick={() => setCurrentPage(c => c - 1)} className="px-2 py-1 border rounded disabled:opacity-50">Prev</button><span>Page {currentPage} of {totalPages}</span><button disabled={currentPage === totalPages} onClick={() => setCurrentPage(c => c + 1)} className="px-2 py-1 border rounded disabled:opacity-50">Next</button></div></div>)}
        </div>
      </div>
      {isEmailModalOpen && <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm"><div className="w-full max-w-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-scale-in"><div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50"><h2 className="text-2xl font-bold text-slate-900 dark:text-white flex items-center"><IconMail className="w-5 h-5 mr-3 text-purple-500" />Compose Email</h2><button onClick={closeEmailModal} className="text-slate-400 hover:text-slate-600 dark:hover:text-white"><IconX className="w-6 h-6" /></button></div><div className="p-6 overflow-y-auto space-y-4"><div><label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">To</label><div className="p-2 bg-slate-100 dark:bg-slate-800 rounded-lg text-sm text-slate-600 dark:text-slate-400">{selectedLeadIds.size} selected leads</div></div><div><label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Template</label><select onChange={handleTemplateChange} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500 text-slate-900 dark:text-white"><option value="">-- No Template --</option>{MOCK_TEMPLATES.map(template => (<option key={template.id} value={template.id}>{template.name}</option>))}</select>{previewLeadName && (<p className="text-sm text-slate-500 dark:text-slate-400 mt-1">Showing a preview using data from <span className="font-semibold">{previewLeadName}</span>.</p>)}</div><div><label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Subject</label><input type="text" value={emailSubject} onChange={(e) => setEmailSubject(e.target.value)} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500 text-slate-900 dark:text-white" /></div><div><label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-2">AI Actions</label><div className="flex items-center gap-2"><div className="flex items-center p-1 bg-slate-100 dark:bg-slate-800 rounded-lg">{(['formal', 'casual', 'persuasive'] as const).map(t => (<button key={t} type="button" onClick={() => setEmailTone(t)} className={`px-3 py-1 text-sm font-medium rounded-md transition-colors ${emailTone === t ? 'bg-white dark:bg-slate-700 text-purple-600 dark:text-white shadow-sm' : 'text-slate-500 hover:bg-slate-200/50 dark:hover:bg-slate-700/50'}`}>{t.charAt(0).toUpperCase() + t.slice(1)}</button>))}</div><button type="button" onClick={handleAIDraft} disabled={isDraftingAI} className="flex items-center px-4 py-1.5 text-sm font-medium text-white bg-purple-600 rounded-lg hover:bg-purple-500 shadow-sm transition-colors disabled:opacity-50"><IconSparkles className="w-4 h-4 mr-2" />{isDraftingAI ? 'Drafting...' : 'Draft with AI'}</button></div></div><div><label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Body</label><textarea value={emailBody} onChange={(e) => setEmailBody(e.target.value)} rows={10} placeholder={isDraftingAI ? "Nova is thinking..." : "Your email body will appear here..."} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500 text-slate-900 dark:text-white font-mono text-base" /></div><div className="pt-2"><div className="flex items-center"><input type="checkbox" id="schedule-email" checked={isSchedulingEmail} onChange={(e) => setIsSchedulingEmail(e.target.checked)} className="w-4 h-4 text-purple-600 bg-slate-100 border-slate-300 rounded focus:ring-purple-500 dark:focus:ring-purple-600 dark:ring-offset-slate-800 focus:ring-2 dark:bg-slate-700 dark:border-slate-600" /><label htmlFor="schedule-email" className="ml-2 text-sm font-medium text-slate-700 dark:text-slate-300">Schedule for later</label></div>{isSchedulingEmail && (<div className="mt-2 animate-fade-in"><input type="datetime-local" value={scheduleDateTime} onChange={(e) => setScheduleDateTime(e.target.value)} className="w-full md:w-1/2 px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500 text-slate-900 dark:text-white" /></div>)}</div></div><div className="p-6 border-t border-slate-200 dark:border-slate-800 flex justify-end gap-3 bg-slate-50 dark:bg-slate-800/50"><button type="button" onClick={closeEmailModal} className="px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">Cancel</button><button onClick={handleSendEmail} className="px-4 py-2 text-sm font-medium text-white bg-purple-600 rounded-lg hover:bg-purple-500 shadow-lg shadow-purple-500/20 transition-colors flex items-center">{isSchedulingEmail ? <IconClock className="w-4 h-4 mr-2" /> : <IconSend className="w-4 h-4 mr-2" />}{isSchedulingEmail ? 'Schedule Email' : 'Send Email'}</button></div></div></div>}
      {isNurtureModalOpen && <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm"><div className="w-full max-w-3xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-scale-in"><div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50"><h2 className="text-xl font-bold text-slate-900 dark:text-white flex items-center"><IconBot className="w-5 h-5 mr-3 text-purple-500" />AI Nurture Sequence</h2><button onClick={closeNurtureModal} className="text-slate-400 hover:text-slate-600 dark:hover:text-white"><IconX className="w-6 h-6" /></button></div><div className="p-6 overflow-y-auto">{isNurturing ? (<div className="flex flex-col items-center justify-center h-64 text-center"><IconSparkles className="w-12 h-12 text-purple-500 animate-pulse" /><p className="mt-4 text-slate-600 dark:text-slate-300">Generating personalized sequence for {selectedLead?.name}...</p></div>) : nurtureSequence ? (<div className="space-y-4">{nurtureSequence.map((email, index) => (<div key={index} className="border border-slate-200 dark:border-slate-800 rounded-lg overflow-hidden"><button onClick={() => setActiveNurtureAccordion(activeNurtureAccordion === index ? null : index)} className="w-full flex justify-between items-center p-4 bg-slate-50 dark:bg-slate-800/50 hover:bg-slate-100 dark:hover:bg-slate-800"><div className="font-medium text-slate-900 dark:text-white"><span className="text-purple-600 dark:text-purple-400">Step {index + 1}:</span> {email.delay} - {email.subject}</div><IconChevronDown className={`w-5 h-5 text-slate-500 transition-transform ${activeNurtureAccordion === index ? 'rotate-180' : ''}`} /></button>{activeNurtureAccordion === index && (<div className="p-4 border-t border-slate-200 dark:border-slate-800 animate-fade-in"><p className="text-sm text-slate-600 dark:text-slate-400 whitespace-pre-wrap font-mono">{email.body}</p></div>)}</div>))}</div>) : null}</div><div className="p-6 border-t border-slate-200 dark:border-slate-800 flex justify-end gap-3 bg-slate-50 dark:bg-slate-800/50"><button type="button" onClick={closeNurtureModal} className="px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">Close</button><button className="px-4 py-2 text-sm font-medium text-white bg-purple-600 rounded-lg hover:bg-purple-500 shadow-lg shadow-purple-500/20 transition-colors flex items-center"><IconSend className="w-4 h-4 mr-2" />Start Sequence</button></div></div></div>}
    </>
  );
};

export default Leads;

import React, { useState, useMemo } from 'react';
import { Contact, ContactStatus, LayoutField } from '../types';
import { IconFilter, IconPhone, IconMail, IconX, IconUser, IconBuilding, IconList, IconKanban, IconInfo } from './Icons';
import ContactLayoutEditor from './ContactLayoutEditor';

interface ContactsProps {
  contacts: Contact[];
  onAddContact: (contactData: Omit<Contact, 'id' | 'lastActivity'>) => void;
  onUpdateContact: (contact: Contact) => void;
}

const DEFAULT_LAYOUT: LayoutField[] = [
    { id: 'f1', label: 'Contact Owner', type: 'User', key: 'owner', value: 'User', required: false, isLocked: true },
    { id: 'f2', label: 'Lead Source', type: 'select', key: 'leadSource', value: 'Web Search', required: false, isLocked: false },
    { id: 'f3', label: 'First Name', type: 'text', key: 'firstName', value: 'Mr. ', required: false, isLocked: false, isComposite: true },
    { id: 'f4', label: 'Last Name', type: 'text', key: 'lastName', value: 'Single Line', required: true, isLocked: false },
    { id: 'f5', label: 'Account Name', type: 'text', key: 'company', value: 'Lookup', required: true, isLocked: false },
    { id: 'f6', label: 'Title', type: 'text', key: 'title', value: 'Single Line', required: false, isLocked: false },
    { id: 'f7', label: 'Email', type: 'email', key: 'email', value: 'Email', required: false, isLocked: false },
    { id: 'f8', label: 'Department', type: 'text', key: 'department', value: 'Single Line', required: false, isLocked: false },
    { id: 'f9', label: 'Phone', type: 'tel', key: 'phone', value: 'Phone', required: false, isLocked: false },
    { id: 'f11', label: 'Other Phone', type: 'tel', key: 'otherPhone', value: 'Phone', required: false, isLocked: false },
    { id: 'f13', label: 'Mobile', type: 'tel', key: 'mobile', value: 'Phone', required: false, isLocked: false },
    { id: 'f15', label: 'Assistant', type: 'text', key: 'assistant', value: 'Single Line', required: false, isLocked: false },
    { id: 'f17', label: 'Email Opt Out', type: 'checkbox', key: 'emailOptOut', value: 'Check', required: false, isLocked: false },
    { id: 'f18', label: 'Status', type: 'select', key: 'status', value: 'New', required: true, isLocked: false }
];

const CONTACT_STATUSES: ContactStatus[] = ['New', 'Active', 'Inactive'];

const LEAD_SOURCES = [
    'Advertisement',
    'Cold Call',
    'Employee Referral',
    'External Referral',
    'Online Store',
    'Partner',
    'Trade Show',
    'Web Download',
    'Web Search',
    'Chat'
];

const Contacts: React.FC<ContactsProps> = ({ contacts, onAddContact, onUpdateContact }) => {
  const [viewMode, setViewMode] = useState<'list' | 'kanban'>('list');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [layoutFields, setLayoutFields] = useState<LayoutField[]>(DEFAULT_LAYOUT);
  const [formData, setFormData] = useState<Partial<Contact>>({});
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isLayoutEditorOpen, setIsLayoutEditorOpen] = useState(false);

  // Drag and Drop State
  const [draggedContactId, setDraggedContactId] = useState<string | null>(null);
  const [dragOverColumn, setDragOverColumn] = useState<ContactStatus | null>(null);

  // If layout editor mode is active, show the editor instead of the list
  if (isLayoutEditorOpen) {
    return <ContactLayoutEditor 
      currentLayout={layoutFields}
      onSave={(newLayout) => {
        setLayoutFields(newLayout);
        setIsLayoutEditorOpen(false);
      }}
      onBack={() => setIsLayoutEditorOpen(false)} 
    />;
  }

  const handleOpenModal = () => {
    setFormData({ status: 'New', leadSource: 'Web Search' }); // Default Values
    setEditingId(null);
    setIsModalOpen(true);
  };

  const handleEditClick = (contact: Contact) => {
    setFormData({ ...contact });
    setEditingId(contact.id);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setEditingId(null);
  };

  const handleEditPageLayout = (e: React.MouseEvent) => {
      e.preventDefault();
      setIsModalOpen(false);
      setIsLayoutEditorOpen(true);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const checked = (e.target as HTMLInputElement).checked;

    setFormData(prev => ({ 
      ...prev, 
      [name]: type === 'checkbox' ? checked : value 
    }));
  };

  const saveContact = () => {
    // Dynamic Validation based on Layout
    const missingFields = layoutFields.filter(field => field.required && !formData[field.key as keyof Contact] && field.key !== 'owner');

    if (missingFields.length > 0) {
      alert(`Please fill in the required fields: ${missingFields.map(f => f.label).join(', ')}`);
      return false;
    }

    // Name Construction logic
    let fullName = formData.name;
    if (!fullName) {
        const firstName = formData.firstName || '';
        const lastName = formData.lastName || '';
        fullName = `${firstName} ${lastName}`.trim();
        if (!fullName && formData.company) fullName = formData.company; // Fallback
    }

    const contactData = {
      ...formData,
      name: fullName || 'Unknown',
      status: formData.status || 'New',
    } as Contact;

    if (editingId) {
      const originalContact = contacts.find(c => c.id === editingId);
      if (originalContact) {
        onUpdateContact({
          ...originalContact,
          ...contactData
        });
      }
    } else {
      onAddContact(contactData);
    }
    return true;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (saveContact()) {
      handleCloseModal();
    }
  };

  const handleSaveAndNew = (e: React.MouseEvent) => {
    e.preventDefault();
    if (saveContact()) {
      setFormData({ status: 'New' });
      setEditingId(null);
    }
  };

  // Drag and Drop Handlers (Kanban)
  const handleDragStart = (e: React.DragEvent, id: string) => {
    setDraggedContactId(id);
    e.dataTransfer.setData('contactId', id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragEnd = () => {
    setDraggedContactId(null);
    setDragOverColumn(null);
  };

  const handleDragOver = (e: React.DragEvent, status: ContactStatus) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    if (dragOverColumn !== status) {
        setDragOverColumn(status);
    }
  };

  const handleDrop = (e: React.DragEvent, status: ContactStatus) => {
    e.preventDefault();
    setDragOverColumn(null);
    const id = e.dataTransfer.getData('contactId');
    const contact = contacts.find(c => c.id === id);

    if (contact && contact.status !== status) {
      onUpdateContact({ ...contact, status });
    }
    setDraggedContactId(null);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Active': return 'bg-emerald-100 text-emerald-800 border-emerald-200 dark:bg-emerald-900/30 dark:text-emerald-300 dark:border-emerald-700/50';
      case 'Inactive': return 'bg-slate-100 text-slate-800 border-slate-200 dark:bg-slate-800/50 dark:text-slate-400 dark:border-slate-700';
      default: return 'bg-blue-100 text-blue-800 border-blue-200 dark:bg-blue-900/30 dark:text-blue-300 dark:border-blue-700/50';
    }
  };

  const renderField = (field: LayoutField) => {
      const isRequired = field.required;
      const commonClasses = `w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800/50 border ${isRequired && !formData[field.key as keyof Contact] ? 'border-red-300 dark:border-red-800' : 'border-slate-200 dark:border-slate-700'} rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500/50 text-slate-900 dark:text-white transition-all`;

      if (field.key === 'owner') {
          return (
            <div className="relative group">
                <input type="text" value="Bayas Ahamed" readOnly className={`${commonClasses} cursor-default`} />
                <IconUser className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 group-hover:text-purple-500 transition-colors" />
            </div>
          );
      }

      if (field.isComposite && field.key === 'firstName') {
          return (
            <div className="flex gap-2">
                <select className="w-24 px-2 py-2.5 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500/50 text-slate-900 dark:text-white text-sm">
                    <option>Mr.</option>
                    <option>Ms.</option>
                    <option>Dr.</option>
                </select>
                <input 
                    type="text" 
                    name={field.key} 
                    value={formData[field.key as keyof Contact] || ''} 
                    onChange={handleInputChange} 
                    className={commonClasses} 
                />
            </div>
          );
      }

      switch (field.type) {
          case 'select':
              let options = (
                 <>
                    <option value="">-None-</option>
                    <option value="Option 1">Option 1</option>
                    <option value="Option 2">Option 2</option>
                 </>
              );

              if (field.key === 'status') {
                  options = <>{CONTACT_STATUSES.map(s => <option key={s} value={s}>{s}</option>)}</>;
              } else if (field.key === 'leadSource') {
                  options = (
                    <>
                        <option value="">-None-</option>
                        {LEAD_SOURCES.map(s => <option key={s} value={s}>{s}</option>)}
                    </>
                  );
              }

              return (
                  <select name={field.key} value={formData[field.key as keyof Contact] || ''} onChange={handleInputChange} className={commonClasses}>
                      {options}
                  </select>
              );
          case 'checkbox':
              return (
                  <div className="flex items-center h-full">
                      <input type="checkbox" name={field.key} checked={!!formData[field.key as keyof Contact]} onChange={handleInputChange} className="w-5 h-5 text-purple-600 bg-slate-100 border-slate-300 rounded focus:ring-purple-500 dark:focus:ring-purple-600 dark:ring-offset-slate-800 focus:ring-2 dark:bg-slate-700 dark:border-slate-600 cursor-pointer" />
                  </div>
              );
          default:
              return (
                  <div className="relative group">
                    <input 
                        type={field.type} 
                        name={field.key} 
                        value={formData[field.key as keyof Contact] || ''} 
                        onChange={handleInputChange} 
                        className={commonClasses} 
                    />
                    {field.key === 'company' && <IconBuilding className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 group-hover:text-purple-500 transition-colors" />}
                  </div>
              );
      }
  };

  return (
    <>
      <div className="space-y-8 h-full flex flex-col animate-fade-in">
        {/* Header and Kanban/List Toggle */}
        <div className="flex justify-between items-center flex-shrink-0">
          <div className="flex items-center gap-4">
             <h1 className="text-3xl font-bold text-slate-900 dark:text-white">Contacts</h1>
             <div className="flex bg-slate-100 dark:bg-slate-800/50 p-1 rounded-xl border border-slate-200 dark:border-slate-700/50">
                <button onClick={() => setViewMode('list')} className={`p-2 rounded-lg transition-all duration-200 ${viewMode === 'list' ? 'bg-white dark:bg-slate-700 shadow-sm text-purple-600 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200'}`}><IconList className="w-4 h-4" /></button>
                <button onClick={() => setViewMode('kanban')} className={`p-2 rounded-lg transition-all duration-200 ${viewMode === 'kanban' ? 'bg-white dark:bg-slate-700 shadow-sm text-purple-600 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200'}`}><IconKanban className="w-4 h-4" /></button>
             </div>
          </div>
          <button onClick={handleOpenModal} className="px-5 py-2.5 text-sm font-medium text-white bg-purple-600 rounded-xl hover:bg-purple-500 shadow-lg shadow-purple-500/25 hover:shadow-purple-500/40 hover:-translate-y-0.5 transition-all duration-200">+ New Contact</button>
        </div>

        {/* Views Render (List or Kanban) */}
        {viewMode === 'list' ? (
          <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-sm dark:shadow-none overflow-hidden flex flex-col h-full">
            <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between bg-slate-50/50 dark:bg-slate-900/50">
              <div className="flex items-center space-x-2 bg-white dark:bg-slate-800 px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-700">
                  <IconFilter className="w-4 h-4 text-slate-400" />
                  <select className="bg-transparent text-sm font-medium text-slate-700 dark:text-slate-300 focus:outline-none cursor-pointer"><option>All Contacts</option></select>
              </div>
            </div>
            <div className="overflow-auto flex-1 custom-scrollbar">
                <table className="w-full text-left text-sm">
                <thead className="sticky top-0 z-20 bg-slate-50/90 dark:bg-slate-900/90 backdrop-blur-sm border-b border-slate-200 dark:border-slate-800">
                    <tr>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Name</th>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Title</th>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Account Name</th>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Email</th>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Phone</th>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Status</th>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Last Activity</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 dark:divide-slate-800/50">
                    {contacts.map((contact) => (
                    <tr key={contact.id} onClick={() => handleEditClick(contact)} className="hover:bg-slate-50/80 dark:hover:bg-slate-800/40 transition-colors cursor-pointer group">
                        <td className="px-6 py-4 text-base font-medium text-slate-900 dark:text-white flex items-center">
                            <div className="w-9 h-9 rounded-full bg-gradient-to-br from-purple-100 to-blue-100 dark:from-slate-700 dark:to-slate-600 flex items-center justify-center mr-3 text-sm font-bold text-slate-700 dark:text-slate-200 shadow-sm border border-white dark:border-slate-600">
                                {contact.name.charAt(0)}
                            </div>
                            <span className="group-hover:text-purple-600 dark:group-hover:text-purple-400 transition-colors">{contact.name}</span>
                        </td>
                        <td className="px-6 py-4 text-slate-600 dark:text-slate-400">{contact.title}</td>
                        <td className="px-6 py-4 text-slate-600 dark:text-slate-400">{contact.company}</td>
                        <td className="px-6 py-4 text-slate-600 dark:text-slate-400"><div className="flex items-center gap-2 group-hover:text-slate-900 dark:group-hover:text-slate-200 transition-colors"><IconMail className="w-3.5 h-3.5 opacity-50" />{contact.email}</div></td>
                        <td className="px-6 py-4 text-slate-600 dark:text-slate-400"><div className="flex items-center gap-2 group-hover:text-slate-900 dark:group-hover:text-slate-200 transition-colors"><IconPhone className="w-3.5 h-3.5 opacity-50" />{contact.phone}</div></td>
                        <td className="px-6 py-4"><span className={`px-2.5 py-1 text-xs font-semibold rounded-full border ${getStatusColor(contact.status || 'New')}`}>{contact.status || 'New'}</span></td>
                        <td className="px-6 py-4 text-slate-500 dark:text-slate-500">{contact.lastActivity}</td>
                    </tr>
                    ))}
                </tbody>
                </table>
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-x-auto overflow-y-hidden pb-4">
            <div className="flex h-full gap-6 min-w-full">
              {CONTACT_STATUSES.map(status => (
                <div 
                    key={status} 
                    onDragOver={(e) => handleDragOver(e, status)} 
                    onDrop={(e) => handleDrop(e, status)} 
                    className={`flex-1 min-w-[340px] flex flex-col border rounded-2xl h-full transition-all duration-300 ${
                        dragOverColumn === status 
                            ? 'bg-purple-50/50 dark:bg-purple-900/10 border-purple-300 dark:border-purple-500 shadow-inner' 
                            : 'bg-slate-100/50 dark:bg-slate-900/30 border-slate-200 dark:border-slate-800'
                    }`}
                >
                  <div className="p-4 border-b border-slate-200 dark:border-slate-800/50 flex justify-between items-center bg-white/40 dark:bg-slate-800/40 rounded-t-2xl backdrop-blur-md sticky top-0 z-10">
                    <h3 className="font-bold text-slate-700 dark:text-slate-200 flex items-center gap-2">
                        <span className={`w-3 h-3 rounded-full shadow-sm ${status === 'Active' ? 'bg-emerald-500' : status === 'Inactive' ? 'bg-slate-400' : 'bg-blue-500'}`}></span>
                        {status}
                    </h3>
                    <span className="bg-white dark:bg-slate-700 text-slate-600 dark:text-slate-300 text-xs font-bold px-2.5 py-1 rounded-full shadow-sm">{contacts.filter(c => (c.status || 'New') === status).length}</span>
                  </div>
                  <div className="p-4 space-y-3 overflow-y-auto flex-1 custom-scrollbar">
                     {contacts.filter(c => (c.status || 'New') === status).map(contact => (
                       <div 
                         key={contact.id} 
                         draggable 
                         onDragStart={(e) => handleDragStart(e, contact.id)} 
                         onDragEnd={handleDragEnd}
                         onClick={() => handleEditClick(contact)} 
                         className={`p-4 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl shadow-sm hover:shadow-lg hover:border-purple-300 dark:hover:border-purple-500/30 transition-all duration-200 cursor-move group select-none ${draggedContactId === contact.id ? 'opacity-40 scale-95' : 'hover:-translate-y-1'}`}
                       >
                         <div className="flex items-start justify-between mb-3">
                           <div className="flex items-center">
                                <div className="w-9 h-9 rounded-full bg-slate-50 dark:bg-slate-700 flex items-center justify-center text-xs font-bold text-slate-600 dark:text-slate-300 mr-3 border border-slate-100 dark:border-slate-600 shadow-sm">{contact.name.charAt(0)}</div>
                                <div>
                                    <h4 className="font-semibold text-slate-800 dark:text-slate-100 text-sm leading-tight group-hover:text-purple-600 dark:group-hover:text-purple-400 transition-colors">{contact.name}</h4>
                                    <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">{contact.title}</p>
                                </div>
                           </div>
                         </div>
                         <div className="pl-12 space-y-2">
                             <p className="text-sm text-slate-600 dark:text-slate-300 flex items-center">
                                 <IconBuilding className="w-3.5 h-3.5 mr-2 text-slate-400" />
                                 <span className="truncate">{contact.company}</span>
                             </p>
                             {(contact.email || contact.phone) && (
                                 <div className="flex items-center gap-3 pt-1">
                                    {contact.email && <div className="p-1.5 rounded-md bg-slate-50 dark:bg-slate-700/50 text-slate-500 dark:text-slate-400 hover:text-purple-600 dark:hover:text-purple-400 transition-colors"><IconMail className="w-3.5 h-3.5" /></div>}
                                    {contact.phone && <div className="p-1.5 rounded-md bg-slate-50 dark:bg-slate-700/50 text-slate-500 dark:text-slate-400 hover:text-purple-600 dark:hover:text-purple-400 transition-colors"><IconPhone className="w-3.5 h-3.5" /></div>}
                                 </div>
                             )}
                         </div>
                         <div className="flex justify-between items-center pt-3 mt-3 border-t border-slate-50 dark:border-slate-700/50 pl-12">
                             <span className="text-[10px] font-medium text-slate-400 uppercase tracking-wide">Last Activity</span>
                             <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">{contact.lastActivity}</span>
                         </div>
                       </div>
                     ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm transition-opacity duration-300">
          <div className="w-full max-w-5xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-scale-in">
            {/* Header */}
            <div className="p-5 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50/80 dark:bg-slate-950/80 backdrop-blur-md">
               <div className="flex items-center gap-3">
                  <h2 className="text-xl font-bold text-slate-900 dark:text-white">
                    {editingId ? 'Edit Contact' : 'Create Contact'}
                  </h2>
                  <button onClick={handleEditPageLayout} className="text-sm font-medium text-purple-600 hover:text-purple-700 dark:text-purple-400 hover:underline transition-colors">Edit Page Layout</button>
               </div>
               <div className="flex items-center gap-3">
                 <button onClick={handleCloseModal} className="px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">Cancel</button>
                 <button onClick={handleSaveAndNew} className="px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">Save and New</button>
                 <button onClick={handleSubmit} className="px-5 py-2 text-sm font-medium text-white bg-purple-600 rounded-lg hover:bg-purple-500 shadow-lg shadow-purple-500/20 transition-all">Save</button>
               </div>
            </div>

            {/* Dynamic Form Content */}
            <div className="overflow-y-auto p-8 bg-white dark:bg-slate-900 custom-scrollbar">
              <form onSubmit={handleSubmit}>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-8">
                    {layoutFields.map((field) => (
                        <div key={field.id} className="grid grid-cols-1 md:grid-cols-3 gap-4 items-center group">
                            <label className={`text-sm font-medium text-slate-600 dark:text-slate-400 md:text-right transition-colors group-focus-within:text-purple-600 dark:group-focus-within:text-purple-400 ${field.required ? 'after:content-["*"] after:text-red-500 after:ml-1' : ''}`}>
                                {field.label}
                            </label>
                            <div className="md:col-span-2">
                                {renderField(field)}
                            </div>
                        </div>
                    ))}
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default Contacts;

import React, { useState, useMemo } from 'react';
import { Contact, ContactStatus, LayoutField } from '../types';
import { IconFilter, IconPhone, IconMail, IconX, IconUser, IconBuilding, IconList, IconKanban, IconInfo } from './Icons';
import ContactLayoutEditor from './ContactLayoutEditor';

interface ContactsProps {
  contacts: Contact[];
  onAddContact: (contactData: Omit<Contact, 'id' | 'lastActivity'>) => void;
  onUpdateContact: (contact: Contact) => void;
}

const DEFAULT_LAYOUT: LayoutField[] = [
    { id: 'f1', label: 'Contact Owner', type: 'User', key: 'owner', value: 'User', required: false, isLocked: true },
    { id: 'f2', label: 'Lead Source', type: 'select', key: 'leadSource', value: 'Web Search', required: false, isLocked: false },
    { id: 'f3', label: 'First Name', type: 'text', key: 'firstName', value: 'Mr. ', required: false, isLocked: false, isComposite: true },
    { id: 'f4', label: 'Last Name', type: 'text', key: 'lastName', value: 'Single Line', required: true, isLocked: false },
    { id: 'f5', label: 'Account Name', type: 'text', key: 'company', value: 'Lookup', required: true, isLocked: false },
    { id: 'f6', label: 'Title', type: 'text', key: 'title', value: 'Single Line', required: false, isLocked: false },
    { id: 'f7', label: 'Email', type: 'email', key: 'email', value: 'Email', required: false, isLocked: false },
    { id: 'f8', label: 'Department', type: 'text', key: 'department', value: 'Single Line', required: false, isLocked: false },
    { id: 'f9', label: 'Phone', type: 'tel', key: 'phone', value: 'Phone', required: false, isLocked: false },
    { id: 'f11', label: 'Other Phone', type: 'tel', key: 'otherPhone', value: 'Phone', required: false, isLocked: false },
    { id: 'f13', label: 'Mobile', type: 'tel', key: 'mobile', value: 'Phone', required: false, isLocked: false },
    { id: 'f17', label: 'Email Opt Out', type: 'checkbox', key: 'emailOptOut', value: 'Check', required: false, isLocked: false },
    { id: 'f18', label: 'Status', type: 'select', key: 'status', value: 'New', required: true, isLocked: false }
];

const CONTACT_STATUSES: ContactStatus[] = ['New', 'Active', 'Inactive'];

const LEAD_SOURCES = [
    'Advertisement',
    'Cold Call',
    'Employee Referral',
    'External Referral',
    'Online Store',
    'Partner',
    'Trade Show',
    'Web Download',
    'Web Search',
    'Chat'
];

const Contacts: React.FC<ContactsProps> = ({ contacts, onAddContact, onUpdateContact }) => {
  const [viewMode, setViewMode] = useState<'list' | 'kanban'>('list');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [layoutFields, setLayoutFields] = useState<LayoutField[]>(DEFAULT_LAYOUT);
  const [formData, setFormData] = useState<Partial<Contact>>({});
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isLayoutEditorOpen, setIsLayoutEditorOpen] = useState(false);

  // Drag and Drop State
  const [draggedContactId, setDraggedContactId] = useState<string | null>(null);
  const [dragOverColumn, setDragOverColumn] = useState<ContactStatus | null>(null);

  // If layout editor mode is active, show the editor instead of the list
  if (isLayoutEditorOpen) {
    return <ContactLayoutEditor 
      currentLayout={layoutFields}
      onSave={(newLayout) => {
        setLayoutFields(newLayout);
        setIsLayoutEditorOpen(false);
      }}
      onBack={() => setIsLayoutEditorOpen(false)} 
    />;
  }

  const handleOpenModal = () => {
    setFormData({ status: 'New', leadSource: 'Web Search' }); // Default Values
    setEditingId(null);
    setIsModalOpen(true);
  };

  const handleEditClick = (contact: Contact) => {
    setFormData({ ...contact });
    setEditingId(contact.id);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setEditingId(null);
  };

  const handleEditPageLayout = (e: React.MouseEvent) => {
      e.preventDefault();
      setIsModalOpen(false);
      setIsLayoutEditorOpen(true);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const checked = (e.target as HTMLInputElement).checked;

    setFormData(prev => ({ 
      ...prev, 
      [name]: type === 'checkbox' ? checked : value 
    }));
  };

  const saveContact = () => {
    // Dynamic Validation based on Layout
    const missingFields = layoutFields.filter(field => field.required && !formData[field.key as keyof Contact] && field.key !== 'owner');

    if (missingFields.length > 0) {
      alert(`Please fill in the required fields: ${missingFields.map(f => f.label).join(', ')}`);
      return false;
    }

    // Name Construction logic
    let fullName = formData.name;
    if (!fullName) {
        const firstName = formData.firstName || '';
        const lastName = formData.lastName || '';
        fullName = `${firstName} ${lastName}`.trim();
        if (!fullName && formData.company) fullName = formData.company; // Fallback
    }

    const contactData = {
      ...formData,
      name: fullName || 'Unknown',
      status: formData.status || 'New',
    } as Contact;

    if (editingId) {
      const originalContact = contacts.find(c => c.id === editingId);
      if (originalContact) {
        onUpdateContact({
          ...originalContact,
          ...contactData
        });
      }
    } else {
      onAddContact(contactData);
    }
    return true;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (saveContact()) {
      handleCloseModal();
    }
  };

  const handleSaveAndNew = (e: React.MouseEvent) => {
    e.preventDefault();
    if (saveContact()) {
      setFormData({ status: 'New' });
      setEditingId(null);
    }
  };

  // Drag and Drop Handlers (Kanban)
  const handleDragStart = (e: React.DragEvent, id: string) => {
    setDraggedContactId(id);
    e.dataTransfer.setData('contactId', id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragEnd = () => {
    setDraggedContactId(null);
    setDragOverColumn(null);
  };

  const handleDragOver = (e: React.DragEvent, status: ContactStatus) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    if (dragOverColumn !== status) {
        setDragOverColumn(status);
    }
  };

  const handleDrop = (e: React.DragEvent, status: ContactStatus) => {
    e.preventDefault();
    setDragOverColumn(null);
    const id = e.dataTransfer.getData('contactId');
    const contact = contacts.find(c => c.id === id);

    if (contact && contact.status !== status) {
      onUpdateContact({ ...contact, status });
    }
    setDraggedContactId(null);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Active': return 'bg-emerald-100 text-emerald-800 border-emerald-200 dark:bg-emerald-900/30 dark:text-emerald-300 dark:border-emerald-700/50';
      case 'Inactive': return 'bg-slate-100 text-slate-800 border-slate-200 dark:bg-slate-800/50 dark:text-slate-400 dark:border-slate-700';
      default: return 'bg-blue-100 text-blue-800 border-blue-200 dark:bg-blue-900/30 dark:text-blue-300 dark:border-blue-700/50';
    }
  };

  const renderField = (field: LayoutField) => {
      const isRequired = field.required;
      const commonClasses = `w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800/50 border ${isRequired && !formData[field.key as keyof Contact] ? 'border-red-300 dark:border-red-800' : 'border-slate-200 dark:border-slate-700'} rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500/50 text-slate-900 dark:text-white transition-all`;

      if (field.key === 'owner') {
          return (
            <div className="relative group">
                <input type="text" value="Bayas Ahamed" readOnly className={`${commonClasses} cursor-default`} />
                <IconUser className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 group-hover:text-purple-500 transition-colors" />
            </div>
          );
      }

      if (field.isComposite && field.key === 'firstName') {
          return (
            <div className="flex gap-2">
                <select className="w-24 px-2 py-2.5 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500/50 text-slate-900 dark:text-white text-sm">
                    <option>Mr.</option>
                    <option>Ms.</option>
                    <option>Dr.</option>
                </select>
                <input 
                    type="text" 
                    name={field.key} 
                    value={formData[field.key as keyof Contact] || ''} 
                    onChange={handleInputChange} 
                    className={commonClasses} 
                />
            </div>
          );
      }

      switch (field.type) {
          case 'select':
              let options = (
                 <>
                    <option value="">-None-</option>
                    <option value="Option 1">Option 1</option>
                    <option value="Option 2">Option 2</option>
                 </>
              );

              if (field.key === 'status') {
                  options = <>{CONTACT_STATUSES.map(s => <option key={s} value={s}>{s}</option>)}</>;
              } else if (field.key === 'leadSource') {
                  options = (
                    <>
                        <option value="">-None-</option>
                        {LEAD_SOURCES.map(s => <option key={s} value={s}>{s}</option>)}
                    </>
                  );
              }

              return (
                  <select name={field.key} value={formData[field.key as keyof Contact] || ''} onChange={handleInputChange} className={commonClasses}>
                      {options}
                  </select>
              );
          case 'checkbox':
              return (
                  <div className="flex items-center h-full">
                      <input type="checkbox" name={field.key} checked={!!formData[field.key as keyof Contact]} onChange={handleInputChange} className="w-5 h-5 text-purple-600 bg-slate-100 border-slate-300 rounded focus:ring-purple-500 dark:focus:ring-purple-600 dark:ring-offset-slate-800 focus:ring-2 dark:bg-slate-700 dark:border-slate-600 cursor-pointer" />
                  </div>
              );
          default:
              return (
                  <div className="relative group">
                    <input 
                        type={field.type} 
                        name={field.key} 
                        value={formData[field.key as keyof Contact] || ''} 
                        onChange={handleInputChange} 
                        className={commonClasses} 
                    />
                    {field.key === 'company' && <IconBuilding className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 group-hover:text-purple-500 transition-colors" />}
                  </div>
              );
      }
  };

  return (
    <>
      <div className="space-y-8 h-full flex flex-col animate-fade-in">
        {/* Header and Kanban/List Toggle */}
        <div className="flex justify-between items-center flex-shrink-0">
          <div className="flex items-center gap-4">
             <h1 className="text-3xl font-bold text-slate-900 dark:text-white">Contacts</h1>
             <div className="flex bg-slate-100 dark:bg-slate-800/50 p-1 rounded-xl border border-slate-200 dark:border-slate-700/50">
                <button onClick={() => setViewMode('list')} className={`p-2 rounded-lg transition-all duration-200 ${viewMode === 'list' ? 'bg-white dark:bg-slate-700 shadow-sm text-purple-600 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200'}`}><IconList className="w-4 h-4" /></button>
                <button onClick={() => setViewMode('kanban')} className={`p-2 rounded-lg transition-all duration-200 ${viewMode === 'kanban' ? 'bg-white dark:bg-slate-700 shadow-sm text-purple-600 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200'}`}><IconKanban className="w-4 h-4" /></button>
             </div>
          </div>
          <button onClick={handleOpenModal} className="px-5 py-2.5 text-sm font-medium text-white bg-purple-600 rounded-xl hover:bg-purple-500 shadow-lg shadow-purple-500/25 hover:shadow-purple-500/40 hover:-translate-y-0.5 transition-all duration-200">+ New Contact</button>
        </div>

        {/* Views Render (List or Kanban) */}
        {viewMode === 'list' ? (
          <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-sm dark:shadow-none overflow-hidden flex flex-col h-full">
            <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between bg-slate-50/50 dark:bg-slate-900/50">
              <div className="flex items-center space-x-2 bg-white dark:bg-slate-800 px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-700">
                  <IconFilter className="w-4 h-4 text-slate-400" />
                  <select className="bg-transparent text-sm font-medium text-slate-700 dark:text-slate-300 focus:outline-none cursor-pointer"><option>All Contacts</option></select>
              </div>
            </div>
            <div className="overflow-auto flex-1 custom-scrollbar">
                <table className="w-full text-left text-sm">
                <thead className="sticky top-0 z-20 bg-slate-50/90 dark:bg-slate-900/90 backdrop-blur-sm border-b border-slate-200 dark:border-slate-800">
                    <tr>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Name</th>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Title</th>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Account Name</th>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Email</th>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Phone</th>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Status</th>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Last Activity</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 dark:divide-slate-800/50">
                    {contacts.map((contact) => (
                    <tr key={contact.id} onClick={() => handleEditClick(contact)} className="hover:bg-slate-50/80 dark:hover:bg-slate-800/40 transition-colors cursor-pointer group">
                        <td className="px-6 py-4 text-base font-medium text-slate-900 dark:text-white flex items-center">
                            <div className="w-9 h-9 rounded-full bg-gradient-to-br from-purple-100 to-blue-100 dark:from-slate-700 dark:to-slate-600 flex items-center justify-center mr-3 text-sm font-bold text-slate-700 dark:text-slate-200 shadow-sm border border-white dark:border-slate-600">
                                {contact.name.charAt(0)}
                            </div>
                            <span className="group-hover:text-purple-600 dark:group-hover:text-purple-400 transition-colors">{contact.name}</span>
                        </td>
                        <td className="px-6 py-4 text-slate-600 dark:text-slate-400">{contact.title}</td>
                        <td className="px-6 py-4 text-slate-600 dark:text-slate-400">{contact.company}</td>
                        <td className="px-6 py-4 text-slate-600 dark:text-slate-400"><div className="flex items-center gap-2 group-hover:text-slate-900 dark:group-hover:text-slate-200 transition-colors"><IconMail className="w-3.5 h-3.5 opacity-50" />{contact.email}</div></td>
                        <td className="px-6 py-4 text-slate-600 dark:text-slate-400"><div className="flex items-center gap-2 group-hover:text-slate-900 dark:group-hover:text-slate-200 transition-colors"><IconPhone className="w-3.5 h-3.5 opacity-50" />{contact.phone}</div></td>
                        <td className="px-6 py-4"><span className={`px-2.5 py-1 text-xs font-semibold rounded-full border ${getStatusColor(contact.status || 'New')}`}>{contact.status || 'New'}</span></td>
                        <td className="px-6 py-4 text-slate-500 dark:text-slate-500">{contact.lastActivity}</td>
                    </tr>
                    ))}
                </tbody>
                </table>
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-x-auto overflow-y-hidden pb-4">
            <div className="flex h-full gap-6 min-w-full">
              {CONTACT_STATUSES.map(status => (
                <div 
                    key={status} 
                    onDragOver={(e) => handleDragOver(e, status)} 
                    onDrop={(e) => handleDrop(e, status)} 
                    className={`flex-1 min-w-[340px] flex flex-col border rounded-2xl h-full transition-all duration-300 ${
                        dragOverColumn === status 
                            ? 'bg-purple-50/50 dark:bg-purple-900/10 border-purple-300 dark:border-purple-500 shadow-inner' 
                            : 'bg-slate-100/50 dark:bg-slate-900/30 border-slate-200 dark:border-slate-800'
                    }`}
                >
                  <div className="p-4 border-b border-slate-200 dark:border-slate-800/50 flex justify-between items-center bg-white/40 dark:bg-slate-800/40 rounded-t-2xl backdrop-blur-md sticky top-0 z-10">
                    <h3 className="font-bold text-slate-700 dark:text-slate-200 flex items-center gap-2">
