import React, { useState } from 'react';
import { 
  IconUser, 
  IconBuilding, 
  IconGlobe, 
  IconSparkles, 
  IconBell, 
  IconShield, 
  IconSave,
  IconCheckCircle,
  IconMoon,
  IconSun,
  IconBot,
  IconZap,
  IconMail,
  IconCopy,
  IconCheckSquare,
  IconFileText
} from './Icons';

interface SettingsProps {
  isDark: boolean;
  toggleTheme: () => void;
  primaryColor: string;
  setPrimaryColor: (color: string) => void;
  pipelineGoal: number;
  setPipelineGoal: (goal: number) => void;
}

const Toggle = ({ label, description, checked, onChange }: { label: string, description?: string, checked: boolean, onChange: (v: boolean) => void }) => (
  <div className="flex items-center justify-between py-4 border-b border-slate-100 dark:border-slate-800 last:border-0">
    <div>
      <p className="font-medium text-slate-900 dark:text-white">{label}</p>
      {description && <p className="text-sm text-slate-500 dark:text-slate-400 mt-0.5">{description}</p>}
    </div>
    <button 
      onClick={() => onChange(!checked)}
      className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-purple-500 focus:ring-offset-2 dark:focus:ring-offset-slate-900 ${checked ? 'bg-purple-600' : 'bg-slate-200 dark:bg-slate-700'}`}
    >
      <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${checked ? 'translate-x-6' : 'translate-x-1'}`} />
    </button>
  </div>
);

const RadioCard = ({ label, description, checked, onClick }: { label: string, description?: string, checked: boolean, onClick: () => void }) => (
    <div 
        onClick={onClick}
        className={`p-4 rounded-xl border-2 cursor-pointer transition-all ${checked ? 'border-purple-500 bg-purple-50 dark:bg-purple-900/10' : 'border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 hover:border-purple-200 dark:hover:border-slate-600'}`}
    >
        <div className="flex items-center justify-between mb-1">
            <span className={`font-semibold ${checked ? 'text-purple-700 dark:text-purple-400' : 'text-slate-900 dark:text-white'}`}>{label}</span>
            {checked && <IconCheckCircle className="w-5 h-5 text-purple-600 dark:text-purple-400" />}
        </div>
        {description && <p className="text-xs text-slate-500 dark:text-slate-400">{description}</p>}
    </div>
);

const Settings: React.FC<SettingsProps> = ({ 
  isDark, 
  toggleTheme, 
  primaryColor, 
  setPrimaryColor,
  pipelineGoal,
  setPipelineGoal
}) => {
  const [activeTab, setActiveTab] = useState('company');
  const [companyName, setCompanyName] = useState('TalentSense AI');
  const [goalInput, setGoalInput] = useState(pipelineGoal.toString());
  const [isSaved, setIsSaved] = useState(false);

  // Theme Extended State
  const [fontFamily, setFontFamily] = useState('Inter');
  const [density, setDensity] = useState('Comfortable');

  // AI State
  const [aiScoring, setAiScoring] = useState(true);
  const [autoDraft, setAutoDraft] = useState(false);
  const [predictivePipeline, setPredictivePipeline] = useState(true);
  const [creativityLevel, setCreativityLevel] = useState(0.7);

  // Notification State
  const [emailAlerts, setEmailAlerts] = useState(true);
  const [dealWonAlert, setDealWonAlert] = useState(true);
  const [newLeadAlert, setNewLeadAlert] = useState(true);
  const [taskReminders, setTaskReminders] = useState(false);

  // Security State
  const [twoFactor, setTwoFactor] = useState(true);
  const [sessionTimeout, setSessionTimeout] = useState('30');
  const [apiKeyVisible, setApiKeyVisible] = useState(false);

  // Regional State
  const [weekStart, setWeekStart] = useState('Sunday');
  const [dateFormat, setDateFormat] = useState('MM/DD/YYYY');

  const handleSave = () => {
    setPipelineGoal(Number(goalInput));
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const colors = [
    { name: 'Violet', value: 'purple', class: 'bg-purple-600' },
    { name: 'Royal Blue', value: 'blue', class: 'bg-blue-600' },
    { name: 'Emerald', value: 'emerald', class: 'bg-emerald-600' },
    { name: 'Amber', value: 'amber', class: 'bg-amber-600' },
    { name: 'Orange', value: 'orange', class: 'bg-orange-600' },
    { name: 'Rose', value: 'rose', class: 'bg-rose-600' },
    { name: 'Cyan', value: 'cyan', class: 'bg-cyan-600' },
    { name: 'Pink', value: 'pink', class: 'bg-pink-600' },
    { name: 'Slate', value: 'slate', class: 'bg-slate-600' },
  ];

  const fonts = [
      { name: 'Inter', value: 'Inter', description: 'Clean & Modern (Default)' },
      { name: 'Roboto', value: 'Roboto', description: 'Geometric & Friendly' },
      { name: 'System UI', value: 'System', description: 'Native Operating System' },
      { name: 'Serif', value: 'Serif', description: 'Elegant & Classic' },
  ];

  const renderContent = () => {
    switch (activeTab) {
      case 'company':
        return (
          <div className="space-y-8 animate-fade-in">
            <div>
              <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-1">Company Profile Configuration</h3>
              <p className="text-sm text-slate-500 dark:text-slate-400">Manage your organization's public identity and contact details.</p>
            </div>

            <div className="p-6 bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm">
               <div className="flex items-center gap-6 mb-8">
                  <div className="w-20 h-20 bg-slate-100 dark:bg-slate-700 rounded-xl border-2 border-dashed border-slate-300 dark:border-slate-600 flex items-center justify-center flex-shrink-0">
                      <IconBuilding className="w-8 h-8 text-slate-400" />
                  </div>
                  <div>
                      <h4 className="font-semibold text-slate-900 dark:text-white">Organization Logo</h4>
                      <p className="text-xs text-slate-500 dark:text-slate-400 mb-3">Auto-scales for header, payslips, and job portal.</p>
                      <button className="px-4 py-2 text-xs font-bold text-purple-600 dark:text-purple-400 bg-purple-50 dark:bg-purple-900/20 rounded-lg hover:bg-purple-100 dark:hover:bg-purple-900/30 transition-colors">UPLOAD NEW</button>
                  </div>
               </div>

               <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                      <label className="block text-xs font-bold text-slate-500 uppercase tracking-wide mb-2">Organization Name</label>
                      <input 
                        type="text" 
                        value={companyName} 
                        onChange={(e) => setCompanyName(e.target.value)}
                        className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg focus:ring-2 focus:ring-purple-500 focus:outline-none text-slate-900 dark:text-white font-medium transition-all"
                      />
                  </div>
                  <div>
                      <label className="block text-xs font-bold text-slate-500 uppercase tracking-wide mb-2">Primary Support Email</label>
                      <input 
                        type="email" 
                        defaultValue="ops@talentsense.io"
                        className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg focus:ring-2 focus:ring-purple-500 focus:outline-none text-slate-900 dark:text-white font-medium transition-all"
                      />
                  </div>
                  <div className="md:col-span-2">
                      <label className="block text-xs font-bold text-slate-500 uppercase tracking-wide mb-2">Official Website URL</label>
                      <input 
                        type="url" 
                        defaultValue="https://talentsense.io"
                        className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg focus:ring-2 focus:ring-purple-500 focus:outline-none text-slate-900 dark:text-white font-medium transition-all"
                      />
                  </div>
               </div>
            </div>
          </div>
        );

