  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-[#0f172a] overflow-hidden">
        {/* Header */}
        <div className="px-8 py-6 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center sticky top-0 z-10">
            <div>
                <h1 className="text-2xl font-bold text-slate-900 dark:text-white tracking-tight">Command Center</h1>
                <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">Configure core logic, branding, and regulatory compliance.</p>
