                <div className="p-6 bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm space-y-6">
                    <div>
                        <h4 className="font-bold text-slate-900 dark:text-white mb-4 flex items-center">
                            <IconShield className="w-5 h-5 mr-2 text-emerald-500" />
                            Login Security
                        </h4>
                        <Toggle 
                            label="Two-Factor Authentication (2FA)" 
                            description="Require an extra security code when logging in from a new device."
                            checked={twoFactor}
                            onChange={setTwoFactor}
                        />
                    </div>

                    <div className="pt-4 border-t border-slate-100 dark:border-slate-700">
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">Session Timeout</label>
                        <select 
                            value={sessionTimeout}
