    </div>
  );
};

export default Settings;

import React, { useState, useMemo, useEffect } from 'react';
import { Lead, EmailTemplate, NurtureEmail, LeadStatus } from '../types';
import { MOCK_TEMPLATES } from '../constants';
import LeadForm from './LeadForm'; 
import LeadDetail from './LeadDetail';
import { 
  IconSearch, 
  IconChevronDown, 
  IconChevronRight, 
  IconSparkles, 
  IconMail,
  IconSend,
  IconX,
  IconTrash,
  IconBot,
  IconClock,
  IconArrowUp,
  IconArrowDown,
  IconFunnel
} from './Icons';
import { generateSmartFilterCriteria, batchAnalyzeLeads, generateAIBulkEmail, generateNurtureSequence } from '../services/geminiService';

interface LeadsProps {
  leads: Lead[];
  onAddLead: (leadData: Omit<Lead, 'id'>) => void;
  onUpdateLead: (lead: Lead) => void;
  onDeleteLeads: (leadIds: string[]) => void;
}

type ViewMode = 'list' | 'create' | 'edit' | 'detail';
type SortKey = keyof Lead;
type SortDirection = 'asc' | 'desc';

const FilterCheckbox: React.FC<{ label: string; count?: number; filterKey?: string; checked: boolean; onChange: (checked: boolean) => void; }> = ({ label, count, filterKey, checked, onChange }) => {
  const checkboxId = `filter-${filterKey || label}`;
  return (
    <div className="flex items-center group cursor-pointer py-1">
      <input type="checkbox" id={checkboxId} className="w-4 h-4 rounded border-slate-300 text-primary-600 focus:ring-primary-500 bg-white dark:bg-slate-800 dark:border-slate-700 cursor-pointer" onChange={(e) => onChange(e.target.checked)} checked={checked} />
      <label htmlFor={checkboxId} className="ml-2 text-sm text-slate-600 dark:text-slate-300 group-hover:text-primary-600 dark:group-hover:text-primary-400 transition-colors cursor-pointer flex-1 truncate">{label}</label>
      {count !== undefined && <span className="ml-auto text-xs text-slate-400 bg-slate-100 dark:bg-slate-800 px-1.5 py-0.5 rounded-full">{count}</span>}
    </div>
  );
};

const Leads: React.FC<LeadsProps> = ({ leads, onAddLead, onUpdateLead, onDeleteLeads }) => {
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [selectedLead, setSelectedLead] = useState<Lead | null>(null);
  const [expandedSections, setExpandedSections] = useState<Record<string, boolean>>({'source': true, 'status': true});

  // Filtering, Sorting, and Pagination State
  const [searchQuery, setSearchQuery] = useState('');
  const [smartFilterQuery, setSmartFilterQuery] = useState('');
  const [isProcessingAI, setIsProcessingAI] = useState(false);
  const [selectedFilters, setSelectedFilters] = useState<Record<string, boolean>>({});
  const [aiFilters, setAiFilters] = useState<any[]>([]);
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: SortDirection } | null>({ key: 'score', direction: 'desc' });
  const [currentPage, setCurrentPage] = useState(1);
  const [recordsPerPage, setRecordsPerPage] = useState(10);

  const [selectedLeadIds, setSelectedLeadIds] = useState<Set<string>>(new Set());
  const [batchAnalysisResult, setBatchAnalysisResult] = useState<string | null>(null);
  const [isEmailModalOpen, setIsEmailModalOpen] = useState(false);
  const [emailSubject, setEmailSubject] = useState('');
  const [emailBody, setEmailBody] = useState('');
  const [emailTone, setEmailTone] = useState<'formal' | 'casual' | 'persuasive'>('persuasive');
  const [isDraftingAI, setIsDraftingAI] = useState(false);
  const [previewLeadName, setPreviewLeadName] = useState<string | null>(null);
  const [isSchedulingEmail, setIsSchedulingEmail] = useState(false);
  const [scheduleDateTime, setScheduleDateTime] = useState('');
  const [isNurtureModalOpen, setIsNurtureModalOpen] = useState(false);
  const [nurtureSequence, setNurtureSequence] = useState<NurtureEmail[] | null>(null);
  const [isNurturing, setIsNurturing] = useState(false);
  const [activeNurtureAccordion, setActiveNurtureAccordion] = useState<number | null>(0);

  // Move useMemo hooks to the top level, before any conditional returns
  const uniqueLeadSources = useMemo(() => Array.from(new Set(leads.map(l => l.leadSource).filter(Boolean))).sort(), [leads]);
  const uniqueStatuses = useMemo(() => Object.values(LeadStatus), []);
  const uniqueIndustries = useMemo(() => Array.from(new Set(leads.map(l => l.industry).filter(Boolean))).sort(), [leads]);
  const uniqueRatings = useMemo(() => Array.from(new Set(leads.map(l => l.rating).filter(Boolean))).sort(), [leads]);

  const applyAIFilters = (lead: Lead, filters: any[]) => {
      if (!filters || filters.length === 0) return true;
      return filters.every(filter => {
          const leadValue = lead[filter.field as keyof Lead] as any;
          if (leadValue === undefined) return false;
          const filterValue = isNaN(Number(filter.value)) ? filter.value : Number(filter.value);
          const leadValueNormalized = typeof leadValue === 'string' ? leadValue.toLowerCase() : leadValue;
          const filterValueNormalized = typeof filterValue === 'string' ? filterValue.toLowerCase() : filterValue;

          switch (filter.operator) {
              case '$gt': return leadValueNormalized > filterValueNormalized;
              case '$lt': return leadValueNormalized < filterValueNormalized;
              case '$eq': return leadValueNormalized == filterValueNormalized;
              case '$contains': return typeof leadValueNormalized === 'string' && leadValueNormalized.includes(filterValueNormalized as string);
              default: return true;
          }
      });
  };

  const filteredLeads = useMemo(() => {
    const query = searchQuery.toLowerCase();
    const activeSourceFilters = uniqueLeadSources.filter(source => selectedFilters[`Source: ${source}`]);
    const activeStatusFilters = uniqueStatuses.filter(status => selectedFilters[`Status: ${status}`]);
    const activeIndustryFilters = uniqueIndustries.filter(industry => selectedFilters[`Industry: ${industry}`]);
    const activeRatingFilters = uniqueRatings.filter(rating => selectedFilters[`Rating: ${rating}`]);

    return leads.filter(lead => {
      const matchesSearch = !query || ['name', 'company', 'email', 'leadSource', 'city'].some(field => lead[field as keyof Lead]?.toString().toLowerCase().includes(query));

      const matchesSource = activeSourceFilters.length === 0 || (lead.leadSource && activeSourceFilters.includes(lead.leadSource));
      const matchesStatus = activeStatusFilters.length === 0 || (lead.status && activeStatusFilters.includes(lead.status));
      const matchesIndustry = activeIndustryFilters.length === 0 || (lead.industry && activeIndustryFilters.includes(lead.industry));
      const matchesRating = activeRatingFilters.length === 0 || (lead.rating && activeRatingFilters.includes(lead.rating));

      const matchesAI = applyAIFilters(lead, aiFilters);

      return matchesSearch && matchesSource && matchesStatus && matchesIndustry && matchesRating && matchesAI;
    });
  }, [leads, searchQuery, selectedFilters, uniqueLeadSources, uniqueStatuses, uniqueIndustries, uniqueRatings, aiFilters]);


  const sortedLeads = useMemo(() => {
    let sortableItems = [...filteredLeads];
    if (sortConfig !== null) {
      sortableItems.sort((a, b) => {
        const aValue = a[sortConfig.key];
        const bValue = b[sortConfig.key];
        if (aValue === undefined || aValue < bValue) return sortConfig.direction === 'asc' ? -1 : 1;
        if (bValue === undefined || aValue > bValue) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
      });
    }
    return sortableItems;
  }, [filteredLeads, sortConfig]);

  const handleViewLeadDetail = (lead: Lead) => { setSelectedLead(lead); setViewMode('detail'); };
  const handleCreateNewLead = () => { setSelectedLead(null); setViewMode('create'); };
  const handleEditLead = (lead: Lead) => { setSelectedLead(lead); setViewMode('edit'); };
  const handleCancelForm = () => { setSelectedLead(null); setViewMode('list'); };
  const handleBackToList = () => { setSelectedLead(null); setViewMode('list'); };

  useEffect(() => {
    setSelectedLeadIds(new Set()); // Reset selection when filters or page change
  }, [searchQuery, selectedFilters, aiFilters, currentPage, recordsPerPage]);


  const handleSaveLead = (leadData: Lead) => {
    if (viewMode === 'edit' && selectedLead) {
      onUpdateLead({ ...selectedLead, ...leadData });
    } else {
      onAddLead(leadData);
    }
    setViewMode('list');
    setSelectedLead(null);
  };

  const handleDeleteSelected = () => {
    if (selectedLeadIds.size === 0) return;
    if (window.confirm(`Are you sure you want to delete ${selectedLeadIds.size} selected lead(s)?`)) {
      onDeleteLeads(Array.from(selectedLeadIds));
      setSelectedLeadIds(new Set());
    }
  };

  const handleDeleteFromDetail = (leadId: string) => {
     if (window.confirm(`Are you sure you want to delete this lead?`)) {
      onDeleteLeads([leadId]);
      setViewMode('list');
      setSelectedLead(null);
    }
  };

  const handleNurtureLead = async (lead: Lead) => {
    setIsNurturing(true);
    setNurtureSequence(null);
    setActiveNurtureAccordion(0);
    setIsNurtureModalOpen(true);
    const sequence = await generateNurtureSequence(lead);
    setNurtureSequence(sequence);
    setIsNurturing(false);
  };

  const closeNurtureModal = () => {
    setIsNurtureModalOpen(false);
    setNurtureSequence(null);
  };

  const toggleSection = (section: string) => setExpandedSections(prev => ({ ...prev, [section]: !prev[section] }));
  const toggleSelection = (id: string) => {
    const newSelected = new Set(selectedLeadIds);
    newSelected.has(id) ? newSelected.delete(id) : newSelected.add(id);
    setSelectedLeadIds(newSelected);
  };

  const handleSmartFilter = async () => {
    if (!smartFilterQuery.trim()) { setAiFilters([]); return; }
    setIsProcessingAI(true);
    setSearchQuery('');
    const criteria = await generateSmartFilterCriteria(smartFilterQuery);
    setAiFilters(criteria.filters || []);
    setIsProcessingAI(false);
    setCurrentPage(1);
  };

  const handleBatchAnalyze = async () => {
    if (selectedLeadIds.size === 0) return;
    setIsProcessingAI(true);
    const selectedLeads = leads.filter(l => selectedLeadIds.has(l.id));
    const result = await batchAnalyzeLeads(selectedLeads);
    setBatchAnalysisResult(result);
    setIsProcessingAI(false);
  };

  const handleOpenEmailModal = () => { if (selectedLeadIds.size > 0) setIsEmailModalOpen(true); };
  const closeEmailModal = () => { setIsEmailModalOpen(false); setEmailSubject(''); setEmailBody(''); setPreviewLeadName(null); setIsSchedulingEmail(false); setScheduleDateTime(''); };

  const handleTemplateChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const templateId = e.target.value;
    if (!templateId) { setEmailSubject(''); setEmailBody(''); setPreviewLeadName(null); return; }
    const template = MOCK_TEMPLATES.find(t => t.id === templateId);
    if (!template) return;
    const previewLead = leads.find(l => l.id === Array.from(selectedLeadIds)[0]);
    if (previewLead) {
      setPreviewLeadName(previewLead.name);
      setEmailSubject(template.subject.replace(/{{name}}/g, previewLead.name).replace(/{{company}}/g, previewLead.company));
      setEmailBody(template.body.replace(/{{name}}/g, previewLead.name).replace(/{{company}}/g, previewLead.company));
    } else {
      setPreviewLeadName(null);
      setEmailSubject(template.subject.replace(/{{.+?}}/g, '[Variable]'));
      setEmailBody(template.body.replace(/{{name}}/g, '[Lead Name]').replace(/{{company}}/g, '[Company Name]'));
    }
  };

  const handleAIDraft = async () => {
    if (selectedLeadIds.size === 0) return;
    setIsDraftingAI(true);
    const selectedLeads = leads.filter(l => selectedLeadIds.has(l.id));
    const result = await generateAIBulkEmail(selectedLeads, emailTone, emailBody);
    setEmailBody(result);
    setIsDraftingAI(false);
  };

  const handleSendEmail = () => {
    const message = isSchedulingEmail ? `Email scheduled for ${new Date(scheduleDateTime).toLocaleString()}` : `Email successfully sent`;
    alert(`${message} to ${selectedLeadIds.size} selected leads!`);
    closeEmailModal();
  };

  const paginatedLeads = sortedLeads.slice((currentPage - 1) * recordsPerPage, currentPage * recordsPerPage);
  const totalPages = Math.ceil(sortedLeads.length / recordsPerPage);

  const toggleSelectAll = () => {
    if (selectedLeadIds.size === paginatedLeads.length) setSelectedLeadIds(new Set());
    else setSelectedLeadIds(new Set(paginatedLeads.map(l => l.id)));
  };

  const requestSort = (key: SortKey) => {
    let direction: SortDirection = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') direction = 'desc';
    setSortConfig({ key, direction });
  };

  const getSortIcon = (key: SortKey) => {
    if (!sortConfig || sortConfig.key !== key) return <span className="w-3 h-3 opacity-0 group-hover:opacity-50 transition-opacity">↕️</span>;
    if (sortConfig.direction === 'asc') return <IconArrowUp className="w-3 h-3 text-primary-500" />;
    return <IconArrowDown className="w-3 h-3 text-primary-500" />;
  };

  // Helper for Status Badge Color
  const getStatusStyle = (status: string) => {
    switch(status) {
        case LeadStatus.NEW: return 'bg-blue-50 text-blue-700 border-blue-200 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-800/30';
        case LeadStatus.CONTACTED: return 'bg-primary-50 text-primary-700 border-primary-200 dark:bg-primary-900/20 dark:text-primary-400 dark:border-primary-800/30';
        case LeadStatus.QUALIFIED: return 'bg-indigo-50 text-indigo-700 border-indigo-200 dark:bg-indigo-900/20 dark:text-indigo-400 dark:border-indigo-800/30';
        case LeadStatus.PROPOSAL: return 'bg-amber-50 text-amber-700 border-amber-200 dark:bg-amber-900/20 dark:text-amber-400 dark:border-amber-800/30';
        case LeadStatus.NEGOTIATION: return 'bg-orange-50 text-orange-700 border-orange-200 dark:bg-orange-900/20 dark:text-orange-400 dark:border-orange-800/30';
        case LeadStatus.CLOSED: return 'bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-900/20 dark:text-emerald-400 dark:border-emerald-800/30';
        case LeadStatus.LOST: return 'bg-slate-50 text-slate-600 border-slate-200 dark:bg-slate-800 dark:text-slate-400 dark:border-slate-700';
        default: return 'bg-slate-50 text-slate-600 border-slate-200';
    }
  };

  const getInitials = (name: string) => {
    return name.split(' ').map(n => n[0]).join('').substring(0, 2).toUpperCase();
  };

  const getScoreColor = (score: number) => {
      if (score >= 80) return 'text-emerald-500';
      if (score >= 50) return 'text-yellow-500';
      return 'text-red-500';
  };

  // Conditional rendering at the end to avoid Hook error #300
  if (viewMode === 'create' || viewMode === 'edit') return <LeadForm onCancel={handleCancelForm} onSave={handleSaveLead} initialData={selectedLead} />;
  if (viewMode === 'detail' && selectedLead) return <LeadDetail lead={selectedLead} onBack={handleBackToList} onEdit={() => handleEditLead(selectedLead)} onDelete={() => handleDeleteFromDetail(selectedLead.id)} onNurture={() => handleNurtureLead(selectedLead)} isNurturing={isNurturing} leads={leads} />;

  return (
    <>
      <div className="flex flex-col md:flex-row h-full gap-4 md:gap-6">
        {/* Filters Sidebar */}
        <div className="w-full md:w-64 flex-shrink-0 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden flex flex-col h-full animate-fade-in">
          <div className="p-4 border-b border-slate-100 dark:border-slate-800 flex items-center gap-2 bg-slate-50/50 dark:bg-slate-800/30">
            <IconFunnel className="w-4 h-4 text-primary-500" />
            <h2 className="text-sm font-bold text-slate-800 dark:text-slate-200 uppercase tracking-wide">Smart Filters</h2>
          </div>
          <div className="flex-1 overflow-y-auto p-3 custom-scrollbar space-y-3">
            {/* Lead Source Section */}
            <div className="bg-slate-50/50 dark:bg-slate-800/30 rounded-lg p-2">
              <button onClick={() => toggleSection('source')} className="flex items-center justify-between w-full text-left mb-2 group">
                <span className="text-sm font-semibold text-slate-700 dark:text-slate-300 group-hover:text-primary-600 transition-colors">Lead Source</span>
                {expandedSections['source'] ? <IconChevronDown className="w-3.5 h-3.5 text-slate-400" /> : <IconChevronRight className="w-3.5 h-3.5 text-slate-400" />}
              </button>
              {expandedSections['source'] && <div className="space-y-0.5 animate-fade-in">{uniqueLeadSources.map(source => <FilterCheckbox key={source} label={source || 'Unknown'} filterKey={`Source: ${source}`} checked={!!selectedFilters[`Source: ${source}`]} onChange={(checked) => setSelectedFilters(prev => ({ ...prev, [`Source: ${source}`]: checked }))} count={leads.filter(l => l.leadSource === source).length} />)}</div>}
            </div>

            {/* Status Section */}
            <div className="bg-slate-50/50 dark:bg-slate-800/30 rounded-lg p-2">
              <button onClick={() => toggleSection('status')} className="flex items-center justify-between w-full text-left mb-2 group">
                <span className="text-sm font-semibold text-slate-700 dark:text-slate-300 group-hover:text-primary-600 transition-colors">Status</span>
                {expandedSections['status'] ? <IconChevronDown className="w-3.5 h-3.5 text-slate-400" /> : <IconChevronRight className="w-3.5 h-3.5 text-slate-400" />}
              </button>
