                </div>

                <div>
                  <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Stage</label>
                  <select
                    name="stage"
                    value={formData.stage}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white"
                  >
                    <option value="Qualification">Qualification</option>
                    <option value="Needs Analysis">Needs Analysis</option>
                    <option value="Value Proposition">Value Proposition</option>
                    <option value="Id. Decision Makers">Id. Decision Makers</option>
                    <option value="Proposal/Price Quote">Proposal/Price Quote</option>
                    <option value="Negotiation/Review">Negotiation/Review</option>
                    <option value="Closed Won">Closed Won</option>
                    <option value="Closed Lost">Closed Lost</option>
                  </select>
                </div>

                <div className="pt-4 flex space-x-3">
                  <button
                    type="button"
                    onClick={() => { setIsModalOpen(false); setSelectedDeal(null); }}
                    className="flex-1 px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    className="flex-1 px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-colors"
                  >
                    {selectedDeal ? 'Update Deal' : 'Create Deal'}
                  </button>
                </div>
              </form>

              {/* Activity Log Section */}
              {selectedDeal && (
                <div className="mt-8 pt-6 border-t border-slate-200 dark:border-slate-800">
                   {/* Quick Actions for Logging */}
                  <div className="flex gap-2 mb-6">
                    <button 
                      onClick={() => handleLogActivity('email_sent', 'Sent follow-up email')}
                      className="flex-1 flex items-center justify-center px-3 py-2 text-xs font-medium bg-indigo-50 text-indigo-700 dark:bg-indigo-500/10 dark:text-indigo-400 border border-indigo-200 dark:border-indigo-500/20 rounded-lg hover:bg-indigo-100 dark:hover:bg-indigo-500/20 transition-colors"
                    >
                      <IconMail className="w-3 h-3 mr-1.5" /> Email Sent
                    </button>
                    <button 
                      onClick={() => handleLogActivity('meeting_scheduled', 'Scheduled a meeting')}
                      className="flex-1 flex items-center justify-center px-3 py-2 text-xs font-medium bg-pink-50 text-pink-700 dark:bg-pink-500/10 dark:text-pink-400 border border-pink-200 dark:border-pink-500/20 rounded-lg hover:bg-pink-100 dark:hover:bg-pink-500/20 transition-colors"
                    >
                      <IconCalendar className="w-3 h-3 mr-1.5" /> Meeting
                    </button>
                    <button 
                      onClick={() => handleLogActivity('follow_up', 'Completed follow-up task')}
                      className="flex-1 flex items-center justify-center px-3 py-2 text-xs font-medium bg-cyan-50 text-cyan-700 dark:bg-cyan-500/10 dark:text-cyan-400 border border-cyan-200 dark:border-cyan-500/20 rounded-lg hover:bg-cyan-100 dark:hover:bg-cyan-500/20 transition-colors"
                    >
                      <IconCheckCircle className="w-3 h-3 mr-1.5" /> Follow Up
                    </button>
                  </div>

                  <div className="flex items-center mb-4">
                    <IconHistory className="w-5 h-5 text-slate-400 mr-2" />
                    <h3 className="text-sm font-bold text-slate-900 dark:text-white uppercase tracking-wider">Activity Log</h3>
                  </div>

                  <div className="space-y-4 max-h-48 overflow-y-auto pr-2">
                    {selectedDeal.activities && selectedDeal.activities.length > 0 ? (
                      [...selectedDeal.activities].reverse().map((activity) => (
                        <div key={activity.id} className="flex gap-3 text-sm group">
                           <div className="flex flex-col items-center">
                              <div className={`w-2 h-2 rounded-full mt-2 ${
                                activity.type === 'created' ? 'bg-emerald-400' :
                                activity.type === 'stage_change' ? 'bg-blue-400' :
                                activity.type === 'email_sent' ? 'bg-indigo-400' :
                                activity.type === 'meeting_scheduled' ? 'bg-pink-400' :
                                activity.type === 'follow_up' ? 'bg-cyan-400' :
                                'bg-slate-300 dark:bg-slate-600'
                              }`}></div>
                              <div className="w-px h-full bg-slate-200 dark:bg-slate-800 my-1 last:hidden group-last:hidden"></div>
                           </div>
                           <div className="pb-4 w-full">
                             <div className="flex justify-between items-start">
                                <span className={`text-[10px] px-2 py-0.5 rounded-full border font-semibold uppercase tracking-wide mb-1 ${getActivityTypeStyle(activity.type)}`}>
                                 {formatActivityType(activity.type)}
                                </span>
                                <div className="flex items-center text-xs text-slate-400 whitespace-nowrap ml-2">
                                  <IconClock className="w-3 h-3 mr-1" />
                                  {new Date(activity.timestamp).toLocaleString()}
                                </div>
                             </div>
                             <p className="text-slate-700 dark:text-slate-300 mt-1">{activity.description}</p>
                           </div>
                        </div>
                      ))
                    ) : (
                      <p className="text-sm text-slate-500 italic">No activity recorded yet.</p>
                    )}
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Pipeline;

import React, { useState, useMemo } from 'react';
import { Task } from '../types';
import { IconCheckSquare, IconFilter, IconArrowUp, IconArrowDown } from './Icons';

interface TasksProps {
  tasks: Task[];
}

type SortKey = 'title' | 'dueDate' | 'priority';
type SortDirection = 'asc' | 'desc';

const Tasks: React.FC<TasksProps> = ({ tasks }) => {
  const [priorityFilter, setPriorityFilter] = useState('All');
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: SortDirection } | null>(null);

  const filteredAndSortedTasks = useMemo(() => {
    let filteredTasks = [...tasks]; // Create a mutable copy
    if (priorityFilter !== 'All') {
      filteredTasks = tasks.filter(task => task.priority === priorityFilter);
    }

    if (sortConfig !== null) {
      filteredTasks.sort((a, b) => {
        if (a[sortConfig.key] < b[sortConfig.key]) {
          return sortConfig.direction === 'asc' ? -1 : 1;
        }
        if (a[sortConfig.key] > b[sortConfig.key]) {
          return sortConfig.direction === 'asc' ? 1 : -1;
        }
        return 0;
      });
    }
    return filteredTasks;
  }, [tasks, priorityFilter, sortConfig]);

  const requestSort = (key: SortKey) => {
    let direction: SortDirection = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    } else if (sortConfig && sortConfig.key === key && sortConfig.direction === 'desc') {
        setSortConfig(null);
        return;
    }
    setSortConfig({ key, direction });
  };

  const getSortIcon = (key: SortKey) => {
    if (!sortConfig || sortConfig.key !== key) {
        return <span className="w-4 h-4 opacity-0 group-hover:opacity-50 transition-opacity">⇅</span>;
    }
    if (sortConfig.direction === 'asc') {
        return <IconArrowUp className="w-4 h-4 text-primary-500" />;
    }
    return <IconArrowDown className="w-4 h-4 text-primary-500" />;
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Tasks</h1>
        <button className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-all">
          + New Task
        </button>
      </div>

      <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm dark:shadow-none overflow-hidden">
        <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between">
           <div className="flex items-center space-x-2">
             <IconFilter className="w-4 h-4 text-slate-400" />
             <select 
               value={priorityFilter}
               onChange={(e) => setPriorityFilter(e.target.value)}
               className="bg-transparent text-sm font-medium text-slate-700 dark:text-slate-300 focus:outline-none cursor-pointer"
             >
               <option value="All">All Priorities</option>
               <option value="High">High</option>
               <option value="Normal">Normal</option>
               <option value="Low">Low</option>
             </select>
           </div>
        </div>
        <table className="w-full text-left text-sm">
          <thead>
            <tr className="bg-slate-50 dark:bg-slate-950/50 text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-800">
              <th className="px-6 py-4 text-sm font-medium">
                 <button onClick={() => requestSort('title')} className="flex items-center gap-2 group">
                    Subject {getSortIcon('title')}
                 </button>
              </th>
              <th className="px-6 py-4 text-sm font-medium">
                 <button onClick={() => requestSort('dueDate')} className="flex items-center gap-2 group">
                   Due Date {getSortIcon('dueDate')}
                 </button>
              </th>
              <th className="px-6 py-4 text-sm font-medium">Status</th>
              <th className="px-6 py-4 text-sm font-medium">
                 <button onClick={() => requestSort('priority')} className="flex items-center gap-2 group">
                   Priority {getSortIcon('priority')}
                 </button>
              </th>
              <th className="px-6 py-4 text-sm font-medium">Related To</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
            {filteredAndSortedTasks.map((task) => (
              <tr key={task.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                <td className="px-6 py-4 text-base font-medium text-slate-900 dark:text-white flex items-center">
                  <IconCheckSquare className="w-4 h-4 mr-2 text-slate-400" />
                  {task.title}
                </td>
                <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300">{task.dueDate}</td>
                <td className="px-6 py-4">
                  <span className={`px-2 py-1 text-sm font-medium rounded-full ${
                    task.status === 'Completed' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-500/10 dark:text-emerald-400' :
                    task.status === 'In Progress' ? 'bg-blue-100 text-blue-700 dark:bg-blue-500/10 dark:text-blue-400' :
                    task.status === 'Deferred' ? 'bg-red-100 text-red-700 dark:bg-red-500/10 dark:text-red-400' :
                    'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400'
                  }`}>
                    {task.status}
                  </span>
                </td>
                <td className="px-6 py-4">
                   <span className={`px-2 py-1 text-sm font-medium rounded-full ${
                    task.priority === 'High' ? 'bg-orange-100 text-orange-700 dark:bg-orange-500/10 dark:text-orange-400' :
                    task.priority === 'Low' ? 'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400' :
                    'bg-yellow-100 text-yellow-700 dark:bg-yellow-500/10 dark:text-yellow-400'
                   }`}>
                     {task.priority}
                   </span>
                </td>
                <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300">{task.relatedTo}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default Tasks;

