                                                        <span className="text-base font-semibold text-slate-700 dark:text-slate-200">{field.label}</span>
                                                    </div>
                                                    <button className="text-slate-300 group-hover:text-slate-500 dark:text-slate-600 dark:group-hover:text-slate-400 transition-colors">
                                                        <IconSettings className="w-5 h-5" />
                                                    </button>
                                                </div>

                                                <div className="flex items-center justify-between pointer-events-none">
                                                    {field.isComposite ? (
                                                        <div className="flex gap-3 w-full items-center bg-slate-50 dark:bg-slate-900/50 p-2 rounded-lg border border-slate-100 dark:border-slate-700/50">
                                                            <div className="w-1/3 border-r border-slate-200 dark:border-slate-700 pr-3 text-right">
                                                                <span className="text-xs font-medium text-slate-400 uppercase tracking-wide">Salutation</span>
                                                            </div>
                                                            <div className="flex-1 pl-1">
                                                                <span className="text-base text-blue-600 dark:text-blue-400 font-medium">{field.value}</span>
                                                            </div>
                                                        </div>
                                                    ) : (
                                                        <div className="w-full bg-slate-50 dark:bg-slate-900/50 p-2.5 rounded-lg border border-slate-100 dark:border-slate-700/50 flex items-center justify-between">
                                                            <span className={`text-base font-medium ${field.value ? 'text-blue-600 dark:text-blue-400' : 'text-slate-400 italic'}`}>
                                                                {field.value || `Enter ${field.label}...`}
                                                            </span>
                                                            {field.isLocked && <span className="text-xs text-slate-400 bg-slate-200 dark:bg-slate-700 px-1.5 py-0.5 rounded">Locked</span>}
                                                        </div>
                                                    )}
                                                </div>

                                                {/* Context Menu */}
                                                {activeFieldId === field.id && (
                                                    <div className="absolute top-full right-0 mt-2 w-56 bg-white dark:bg-slate-800 rounded-xl shadow-2xl border border-slate-200 dark:border-slate-700 z-50 overflow-hidden animate-fade-in-down cursor-default ring-1 ring-black/5">
                                                        <div className="p-1.5">
                                                            <button 
                                                                onClick={(e) => { e.stopPropagation(); handleToggleRequired(field.id); }}
                                                                className="w-full text-left px-4 py-2.5 text-sm font-medium text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700 flex items-center rounded-lg transition-colors"
                                                            >
                                                                <IconCheckSquare className={`w-4 h-4 mr-3 ${field.required ? 'text-primary-600' : 'text-slate-400'}`} />
                                                                {field.required ? 'Unmark Required' : 'Mark as Required'}
                                                            </button>
                                                            {!field.isLocked && (
                                                                <>
                                                                    <div className="border-t border-slate-100 dark:border-slate-700 my-1.5"></div>
                                                                    <button 
                                                                        onClick={(e) => { e.stopPropagation(); handleRemoveField(field.id); }}
                                                                        className="w-full text-left px-4 py-2.5 text-sm font-medium text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 flex items-center rounded-lg transition-colors"
                                                                    >
                                                                        <IconTrash className="w-4 h-4 mr-3" />
                                                                        Remove Field
                                                                    </button>
                                                                </>
                                                            )}
                                                        </div>
                                                    </div>
                                                )}
                                             </div>
                                         </div>
                                     ))}
                                 </div>
                             </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

