const StatCard: React.FC<StatCardProps> = ({ title, value, icon: Icon, trend, progress, goalText, color = "primary" }) => {
  const styles = {
      primary: {
          bg: "bg-white dark:bg-slate-800",
          iconBg: "bg-primary-50 text-primary-600 dark:bg-primary-500/20 dark:text-primary-400",
          border: "border-primary-100 dark:border-primary-500/20",
          gradient: "from-primary-500/10",
