  const style = styles[color as keyof typeof styles] || styles.primary;

  return (
    <div className={`group relative p-6 rounded-2xl border ${style.border} bg-white dark:bg-slate-900 shadow-sm hover:shadow-lg transition-all duration-300 overflow-hidden`}>
