                                    <option value="DD/MM/YYYY">DD/MM/YYYY (Day-Month-Year)</option>
                                    <option value="YYYY-MM-DD">YYYY-MM-DD (ISO Format)</option>
                                </select>
                            </div>

                            <div>
                                <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-3">Live Preview</label>
                                <div className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-primary-600 dark:text-primary-400 font-bold text-right shadow-sm">
                                    28/12/2025
                                </div>
                            </div>

                            <div>
                                <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-3">First Day of Week</label>
                                <div className="bg-white dark:bg-slate-800 p-1 rounded-xl border border-slate-200 dark:border-slate-700 flex">
                                    {['Sunday', 'Monday'].map(day => (
                                        <button
                                            key={day}
                                            onClick={() => setWeekStart(day)}
