                                        >
                                            {day}
                                        </button>
                                    ))}
                                </div>
                            </div>
                        </div>

                        {/* Right Column */}
                        <div className="space-y-8">
                            <div>
                                <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-3">Designated Working Days</label>
                                <div className="flex justify-between gap-2">
                                    {['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'].map((day) => {
                                        const fullDay = { 'SUN': 'Sun', 'MON': 'Mon', 'TUE': 'Tue', 'WED': 'Wed', 'THU': 'Thu', 'FRI': 'Fri', 'SAT': 'Sat' }[day] || '';
                                        const isSelected = workingDays.includes(fullDay);
                                        return (
                                            <button
                                                key={day}
                                                onClick={() => toggleWorkingDay(fullDay)}
                                                className={`w-10 h-10 md:w-12 md:h-12 flex items-center justify-center rounded-xl text-[10px] md:text-xs font-bold transition-all ${isSelected ? 'bg-primary-600 text-white shadow-lg shadow-primary-500/30 transform -translate-y-1' : 'bg-white dark:bg-slate-800 text-slate-400 border border-slate-200 dark:border-slate-700 hover:border-primary-300'}`}
                                            >
                                                {day}
                                            </button>
                                        );
                                    })}
                                </div>
                                <p className="text-[10px] text-slate-400 italic mt-3 uppercase tracking-wide">* Used for calculating attendance anomalies and overtime.</p>
                            </div>

                            <div className="pt-4 border-t border-slate-200 dark:border-slate-800">
                                <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-3">Fiscal Year Commencement</label>
                                <select 
                                    value={fiscalYearStart}
                                    onChange={(e) => setFiscalYearStart(e.target.value)}
                                    className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-primary-500 focus:outline-none text-slate-900 dark:text-white font-medium cursor-pointer shadow-sm"
                                >
                                    {['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'].map(month => (
                                        <option key={month} value={month}>{month}</option>
                                    ))}
                                </select>
                                <p className="text-xs text-slate-400 mt-2">Defines the baseline for annual performance cycles and budget resets.</p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        );

      case 'ai':
        return (
          <div className="space-y-8 animate-fade-in">
            <div>
              <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-1 uppercase tracking-wider">AI Intelligence Suite</h3>
              <p className="text-sm text-slate-500 dark:text-slate-400">Configure how Nova AI interacts with your pipeline and data.</p>
            </div>

            <div className="bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm overflow-hidden">
                <div className="p-6 border-b border-slate-100 dark:border-slate-700 bg-gradient-to-r from-primary-50/50 to-blue-50/50 dark:from-primary-900/10 dark:to-blue-900/10">
