                        <div className="p-3 bg-white dark:bg-slate-800 rounded-xl shadow-sm">
                            <IconBot className="w-6 h-6 text-primary-600 dark:text-primary-400" />
                        </div>
                        <div>
                            <h4 className="font-bold text-slate-900 dark:text-white">Generative Features</h4>
                            <p className="text-xs text-slate-500 dark:text-slate-400">Powered by Gemini 2.5 Flash</p>
                        </div>
                    </div>
                </div>
                <div className="p-6 space-y-2">
                    <Toggle 
                        label="Predictive Lead Scoring" 
                        description="Automatically score leads based on historical conversion data and firmographics."
                        checked={aiScoring}
                        onChange={setAiScoring}
                    />
                    <Toggle 
                        label="Automated Email Drafting" 
                        description="Allow AI to pre-draft emails for new leads based on context."
                        checked={autoDraft}
                        onChange={setAutoDraft}
                    />
                    <Toggle 
                        label="Pipeline Health Analysis" 
                        description="Periodic AI reviews of your deal stages to identify stalled opportunities."
                        checked={predictivePipeline}
                        onChange={setPredictivePipeline}
                    />
                </div>
            </div>

            <div className="p-6 bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm">
