                    <h4 className="font-bold text-slate-900 dark:text-white">AI Creativity Level</h4>
                    <span className="text-xs font-medium px-2 py-1 bg-primary-100 text-primary-700 dark:bg-primary-900/30 dark:text-primary-300 rounded-md">
                        {creativityLevel < 0.4 ? 'Conservative' : creativityLevel > 0.7 ? 'Creative' : 'Balanced'}
                    </span>
                </div>
                <input 
                    type="range" 
                    min="0" 
                    max="1" 
                    step="0.1" 
                    value={creativityLevel} 
                    onChange={(e) => setCreativityLevel(parseFloat(e.target.value))}
                    className="w-full h-2 bg-slate-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-primary-600"
