                        <div className="flex items-center gap-3">
                            <div className={`p-2 rounded-lg ${isApiKeySet ? 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400' : 'bg-slate-200 text-slate-500 dark:bg-slate-800 dark:text-slate-400'}`}>
                                <IconZap className="w-5 h-5" />
                            </div>
                            <div className="flex-1">
                                <p className="text-sm font-medium text-slate-900 dark:text-white">Google Gemini API</p>
                                <p className="text-xs text-slate-500 dark:text-slate-400">{isApiKeySet ? 'Your application is authenticated and ready to generate content.' : 'Authentication required for AI features.'}</p>
