                            <button 
                                onClick={handleConfigureApiKey}
                                className="px-4 py-2 bg-primary-600 hover:bg-primary-500 text-white text-sm font-medium rounded-lg transition-colors shadow-sm"
                            >
                                {isApiKeySet ? 'Change Key' : 'Connect'}
                            </button>
                        </div>
                    </div>

                    <div className="text-xs text-slate-500 dark:text-slate-400">
                        <p>A paid Google Cloud Project is required for advanced features like Video Generation (Veo).</p>
                        <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noopener noreferrer" className="text-primary-600 hover:text-primary-500 hover:underline mt-1 inline-block">
                            View Billing Documentation &rarr;
                        </a>
                    </div>
                </div>
            </div>
        );

      default:
        return <div className="text-slate-500">Select a category</div>;
    }
  };

  const navItemClass = (id: string) => `
    w-full flex items-center px-4 py-3 text-sm font-medium rounded-lg transition-all duration-200 
    ${activeTab === id 
        ? 'bg-primary-50 text-primary-700 dark:bg-primary-900/20 dark:text-primary-400 shadow-sm' 
        : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800 hover:text-slate-900 dark:hover:text-slate-200'}
  `;

  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-[#0f172a] overflow-hidden">
        {/* Header */}
        <div className="px-8 py-6 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center sticky top-0 z-10">
            <div>
                <h1 className="text-2xl font-bold text-slate-900 dark:text-white tracking-tight">Command Center</h1>
                <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">Configure core logic, branding, and regulatory compliance.</p>
            </div>
            <button 
                onClick={handleSave}
                className={`flex items-center gap-2 px-6 py-2.5 font-bold text-sm rounded-lg shadow-lg transition-all active:translate-y-0 hover:-translate-y-0.5 ${isSaved ? 'bg-emerald-500 text-white shadow-emerald-500/30' : 'bg-primary-600 hover:bg-primary-500 text-white shadow-primary-500/30'}`}
            >
                {isSaved ? <IconCheckCircle className="w-4 h-4" /> : <IconSave className="w-4 h-4" />}
                {isSaved ? 'SETTINGS SAVED' : 'UPDATE GLOBAL SETTINGS'}
            </button>
        </div>

        <div className="flex flex-1 overflow-hidden p-8 max-w-7xl mx-auto w-full gap-8">
            {/* Sidebar Navigation */}
            <div className="w-64 flex-shrink-0">
                <nav className="space-y-1">
                    <button onClick={() => setActiveTab('company')} className={navItemClass('company')}>
                        <IconBuilding className="w-5 h-5 mr-3 opacity-70" />
                        Company Profile
                    </button>
                    <button onClick={() => setActiveTab('theme')} className={navItemClass('theme')}>
                        <IconGlobe className="w-5 h-5 mr-3 opacity-70" />
                        Theme & Brand
                    </button>
                    <button onClick={() => setActiveTab('regional')} className={navItemClass('regional')}>
                        <IconGlobe className="w-5 h-5 mr-3 opacity-70" />
                        Regional & Date
                    </button>
                    <button onClick={() => setActiveTab('ai')} className={navItemClass('ai')}>
                        <IconSparkles className="w-5 h-5 mr-3 opacity-70" />
                        AI & Automation
                    </button>
                    <button onClick={() => setActiveTab('notifications')} className={navItemClass('notifications')}>
                        <IconBell className="w-5 h-5 mr-3 opacity-70" />
                        Alerts & Email
                    </button>
                    <button onClick={() => setActiveTab('security')} className={navItemClass('security')}>
                        <IconShield className="w-5 h-5 mr-3 opacity-70" />
                        Security & Access
                    </button>
                </nav>
            </div>

            {/* Content Area */}
            <div className="flex-1 bg-transparent overflow-y-auto custom-scrollbar">
                {renderContent()}
            </div>
        </div>
    </div>
  );
};

