const SidebarItem = ({ label, type }: { label: string, type: string }) => {
    const handleDragStart = (e: React.DragEvent) => {
        const fieldKey = `custom_${type.toLowerCase().replace(/[^a-z0-9]/g, '_')}_${Date.now()}`;
        const newFieldData: LayoutField = {
            id: `new_template_${Date.now()}`, 
            label: label,
            type: type,
            key: fieldKey,
            required: false,
            isLocked: false,
            value: `[${label}]`
        };
        e.dataTransfer.setData('application/new-field', JSON.stringify(newFieldData));
        e.dataTransfer.effectAllowed = 'copy';
    };

    return (
        <div 
            draggable 
            onDragStart={handleDragStart}
            className="flex items-center px-4 py-3 bg-[#1e2330] border border-[#2d3342] rounded-lg mb-2.5 cursor-grab hover:bg-[#252b3b] hover:border-[#6366f1]/50 transition-all duration-200 active:cursor-grabbing group select-none"
        >
            <div className="mr-3 text-slate-500 group-hover:text-slate-300">
                <IconGripVertical className="w-5 h-5" />
            </div>
            <span className="text-sm font-medium text-slate-300 group-hover:text-white">{label}</span>
        </div>
    );
};

