const Contacts: React.FC<ContactsProps> = ({ contacts, accounts = [], onAddContact, onUpdateContact }) => {
  const [viewMode, setViewMode] = useState<'list' | 'kanban'>('list');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [layoutFields, setLayoutFields] = useState<LayoutField[]>(DEFAULT_LAYOUT);
  const [formData, setFormData] = useState<Partial<Contact>>({});
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isLayoutEditorOpen, setIsLayoutEditorOpen] = useState(false);

  // Drag and Drop State
  const [draggedContactId, setDraggedContactId] = useState<string | null>(null);
  const [dragOverColumn, setDragOverColumn] = useState<ContactStatus | null>(null);

  // If layout editor mode is active, show the editor instead of the list
  if (isLayoutEditorOpen) {
    return <ContactLayoutEditor 
      currentLayout={layoutFields}
      onSave={(newLayout) => {
        setLayoutFields(newLayout);
        setIsLayoutEditorOpen(false);
      }}
      onBack={() => setIsLayoutEditorOpen(false)} 
    />;
  }

  const handleOpenModal = () => {
    setFormData({ status: 'New', leadSource: 'Web Search' }); // Default Values
    setEditingId(null);
    setIsModalOpen(true);
  };

  const handleEditClick = (contact: Contact) => {
    setFormData({ ...contact });
    setEditingId(contact.id);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setEditingId(null);
  };

  const handleEditPageLayout = (e: React.MouseEvent) => {
      e.preventDefault();
      setIsModalOpen(false);
      setIsLayoutEditorOpen(true);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const checked = (e.target as HTMLInputElement).checked;

    setFormData(prev => ({ 
      ...prev, 
      [name]: type === 'checkbox' ? checked : value 
    }));
  };

  const saveContact = () => {
    // Dynamic Validation based on Layout
    const missingFields = layoutFields.filter(field => 
        field.required && 
        field.type !== 'section' && // Ignore sections for validation
        !formData[field.key as keyof Contact] && 
        field.key !== 'owner'
    );

    if (missingFields.length > 0) {
      alert(`Please fill in the required fields: ${missingFields.map(f => f.label).join(', ')}`);
      return false;
    }

    // Name Construction logic
    let fullName = formData.name;
    if (!fullName) {
        const firstName = formData.firstName || '';
        const lastName = formData.lastName || '';
        fullName = `${firstName} ${lastName}`.trim();
        if (!fullName && formData.company) fullName = formData.company; // Fallback
    }

    const contactData = {
      ...formData,
      name: fullName || 'Unknown',
      status: formData.status || 'New',
    } as Contact;

    if (editingId) {
      const originalContact = contacts.find(c => c.id === editingId);
      if (originalContact) {
        onUpdateContact({
          ...originalContact,
          ...contactData
        });
      }
    } else {
      onAddContact(contactData);
    }
    return true;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (saveContact()) {
      handleCloseModal();
    }
  };

  const handleSaveAndNew = (e: React.MouseEvent) => {
    e.preventDefault();
    if (saveContact()) {
      setFormData({ status: 'New' });
      setEditingId(null);
    }
  };

  // Drag and Drop Handlers (Kanban)
  const handleDragStart = (e: React.DragEvent, id: string) => {
    setDraggedContactId(id);
    e.dataTransfer.setData('contactId', id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragEnd = () => {
    setDraggedContactId(null);
    setDragOverColumn(null);
  };

  const handleDragOver = (e: React.DragEvent, status: ContactStatus) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    if (dragOverColumn !== status) {
        setDragOverColumn(status);
    }
  };

  const handleDrop = (e: React.DragEvent, status: ContactStatus) => {
    e.preventDefault();
    setDragOverColumn(null);
    const id = e.dataTransfer.getData('contactId');
    const contact = contacts.find(c => c.id === id);

    if (contact && contact.status !== status) {
      onUpdateContact({ ...contact, status });
    }
    setDraggedContactId(null);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Active': return 'bg-emerald-100 text-emerald-800 border-emerald-200 dark:bg-emerald-900/30 dark:text-emerald-300 dark:border-emerald-700/50';
      case 'Inactive': return 'bg-slate-100 text-slate-800 border-slate-200 dark:bg-slate-800/50 dark:text-slate-400 dark:border-slate-700';
      default: return 'bg-blue-100 text-blue-800 border-blue-200 dark:bg-blue-900/30 dark:text-blue-300 dark:border-blue-700/50';
    }
  };

  const renderField = (field: LayoutField) => {
      const isRequired = field.required;
      const commonClasses = `w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800/50 border ${isRequired && !formData[field.key as keyof Contact] ? 'border-red-300 dark:border-red-800' : 'border-slate-200 dark:border-slate-700'} rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500/50 text-slate-900 dark:text-white transition-all`;

      if (field.key === 'owner') {
          return (
            <div className="relative group">
                <input type="text" value="Bayas Ahamed" readOnly className={`${commonClasses} cursor-default`} />
                <IconUser className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 group-hover:text-primary-500 transition-colors" />
            </div>
          );
      }

      if (field.isComposite && field.key === 'firstName') {
          return (
            <div className="flex gap-2">
                <select className="w-24 px-2 py-2.5 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500/50 text-slate-900 dark:text-white text-sm">
                    <option>Mr.</option>
                    <option>Ms.</option>
                    <option>Dr.</option>
                </select>
                <input 
                    type="text" 
                    name={field.key} 
                    value={formData[field.key as keyof Contact] || ''} 
                    onChange={handleInputChange} 
                    className={commonClasses} 
                />
            </div>
          );
      }

      switch (field.type) {
          case 'select':
              let options = (
                 <>
                    <option value="">-None-</option>
                    <option value="Option 1">Option 1</option>
                    <option value="Option 2">Option 2</option>
                 </>
              );

              if (field.key === 'status') {
                  options = <>{CONTACT_STATUSES.map(s => <option key={s} value={s}>{s}</option>)}</>;
              } else if (field.key === 'leadSource') {
                  options = (
                    <>
                        <option value="">-None-</option>
                        {LEAD_SOURCES.map(s => <option key={s} value={s}>{s}</option>)}
                    </>
                  );
              }

              return (
                  <select name={field.key} value={formData[field.key as keyof Contact] || ''} onChange={handleInputChange} className={commonClasses}>
                      {options}
                  </select>
              );
          case 'checkbox':
              return (
                  <div className="flex items-center h-full">
                      <input type="checkbox" name={field.key} checked={!!formData[field.key as keyof Contact]} onChange={handleInputChange} className="w-5 h-5 text-primary-600 bg-slate-100 border-slate-300 rounded focus:ring-primary-500 dark:focus:ring-primary-600 dark:ring-offset-slate-800 focus:ring-2 dark:bg-slate-700 dark:border-slate-600 cursor-pointer" />
                  </div>
              );
          default:
              return (
                  <div className="relative group">
                    <input 
                        type={field.type} 
                        name={field.key} 
                        value={formData[field.key as keyof Contact] || ''} 
                        onChange={handleInputChange} 
                        className={commonClasses} 
                        list={field.key === 'company' && accounts.length > 0 ? "account-options" : undefined}
                        autoComplete={field.key === 'company' ? "off" : "on"}
                    />
                    {field.key === 'company' && accounts.length > 0 && (
                        <datalist id="account-options">
                            {accounts.map(account => (
                                <option key={account.id} value={account.name} />
                            ))}
                        </datalist>
                    )}
                    {field.key === 'company' && <IconBuilding className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 group-hover:text-primary-500 transition-colors" />}
                  </div>
              );
      }
  };

  return (
    <>
      <div className="space-y-8 h-full flex flex-col animate-fade-in">
        {/* Header and Kanban/List Toggle */}
        <div className="flex justify-between items-center flex-shrink-0">
          <div className="flex items-center gap-4">
             <h1 className="text-3xl font-bold text-slate-900 dark:text-white">Contacts</h1>
             <div className="flex bg-slate-100 dark:bg-slate-800/50 p-1 rounded-xl border border-slate-200 dark:border-slate-700/50">
                <button onClick={() => setViewMode('list')} className={`p-2 rounded-lg transition-all duration-200 ${viewMode === 'list' ? 'bg-white dark:bg-slate-700 shadow-sm text-primary-600 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200'}`}><IconList className="w-4 h-4" /></button>
                <button onClick={() => setViewMode('kanban')} className={`p-2 rounded-lg transition-all duration-200 ${viewMode === 'kanban' ? 'bg-white dark:bg-slate-700 shadow-sm text-primary-600 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200'}`}><IconKanban className="w-4 h-4" /></button>
             </div>
          </div>
          <button onClick={handleOpenModal} className="px-5 py-2.5 text-sm font-medium text-white bg-primary-600 rounded-xl hover:bg-primary-500 shadow-lg shadow-primary-500/25 hover:shadow-primary-500/40 hover:-translate-y-0.5 transition-all duration-200">+ New Contact</button>
        </div>

        {/* Views Render (List or Kanban) */}
        {viewMode === 'list' ? (
          <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-sm dark:shadow-none overflow-hidden flex flex-col h-full">
            <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between bg-slate-50/50 dark:bg-slate-900/50">
              <div className="flex items-center space-x-2 bg-white dark:bg-slate-800 px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-700">
                  <IconFilter className="w-4 h-4 text-slate-400" />
                  <select className="bg-transparent text-sm font-medium text-slate-700 dark:text-slate-300 focus:outline-none cursor-pointer"><option>All Contacts</option></select>
              </div>
            </div>
            <div className="overflow-auto flex-1 custom-scrollbar">
                <table className="w-full text-left text-sm">
                <thead className="sticky top-0 z-20 bg-slate-50/90 dark:bg-slate-900/90 backdrop-blur-sm border-b border-slate-200 dark:border-slate-800">
                    <tr>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Name</th>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Title</th>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Account Name</th>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Email</th>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Phone</th>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Status</th>
                    <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Last Activity</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 dark:divide-slate-800/50">
                    {contacts.map((contact) => (
                    <tr key={contact.id} onClick={() => handleEditClick(contact)} className="hover:bg-slate-50/80 dark:hover:bg-slate-800/40 transition-colors cursor-pointer group">
                        <td className="px-6 py-4 text-base font-medium text-slate-900 dark:text-white flex items-center">
                            <div className="w-9 h-9 rounded-full bg-gradient-to-br from-primary-100 to-blue-100 dark:from-slate-700 dark:to-slate-600 flex items-center justify-center mr-3 text-sm font-bold text-slate-700 dark:text-slate-200 shadow-sm border border-white dark:border-slate-600">
                                {contact.name.charAt(0)}
                            </div>
                            <span className="group-hover:text-primary-600 dark:group-hover:text-primary-400 transition-colors">{contact.name}</span>
                        </td>
                        <td className="px-6 py-4 text-slate-600 dark:text-slate-400">{contact.title}</td>
                        <td className="px-6 py-4 text-slate-600 dark:text-slate-400">{contact.company}</td>
                        <td className="px-6 py-4 text-slate-600 dark:text-slate-400"><div className="flex items-center gap-2 group-hover:text-slate-900 dark:group-hover:text-slate-200 transition-colors"><IconMail className="w-3.5 h-3.5 opacity-50" />{contact.email}</div></td>
                        <td className="px-6 py-4 text-slate-600 dark:text-slate-400"><div className="flex items-center gap-2 group-hover:text-slate-900 dark:group-hover:text-slate-200 transition-colors"><IconPhone className="w-3.5 h-3.5 opacity-50" />{contact.phone}</div></td>
                        <td className="px-6 py-4"><span className={`px-2.5 py-1 text-xs font-semibold rounded-full border ${getStatusColor(contact.status || 'New')}`}>{contact.status || 'New'}</span></td>
                        <td className="px-6 py-4 text-slate-500 dark:text-slate-500">{contact.lastActivity}</td>
                    </tr>
                    ))}
                </tbody>
                </table>
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-x-auto overflow-y-hidden pb-4">
            <div className="flex h-full gap-6 min-w-full">
              {CONTACT_STATUSES.map(status => (
                <div 
                    key={status} 
                    onDragOver={(e) => handleDragOver(e, status)} 
                    onDrop={(e) => handleDrop(e, status)} 
                    className={`flex-1 min-w-[340px] flex flex-col border rounded-2xl h-full transition-all duration-300 ${
                        dragOverColumn === status 
                            ? 'bg-primary-50/50 dark:bg-primary-900/10 border-primary-300 dark:border-primary-500 shadow-inner' 
                            : 'bg-slate-100/50 dark:bg-slate-900/30 border-slate-200 dark:border-slate-800'
                    }`}
                >
                  <div className="p-4 border-b border-slate-200 dark:border-slate-800/50 flex justify-between items-center bg-white/40 dark:bg-slate-800/40 rounded-t-2xl backdrop-blur-md sticky top-0 z-10">
                    <h3 className="font-bold text-slate-700 dark:text-slate-200 flex items-center gap-2">
                        <span className={`w-3 h-3 rounded-full shadow-sm ${status === 'Active' ? 'bg-emerald-500' : status === 'Inactive' ? 'bg-slate-400' : 'bg-blue-500'}`}></span>
                        {status}
                    </h3>
                    <span className="bg-white dark:bg-slate-700 text-slate-600 dark:text-slate-300 text-xs font-bold px-2.5 py-1 rounded-full shadow-sm">{contacts.filter(c => (c.status || 'New') === status).length}</span>
                  </div>
                  <div className="p-4 space-y-3 overflow-y-auto flex-1 custom-scrollbar">
                     {contacts.filter(c => (c.status || 'New') === status).map(contact => (
                       <div 
                         key={contact.id} 
                         draggable 
                         onDragStart={(e) => handleDragStart(e, contact.id)} 
                         onDragEnd={handleDragEnd}
                         onClick={() => handleEditClick(contact)} 
                         className={`p-4 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl shadow-sm hover:shadow-lg hover:border-primary-300 dark:hover:border-primary-500/30 transition-all duration-200 cursor-move group select-none ${draggedContactId === contact.id ? 'opacity-40 scale-95' : 'hover:-translate-y-1'}`}
                       >
                         <div className="flex items-start justify-between mb-3">
                           <div className="flex items-center">
                                <div className="w-9 h-9 rounded-full bg-slate-50 dark:bg-slate-700 flex items-center justify-center text-xs font-bold text-slate-600 dark:text-slate-300 mr-3 border border-slate-100 dark:border-slate-600 shadow-sm">{contact.name.charAt(0)}</div>
                                <div>
                                    <h4 className="font-semibold text-slate-800 dark:text-slate-100 text-sm leading-tight group-hover:text-primary-600 dark:group-hover:text-primary-400 transition-colors">{contact.name}</h4>
                                    <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">{contact.title}</p>
                                </div>
                           </div>
                         </div>
                         <div className="pl-12 space-y-2">
                             <p className="text-sm text-slate-600 dark:text-slate-300 flex items-center">
                                 <IconBuilding className="w-3.5 h-3.5 mr-2 text-slate-400" />
                                 <span className="truncate">{contact.company}</span>
                             </p>
                             {(contact.email || contact.phone) && (
                                 <div className="flex items-center gap-3 pt-1">
                                    {contact.email && <div className="p-1.5 rounded-md bg-slate-50 dark:bg-slate-700/50 text-slate-500 dark:text-slate-400 hover:text-primary-600 dark:hover:text-primary-400 transition-colors"><IconMail className="w-3.5 h-3.5" /></div>}
                                    {contact.phone && <div className="p-1.5 rounded-md bg-slate-50 dark:bg-slate-700/50 text-slate-500 dark:text-slate-400 hover:text-primary-600 dark:hover:text-primary-400 transition-colors"><IconPhone className="w-3.5 h-3.5" /></div>}
                                 </div>
                             )}
                         </div>
                         <div className="flex justify-between items-center pt-3 mt-3 border-t border-slate-50 dark:border-slate-700/50 pl-12">
                             <span className="text-[10px] font-medium text-slate-400 uppercase tracking-wide">Last Activity</span>
                             <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">{contact.lastActivity}</span>
                         </div>
                       </div>
                     ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm transition-opacity duration-300">
          <div className="w-full max-w-5xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-scale-in">
            {/* Header */}
            <div className="p-5 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50/80 dark:bg-slate-950/80 backdrop-blur-md">
               <div className="flex items-center gap-3">
                  <h2 className="text-xl font-bold text-slate-900 dark:text-white">
                    {editingId ? 'Edit Contact' : 'Create Contact'}
                  </h2>
                  <button onClick={handleEditPageLayout} className="text-sm font-medium text-primary-600 hover:text-primary-700 dark:text-primary-400 hover:underline transition-colors">Edit Page Layout</button>
               </div>
               <div className="flex items-center gap-3">
                 <button onClick={handleCloseModal} className="px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">Cancel</button>
                 <button onClick={handleSaveAndNew} className="px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">Save and New</button>
                 <button onClick={handleSubmit} className="px-5 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-all">Save</button>
               </div>
            </div>

            {/* Dynamic Form Content */}
            <div className="overflow-y-auto p-8 bg-white dark:bg-slate-900 custom-scrollbar">
              <form onSubmit={handleSubmit}>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-8">
                    {layoutFields.map((field) => {
                        if (field.type === 'section') {
                            return (
                                <div key={field.id} className="col-span-1 md:col-span-2 mt-4 pt-4 border-t border-slate-100 dark:border-slate-800 first:mt-0 first:pt-0 first:border-0">
                                    <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-2">{field.label}</h3>
                                </div>
                            );
                        }
                        return (
                            <div key={field.id} className="grid grid-cols-1 md:grid-cols-3 gap-4 items-center group">
                                <label className={`text-sm font-medium text-slate-600 dark:text-slate-400 md:text-right transition-colors group-focus-within:text-primary-600 dark:group-focus-within:text-primary-400 ${field.required ? 'after:content-["*"] after:text-red-500 after:ml-1' : ''}`}>
                                    {field.label}
                                </label>
                                <div className="md:col-span-2">
                                    {renderField(field)}
                                </div>
                            </div>
                        );
                    })}
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default Contacts;

import React, { useState, useEffect } from 'react';
import { Account, Contact, Deal, Lead } from '../types';
import { 
  IconArrowLeft, 
  IconEdit, 
  IconTrash, 
  IconBuilding, 
  IconGlobe, 
  IconPhone, 
  IconUser, 
  IconUsers, 
  IconKanban,
  IconSparkles,
  IconMail,
  IconPlus,
  IconX,
  IconTarget
} from './Icons';
import { generateAccountInsights } from '../services/geminiService';

interface AccountDetailProps {
  account: Account;
  onBack: () => void;
  onEdit: () => void;
  onDelete: () => void;
  contacts: Contact[];
  deals: Deal[];
  leads: Lead[];
  onAddContact: (contact: Omit<Contact, 'id' | 'lastActivity'>) => void;
}

const DetailRow: React.FC<{ label: string; value?: string | number | null; icon?: React.ElementType; isLink?: boolean }> = ({ label, value, icon: Icon, isLink }) => {
  if (!value) return null;
  return (
    <div>
      <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">{label}</label>
      <p className="text-base font-medium text-slate-900 dark:text-slate-100 flex items-center mt-1">
        {Icon && <Icon className="w-4 h-4 mr-2 text-slate-400" />}
        {isLink ? (
            <a href={value.toString().startsWith('http') ? value.toString() : `https://${value}`} target="_blank" rel="noopener noreferrer" className="text-primary-600 hover:underline">
                {value}
            </a>
        ) : value}
      </p>
    </div>
  );
};

const AccountDetail: React.FC<AccountDetailProps> = ({ account, onBack, onEdit, onDelete, contacts, deals, leads, onAddContact }) => {
  const [insights, setInsights] = useState<string>('');
  const [isLoadingInsights, setIsLoadingInsights] = useState(false);

  // Contact Modal State
  const [isContactModalOpen, setIsContactModalOpen] = useState(false);
  const [newContact, setNewContact] = useState({ firstName: '', lastName: '', title: '', email: '', phone: '' });

  // Use case-insensitive matching for company name
  const relatedContacts = contacts.filter(c => c.company?.trim().toLowerCase() === account.name.trim().toLowerCase());
  const relatedDeals = deals.filter(d => d.company?.trim().toLowerCase() === account.name.trim().toLowerCase());
  const relatedLeads = leads.filter(l => l.company?.trim().toLowerCase() === account.name.trim().toLowerCase());

  const handleGenerateInsights = async () => {
    setIsLoadingInsights(true);
    const result = await generateAccountInsights(account);
    setInsights(result);
    setIsLoadingInsights(false);
  };

  const handleContactSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      onAddContact({
          name: `${newContact.firstName} ${newContact.lastName}`.trim(),
          firstName: newContact.firstName,
          lastName: newContact.lastName,
          title: newContact.title,
          email: newContact.email,
          phone: newContact.phone,
          company: account.name, // Auto-link to this account
          status: 'New'
      });
      setIsContactModalOpen(false);
      setNewContact({ firstName: '', lastName: '', title: '', email: '', phone: '' });
  };

  const handleContactChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      setNewContact({ ...newContact, [e.target.name]: e.target.value });
  };

  return (
    <div className="bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm h-full flex flex-col animate-fade-in">
      {/* Header */}
      <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-950/50 rounded-t-xl flex-shrink-0">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800 transition-colors group">
            <IconArrowLeft className="w-5 h-5 text-slate-600 dark:text-slate-300 group-hover:-translate-x-1 transition-transform" />
          </button>
          <div>
            <h1 className="text-2xl font-bold text-slate-900 dark:text-white flex items-center gap-2">
                <IconBuilding className="w-6 h-6 text-primary-600 dark:text-primary-400" />
                {account.name}
            </h1>
            <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">{account.industry}</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={onEdit} className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors shadow-sm">
            <IconEdit className="w-4 h-4" /> Edit
          </button>
          <button onClick={onDelete} className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-red-600 bg-red-50 dark:bg-red-500/10 border border-red-200 dark:border-red-500/20 rounded-lg hover:bg-red-100 dark:hover:bg-red-500/20 transition-colors shadow-sm">
            <IconTrash className="w-4 h-4" /> Delete
          </button>
        </div>
      </div>

      {/* Body */}
      <div className="flex-1 overflow-y-auto p-8 bg-slate-50/30 dark:bg-[#0b1120]/30 custom-scrollbar">
        <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">

          {/* Main Info Column */}
          <div className="xl:col-span-2 space-y-8">
            {/* Account Details Card */}
            <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm">
              <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-6 flex items-center">
                  <span className="w-1.5 h-1.5 bg-primary-500 rounded-full mr-2.5"></span>
                  Overview
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-y-6 gap-x-12">
                <DetailRow label="Account Owner" value={account.owner} icon={IconUser} />
                <DetailRow label="Phone" value={account.phone} icon={IconPhone} />
                <DetailRow label="Website" value={account.website} icon={IconGlobe} isLink />
                <DetailRow label="Industry" value={account.industry} />
              </div>
            </div>

            {/* Related Contacts */}
            <div className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden">
