                                                        {contact.name.charAt(0)}
                                                    </div>
                                                    <span className="font-semibold text-slate-900 dark:text-white">{contact.name}</span>
                                                </div>
                                            </td>
                                            <td className="px-6 py-4 text-slate-600 dark:text-slate-400">{contact.title}</td>
                                            <td className="px-6 py-4 text-slate-600 dark:text-slate-400">{contact.email}</td>
                                            <td className="px-6 py-4 text-slate-600 dark:text-slate-400">{contact.phone}</td>
