                                <IconUsers className="w-6 h-6 text-slate-400" />
                            </div>
                            <h3 className="text-slate-900 dark:text-white font-medium mb-1">No contacts yet</h3>
                            <p className="text-slate-500 dark:text-slate-400 text-sm mb-4">Add people associated with this account.</p>
                            <button 
                                onClick={() => setIsContactModalOpen(true)}
                                className="text-primary-600 dark:text-primary-400 font-bold text-sm hover:underline"
                            >
                                Add First Contact
                            </button>
                        </div>
                    )}
                </div>
            )}

            {activeTab === 'deals' && (
                <div className="space-y-4 animate-fade-in">
                    <div className="flex justify-between items-center mb-2">
                        <h3 className="text-lg font-bold text-slate-900 dark:text-white">Active Deals</h3>
                    </div>
                    {relatedDeals.length > 0 ? (
                        <div className="grid grid-cols-1 gap-4">
                            {relatedDeals.map(deal => (
                                <div key={deal.id} className="p-5 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm hover:border-primary-300 dark:hover:border-primary-700 transition-colors flex justify-between items-center group">
                                    <div>
                                        <h4 className="font-bold text-slate-900 dark:text-white mb-1 group-hover:text-primary-600 transition-colors">{deal.title}</h4>
                                        <div className="flex items-center gap-3 text-sm text-slate-500 dark:text-slate-400">
                                            <span className="bg-slate-100 dark:bg-slate-800 px-2 py-0.5 rounded text-xs font-medium">{deal.stage}</span>
                                            <span>•</span>
                                            <span>Close: {deal.closeDate}</span>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <p className="text-lg font-bold text-slate-900 dark:text-white">${deal.value.toLocaleString()}</p>
                                        <p className="text-sm text-slate-500 dark:text-slate-400">{deal.probability}% Prob.</p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="p-12 text-center bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 border-dashed">
                            <p className="text-slate-500 dark:text-slate-400">No active deals found.</p>
                        </div>
                    )}
                </div>
            )}

            {activeTab === 'leads' && (
                <div className="space-y-4 animate-fade-in">
                    <div className="flex justify-between items-center mb-2">
                        <h3 className="text-lg font-bold text-slate-900 dark:text-white">Associated Leads</h3>
                    </div>
                    {relatedLeads.length > 0 ? (
                        <div className="grid grid-cols-1 gap-4">
                            {relatedLeads.map(lead => (
                                <div key={lead.id} className="p-5 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm flex justify-between items-center">
                                    <div className="flex items-center gap-4">
                                        <div className="w-10 h-10 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-slate-500 font-bold border border-slate-200 dark:border-slate-700">
                                            {lead.name.charAt(0)}
                                        </div>
                                        <div>
                                            <h4 className="font-bold text-slate-900 dark:text-white">{lead.name}</h4>
                                            <p className="text-sm text-slate-500 dark:text-slate-400">{lead.title}</p>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <span className={`px-2.5 py-1 text-xs font-semibold rounded-full border ${
                                            lead.score > 70 ? 'bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-900/20 dark:text-emerald-400' : 'bg-slate-100 text-slate-600 border-slate-200 dark:bg-slate-800 dark:text-slate-400'
                                        }`}>
                                            Score: {lead.score}
                                        </span>
                                    </div>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="p-12 text-center bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 border-dashed">
                            <p className="text-slate-500 dark:text-slate-400">No leads found.</p>
                        </div>
                    )}
                </div>
            )}

          </div>

          {/* Right Sidebar - AI & Stats (Always Visible or contextual?) */}
          <div className="space-y-8">
             {/* AI Account Strategy */}
             <div className="bg-gradient-to-br from-indigo-50 to-purple-50 dark:from-slate-800 dark:to-slate-900 rounded-2xl border border-indigo-100 dark:border-slate-700 shadow-sm p-6">
                <div className="flex items-center justify-between mb-4">
                    <h3 className="text-lg font-bold text-indigo-900 dark:text-indigo-100 flex items-center">
                        <IconSparkles className="w-5 h-5 mr-2 text-indigo-600 dark:text-indigo-400" />
                        Nova AI Strategy
                    </h3>
                </div>

                {insights ? (
                    <div className="prose prose-sm dark:prose-invert max-w-none text-slate-700 dark:text-slate-300 leading-relaxed">
                        <div dangerouslySetInnerHTML={{ __html: insights.replace(/\n/g, '<br />') }} />
                    </div>
                ) : (
                    <div className="text-center py-6">
                        <p className="text-sm text-slate-600 dark:text-slate-400 mb-4">Generate AI-powered insights to grow this account.</p>
                        <button 
                            onClick={handleGenerateInsights}
                            disabled={isLoadingInsights}
                            className="w-full py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-semibold shadow-md shadow-indigo-500/20 transition-all disabled:opacity-70 disabled:cursor-not-allowed flex items-center justify-center"
                        >
                            {isLoadingInsights ? (
                                <span className="flex items-center"><span className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></span> Analyzing...</span>
                            ) : (
                                "Generate Strategy"
                            )}
                        </button>
                    </div>
                )}
             </div>

             {/* Simple Stats */}
             <div className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm p-6">
                 <h3 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-4">Pipeline Metrics</h3>
                 <div className="space-y-4">
                    <div>
                        <p className="text-sm text-slate-500 dark:text-slate-400 mb-1">Total Pipeline Value</p>
                        <div className="text-3xl font-bold text-slate-900 dark:text-white">
                            ${relatedDeals.reduce((acc, deal) => acc + deal.value, 0).toLocaleString()}
                        </div>
                    </div>
                    <div className="h-px bg-slate-100 dark:bg-slate-800"></div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <p className="text-xs text-slate-500 dark:text-slate-400 mb-1">Open Deals</p>
                            <p className="text-xl font-bold text-slate-900 dark:text-white">{relatedDeals.filter(d => !['Closed Won', 'Closed Lost'].includes(d.stage)).length}</p>
                        </div>
                        <div>
                            <p className="text-xs text-slate-500 dark:text-slate-400 mb-1">Contacts</p>
                            <p className="text-xl font-bold text-slate-900 dark:text-white">{relatedContacts.length}</p>
                        </div>
                    </div>
                 </div>
             </div>
          </div>

        </div>
      </div>

      {/* Add Contact Modal */}
      {isContactModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
            <div className="w-full max-w-lg bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden animate-scale-in">
                <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50">
                    <h2 className="text-xl font-bold text-slate-900 dark:text-white flex items-center gap-2">
                        <IconUser className="w-5 h-5 text-primary-500" />
                        Create Contact
                    </h2>
                    <button onClick={() => setIsContactModalOpen(false)} className="text-slate-400 hover:text-slate-600 dark:hover:text-white transition-colors"><IconX className="w-6 h-6" /></button>
                </div>
                <div className="p-6 bg-slate-50/50 dark:bg-[#0b1120]/50 border-b border-slate-200 dark:border-slate-800">
                    <p className="text-sm text-slate-600 dark:text-slate-400">
                        This contact will be automatically linked to <span className="font-bold text-slate-900 dark:text-white">{account.name}</span>.
                    </p>
                </div>
                <form onSubmit={handleContactSubmit} className="p-6 space-y-4">
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">First Name</label>
                            <input type="text" name="firstName" value={newContact.firstName} onChange={handleContactChange} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white" required />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Last Name</label>
                            <input type="text" name="lastName" value={newContact.lastName} onChange={handleContactChange} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white" required />
                        </div>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Title</label>
                        <input type="text" name="title" value={newContact.title} onChange={handleContactChange} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white" />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Email</label>
                        <input type="email" name="email" value={newContact.email} onChange={handleContactChange} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white" />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Phone</label>
                        <input type="tel" name="phone" value={newContact.phone} onChange={handleContactChange} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white" />
                    </div>
                    <div className="pt-4 flex justify-end gap-3">
                        <button type="button" onClick={() => setIsContactModalOpen(false)} className="px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 rounded-lg hover:bg-slate-200 transition-colors">Cancel</button>
                        <button type="submit" className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 transition-colors shadow-lg shadow-primary-500/20">Create Contact</button>
                    </div>
                </form>
            </div>
        </div>
      )}
    </div>
  );
};

