                                            lead.score > 70 ? 'bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-900/20 dark:text-emerald-400' : 'bg-slate-100 text-slate-600 border-slate-200 dark:bg-slate-800 dark:text-slate-400'
                                        }`}>
                                            Score: {lead.score}
                                        </span>
                                    </div>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="p-12 text-center bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 border-dashed">
                            <p className="text-slate-500 dark:text-slate-400">No leads found.</p>
                        </div>
                    )}
                </div>
            )}

          </div>

          {/* Right Sidebar - AI & Stats (Always Visible or contextual?) */}
          <div className="space-y-8">
             {/* AI Account Strategy */}
             <div className="bg-gradient-to-br from-indigo-50 to-purple-50 dark:from-slate-800 dark:to-slate-900 rounded-2xl border border-indigo-100 dark:border-slate-700 shadow-sm p-6">
                <div className="flex items-center justify-between mb-4">
                    <h3 className="text-lg font-bold text-indigo-900 dark:text-indigo-100 flex items-center">
                        <IconSparkles className="w-5 h-5 mr-2 text-indigo-600 dark:text-indigo-400" />
                        Nova AI Strategy
                    </h3>
                </div>

                {insights ? (
                    <div className="prose prose-sm dark:prose-invert max-w-none text-slate-700 dark:text-slate-300 leading-relaxed">
                        <div dangerouslySetInnerHTML={{ __html: insights.replace(/\n/g, '<br />') }} />
                    </div>
                ) : (
                    <div className="text-center py-6">
                        <p className="text-sm text-slate-600 dark:text-slate-400 mb-4">Generate AI-powered insights to grow this account.</p>
                        <button 
                            onClick={handleGenerateInsights}
                            disabled={isLoadingInsights}
                            className="w-full py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-semibold shadow-md shadow-indigo-500/20 transition-all disabled:opacity-70 disabled:cursor-not-allowed flex items-center justify-center"
                        >
                            {isLoadingInsights ? (
                                <span className="flex items-center"><span className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></span> Analyzing...</span>
                            ) : (
                                "Generate Strategy"
                            )}
                        </button>
                    </div>
                )}
             </div>

             {/* Simple Stats */}
             <div className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm p-6">
                 <h3 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-4">Pipeline Metrics</h3>
                 <div className="space-y-4">
                    <div>
                        <p className="text-sm text-slate-500 dark:text-slate-400 mb-1">Total Pipeline Value</p>
                        <div className="text-3xl font-bold text-slate-900 dark:text-white">
                            ${relatedDeals.reduce((acc, deal) => acc + deal.value, 0).toLocaleString()}
                        </div>
                    </div>
                    <div className="h-px bg-slate-100 dark:bg-slate-800"></div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <p className="text-xs text-slate-500 dark:text-slate-400 mb-1">Open Deals</p>
                            <p className="text-xl font-bold text-slate-900 dark:text-white">{relatedDeals.filter(d => !['Closed Won', 'Closed Lost'].includes(d.stage)).length}</p>
                        </div>
                        <div>
                            <p className="text-xs text-slate-500 dark:text-slate-400 mb-1">Contacts</p>
                            <p className="text-xl font-bold text-slate-900 dark:text-white">{relatedContacts.length}</p>
                        </div>
                    </div>
                 </div>
             </div>
          </div>

        </div>
      </div>

      {/* Add Contact Modal */}
      {isContactModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
            <div className="w-full max-w-lg bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden animate-scale-in">
                <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50">
                    <h2 className="text-xl font-bold text-slate-900 dark:text-white flex items-center gap-2">
                        <IconUser className="w-5 h-5 text-primary-500" />
                        Create Contact
                    </h2>
                    <button onClick={() => setIsContactModalOpen(false)} className="text-slate-400 hover:text-slate-600 dark:hover:text-white transition-colors"><IconX className="w-6 h-6" /></button>
                </div>
                <div className="p-6 bg-slate-50/50 dark:bg-[#0b1120]/50 border-b border-slate-200 dark:border-slate-800">
                    <p className="text-sm text-slate-600 dark:text-slate-400">
                        This contact will be automatically linked to <span className="font-bold text-slate-900 dark:text-white">{account.name}</span>.
                    </p>
                </div>
                <form onSubmit={handleContactSubmit} className="p-6 space-y-4">
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">First Name</label>
                            <input type="text" name="firstName" value={newContact.firstName} onChange={handleContactChange} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white" required />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Last Name</label>
                            <input type="text" name="lastName" value={newContact.lastName} onChange={handleContactChange} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white" required />
                        </div>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Title</label>
                        <input type="text" name="title" value={newContact.title} onChange={handleContactChange} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white" />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Email</label>
                        <input type="email" name="email" value={newContact.email} onChange={handleContactChange} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white" />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Phone</label>
                        <input type="tel" name="phone" value={newContact.phone} onChange={handleContactChange} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white" />
                    </div>
                    <div className="pt-4 flex justify-end gap-3">
                        <button type="button" onClick={() => setIsContactModalOpen(false)} className="px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 rounded-lg hover:bg-slate-200 transition-colors">Cancel</button>
                        <button type="submit" className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 transition-colors shadow-lg shadow-primary-500/20">Create Contact</button>
                    </div>
                </form>
            </div>
        </div>
      )}
    </div>
  );
};

export default AccountDetail;

import React, { useState, useEffect } from 'react';
import { Account, Contact, Deal, Lead, ContactStatus } from '../types';
import { 
  IconArrowLeft, 
  IconEdit, 
  IconTrash, 
  IconBuilding, 
  IconGlobe, 
  IconPhone, 
  IconUser, 
  IconUsers, 
  IconKanban,
  IconSparkles,
  IconMail,
  IconPlus,
  IconX,
  IconTarget,
  IconBriefcase
} from './Icons';
import { generateAccountInsights } from '../services/geminiService';
import ContactDetail from './ContactDetail';

interface AccountDetailProps {
  account: Account;
  onBack: () => void;
  onEdit: () => void;
  onDelete: () => void;
  contacts: Contact[];
  deals: Deal[];
  leads: Lead[];
  onAddContact: (contact: Omit<Contact, 'id' | 'lastActivity'>) => void;
  onUpdateContact?: (contact: Contact) => void;
}

const DetailRow: React.FC<{ label: string; value?: string | number | null; icon?: React.ElementType; isLink?: boolean }> = ({ label, value, icon: Icon, isLink }) => {
  if (!value) return null;
  return (
    <div>
      <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">{label}</label>
      <p className="text-base font-medium text-slate-900 dark:text-slate-100 flex items-center mt-1">
        {Icon && <Icon className="w-4 h-4 mr-2 text-slate-400" />}
        {isLink ? (
            <a href={value.toString().startsWith('http') ? value.toString() : `https://${value}`} target="_blank" rel="noopener noreferrer" className="text-primary-600 hover:underline">
                {value}
            </a>
        ) : value}
      </p>
    </div>
  );
};

const AccountDetail: React.FC<AccountDetailProps> = ({ account, onBack, onEdit, onDelete, contacts, deals, leads, onAddContact, onUpdateContact }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'contacts' | 'deals' | 'leads'>('overview');
  const [insights, setInsights] = useState<string>('');
  const [isLoadingInsights, setIsLoadingInsights] = useState(false);
  const [selectedContactId, setSelectedContactId] = useState<string | null>(null);

  // Contact Modal State
  const [isContactModalOpen, setIsContactModalOpen] = useState(false);
  const [newContact, setNewContact] = useState<{
      firstName: string;
      lastName: string;
      title: string;
      email: string;
      phone: string;
      mobile: string;
      department: string;
      leadSource: string;
      status: ContactStatus;
  }>({ 
      firstName: '', 
      lastName: '', 
      title: '', 
      email: '', 
      phone: '', 
      mobile: '',
      department: '',
      leadSource: '',
      status: 'New' 
  });

  // Use case-insensitive matching for company name
  const relatedContacts = contacts.filter(c => c.company?.trim().toLowerCase() === account.name.trim().toLowerCase());
  const relatedDeals = deals.filter(d => d.company?.trim().toLowerCase() === account.name.trim().toLowerCase());
  const relatedLeads = leads.filter(l => l.company?.trim().toLowerCase() === account.name.trim().toLowerCase());

  // Handle Contact Selection
  const selectedContact = contacts.find(c => c.id === selectedContactId);

  const handleGenerateInsights = async () => {
    setIsLoadingInsights(true);
    const result = await generateAccountInsights(account);
    setInsights(result);
    setIsLoadingInsights(false);
  };

  const handleContactSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      onAddContact({
          name: `${newContact.firstName} ${newContact.lastName}`.trim(),
          firstName: newContact.firstName,
          lastName: newContact.lastName,
          title: newContact.title,
          email: newContact.email,
          phone: newContact.phone,
          mobile: newContact.mobile,
          department: newContact.department,
          leadSource: newContact.leadSource,
          company: account.name, // Auto-link to this account
          status: newContact.status
      });
      setIsContactModalOpen(false);
      setNewContact({ firstName: '', lastName: '', title: '', email: '', phone: '', mobile: '', department: '', leadSource: '', status: 'New' });
  };

  const handleContactChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
      setNewContact({ ...newContact, [e.target.name]: e.target.value });
  };

  const renderTabButton = (id: typeof activeTab, label: string, count?: number, icon?: React.ElementType) => {
      const Icon = icon;
      return (
        <button 
            onClick={() => setActiveTab(id)}
            className={`flex items-center gap-2 py-4 px-1 border-b-2 font-medium text-sm transition-all ${
                activeTab === id 
                ? 'border-primary-500 text-primary-600 dark:text-primary-400' 
                : 'border-transparent text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-300'
            }`}
        >
            {Icon && <Icon className="w-4 h-4" />}
            {label}
            {count !== undefined && (
                <span className={`ml-1 text-xs px-2 py-0.5 rounded-full ${activeTab === id ? 'bg-primary-100 text-primary-700 dark:bg-primary-900/30' : 'bg-slate-100 text-slate-600 dark:bg-slate-800'}`}>
                    {count}
                </span>
            )}
        </button>
      );
  };

  // If a contact is selected, show the ContactDetail view
  if (selectedContact) {
      return (
          <ContactDetail 
              contact={selectedContact}
              onBack={() => setSelectedContactId(null)}
              onUpdate={(updated) => {
                  if (onUpdateContact) onUpdateContact(updated);
              }}
          />
      );
  }

  return (
    <div className="bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm h-full flex flex-col animate-fade-in">
      {/* Header */}
      <div className="px-6 pt-6 pb-0 border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-950/50 rounded-t-xl flex-shrink-0">
        <div className="flex justify-between items-start mb-6">
            <div className="flex items-center gap-4">
            <button onClick={onBack} className="p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800 transition-colors group">
                <IconArrowLeft className="w-5 h-5 text-slate-600 dark:text-slate-300 group-hover:-translate-x-1 transition-transform" />
            </button>
            <div>
                <h1 className="text-2xl font-bold text-slate-900 dark:text-white flex items-center gap-2">
                    <IconBuilding className="w-6 h-6 text-primary-600 dark:text-primary-400" />
                    {account.name}
                </h1>
                <p className="text-sm text-slate-500 dark:text-slate-400 mt-1 flex items-center gap-2">
                    {account.industry} 
                    <span className="w-1 h-1 rounded-full bg-slate-300 dark:bg-slate-600"></span>
                    {account.website}
                </p>
            </div>
            </div>
            <div className="flex items-center gap-3">
            <button onClick={onEdit} className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors shadow-sm">
                <IconEdit className="w-4 h-4" /> Edit
            </button>
            <button onClick={onDelete} className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-red-600 bg-red-50 dark:bg-red-500/10 border border-red-200 dark:border-red-500/20 rounded-lg hover:bg-red-100 dark:hover:bg-red-500/20 transition-colors shadow-sm">
                <IconTrash className="w-4 h-4" /> Delete
            </button>
            </div>
        </div>

        {/* Tabs */}
        <div className="flex gap-6 overflow-x-auto">
            {renderTabButton('overview', 'Overview', undefined, IconBriefcase)}
            {renderTabButton('contacts', 'Contacts', relatedContacts.length, IconUsers)}
            {renderTabButton('deals', 'Deals', relatedDeals.length, IconKanban)}
            {renderTabButton('leads', 'Leads', relatedLeads.length, IconTarget)}
        </div>
      </div>

      {/* Body */}
      <div className="flex-1 overflow-y-auto p-8 bg-slate-50/30 dark:bg-[#0b1120]/30 custom-scrollbar">
        <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">

          {/* Main Content Area */}
          <div className="xl:col-span-2 space-y-6">

            {activeTab === 'overview' && (
                <div className="space-y-6 animate-fade-in">
                    <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm">
                        <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-6 flex items-center">
                            <span className="w-1.5 h-1.5 bg-primary-500 rounded-full mr-2.5"></span>
                            Account Information
                        </h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-y-6 gap-x-12">
                            <DetailRow label="Account Owner" value={account.owner} icon={IconUser} />
                            <DetailRow label="Phone" value={account.phone} icon={IconPhone} />
                            <DetailRow label="Website" value={account.website} icon={IconGlobe} isLink />
                            <DetailRow label="Industry" value={account.industry} />
                        </div>
                    </div>
                    {/* Add a snapshot of recent items or activity here if needed */}
                </div>
            )}

            {activeTab === 'contacts' && (
                <div className="space-y-4 animate-fade-in">
                    <div className="flex justify-between items-center mb-2">
                        <h3 className="text-lg font-bold text-slate-900 dark:text-white">Related Contacts</h3>
                        <button 
                            onClick={() => setIsContactModalOpen(true)}
                            className="flex items-center gap-2 text-sm font-bold text-white bg-primary-600 px-4 py-2 rounded-lg hover:bg-primary-500 transition-colors shadow-sm"
                        >
                            <IconPlus className="w-4 h-4" /> Create Contact
                        </button>
                    </div>

                    {relatedContacts.length > 0 ? (
                        <div className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden">
                            <table className="w-full text-left text-sm">
                                <thead className="bg-slate-50 dark:bg-slate-800/50 border-b border-slate-200 dark:border-slate-800">
                                    <tr>
                                        <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Name</th>
                                        <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Title</th>
                                        <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Email</th>
                                        <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Phone</th>
                                        <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400 text-right">Action</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                                    {relatedContacts.map(contact => (
                                        <tr key={contact.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                                            <td className="px-6 py-4">
                                                <button 
                                                    onClick={() => setSelectedContactId(contact.id)}
                                                    className="flex items-center hover:text-primary-600 dark:hover:text-primary-400 transition-colors text-left"
                                                >
                                                    <div className="w-8 h-8 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-xs font-bold text-slate-500 border border-slate-200 dark:border-slate-700 mr-3">
                                                        {contact.name.charAt(0)}
                                                    </div>
                                                    <span className="font-semibold text-slate-900 dark:text-white">{contact.name}</span>
                                                </button>
                                            </td>
                                            <td className="px-6 py-4 text-slate-600 dark:text-slate-400">{contact.title}</td>
                                            <td className="px-6 py-4 text-slate-600 dark:text-slate-400">{contact.email}</td>
                                            <td className="px-6 py-4 text-slate-600 dark:text-slate-400">{contact.phone}</td>
                                            <td className="px-6 py-4 text-right">
                                                <button 
                                                    onClick={() => setSelectedContactId(contact.id)}
                                                    className="text-xs font-medium text-primary-600 dark:text-primary-400 hover:underline"
                                                >
                                                    View History
                                                </button>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    ) : (
                        <div className="p-12 text-center bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 border-dashed">
                            <div className="mx-auto w-12 h-12 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center mb-4">
                                <IconUsers className="w-6 h-6 text-slate-400" />
                            </div>
                            <h3 className="text-slate-900 dark:text-white font-medium mb-1">No contacts yet</h3>
                            <p className="text-slate-500 dark:text-slate-400 text-sm mb-4">Add people associated with this account.</p>
                            <button 
                                onClick={() => setIsContactModalOpen(true)}
                                className="text-primary-600 dark:text-primary-400 font-bold text-sm hover:underline"
                            >
                                Add First Contact
                            </button>
                        </div>
                    )}
                </div>
            )}

            {activeTab === 'deals' && (
                <div className="space-y-4 animate-fade-in">
                    <div className="flex justify-between items-center mb-2">
                        <h3 className="text-lg font-bold text-slate-900 dark:text-white">Active Deals</h3>
                    </div>
                    {relatedDeals.length > 0 ? (
                        <div className="grid grid-cols-1 gap-4">
                            {relatedDeals.map(deal => (
                                <div key={deal.id} className="p-5 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm hover:border-primary-300 dark:hover:border-primary-700 transition-colors flex justify-between items-center group">
                                    <div>
                                        <h4 className="font-bold text-slate-900 dark:text-white mb-1 group-hover:text-primary-600 transition-colors">{deal.title}</h4>
                                        <div className="flex items-center gap-3 text-sm text-slate-500 dark:text-slate-400">
                                            <span className="bg-slate-100 dark:bg-slate-800 px-2 py-0.5 rounded text-xs font-medium">{deal.stage}</span>
                                            <span>•</span>
                                            <span>Close: {deal.closeDate}</span>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <p className="text-lg font-bold text-slate-900 dark:text-white">${deal.value.toLocaleString()}</p>
                                        <p className="text-sm text-slate-500 dark:text-slate-400">{deal.probability}% Prob.</p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="p-12 text-center bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 border-dashed">
                            <p className="text-slate-500 dark:text-slate-400">No active deals found.</p>
                        </div>
                    )}
                </div>
            )}

            {activeTab === 'leads' && (
                <div className="space-y-4 animate-fade-in">
                    <div className="flex justify-between items-center mb-2">
                        <h3 className="text-lg font-bold text-slate-900 dark:text-white">Associated Leads</h3>
                    </div>
                    {relatedLeads.length > 0 ? (
                        <div className="grid grid-cols-1 gap-4">
                            {relatedLeads.map(lead => (
                                <div key={lead.id} className="p-5 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm flex justify-between items-center">
                                    <div className="flex items-center gap-4">
                                        <div className="w-10 h-10 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-slate-500 font-bold border border-slate-200 dark:border-slate-700">
                                            {lead.name.charAt(0)}
                                        </div>
                                        <div>
                                            <h4 className="font-bold text-slate-900 dark:text-white">{lead.name}</h4>
                                            <p className="text-sm text-slate-500 dark:text-slate-400">{lead.title}</p>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <span className={`px-2.5 py-1 text-xs font-semibold rounded-full border ${
                                            lead.score > 70 ? 'bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-900/20 dark:text-emerald-400' : 'bg-slate-100 text-slate-600 border-slate-200 dark:bg-slate-800 dark:text-slate-400'
                                        }`}>
                                            Score: {lead.score}
                                        </span>
                                    </div>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="p-12 text-center bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 border-dashed">
                            <p className="text-slate-500 dark:text-slate-400">No leads found.</p>
                        </div>
                    )}
                </div>
            )}

          </div>

          {/* Right Sidebar - AI & Stats (Always Visible or contextual?) */}
          <div className="space-y-8">
             {/* AI Account Strategy */}
             <div className="bg-gradient-to-br from-indigo-50 to-purple-50 dark:from-slate-800 dark:to-slate-900 rounded-2xl border border-indigo-100 dark:border-slate-700 shadow-sm p-6">
                <div className="flex items-center justify-between mb-4">
                    <h3 className="text-lg font-bold text-indigo-900 dark:text-indigo-100 flex items-center">
                        <IconSparkles className="w-5 h-5 mr-2 text-indigo-600 dark:text-indigo-400" />
                        Nova AI Strategy
                    </h3>
                </div>

                {insights ? (
                    <div className="prose prose-sm dark:prose-invert max-w-none text-slate-700 dark:text-slate-300 leading-relaxed">
                        <div dangerouslySetInnerHTML={{ __html: insights.replace(/\n/g, '<br />') }} />
                    </div>
                ) : (
                    <div className="text-center py-6">
                        <p className="text-sm text-slate-600 dark:text-slate-400 mb-4">Generate AI-powered insights to grow this account.</p>
                        <button 
                            onClick={handleGenerateInsights}
                            disabled={isLoadingInsights}
                            className="w-full py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-semibold shadow-md shadow-indigo-500/20 transition-all disabled:opacity-70 disabled:cursor-not-allowed flex items-center justify-center"
                        >
                            {isLoadingInsights ? (
                                <span className="flex items-center"><span className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></span> Analyzing...</span>
                            ) : (
                                "Generate Strategy"
                            )}
                        </button>
                    </div>
                )}
             </div>

             {/* Simple Stats */}
             <div className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm p-6">
                 <h3 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-4">Pipeline Metrics</h3>
                 <div className="space-y-4">
                    <div>
                        <p className="text-sm text-slate-500 dark:text-slate-400 mb-1">Total Pipeline Value</p>
                        <div className="text-3xl font-bold text-slate-900 dark:text-white">
                            ${relatedDeals.reduce((acc, deal) => acc + deal.value, 0).toLocaleString()}
                        </div>
                    </div>
                    <div className="h-px bg-slate-100 dark:bg-slate-800"></div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <p className="text-xs text-slate-500 dark:text-slate-400 mb-1">Open Deals</p>
                            <p className="text-xl font-bold text-slate-900 dark:text-white">{relatedDeals.filter(d => !['Closed Won', 'Closed Lost'].includes(d.stage)).length}</p>
                        </div>
                        <div>
                            <p className="text-xs text-slate-500 dark:text-slate-400 mb-1">Contacts</p>
                            <p className="text-xl font-bold text-slate-900 dark:text-white">{relatedContacts.length}</p>
                        </div>
                    </div>
                 </div>
             </div>
          </div>

        </div>
      </div>

      {/* Add Contact Modal */}
      {isContactModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
            <div className="w-full max-w-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden animate-scale-in">
                <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50">
                    <h2 className="text-xl font-bold text-slate-900 dark:text-white flex items-center gap-2">
                        <IconUser className="w-5 h-5 text-primary-500" />
                        Create Contact
                    </h2>
                    <button onClick={() => setIsContactModalOpen(false)} className="text-slate-400 hover:text-slate-600 dark:hover:text-white transition-colors"><IconX className="w-6 h-6" /></button>
                </div>
                <div className="p-6 bg-slate-50/50 dark:bg-[#0b1120]/50 border-b border-slate-200 dark:border-slate-800">
                    <p className="text-sm text-slate-600 dark:text-slate-400">
                        This contact will be automatically linked to <span className="font-bold text-slate-900 dark:text-white">{account.name}</span>.
                    </p>
                </div>
                <form onSubmit={handleContactSubmit} className="p-8 space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">First Name <span className="text-red-500">*</span></label>
                            <input type="text" name="firstName" value={newContact.firstName} onChange={handleContactChange} className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 dark:text-white" required />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Last Name <span className="text-red-500">*</span></label>
                            <input type="text" name="lastName" value={newContact.lastName} onChange={handleContactChange} className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 dark:text-white" required />
                        </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Title</label>
                            <input type="text" name="title" value={newContact.title} onChange={handleContactChange} className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 dark:text-white" placeholder="e.g. Sales Manager" />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Department</label>
                            <input type="text" name="department" value={newContact.department} onChange={handleContactChange} className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 dark:text-white" placeholder="e.g. Marketing" />
                        </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Email <span className="text-red-500">*</span></label>
                            <div className="relative">
                                <input type="email" name="email" value={newContact.email} onChange={handleContactChange} className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 dark:text-white pl-10" required />
                                <IconMail className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                            </div>
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Lead Source</label>
                            <select name="leadSource" value={newContact.leadSource} onChange={handleContactChange} className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 dark:text-white cursor-pointer">
                                <option value="">- None -</option>
                                <option value="Advertisement">Advertisement</option>
                                <option value="Cold Call">Cold Call</option>
                                <option value="Employee Referral">Employee Referral</option>
                                <option value="External Referral">External Referral</option>
                                <option value="Online Store">Online Store</option>
                                <option value="Partner">Partner</option>
                                <option value="Trade Show">Trade Show</option>
                                <option value="Web Download">Web Download</option>
                                <option value="Web Search">Web Search</option>
                                <option value="Chat">Chat</option>
                            </select>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Phone</label>
                            <div className="relative">
                                <input type="tel" name="phone" value={newContact.phone} onChange={handleContactChange} className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 dark:text-white pl-10" />
                                <IconPhone className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                            </div>
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Mobile</label>
                            <input type="tel" name="mobile" value={newContact.mobile} onChange={handleContactChange} className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 dark:text-white" />
                        </div>
                    </div>

                    <div className="pt-4 flex justify-end gap-3 border-t border-slate-100 dark:border-slate-800">
                        <button type="button" onClick={() => setIsContactModalOpen(false)} className="px-5 py-2.5 text-sm font-medium text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 rounded-xl hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">Cancel</button>
                        <button type="submit" className="px-6 py-2.5 text-sm font-medium text-white bg-primary-600 rounded-xl hover:bg-primary-500 transition-colors shadow-lg shadow-primary-500/20">Create Contact</button>
                    </div>
                </form>
            </div>
        </div>
      )}
    </div>
  );
};

export default AccountDetail;

import React, { useState, useEffect } from 'react';
import { Account, Contact, Deal, Lead, ContactStatus } from '../types';
import { 
  IconArrowLeft, 
  IconEdit, 
  IconTrash, 
  IconBuilding, 
  IconGlobe, 
  IconPhone, 
  IconUser, 
  IconUsers, 
  IconKanban, 
  IconSparkles,
  IconMail,
  IconPlus,
  IconX,
  IconTarget,
  IconBriefcase
} from './Icons';
import { generateAccountInsights } from '../services/geminiService';
import ContactDetail from './ContactDetail';

interface AccountDetailProps {
  account: Account;
  onBack: () => void;
  onEdit: () => void;
  onDelete: () => void;
  contacts: Contact[];
  deals: Deal[];
  leads: Lead[];
  onAddContact: (contact: Omit<Contact, 'id' | 'lastActivity'>) => void;
  onUpdateContact?: (contact: Contact) => void;
}

const DetailRow: React.FC<{ label: string; value?: string | number | null; icon?: React.ElementType; isLink?: boolean }> = ({ label, value, icon: Icon, isLink }) => {
  if (!value) return null;
  return (
    <div>
      <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">{label}</label>
      <p className="text-base font-medium text-slate-900 dark:text-slate-100 flex items-center mt-1">
        {Icon && <Icon className="w-4 h-4 mr-2 text-slate-400" />}
        {isLink ? (
            <a href={value.toString().startsWith('http') ? value.toString() : `https://${value}`} target="_blank" rel="noopener noreferrer" className="text-primary-600 hover:underline">
                {value}
            </a>
        ) : value}
      </p>
    </div>
  );
};

const AccountDetail: React.FC<AccountDetailProps> = ({ account, onBack, onEdit, onDelete, contacts, deals, leads, onAddContact, onUpdateContact }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'contacts' | 'deals' | 'leads'>('overview');
  const [insights, setInsights] = useState<string>('');
  const [isLoadingInsights, setIsLoadingInsights] = useState(false);
  const [selectedContactId, setSelectedContactId] = useState<string | null>(null);

  // Contact Modal State
  const [isContactModalOpen, setIsContactModalOpen] = useState(false);
  const [newContact, setNewContact] = useState<{
      firstName: string;
      lastName: string;
      title: string;
      email: string;
      phone: string;
      mobile: string;
      department: string;
      leadSource: string;
      status: ContactStatus;
      inactiveReason: string;
  }>({ 
      firstName: '', 
      lastName: '', 
      title: '', 
      email: '', 
      phone: '', 
      mobile: '',
      department: '',
      leadSource: '',
      status: 'New',
      inactiveReason: ''
  });

  // Use case-insensitive matching for company name
  const relatedContacts = contacts.filter(c => c.company?.trim().toLowerCase() === account.name.trim().toLowerCase());
  const relatedDeals = deals.filter(d => d.company?.trim().toLowerCase() === account.name.trim().toLowerCase());
  const relatedLeads = leads.filter(l => l.company?.trim().toLowerCase() === account.name.trim().toLowerCase());

  // Handle Contact Selection
  const selectedContact = contacts.find(c => c.id === selectedContactId);

  const handleGenerateInsights = async () => {
    setIsLoadingInsights(true);
    const result = await generateAccountInsights(account);
    setInsights(result);
    setIsLoadingInsights(false);
  };

  const handleContactSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      onAddContact({
          name: `${newContact.firstName} ${newContact.lastName}`.trim(),
          firstName: newContact.firstName,
          lastName: newContact.lastName,
          title: newContact.title,
          email: newContact.email,
          phone: newContact.phone,
          mobile: newContact.mobile,
          department: newContact.department,
          leadSource: newContact.leadSource,
          company: account.name, // Auto-link to this account
          status: newContact.status,
          inactiveReason: newContact.status === 'Inactive' ? newContact.inactiveReason : undefined
      });
      setIsContactModalOpen(false);
      setNewContact({ firstName: '', lastName: '', title: '', email: '', phone: '', mobile: '', department: '', leadSource: '', status: 'New', inactiveReason: '' });
  };

  const handleContactChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
      setNewContact({ ...newContact, [e.target.name]: e.target.value });
  };

  const renderTabButton = (id: typeof activeTab, label: string, count?: number, icon?: React.ElementType) => {
      const Icon = icon;
      return (
        <button 
            onClick={() => setActiveTab(id)}
            className={`flex items-center gap-2 py-4 px-1 border-b-2 font-medium text-sm transition-all ${
                activeTab === id 
                ? 'border-primary-500 text-primary-600 dark:text-primary-400' 
                : 'border-transparent text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-300'
            }`}
        >
            {Icon && <Icon className="w-4 h-4" />}
            {label}
            {count !== undefined && (
                <span className={`ml-1 text-xs px-2 py-0.5 rounded-full ${activeTab === id ? 'bg-primary-100 text-primary-700 dark:bg-primary-900/30' : 'bg-slate-100 text-slate-600 dark:bg-slate-800'}`}>
                    {count}
                </span>
            )}
        </button>
      );
  };

  // If a contact is selected, show the ContactDetail view
  if (selectedContact) {
      return (
          <ContactDetail 
              contact={selectedContact}
              onBack={() => setSelectedContactId(null)}
              onUpdate={(updated) => {
                  if (onUpdateContact) onUpdateContact(updated);
              }}
          />
      );
  }

  return (
    <div className="bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm h-full flex flex-col animate-fade-in">
      {/* Header */}
      <div className="px-6 pt-6 pb-0 border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-950/50 rounded-t-xl flex-shrink-0">
        <div className="flex justify-between items-start mb-6">
            <div className="flex items-center gap-4">
            <button onClick={onBack} className="p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800 transition-colors group">
                <IconArrowLeft className="w-5 h-5 text-slate-600 dark:text-slate-300 group-hover:-translate-x-1 transition-transform" />
            </button>
            <div>
                <h1 className="text-2xl font-bold text-slate-900 dark:text-white flex items-center gap-2">
                    <IconBuilding className="w-6 h-6 text-primary-600 dark:text-primary-400" />
                    {account.name}
                </h1>
                <p className="text-sm text-slate-500 dark:text-slate-400 mt-1 flex items-center gap-2">
                    {account.industry} 
                    <span className="w-1 h-1 rounded-full bg-slate-300 dark:bg-slate-600"></span>
                    {account.website}
                </p>
            </div>
            </div>
            <div className="flex items-center gap-3">
            <button onClick={onEdit} className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors shadow-sm">
                <IconEdit className="w-4 h-4" /> Edit
            </button>
            <button onClick={onDelete} className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-red-600 bg-red-50 dark:bg-red-500/10 border border-red-200 dark:border-red-500/20 rounded-lg hover:bg-red-100 dark:hover:bg-red-500/20 transition-colors shadow-sm">
                <IconTrash className="w-4 h-4" /> Delete
            </button>
            </div>
        </div>

        {/* Tabs */}
        <div className="flex gap-6 overflow-x-auto">
            {renderTabButton('overview', 'Overview', undefined, IconBriefcase)}
            {renderTabButton('contacts', 'Contacts', relatedContacts.length, IconUsers)}
            {renderTabButton('deals', 'Deals', relatedDeals.length, IconKanban)}
            {renderTabButton('leads', 'Leads', relatedLeads.length, IconTarget)}
        </div>
      </div>

      {/* Body */}
      <div className="flex-1 overflow-y-auto p-8 bg-slate-50/30 dark:bg-[#0b1120]/30 custom-scrollbar">
        <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">

          {/* Main Content Area */}
          <div className="xl:col-span-2 space-y-6">

            {activeTab === 'overview' && (
                <div className="space-y-6 animate-fade-in">
                    <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm">
                        <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-6 flex items-center">
                            <span className="w-1.5 h-1.5 bg-primary-500 rounded-full mr-2.5"></span>
                            Account Information
                        </h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-y-6 gap-x-12">
                            <DetailRow label="Account Owner" value={account.owner} icon={IconUser} />
                            <DetailRow label="Phone" value={account.phone} icon={IconPhone} />
                            <DetailRow label="Website" value={account.website} icon={IconGlobe} isLink />
                            <DetailRow label="Industry" value={account.industry} />
                        </div>
                    </div>
                    {/* Add a snapshot of recent items or activity here if needed */}
                </div>
            )}

            {activeTab === 'contacts' && (
                <div className="space-y-4 animate-fade-in">
                    <div className="flex justify-between items-center mb-2">
                        <h3 className="text-lg font-bold text-slate-900 dark:text-white">Related Contacts</h3>
                        <button 
                            onClick={() => setIsContactModalOpen(true)}
                            className="flex items-center gap-2 text-sm font-bold text-white bg-primary-600 px-4 py-2 rounded-lg hover:bg-primary-500 transition-colors shadow-sm"
                        >
                            <IconPlus className="w-4 h-4" /> Create Contact
                        </button>
                    </div>

                    {relatedContacts.length > 0 ? (
                        <div className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden">
                            <table className="w-full text-left text-sm">
                                <thead className="bg-slate-50 dark:bg-slate-800/50 border-b border-slate-200 dark:border-slate-800">
                                    <tr>
                                        <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Name</th>
                                        <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Title</th>
                                        <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Email</th>
                                        <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400">Phone</th>
                                        <th className="px-6 py-4 font-semibold text-slate-500 dark:text-slate-400 text-right">Action</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                                    {relatedContacts.map(contact => (
                                        <tr key={contact.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                                            <td className="px-6 py-4">
                                                <button 
                                                    onClick={() => setSelectedContactId(contact.id)}
                                                    className="flex items-center hover:text-primary-600 dark:hover:text-primary-400 transition-colors text-left"
                                                >
                                                    <div className="w-8 h-8 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-xs font-bold text-slate-500 border border-slate-200 dark:border-slate-700 mr-3">
                                                        {contact.name.charAt(0)}
                                                    </div>
                                                    <span className="font-semibold text-slate-900 dark:text-white">{contact.name}</span>
                                                </button>
                                            </td>
                                            <td className="px-6 py-4 text-slate-600 dark:text-slate-400">{contact.title}</td>
                                            <td className="px-6 py-4 text-slate-600 dark:text-slate-400">{contact.email}</td>
                                            <td className="px-6 py-4 text-slate-600 dark:text-slate-400">{contact.phone}</td>
                                            <td className="px-6 py-4 text-right">
                                                <button 
                                                    onClick={() => setSelectedContactId(contact.id)}
                                                    className="text-xs font-medium text-primary-600 dark:text-primary-400 hover:underline"
                                                >
                                                    View History
                                                </button>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    ) : (
                        <div className="p-12 text-center bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 border-dashed">
                            <div className="mx-auto w-12 h-12 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center mb-4">
                                <IconUsers className="w-6 h-6 text-slate-400" />
                            </div>
                            <h3 className="text-slate-900 dark:text-white font-medium mb-1">No contacts yet</h3>
                            <p className="text-slate-500 dark:text-slate-400 text-sm mb-4">Add people associated with this account.</p>
                            <button 
                                onClick={() => setIsContactModalOpen(true)}
                                className="text-primary-600 dark:text-primary-400 font-bold text-sm hover:underline"
                            >
                                Add First Contact
                            </button>
                        </div>
                    )}
                </div>
            )}

            {activeTab === 'deals' && (
                <div className="space-y-4 animate-fade-in">
                    <div className="flex justify-between items-center mb-2">
                        <h3 className="text-lg font-bold text-slate-900 dark:text-white">Active Deals</h3>
                    </div>
                    {relatedDeals.length > 0 ? (
                        <div className="grid grid-cols-1 gap-4">
                            {relatedDeals.map(deal => (
                                <div key={deal.id} className="p-5 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm hover:border-primary-300 dark:hover:border-primary-700 transition-colors flex justify-between items-center group">
                                    <div>
                                        <h4 className="font-bold text-slate-900 dark:text-white mb-1 group-hover:text-primary-600 transition-colors">{deal.title}</h4>
                                        <div className="flex items-center gap-3 text-sm text-slate-500 dark:text-slate-400">
                                            <span className="bg-slate-100 dark:bg-slate-800 px-2 py-0.5 rounded text-xs font-medium">{deal.stage}</span>
                                            <span>•</span>
                                            <span>Close: {deal.closeDate}</span>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <p className="text-lg font-bold text-slate-900 dark:text-white">${deal.value.toLocaleString()}</p>
                                        <p className="text-sm text-slate-500 dark:text-slate-400">{deal.probability}% Prob.</p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="p-12 text-center bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 border-dashed">
                            <p className="text-slate-500 dark:text-slate-400">No active deals found.</p>
                        </div>
                    )}
                </div>
            )}

            {activeTab === 'leads' && (
                <div className="space-y-4 animate-fade-in">
                    <div className="flex justify-between items-center mb-2">
                        <h3 className="text-lg font-bold text-slate-900 dark:text-white">Associated Leads</h3>
                    </div>
                    {relatedLeads.length > 0 ? (
                        <div className="grid grid-cols-1 gap-4">
                            {relatedLeads.map(lead => (
                                <div key={lead.id} className="p-5 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm flex justify-between items-center">
                                    <div className="flex items-center gap-4">
                                        <div className="w-10 h-10 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-slate-500 font-bold border border-slate-200 dark:border-slate-700">
                                            {lead.name.charAt(0)}
                                        </div>
                                        <div>
                                            <h4 className="font-bold text-slate-900 dark:text-white">{lead.name}</h4>
                                            <p className="text-sm text-slate-500 dark:text-slate-400">{lead.title}</p>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <span className={`px-2.5 py-1 text-xs font-semibold rounded-full border ${
                                            lead.score > 70 ? 'bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-900/20 dark:text-emerald-400' : 'bg-slate-100 text-slate-600 border-slate-200 dark:bg-slate-800 dark:text-slate-400'
                                        }`}>
                                            Score: {lead.score}
                                        </span>
                                    </div>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="p-12 text-center bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 border-dashed">
                            <p className="text-slate-500 dark:text-slate-400">No leads found.</p>
                        </div>
                    )}
                </div>
            )}

          </div>

          {/* Right Sidebar - AI & Stats (Always Visible or contextual?) */}
          <div className="space-y-8">
             {/* AI Account Strategy */}
             <div className="bg-gradient-to-br from-indigo-50 to-purple-50 dark:from-slate-800 dark:to-slate-900 rounded-2xl border border-indigo-100 dark:border-slate-700 shadow-sm p-6">
                <div className="flex items-center justify-between mb-4">
                    <h3 className="text-lg font-bold text-indigo-900 dark:text-indigo-100 flex items-center">
                        <IconSparkles className="w-5 h-5 mr-2 text-indigo-600 dark:text-indigo-400" />
                        Nova AI Strategy
                    </h3>
                </div>

                {insights ? (
                    <div className="prose prose-sm dark:prose-invert max-w-none text-slate-700 dark:text-slate-300 leading-relaxed">
                        <div dangerouslySetInnerHTML={{ __html: insights.replace(/\n/g, '<br />') }} />
                    </div>
                ) : (
                    <div className="text-center py-6">
                        <p className="text-sm text-slate-600 dark:text-slate-400 mb-4">Generate AI-powered insights to grow this account.</p>
                        <button 
                            onClick={handleGenerateInsights}
                            disabled={isLoadingInsights}
                            className="w-full py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-semibold shadow-md shadow-indigo-500/20 transition-all disabled:opacity-70 disabled:cursor-not-allowed flex items-center justify-center"
                        >
                            {isLoadingInsights ? (
                                <span className="flex items-center"><span className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></span> Analyzing...</span>
                            ) : (
                                "Generate Strategy"
