                    </div>
                    <div className="h-px bg-slate-100 dark:bg-slate-800"></div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <p className="text-xs text-slate-500 dark:text-slate-400 mb-1">Open Deals</p>
                            <p className="text-xl font-bold text-slate-900 dark:text-white">{relatedDeals.filter(d => !['Closed Won', 'Closed Lost'].includes(d.stage)).length}</p>
                        </div>
                        <div>
                            <p className="text-xs text-slate-500 dark:text-slate-400 mb-1">Contacts</p>
                            <p className="text-xl font-bold text-slate-900 dark:text-white">{relatedContacts.length}</p>
                        </div>
                    </div>
                 </div>
             </div>
          </div>

        </div>
      </div>

      {/* Add Contact Modal */}
      {isContactModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
            <div className="w-full max-w-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden animate-scale-in">
                <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50">
                    <h2 className="text-xl font-bold text-slate-900 dark:text-white flex items-center gap-2">
                        <IconUser className="w-5 h-5 text-primary-500" />
                        Create Contact
                    </h2>
                    <button onClick={() => setIsContactModalOpen(false)} className="text-slate-400 hover:text-slate-600 dark:hover:text-white transition-colors"><IconX className="w-6 h-6" /></button>
                </div>
                <div className="p-6 bg-slate-50/50 dark:bg-[#0b1120]/50 border-b border-slate-200 dark:border-slate-800">
                    <p className="text-sm text-slate-600 dark:text-slate-400">
                        This contact will be automatically linked to <span className="font-bold text-slate-900 dark:text-white">{account.name}</span>.
                    </p>
                </div>
                <form onSubmit={handleContactSubmit} className="p-8 space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">First Name <span className="text-red-500">*</span></label>
                            <input type="text" name="firstName" value={newContact.firstName} onChange={handleContactChange} className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 dark:text-white" required />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Last Name <span className="text-red-500">*</span></label>
                            <input type="text" name="lastName" value={newContact.lastName} onChange={handleContactChange} className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 dark:text-white" required />
                        </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Title</label>
                            <input type="text" name="title" value={newContact.title} onChange={handleContactChange} className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 dark:text-white" placeholder="e.g. Sales Manager" />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Department</label>
                            <input type="text" name="department" value={newContact.department} onChange={handleContactChange} className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 dark:text-white" placeholder="e.g. Marketing" />
                        </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Email <span className="text-red-500">*</span></label>
                            <div className="relative">
                                <input type="email" name="email" value={newContact.email} onChange={handleContactChange} className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 dark:text-white pl-10" required />
                                <IconMail className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                            </div>
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Lead Source</label>
                            <select name="leadSource" value={newContact.leadSource} onChange={handleContactChange} className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 dark:text-white cursor-pointer">
                                <option value="">- None -</option>
                                <option value="Advertisement">Advertisement</option>
                                <option value="Cold Call">Cold Call</option>
                                <option value="Employee Referral">Employee Referral</option>
                                <option value="External Referral">External Referral</option>
                                <option value="Online Store">Online Store</option>
                                <option value="Partner">Partner</option>
                                <option value="Trade Show">Trade Show</option>
                                <option value="Web Download">Web Download</option>
                                <option value="Web Search">Web Search</option>
                                <option value="Chat">Chat</option>
                            </select>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Phone</label>
                            <div className="relative">
                                <input type="tel" name="phone" value={newContact.phone} onChange={handleContactChange} className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 dark:text-white pl-10" />
                                <IconPhone className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                            </div>
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Mobile</label>
                            <input type="tel" name="mobile" value={newContact.mobile} onChange={handleContactChange} className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 dark:text-white" />
                        </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Status</label>
                            <select name="status" value={newContact.status} onChange={handleContactChange} className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 dark:text-white cursor-pointer">
                                <option value="New">New</option>
                                <option value="Active">Active</option>
                                <option value="Inactive">Inactive</option>
                            </select>
                        </div>
                        {newContact.status === 'Inactive' && (
                            <div className="animate-fade-in">
                                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Reason for Inactivity <span className="text-red-500">*</span></label>
                                <input type="text" name="inactiveReason" value={newContact.inactiveReason} onChange={handleContactChange} className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 dark:text-white" placeholder="e.g. Left company" required />
                            </div>
                        )}
                    </div>

                    <div className="pt-4 flex justify-end gap-3 border-t border-slate-100 dark:border-slate-800">
                        <button type="button" onClick={() => setIsContactModalOpen(false)} className="px-5 py-2.5 text-sm font-medium text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 rounded-xl hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">Cancel</button>
                        <button type="submit" className="px-6 py-2.5 text-sm font-medium text-white bg-primary-600 rounded-xl hover:bg-primary-500 transition-colors shadow-lg shadow-primary-500/20">Create Contact</button>
                    </div>
                </form>
            </div>
        </div>
      )}
    </div>
  );
};

export default AccountDetail;

import React, { useState, useEffect } from 'react';
import { Account, Contact, Deal, Lead, ContactStatus } from '../types';
import { 
  IconArrowLeft, 
  IconEdit, 
  IconTrash, 
  IconBuilding, 
  IconGlobe, 
  IconPhone, 
  IconUser, 
  IconUsers, 
  IconKanban, 
  IconSparkles,
  IconMail,
  IconPlus,
  IconX,
  IconTarget,
  IconBriefcase
} from './Icons';
import { generateAccountInsights } from '../services/geminiService';
import ContactDetail from './ContactDetail';

interface AccountDetailProps {
  account: Account;
  onBack: () => void;
  onEdit: () => void;
  onDelete: () => void;
  contacts: Contact[];
  deals: Deal[];
  leads: Lead[];
  onAddContact: (contact: Omit<Contact, 'id' | 'lastActivity'>) => void;
  onUpdateContact?: (contact: Contact) => void;
}

const DetailRow: React.FC<{ label: string; value?: string | number | null; icon?: React.ElementType; isLink?: boolean }> = ({ label, value, icon: Icon, isLink }) => {
  if (!value) return null;
  return (
    <div>
      <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">{label}</label>
      <p className="text-base font-medium text-slate-900 dark:text-slate-100 flex items-center mt-1">
        {Icon && <Icon className="w-4 h-4 mr-2 text-slate-400" />}
        {isLink ? (
            <a href={value.toString().startsWith('http') ? value.toString() : `https://${value}`} target="_blank" rel="noopener noreferrer" className="text-primary-600 hover:underline">
                {value}
            </a>
        ) : value}
      </p>
    </div>
  );
};

const AccountDetail: React.FC<AccountDetailProps> = ({ account, onBack, onEdit, onDelete, contacts, deals, leads, onAddContact, onUpdateContact }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'contacts' | 'deals' | 'leads'>('overview');
  const [insights, setInsights] = useState<string>('');
  const [isLoadingInsights, setIsLoadingInsights] = useState(false);
  const [selectedContactId, setSelectedContactId] = useState<string | null>(null);

  // Contact Modal State
  const [isContactModalOpen, setIsContactModalOpen] = useState(false);
  const [newContact, setNewContact] = useState<{
      firstName: string;
      lastName: string;
      title: string;
      email: string;
      phone: string;
      mobile: string;
      department: string;
      leadSource: string;
      status: ContactStatus;
      inactiveReason: string;
  }>({ 
      firstName: '', 
      lastName: '', 
      title: '', 
      email: '', 
      phone: '', 
      mobile: '',
      department: '',
      leadSource: '',
      status: 'New',
      inactiveReason: ''
  });

  // Use case-insensitive matching for company name
  const relatedContacts = contacts.filter(c => c.company?.trim().toLowerCase() === account.name.trim().toLowerCase());
  const relatedDeals = deals.filter(d => d.company?.trim().toLowerCase() === account.name.trim().toLowerCase());
  const relatedLeads = leads.filter(l => l.company?.trim().toLowerCase() === account.name.trim().toLowerCase());

  // Handle Contact Selection
  const selectedContact = contacts.find(c => c.id === selectedContactId);

  const handleGenerateInsights = async () => {
    setIsLoadingInsights(true);
    const result = await generateAccountInsights(account);
    setInsights(result);
    setIsLoadingInsights(false);
  };

  const handleContactSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      onAddContact({
          name: `${newContact.firstName} ${newContact.lastName}`.trim(),
          firstName: newContact.firstName,
          lastName: newContact.lastName,
          title: newContact.title,
          email: newContact.email,
          phone: newContact.phone,
          mobile: newContact.mobile,
          department: newContact.department,
          leadSource: newContact.leadSource,
          company: account.name, // Auto-link to this account
          status: newContact.status,
          inactiveReason: newContact.status === 'Inactive' ? newContact.inactiveReason : undefined
      });
      setIsContactModalOpen(false);
      setNewContact({ firstName: '', lastName: '', title: '', email: '', phone: '', mobile: '', department: '', leadSource: '', status: 'New', inactiveReason: '' });
  };

  const handleContactChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
      setNewContact({ ...newContact, [e.target.name]: e.target.value });
  };

  const renderTabButton = (id: typeof activeTab, label: string, count?: number, icon?: React.ElementType) => {
      const Icon = icon;
      return (
        <button 
            onClick={() => setActiveTab(id)}
            className={`flex items-center gap-2 py-4 px-1 border-b-2 font-medium text-sm transition-all ${
                activeTab === id 
                ? 'border-primary-500 text-primary-600 dark:text-primary-400' 
                : 'border-transparent text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-300'
            }`}
        >
            {Icon && <Icon className="w-4 h-4" />}
            {label}
            {count !== undefined && (
                <span className={`ml-1 text-xs px-2 py-0.5 rounded-full ${activeTab === id ? 'bg-primary-100 text-primary-700 dark:bg-primary-900/30' : 'bg-slate-100 text-slate-600 dark:bg-slate-800'}`}>
                    {count}
                </span>
            )}
        </button>
      );
  };

  // If a contact is selected, show the ContactDetail view
  if (selectedContact) {
      return (
          <ContactDetail 
              contact={selectedContact}
              onBack={() => setSelectedContactId(null)}
              onUpdate={(updated) => {
                  if (onUpdateContact) onUpdateContact(updated);
              }}
          />
      );
  }

  return (
    <div className="bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm h-full flex flex-col animate-fade-in">
      {/* Header */}
      <div className="px-6 pt-6 pb-0 border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-950/50 rounded-t-xl flex-shrink-0">
        <div className="flex justify-between items-start mb-6">
            <div className="flex items-center gap-4">
            <button onClick={onBack} className="p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800 transition-colors group">
                <IconArrowLeft className="w-5 h-5 text-slate-600 dark:text-slate-300 group-hover:-translate-x-1 transition-transform" />
            </button>
            <div>
                <h1 className="text-2xl font-bold text-slate-900 dark:text-white flex items-center gap-2">
                    <IconBuilding className="w-6 h-6 text-primary-600 dark:text-primary-400" />
                    {account.name}
                </h1>
                <p className="text-sm text-slate-500 dark:text-slate-400 mt-1 flex items-center gap-2">
                    {account.industry} 
                    <span className="w-1 h-1 rounded-full bg-slate-300 dark:bg-slate-600"></span>
                    {account.website}
                </p>
            </div>
            </div>
            <div className="flex items-center gap-3">
            <button onClick={onEdit} className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors shadow-sm">
                <IconEdit className="w-4 h-4" /> Edit
            </button>
            <button onClick={onDelete} className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-red-600 bg-red-50 dark:bg-red-500/10 border border-red-200 dark:border-red-500/20 rounded-lg hover:bg-red-100 dark:hover:bg-red-500/20 transition-colors shadow-sm">
                <IconTrash className="w-4 h-4" /> Delete
            </button>
            </div>
        </div>

        {/* Tabs */}
        <div className="flex gap-6 overflow-x-auto">
            {renderTabButton('overview', 'Overview', undefined, IconBriefcase)}
            {renderTabButton('contacts', 'Contacts', relatedContacts.length, IconUsers)}
            {renderTabButton('deals', 'Deals', relatedDeals.length, IconKanban)}
            {renderTabButton('leads', 'Leads', relatedLeads.length, IconTarget)}
        </div>
      </div>

      {/* Body */}
      <div className="flex-1 overflow-y-auto p-8 bg-slate-50/30 dark:bg-[#0b1120]/30 custom-scrollbar">
        <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">

          {/* Main Content Area */}
          <div className="xl:col-span-2 space-y-6">

            {activeTab === 'overview' && (
                <div className="space-y-6 animate-fade-in">
                    <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm">
                        <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-6 flex items-center">
                            <span className="w-1.5 h-1.5 bg-primary-500 rounded-full mr-2.5"></span>
                            Account Information
                        </h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-y-6 gap-x-12">
                            <DetailRow label="Account Owner" value={account.owner} icon={IconUser} />
                            <DetailRow label="Phone" value={account.phone} icon={IconPhone} />
