                    </div>
                </div>

                <div className="p-6 bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm">
                    <div className="flex justify-between items-start mb-4">
                        <div>
                            <h4 className="font-bold text-slate-900 dark:text-white">API Integration</h4>
                            <p className="text-sm text-slate-500 mt-1">Connect your Google Cloud Project to enable Generative AI features.</p>
                        </div>
                        <div className={`px-3 py-1 rounded-full text-xs font-bold border ${isApiKeySet ? 'bg-emerald-50 text-emerald-600 border-emerald-200 dark:bg-emerald-900/20 dark:text-emerald-400 dark:border-emerald-800' : 'bg-amber-50 text-amber-600 border-amber-200 dark:bg-amber-900/20 dark:text-amber-400 dark:border-amber-800'}`}>
                            {isApiKeySet ? 'CONNECTED' : 'NOT CONFIGURED'}
