                    </div>

                    <div className="bg-slate-50 dark:bg-slate-900/50 rounded-lg p-4 border border-slate-200 dark:border-slate-700 mb-4">
                        <div className="flex items-center gap-3">
                            <div className={`p-2 rounded-lg ${isApiKeySet ? 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400' : 'bg-slate-200 text-slate-500 dark:bg-slate-800 dark:text-slate-400'}`}>
                                <IconZap className="w-5 h-5" />
                            </div>
                            <div className="flex-1">
                                <p className="text-sm font-medium text-slate-900 dark:text-white">Google Gemini API</p>
                                <p className="text-xs text-slate-500 dark:text-slate-400">{isApiKeySet ? 'Your application is authenticated and ready to generate content.' : 'Authentication required for AI features.'}</p>
                            </div>
                            <button 
                                onClick={handleConfigureApiKey}
                                className="px-4 py-2 bg-primary-600 hover:bg-primary-500 text-white text-sm font-medium rounded-lg transition-colors shadow-sm"
                            >
                                {isApiKeySet ? 'Change Key' : 'Connect'}
                            </button>
                        </div>
                    </div>

                    <div className="text-xs text-slate-500 dark:text-slate-400">
                        <p>A paid Google Cloud Project is required for advanced features like Video Generation (Veo).</p>
                        <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noopener noreferrer" className="text-primary-600 hover:text-primary-500 hover:underline mt-1 inline-block">
                            View Billing Documentation &rarr;
                        </a>
                    </div>
                </div>
            </div>
        );

      default:
        return <div className="text-slate-500">Select a category</div>;
    }
  };

  const navItemClass = (id: string) => `
    w-full flex items-center px-4 py-3 text-sm font-medium rounded-lg transition-all duration-200 
    ${activeTab === id 
        ? 'bg-primary-50 text-primary-700 dark:bg-primary-900/20 dark:text-primary-400 shadow-sm' 
        : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800 hover:text-slate-900 dark:hover:text-slate-200'}
  `;

  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-[#0f172a] overflow-hidden">
        {/* Header */}
        <div className="px-8 py-6 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center sticky top-0 z-10">
            <div>
                <h1 className="text-2xl font-bold text-slate-900 dark:text-white tracking-tight">Command Center</h1>
                <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">Configure core logic, branding, and regulatory compliance.</p>
            </div>
            <button 
                onClick={handleSave}
                className={`flex items-center gap-2 px-6 py-2.5 font-bold text-sm rounded-lg shadow-lg transition-all active:translate-y-0 hover:-translate-y-0.5 ${isSaved ? 'bg-emerald-500 text-white shadow-emerald-500/30' : 'bg-primary-600 hover:bg-primary-500 text-white shadow-primary-500/30'}`}
            >
                {isSaved ? <IconCheckCircle className="w-4 h-4" /> : <IconSave className="w-4 h-4" />}
                {isSaved ? 'SETTINGS SAVED' : 'UPDATE GLOBAL SETTINGS'}
            </button>
        </div>

        <div className="flex flex-1 overflow-hidden p-8 max-w-7xl mx-auto w-full gap-8">
            {/* Sidebar Navigation */}
            <div className="w-64 flex-shrink-0">
                <nav className="space-y-1">
                    <button onClick={() => setActiveTab('company')} className={navItemClass('company')}>
                        <IconBuilding className="w-5 h-5 mr-3 opacity-70" />
                        Company Profile
                    </button>
                    <button onClick={() => setActiveTab('theme')} className={navItemClass('theme')}>
                        <IconGlobe className="w-5 h-5 mr-3 opacity-70" />
                        Theme & Brand
                    </button>
                    <button onClick={() => setActiveTab('regional')} className={navItemClass('regional')}>
                        <IconGlobe className="w-5 h-5 mr-3 opacity-70" />
                        Regional & Date
                    </button>
                    <button onClick={() => setActiveTab('ai')} className={navItemClass('ai')}>
                        <IconSparkles className="w-5 h-5 mr-3 opacity-70" />
                        AI & Automation
                    </button>
                    <button onClick={() => setActiveTab('notifications')} className={navItemClass('notifications')}>
                        <IconBell className="w-5 h-5 mr-3 opacity-70" />
                        Alerts & Email
                    </button>
                    <button onClick={() => setActiveTab('security')} className={navItemClass('security')}>
                        <IconShield className="w-5 h-5 mr-3 opacity-70" />
                        Security & Access
                    </button>
                </nav>
            </div>

            {/* Content Area */}
            <div className="flex-1 bg-transparent overflow-y-auto custom-scrollbar">
                {renderContent()}
            </div>
        </div>
    </div>
  );
};

export default Settings;

export interface Call {
  id: string;
  subject: string;
  relatedTo: string; // Name of Lead/Contact
  relatedToId: string; // ID of Lead/Contact
  type: 'Inbound' | 'Outbound';
  outcome: 'Connected' | 'Left Voicemail' | 'No Answer' | 'Scheduled Follow-up';
  date: string; // ISO string
  notes: string;
  summary?: string;
}

export enum LeadStatus {
  NEW = 'New',
  CONTACTED = 'Contacted',
  QUALIFIED = 'Qualified',
  PROPOSAL = 'Proposal Sent',
  NEGOTIATION = 'Negotiation',
  CLOSED = 'Closed Won',
  LOST = 'Closed Lost'
}

export interface Lead {
  id: string;
  name: string;
  company: string;
  email: string;
  phone: string;
  status: LeadStatus;
  value: number;
  lastContact: string;
  score: number; // 0-100 AI Score
  scoreBreakdown: {
    fit: number;
    engagement: number;
    budget: number;
  };
  notes: string;
  activities?: Activity[];
  // New fields for enhanced view
  source?: string;
  city?: string;
  industry?: string;
  createdTime?: string;
  lastActivity?: string;
  leadSource?: string; // Specific field for the column

  // Fields for Create Lead form
  firstName?: string;
  lastName?: string;
  title?: string;
  mobile?: string;
  fax?: string;
  website?: string;
  noOfEmployees?: number;
  annualRevenue?: number;
  rating?: 'Acquired' | 'Active' | 'Market Failed' | 'Project Cancelled' | 'Shutdown';
  owner?: string;
}

export interface Activity {
  id: string;
  type: 'stage_change' | 'value_change' | 'probability_change' | 'update' | 'created' | 'email_sent' | 'meeting_scheduled' | 'follow_up' | 'status_change';
  description: string;
  timestamp: string;
}

export interface Deal {
  id: string;
  title: string;
  company: string;
  stage: 'Qualification' | 'Needs Analysis' | 'Value Proposition' | 'Decision Makers' | 'Proposal/Price Quote' | 'Negotiation/Review' | 'Closed Won' | 'Closed Lost';
  value: number;
  probability: number;
  closeDate: string;
  email?: string;
  phone?: string;
  activities: Activity[];
}

export interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

export interface DashboardMetrics {
  totalRevenue: number;
  activeLeads: number;
  conversionRate: number;
  avgDealSize: number;
}

export interface EmailTemplate {
  id: string;
  name: string;
  subject: string;
  body: string;
}

export interface NurtureEmail {
  subject: string;
  body: string;
  delay: string;
}

export interface Task {
  id: string;
  title: string;
  dueDate: string;
  status: 'Not Started' | 'In Progress' | 'Completed' | 'Deferred';
  priority: 'Low' | 'Normal' | 'High';
  relatedTo?: string;
}

export interface Meeting {
  id: string;
  title: string;
  date: string;
  startTime: string;
  endTime: string;
  type: 'Online' | 'Offline';
  relatedTo: string; // Company or Contact name
}

export type ContactStatus = 'New' | 'Active' | 'Inactive';

export interface Contact {
  id: string;
  name: string;
  title: string;
  company: string;
  email: string;
  phone: string;
  lastActivity: string;
  // Extended fields
  firstName?: string;
  lastName?: string;
  leadSource?: string;
  department?: string;
  homePhone?: string;
  otherPhone?: string;
  mobile?: string;
  fax?: string;
  assistant?: string;
  asstPhone?: string;
  dateOfBirth?: string;
  reportingTo?: string;
  emailOptOut?: boolean;
  status?: ContactStatus;
  [key: string]: any; // Allow dynamic fields
}

export interface Account {
  id: string;
  name: string;
  industry: string;
  website: string;
  phone: string;
  owner: string;
}

export interface LayoutField {
    id: string;
    label: string;
    type: string;
    required: boolean;
    isLocked: boolean;
    key: string; // Maps to Contact property key
    value?: string; // Preview value for editor
    isComposite?: boolean;
}

import React, { useState, useMemo, useEffect } from 'react';
import { Deal, Activity } from '../types';
import { IconX, IconMail, IconPhone, IconFilter, IconHistory, IconClock, IconCalendar, IconCheckCircle, IconTarget } from './Icons';

interface PipelineProps {
  deals: Deal[];
  onAddDeal: (deal: Deal) => void;
  onUpdateDeal: (deal: Deal) => void;
  pipelineGoal: number;
  onSetGoal: (goal: number) => void;
}

const Pipeline: React.FC<PipelineProps> = ({ deals, onAddDeal, onUpdateDeal, pipelineGoal, onSetGoal }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isGoalModalOpen, setIsGoalModalOpen] = useState(false);
  const [tempGoal, setTempGoal] = useState(pipelineGoal.toString());

  const [draggedDealId, setDraggedDealId] = useState<string | null>(null);
  const [selectedDeal, setSelectedDeal] = useState<Deal | null>(null);

  const initialFormState = {
    title: '',
    company: '',
    value: '',
    closeDate: '',
    stage: 'Qualification' as Deal['stage'],
    email: '',
    phone: '',
    probability: 50
  };

  const [formData, setFormData] = useState(initialFormState);

  // Sync selectedDeal with deals prop when modal is open to reflect updates immediately
  useEffect(() => {
    if (selectedDeal && isModalOpen) {
      const freshDeal = deals.find(d => d.id === selectedDeal.id);
      if (freshDeal) {
        setSelectedDeal(freshDeal);
      }
    }
  }, [deals, isModalOpen]);

  // Reset form or populate when modal opens/closes or selection changes
  useEffect(() => {
    if (selectedDeal) {
      setFormData({
        title: selectedDeal.title,
        company: selectedDeal.company,
        value: selectedDeal.value.toString(),
        closeDate: selectedDeal.closeDate,
        stage: selectedDeal.stage,
        email: selectedDeal.email || '',
        phone: selectedDeal.phone || '',
        probability: selectedDeal.probability
      });
    } else {
      setFormData(initialFormState);
    }
  }, [selectedDeal]);

  const handleOpenNewDeal = () => {
    setSelectedDeal(null);
    setIsModalOpen(true);
  };

  const handleOpenEditDeal = (deal: Deal) => {
    setSelectedDeal(deal);
    setIsModalOpen(true);
  };

  const handleLogActivity = (type: 'email_sent' | 'meeting_scheduled' | 'follow_up', description: string) => {
    if (!selectedDeal) return;

    const newActivity: Activity = {
      id: Date.now().toString(),
      type,
      description,
      timestamp: new Date().toISOString()
    };

    const updatedDeal: Deal = {
      ...selectedDeal,
      activities: [...(selectedDeal.activities || []), newActivity]
    };

    // Optimistic update for smoother UI
    setSelectedDeal(updatedDeal);
    onUpdateDeal(updatedDeal);
  };

  // Filter States
  const [filterCompany, setFilterCompany] = useState('');
  const [filterDate, setFilterDate] = useState('');

  // Derived Options for Dropdowns
  const uniqueCompanies = useMemo(() => Array.from(new Set(deals.map(d => d.company))).sort(), [deals]);
  const uniqueDates = useMemo(() => Array.from(new Set(deals.map(d => d.closeDate))).sort(), [deals]);

  // Filter Logic
  const filteredDeals = useMemo(() => {
    return deals.filter(deal => {
      const matchesCompany = filterCompany ? deal.company === filterCompany : true;
      const matchesDate = filterDate ? deal.closeDate === filterDate : true;
      return matchesCompany && matchesDate;
    });
  }, [deals, filterCompany, filterDate]);

  const columns = [
    { id: 'Qualification', label: 'Qualification', color: 'bg-slate-500' },
    { id: 'Needs Analysis', label: 'Needs Analysis', color: 'bg-blue-500' },
    { id: 'Value Proposition', label: 'Value Proposition', color: 'bg-indigo-500' },
    { id: 'Decision Makers', label: 'Decision Makers', color: 'bg-purple-500' },
    { id: 'Proposal/Price Quote', label: 'Proposal/Price Quote', color: 'bg-yellow-500' },
    { id: 'Negotiation/Review', label: 'Negotiation/Review', color: 'bg-orange-500' },
    { id: 'Closed Won', label: 'Closed Won', color: 'bg-emerald-500' },
    { id: 'Closed Lost', label: 'Closed Lost', color: 'bg-red-500' },
  ];

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (selectedDeal) {
      // Edit Mode
      const updatedDeal: Deal = {
        ...selectedDeal,
        title: formData.title,
        company: formData.company,
        value: Number(formData.value),
        stage: formData.stage,
        closeDate: formData.closeDate,
        probability: Number(formData.probability),
        email: formData.email,
        phone: formData.phone
      };
      onUpdateDeal(updatedDeal);
    } else {
      // Create Mode
      const newDeal: Deal = {
        id: Date.now().toString(),
        title: formData.title,
        company: formData.company,
        value: Number(formData.value),
        stage: formData.stage,
        closeDate: formData.closeDate || new Date().toISOString().split('T')[0],
        probability: Number(formData.probability),
        email: formData.email,
        phone: formData.phone,
        activities: []
      };
      onAddDeal(newDeal);
    }

    setIsModalOpen(false);
    setSelectedDeal(null);
  };

  const handleSaveGoal = () => {
    const goal = parseFloat(tempGoal);
    if (!isNaN(goal) && goal > 0) {
      onSetGoal(goal);
      setIsGoalModalOpen(false);
    }
  };

  // Drag and Drop Handlers
  const handleDragStart = (e: React.DragEvent, dealId: string) => {
    setDraggedDealId(dealId);
    e.dataTransfer.setData('dealId', dealId);
    e.dataTransfer.effectAllowed = 'move';
    const target = e.target as HTMLElement;
    target.style.opacity = '0.5';
  };

  const handleDragEnd = (e: React.DragEvent) => {
    setDraggedDealId(null);
    const target = e.target as HTMLElement;
    target.style.opacity = '1';
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  };

  const handleDrop = (e: React.DragEvent, stageId: string) => {
    e.preventDefault();
    const dealId = e.dataTransfer.getData('dealId');
    const deal = deals.find(d => d.id === dealId);

    if (deal && deal.stage !== stageId) {
      onUpdateDeal({ ...deal, stage: stageId as Deal['stage'] });
    }
  };

  // Helper functions for Activity Log styling
  const getActivityTypeStyle = (type: Activity['type']) => {
    switch (type) {
      case 'created':
        return 'bg-emerald-100 text-emerald-700 border-emerald-200 dark:bg-emerald-500/10 dark:text-emerald-400 dark:border-emerald-500/20';
      case 'stage_change':
        return 'bg-blue-100 text-blue-700 border-blue-200 dark:bg-blue-500/10 dark:text-blue-400 dark:border-blue-500/20';
      case 'value_change':
        return 'bg-amber-100 text-amber-700 border-amber-200 dark:bg-amber-500/10 dark:text-amber-400 dark:border-amber-500/20';
      case 'probability_change':
        return 'bg-purple-100 text-purple-700 border-purple-200 dark:bg-purple-500/10 dark:text-purple-400 dark:border-purple-500/20';
      case 'email_sent':
        return 'bg-indigo-100 text-indigo-700 border-indigo-200 dark:bg-indigo-500/10 dark:text-indigo-400 dark:border-indigo-500/20';
      case 'meeting_scheduled':
        return 'bg-pink-100 text-pink-700 border-pink-200 dark:bg-pink-500/10 dark:text-pink-400 dark:border-pink-500/20';
      case 'follow_up':
        return 'bg-cyan-100 text-cyan-700 border-cyan-200 dark:bg-cyan-500/10 dark:text-cyan-400 dark:border-cyan-500/20';
      default:
        return 'bg-slate-100 text-slate-700 border-slate-200 dark:bg-slate-800 dark:text-slate-400 dark:border-slate-700';
    }
  };

  const formatActivityType = (type: string) => {
    return type.split('_').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
  };

  return (
    <div className="h-full flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold text-slate-900 dark:text-white">Deal Pipeline</h1>
        <div className="flex gap-3">
          <button
            onClick={() => { setTempGoal(pipelineGoal.toString()); setIsGoalModalOpen(true); }}
            className="flex items-center px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-all"
          >
            <IconTarget className="w-4 h-4 mr-2 text-emerald-500" />
            Set Goal
          </button>
          <button 
            onClick={handleOpenNewDeal}
            className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-all"
          >
            + New Deal
          </button>
        </div>
      </div>

      {/* Filter Bar */}
      <div className="flex flex-wrap items-center gap-4 mb-6 p-4 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm dark:shadow-none transition-colors">
        <div className="flex items-center text-sm font-medium text-slate-500 dark:text-slate-400">
          <IconFilter className="w-4 h-4 mr-2" />
          Filter by:
        </div>

        <select
          value={filterCompany}
          onChange={(e) => setFilterCompany(e.target.value)}
          className="px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm text-slate-700 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-primary-500 transition-colors cursor-pointer"
        >
          <option value="">All Companies</option>
          {uniqueCompanies.map(c => <option key={c} value={c}>{c}</option>)}
        </select>

        <select
          value={filterDate}
          onChange={(e) => setFilterDate(e.target.value)}
          className="px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm text-slate-700 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-primary-500 transition-colors cursor-pointer"
        >
          <option value="">All Dates</option>
          {uniqueDates.map(d => <option key={d} value={d}>{d}</option>)}
        </select>

        {(filterCompany || filterDate) && (
          <button
            onClick={() => { setFilterCompany(''); setFilterDate(''); }}
            className="px-3 py-2 text-sm font-medium text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-500/10 rounded-lg transition-colors"
          >
            Clear Filters
          </button>
        )}
      </div>

      <div className="flex-1 grid grid-cols-1 md:grid-cols-[repeat(8,minmax(300px,1fr))] gap-6 overflow-x-auto pb-4">
        {columns.map((col) => (
          <div 
            key={col.id} 
            onDragOver={handleDragOver}
            onDrop={(e) => handleDrop(e, col.id)}
            className={`flex flex-col h-full min-w-[300px] bg-slate-50 dark:bg-slate-900/50 border border-slate-200 dark:border-slate-800 rounded-xl transition-all duration-300 ${draggedDealId ? 'border-dashed border-slate-300 dark:border-slate-700' : ''}`}
          >
            <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between">
              <h3 className="text-base font-semibold text-slate-900 dark:text-white truncate pr-2">{col.label}</h3>
              <span className="px-2 py-0.5 text-xs font-bold text-slate-700 dark:text-slate-900 bg-slate-200 dark:bg-slate-200 rounded-full flex-shrink-0">
                {filteredDeals.filter(d => d.stage === col.id).length}
              </span>
            </div>
            <div className="p-4 space-y-4 flex-1 overflow-y-auto">
              {filteredDeals.filter(d => d.stage === col.id).map((deal) => (
                <div 
                  key={deal.id} 
                  draggable
                  onDragStart={(e) => handleDragStart(e, deal.id)}
                  onDragEnd={handleDragEnd}
                  onClick={() => handleOpenEditDeal(deal)}
                  className="p-4 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg shadow-sm hover:shadow-md hover:border-primary-300 dark:hover:border-slate-600 transition-all cursor-move group select-none active:cursor-grabbing"
                >
                  <div className="flex justify-between items-start mb-2">
                    <span className="text-sm font-medium text-slate-500 dark:text-slate-400">{deal.company}</span>
                    <div className={`w-2 h-2 rounded-full ${col.color}`}></div>
                  </div>
                  <h4 className="text-base font-semibold text-slate-900 dark:text-white mb-3 group-hover:text-primary-600 dark:group-hover:text-primary-400 transition-colors">{deal.title}</h4>

                  {/* Contact Info */}
                  {(deal.email || deal.phone) && (
                    <div className="mb-3 space-y-1">
                      {deal.email && (
                        <div className="flex items-center text-sm text-slate-500 dark:text-slate-400">
                          <IconMail className="w-3 h-3 mr-1.5 opacity-70" />
                          <span className="truncate max-w-[180px]">{deal.email}</span>
                        </div>
                      )}
                      {deal.phone && (
                        <div className="flex items-center text-sm text-slate-500 dark:text-slate-400">
                          <IconPhone className="w-3 h-3 mr-1.5 opacity-70" />
                          <span>{deal.phone}</span>
                        </div>
                      )}
                    </div>
                  )}

                  <div className="flex justify-between items-center pt-3 border-t border-slate-100 dark:border-slate-700/50">
                    <span className="text-lg font-bold text-slate-700 dark:text-slate-200">${deal.value.toLocaleString()}</span>
                    <div className="flex items-center">
                        <div className="w-16 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full mr-2 overflow-hidden">
                            <div className="h-full bg-primary-500 rounded-full" style={{ width: `${deal.probability}%` }}></div>
                        </div>
                        <span className="text-xs text-slate-500">{deal.probability}%</span>
                    </div>
                  </div>
                </div>
              ))}
              {filteredDeals.filter(d => d.stage === col.id).length === 0 && (
                 <div className="flex items-center justify-center h-24 border-2 border-dashed border-slate-300 dark:border-slate-800 rounded-lg text-slate-500 dark:text-slate-600 text-sm">
                   Drop here
                 </div>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Set Goal Modal */}
      {isGoalModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="w-full max-w-sm bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl shadow-2xl p-6 animate-scale-in">
             <h2 className="text-lg font-bold text-slate-900 dark:text-white mb-4">Set Pipeline Goal</h2>
             <div className="mb-4">
               <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Target Value ($)</label>
               <input 
                 type="number"
                 value={tempGoal}
                 onChange={(e) => setTempGoal(e.target.value)}
                 className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white"
                 placeholder="e.g. 1000000"
               />
             </div>
             <div className="flex gap-3">
               <button 
                 onClick={() => setIsGoalModalOpen(false)}
                 className="flex-1 px-4 py-2 text-sm text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors"
               >
                 Cancel
               </button>
               <button 
                 onClick={handleSaveGoal}
                 className="flex-1 px-4 py-2 text-sm text-white bg-primary-600 rounded-lg hover:bg-primary-500 transition-colors"
               >
                 Save Goal
               </button>
             </div>
          </div>
        </div>
      )}

      {/* New/Edit Deal Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="w-full max-w-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-scale-in">
            <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50">
              <h2 className="text-2xl font-bold text-slate-900 dark:text-white">
                {selectedDeal ? 'Edit Deal' : 'Add New Deal'}
              </h2>
              <button 
                onClick={() => { setIsModalOpen(false); setSelectedDeal(null); }} 
                className="text-slate-400 hover:text-slate-600 dark:hover:text-white transition-colors"
              >
                <IconX className="w-6 h-6" />
              </button>
            </div>

            <div className="overflow-y-auto p-6">
              <form onSubmit={handleSubmit} className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Deal Title</label>
                    <input
                      type="text"
                      name="title"
                      required
                      value={formData.title}
                      onChange={handleInputChange}
                      placeholder="e.g. Enterprise License"
                      className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white"
                    />
                  </div>

                  <div>
                    <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Company</label>
                    <input
                      type="text"
                      name="company"
                      required
                      value={formData.company}
                      onChange={handleInputChange}
                      placeholder="e.g. Acme Corp"
                      className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Email</label>
                    <input
                      type="email"
                      name="email"
                      value={formData.email}
                      onChange={handleInputChange}
                      placeholder="contact@acme.com"
                      className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white"
                    />
                  </div>
                  <div>
                    <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Phone</label>
                    <input
                      type="tel"
                      name="phone"
                      value={formData.phone}
                      onChange={handleInputChange}
                      placeholder="+1 555..."
                      className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Value ($)</label>
                    <input
                      type="number"
                      name="value"
                      required
                      min="0"
                      value={formData.value}
                      onChange={handleInputChange}
                      placeholder="50000"
                      className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white"
                    />
                  </div>
                  <div>
                    <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Close Date</label>
                    <input
                      type="date"
                      name="closeDate"
                      required
                      value={formData.closeDate}
                      onChange={handleInputChange}
                      className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white"
                    />
                  </div>
                </div>

                <div>
                   <div className="flex justify-between items-center mb-1">
                      <label className="block text-base font-medium text-slate-700 dark:text-slate-300">Probability</label>
                      <span className="text-sm font-bold text-primary-600 dark:text-primary-400">{formData.probability}%</span>
                   </div>
                   <input
                     type="range"
                     name="probability"
                     min="0"
                     max="100"
                     step="5"
                     value={formData.probability}
                     onChange={handleInputChange}
                     className="w-full h-2 bg-slate-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-primary-600 focus:outline-none focus:ring-2 focus:ring-primary-500/50"
                   />
                   <div className="flex justify-between text-xs text-slate-400 mt-1">
                      <span>0%</span>
                      <span>50%</span>
                      <span>100%</span>
                   </div>
                </div>

                <div>
                  <label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Stage</label>
                  <select
                    name="stage"
                    value={formData.stage}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white"
                  >
                    <option value="Qualification">Qualification</option>
                    <option value="Needs Analysis">Needs Analysis</option>
                    <option value="Value Proposition">Value Proposition</option>
                    <option value="Decision Makers">Decision Makers</option>
                    <option value="Proposal/Price Quote">Proposal/Price Quote</option>
                    <option value="Negotiation/Review">Negotiation/Review</option>
                    <option value="Closed Won">Closed Won</option>
                    <option value="Closed Lost">Closed Lost</option>
                  </select>
                </div>

                <div className="pt-4 flex space-x-3">
                  <button
                    type="button"
                    onClick={() => { setIsModalOpen(false); setSelectedDeal(null); }}
                    className="flex-1 px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    className="flex-1 px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-colors"
                  >
                    {selectedDeal ? 'Update Deal' : 'Create Deal'}
                  </button>
                </div>
              </form>

              {/* Activity Log Section */}
              {selectedDeal && (
                <div className="mt-8 pt-6 border-t border-slate-200 dark:border-slate-800">
                   {/* Quick Actions for Logging */}
                  <div className="flex gap-2 mb-6">
                    <button 
                      onClick={() => handleLogActivity('email_sent', 'Sent follow-up email')}
                      className="flex-1 flex items-center justify-center px-3 py-2 text-xs font-medium bg-indigo-50 text-indigo-700 dark:bg-indigo-500/10 dark:text-indigo-400 border border-indigo-200 dark:border-indigo-500/20 rounded-lg hover:bg-indigo-100 dark:hover:bg-indigo-500/20 transition-colors"
                    >
                      <IconMail className="w-3 h-3 mr-1.5" /> Email Sent
                    </button>
                    <button 
                      onClick={() => handleLogActivity('meeting_scheduled', 'Scheduled a meeting')}
                      className="flex-1 flex items-center justify-center px-3 py-2 text-xs font-medium bg-pink-50 text-pink-700 dark:bg-pink-500/10 dark:text-pink-400 border border-pink-200 dark:border-pink-500/20 rounded-lg hover:bg-pink-100 dark:hover:bg-pink-500/20 transition-colors"
                    >
                      <IconCalendar className="w-3 h-3 mr-1.5" /> Meeting
                    </button>
                    <button 
                      onClick={() => handleLogActivity('follow_up', 'Completed follow-up task')}
                      className="flex-1 flex items-center justify-center px-3 py-2 text-xs font-medium bg-cyan-50 text-cyan-700 dark:bg-cyan-500/10 dark:text-cyan-400 border border-cyan-200 dark:border-cyan-500/20 rounded-lg hover:bg-cyan-100 dark:hover:bg-cyan-500/20 transition-colors"
                    >
                      <IconCheckCircle className="w-3 h-3 mr-1.5" /> Follow Up
                    </button>
                  </div>

                  <div className="flex items-center mb-4">
                    <IconHistory className="w-5 h-5 text-slate-400 mr-2" />
                    <h3 className="text-sm font-bold text-slate-900 dark:text-white uppercase tracking-wider">Activity Log</h3>
                  </div>

                  <div className="space-y-4 max-h-48 overflow-y-auto pr-2">
                    {selectedDeal.activities && selectedDeal.activities.length > 0 ? (
                      [...selectedDeal.activities].reverse().map((activity) => (
                        <div key={activity.id} className="flex gap-3 text-sm group">
                           <div className="flex flex-col items-center">
                              <div className={`w-2 h-2 rounded-full mt-2 ${
                                activity.type === 'created' ? 'bg-emerald-400' :
                                activity.type === 'stage_change' ? 'bg-blue-400' :
                                activity.type === 'email_sent' ? 'bg-indigo-400' :
                                activity.type === 'meeting_scheduled' ? 'bg-pink-400' :
                                activity.type === 'follow_up' ? 'bg-cyan-400' :
                                'bg-slate-300 dark:bg-slate-600'
                              }`}></div>
                              <div className="w-px h-full bg-slate-200 dark:bg-slate-800 my-1 last:hidden group-last:hidden"></div>
                           </div>
                           <div className="pb-4 w-full">
                             <div className="flex justify-between items-start">
                                <span className={`text-[10px] px-2 py-0.5 rounded-full border font-semibold uppercase tracking-wide mb-1 ${getActivityTypeStyle(activity.type)}`}>
                                 {formatActivityType(activity.type)}
                                </span>
                                <div className="flex items-center text-xs text-slate-400 whitespace-nowrap ml-2">
                                  <IconClock className="w-3 h-3 mr-1" />
                                  {new Date(activity.timestamp).toLocaleString()}
                                </div>
                             </div>
                             <p className="text-slate-700 dark:text-slate-300 mt-1">{activity.description}</p>
                           </div>
                        </div>
                      ))
                    ) : (
                      <p className="text-sm text-slate-500 italic">No activity recorded yet.</p>
                    )}
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

