const ActivityItem: React.FC<{ activity: Activity & { context: string }, isLast: boolean }> = ({ activity, isLast }) => {
    return (
        <div className="flex group relative pl-2">
            {!isLast && <div className="absolute left-[19px] top-8 bottom-0 w-px bg-slate-100 dark:bg-slate-800 group-hover:bg-indigo-100 dark:group-hover:bg-indigo-900/30 transition-colors"></div>}

