                <IconLayoutDashboard className="w-4 h-4" /> / Dashboard
            </div>
            <h1 className="text-3xl font-bold text-slate-900 dark:text-white">Business Overview</h1>
        </div>
        <div className="flex items-center gap-3">
            <span className="text-sm font-medium text-slate-500 bg-white dark:bg-slate-800 px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm">
                Last Updated: {new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
            </span>
            <div className="w-10 h-10 rounded-full bg-slate-200 dark:bg-slate-700 overflow-hidden border-2 border-white dark:border-slate-600 shadow-sm">
                <img src="https://i.pravatar.cc/150?u=a042581f4e29026704d" alt="User" className="w-full h-full object-cover" />
            </div>
        </div>
      </div>

      {/* Row 1: KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-6">
        <BIStatCard 
            title="New Leads (7 Days)" 
            value={newLeadsCount} 
            subtext="Target: 15" 
            icon={IconUsers} 
            colorClass="bg-gradient-to-br from-blue-500 to-blue-600" 
        />
        <BIStatCard 
            title="Active Deals" 
            value={activeDealsCount} 
            subtext="In Pipeline" 
            icon={IconKanban} 
            colorClass="bg-gradient-to-br from-emerald-400 to-emerald-600" 
        />
        <BIStatCard 
