               {selectedLeadIds.size > 0 && (<div className="h-6 w-px bg-slate-300 dark:bg-slate-700 mx-1"></div>)}
               {selectedLeadIds.size > 0 && (<><button onClick={handleBatchAnalyze} className="px-4 py-2 bg-indigo-600 text-white text-sm font-medium rounded-lg hover:bg-indigo-500 transition-colors flex items-center shadow-sm"><IconSparkles className="w-4 h-4 mr-1.5" />Analyze</button><button onClick={handleOpenEmailModal} className="px-4 py-2 bg-emerald-600 text-white text-sm font-medium rounded-lg hover:bg-emerald-500 transition-colors flex items-center shadow-sm"><IconMail className="w-4 h-4 mr-1.5" />Email</button><button onClick={handleDeleteSelected} className="px-4 py-2 bg-red-600 text-white text-sm font-medium rounded-lg hover:bg-red-500 transition-colors flex items-center shadow-sm"><IconTrash className="w-4 h-4 mr-1.5" />Delete</button></>)}
