              </tbody>
            </table>
          </div>
          {totalPages > 1 && (<div className="p-4 border-t border-slate-200 dark:border-slate-800 flex justify-between items-center text-sm bg-slate-50 dark:bg-slate-900/50"><div className="text-slate-600 dark:text-slate-400">Showing <span className="font-semibold">{paginatedLeads.length}</span> of {sortedLeads.length} results</div><div className="flex items-center gap-2"><button disabled={currentPage === 1} onClick={() => setCurrentPage(c => c - 1)} className="px-3 py-1.5 border border-slate-200 dark:border-slate-700 rounded-lg hover:bg-white dark:hover:bg-slate-800 disabled:opacity-50 transition-colors">Prev</button><span className="text-slate-500 dark:text-slate-400">Page {currentPage} of {totalPages}</span><button disabled={currentPage === totalPages} onClick={() => setCurrentPage(c => c + 1)} className="px-3 py-1.5 border border-slate-200 dark:border-slate-700 rounded-lg hover:bg-white dark:hover:bg-slate-800 disabled:opacity-50 transition-colors">Next</button></div></div>)}
