bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white" /></div><div><label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-2">AI Actions</label><div className="flex items-center gap-2"><div className="flex items-center p-1 bg-slate-100 dark:bg-slate-800 rounded-lg">{(['formal', 'casual', 'persuasive'] as const).map(t => (<button key={t} type="button" onClick={() => setEmailTone(t)} className={`px-3 py-1 text-sm font-medium rounded-md transition-colors ${emailTone === t ? 'bg-white dark:bg-slate-700 text-primary-600 dark:text-white shadow-sm' : 'text-slate-500 hover:bg-slate-200/50 dark:hover:bg-slate-700/50'}`}>{t.charAt(0).toUpperCase() + t.slice(1)}</button>))}</div><button type="button" onClick={handleAIDraft} disabled={isDraftingAI} className="flex items-center px-4 py-1.5 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-sm transition-colors disabled:opacity-50"><IconSparkles className="w-4 h-4 mr-2" />{isDraftingAI ? 'Drafting...' : 'Draft with AI'}</button></div></div><div><label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Body</label><textarea value={emailBody} onChange={(e) => setEmailBody(e.target.value)} rows={10} placeholder={isDraftingAI ? "Nova is thinking..." : "Your email body will appear here..."} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white font-mono text-base" /></div><div className="pt-2"><div className="flex items-center"><input type="checkbox" id="schedule-email" checked={isSchedulingEmail} onChange={(e) => setIsSchedulingEmail(e.target.checked)} className="w-4 h-4 text-primary-600 bg-slate-100 border-slate-300 rounded focus:ring-primary-500 dark:focus:ring-primary-600 dark:ring-offset-slate-800 focus:ring-2 dark:bg-slate-700 dark:border-slate-600" /><label htmlFor="schedule-email" className="ml-2 text-sm font-medium text-slate-700 dark:text-slate-300">Schedule for later</label></div>{isSchedulingEmail && (<div className="mt-2 animate-fade-in"><input type="datetime-local" value={scheduleDateTime} onChange={(e) => setScheduleDateTime(e.target.value)} className="w-full md:w-1/2 px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white" /></div>)}</div></div><div className="p-6 border-t border-slate-200 dark:border-slate-800 flex justify-end gap-3 bg-slate-50 dark:bg-slate-800/50"><button type="button" onClick={closeEmailModal} className="px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">Cancel</button><button onClick={handleSendEmail} className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-colors flex items-center">{isSchedulingEmail ? <IconClock className="w-4 h-4 mr-2" /> : <IconSend className="w-4 h-4 mr-2" />}{isSchedulingEmail ? 'Schedule Email' : 'Send Email'}</button></div></div></div>}
      {isNurtureModalOpen && <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm"><div className="w-full max-w-3xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-scale-in"><div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50"><h2 className="text-xl font-bold text-slate-900 dark:text-white flex items-center"><IconBot className="w-5 h-5 mr-3 text-primary-500" />AI Nurture Sequence</h2><button onClick={closeNurtureModal} className="text-slate-400 hover:text-slate-600 dark:hover:text-white"><IconX className="w-6 h-6" /></button></div><div className="p-6 overflow-y-auto">{isNurturing ? (<div className="flex flex-col items-center justify-center h-64 text-center"><IconSparkles className="w-12 h-12 text-primary-500 animate-pulse" /><p className="mt-4 text-slate-600 dark:text-slate-300">Generating personalized sequence for {selectedLead?.name}...</p></div>) : nurtureSequence ? (<div className="space-y-4">{nurtureSequence.map((email, index) => (<div key={index} className="border border-slate-200 dark:border-slate-800 rounded-lg overflow-hidden"><button onClick={() => setActiveNurtureAccordion(activeNurtureAccordion === index ? null : index)} className="w-full flex justify-between items-center p-4 bg-slate-50 dark:bg-slate-800/50 hover:bg-slate-100 dark:hover:bg-slate-800"><div className="font-medium text-slate-900 dark:text-white"><span className="text-primary-600 dark:text-primary-400">Step {index + 1}:</span> {email.delay} - {email.subject}</div><IconChevronDown className={`w-5 h-5 text-slate-500 transition-transform ${activeNurtureAccordion === index ? 'rotate-180' : ''}`} /></button>{activeNurtureAccordion === index && (<div className="p-4 border-t border-slate-200 dark:border-slate-800 animate-fade-in"><p className="text-sm text-slate-600 dark:text-slate-400 whitespace-pre-wrap font-mono">{email.body}</p></div>)}</div>))}</div>) : null}</div><div className="p-6 border-t border-slate-200 dark:border-slate-800 flex justify-end gap-3 bg-slate-50 dark:bg-slate-800/50"><button type="button" onClick={closeNurtureModal} className="px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">Close</button><button className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-colors flex items-center"><IconSend className="w-4 h-4 mr-2" />Start Sequence</button></div></div></div>}
    </>
  );
};

export default Leads;

import React, { useState, useEffect } from 'react';
import { Lead } from '../types';
import { 
  IconArrowLeft, 
  IconEdit, 
  IconTrash, 
  IconMail, 
  IconPhone, 
  IconBuilding, 
  IconSparkles, 
  IconInfo, 
  IconGlobe, 
  IconUsers, 
  IconBot, 
  IconUser,
  IconMessageSquare,
  IconCopy
} from './Icons';
import { generateFollowUpSuggestions } from '../services/geminiService';

interface LeadDetailProps {
  lead: Lead;
  onBack: () => void;
  onEdit: () => void;
  onDelete: () => void;
  onNurture: () => void;
  isNurturing: boolean;
  leads: Lead[];
  onComposeEmail: (lead: Lead, initialContent: string) => void;
}

const DetailRow: React.FC<{ label: string; value?: string | number | null; icon?: React.ElementType }> = ({ label, value, icon: Icon }) => {
  if (!value && value !== 0) return null;
  return (
    <div>
      <label className="text-sm text-slate-500 dark:text-slate-400 uppercase tracking-wider">{label}</label>
      <p className="text-lg text-slate-900 dark:text-slate-100 flex items-center mt-1">
        {Icon && <Icon className="w-4 h-4 mr-2 text-slate-400" />}
        {value}
      </p>
    </div>
  );
};

const LeadDetail: React.FC<LeadDetailProps> = ({ lead, onBack, onEdit, onDelete, onNurture, isNurturing, leads, onComposeEmail }) => {
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [isLoadingSuggestions, setIsLoadingSuggestions] = useState(true);

  useEffect(() => {
    let isMounted = true;
    const fetchSuggestions = async () => {
      setIsLoadingSuggestions(true);
      const result = await generateFollowUpSuggestions(lead);
      if (isMounted) {
        setSuggestions(result);
        setIsLoadingSuggestions(false);
      }
    };

    fetchSuggestions();

    return () => {
      isMounted = false;
    };
  }, [lead]);

  const similarLeads = leads.filter(l => 
    l.id !== lead.id &&
    (l.industry === lead.industry || l.company === lead.company) &&
    l.score > 70
  ).sort((a, b) => b.score - a.score).slice(0, 3);

  return (
    <div className="bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm h-full flex flex-col animate-fade-in">
      {/* Header */}
      <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-950/50 rounded-t-xl flex-shrink-0">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800 transition-colors">
            <IconArrowLeft className="w-5 h-5 text-slate-600 dark:text-slate-300" />
          </button>
          <div>
            <h1 className="text-3xl font-bold text-slate-900 dark:text-white">{lead.name}</h1>
            <p className="text-lg text-slate-500 dark:text-slate-400">{lead.company}</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <button 
            onClick={onNurture}
            disabled={isNurturing}
            className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-md hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-colors disabled:opacity-70 disabled:cursor-not-allowed"
          >
            <IconBot className="w-4 h-4" /> 
            {isNurturing ? 'Generating...' : 'Nurture'}
          </button>
          <button onClick={onEdit} className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-md hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">
            <IconEdit className="w-4 h-4" /> Edit
          </button>
          <button onClick={onDelete} className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-red-600 bg-red-50 dark:bg-red-500/10 border border-red-200 dark:border-red-500/20 rounded-md hover:bg-red-100 dark:hover:bg-red-500/20 transition-colors">
            <IconTrash className="w-4 h-4" /> Delete
          </button>
        </div>
      </div>

      {/* Body */}
      <div className="flex-1 overflow-y-auto p-8">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Main Details Column */}
          <div className="lg:col-span-2 space-y-8">
            <div className="p-6 bg-slate-50 dark:bg-slate-800/50 rounded-lg border border-slate-200 dark:border-slate-800">
              <h3 className="text-xl font-semibold text-slate-900 dark:text-white mb-6">Lead Information</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <DetailRow label="Lead Owner" value={lead.owner} icon={IconUser} />
                <DetailRow label="First Name" value={lead.firstName || lead.name.split(' ')[0]} />
                <DetailRow label="Last Name" value={lead.lastName || lead.name.split(' ').slice(1).join(' ')} />
                <DetailRow label="Company" value={lead.company} icon={IconBuilding} />
                <DetailRow label="Title" value={lead.title} />
                <DetailRow label="Lead Source" value={lead.leadSource} />
                <DetailRow label="Industry" value={lead.industry} />
                <DetailRow label="Annual Revenue" value={lead.annualRevenue ? `$${lead.annualRevenue.toLocaleString()}`: null} />
                <DetailRow label="Status" value={lead.status} />
              </div>
            </div>

            <div className="p-6 bg-slate-50 dark:bg-slate-800/50 rounded-lg border border-slate-200 dark:border-slate-800">
              <h3 className="text-xl font-semibold text-slate-900 dark:text-white mb-6">Contact Details</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <DetailRow label="Email" value={lead.email} icon={IconMail} />
                <DetailRow label="Phone" value={lead.phone} icon={IconPhone} />
                <DetailRow label="Mobile" value={lead.mobile} />
                <DetailRow label="Website" value={lead.website} icon={IconGlobe} />
                <DetailRow label="City" value={lead.city} />
              </div>
            </div>

            {/* AI Follow-up Suggestions */}
            <div className="p-6 bg-slate-50 dark:bg-slate-800/50 rounded-lg border border-slate-200 dark:border-slate-800">
              <h3 className="text-xl font-semibold text-slate-900 dark:text-white mb-6 flex items-center">
                <IconSparkles className="w-5 h-5 mr-2 text-primary-500" />
                AI Follow-up Suggestions
              </h3>
              {isLoadingSuggestions ? (
                <div className="space-y-4 animate-pulse">
                  <div className="h-4 bg-slate-200 dark:bg-slate-700 rounded w-5/6"></div>
                  <div className="h-4 bg-slate-200 dark:bg-slate-700 rounded w-full"></div>
                  <div className="h-4 bg-slate-200 dark:bg-slate-700 rounded w-4/6"></div>
                </div>
              ) : (
                <div className="space-y-4">
                  {suggestions.map((suggestion, index) => (
                    <div key={index} className="flex items-start gap-3 group">
                      <IconMessageSquare className="w-4 h-4 text-slate-400 mt-1 flex-shrink-0" />
                      <p className="flex-1 text-base text-slate-700 dark:text-slate-300">
                        {suggestion}
                      </p>
                      <div className="flex flex-col gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button 
                            onClick={() => onComposeEmail(lead, suggestion)}
                            className="p-1.5 rounded-md text-primary-600 bg-primary-50 hover:bg-primary-100 dark:text-primary-400 dark:bg-primary-900/30 dark:hover:bg-primary-900/50 transition-colors"
                            title="Draft Email"
                        >
                            <IconMail className="w-4 h-4" />
                        </button>
                        <button 
                            onClick={() => navigator.clipboard.writeText(suggestion)}
                            className="p-1.5 rounded-md text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors"
                            title="Copy suggestion"
                        >
                            <IconCopy className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

             {similarLeads.length > 0 && (
              <div className="p-6 bg-slate-50 dark:bg-slate-800/50 rounded-lg border border-slate-200 dark:border-slate-800">
                <h3 className="text-xl font-semibold text-slate-900 dark:text-white mb-6">Similar High-Potential Leads</h3>
                <div className="space-y-4">
                  {similarLeads.map(similarLead => (
                    <div key={similarLead.id} className="flex justify-between items-center p-3 bg-white dark:bg-slate-800 rounded-md border border-slate-200 dark:border-slate-700">
                      <div>
                        <p className="font-medium text-slate-800 dark:text-slate-100">{similarLead.name}</p>
                        <p className="text-sm text-slate-500 dark:text-slate-400">{similarLead.company}</p>
                      </div>
                      <div className="flex items-center gap-2">
                        <div className="w-12 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden">
                           <div className="h-full bg-emerald-500" style={{width: `${similarLead.score}%`}}></div>
                        </div>
                        <span className="text-sm font-bold text-emerald-600 dark:text-emerald-400">{similarLead.score}</span>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* AI Score Column */}
          <div className="space-y-6">
            <div className="p-6 bg-gradient-to-br from-primary-50 to-blue-50 dark:from-slate-800 dark:to-slate-800/50 rounded-lg border border-slate-200 dark:border-slate-800">
               <h3 className="text-xl font-semibold text-slate-900 dark:text-white mb-4 flex items-center">
                 <IconSparkles className="w-5 h-5 mr-2 text-primary-500" />
                 AI Scoring
               </h3>
               <div className="flex items-center justify-between mb-2">
                 <span className="text-base text-slate-600 dark:text-slate-300">Overall Score</span>
                 <span className="text-5xl font-bold text-primary-600 dark:text-primary-400">{lead.score}</span>
               </div>
               <div className="w-full bg-slate-200 dark:bg-slate-700 rounded-full h-2.5 mb-6">
                  <div className={`h-2.5 rounded-full ${
                      lead.score > 75 ? 'bg-emerald-500' :
                      lead.score > 40 ? 'bg-yellow-500' :
                      'bg-slate-400'
                  }`} style={{ width: `${lead.score}%` }}></div>
               </div>

               <div className="space-y-4">
                 <div className="flex justify-between items-center text-base">
                   <span className="text-slate-500 dark:text-slate-400">Profile Fit</span>
                   <span className="font-semibold text-emerald-600 dark:text-emerald-400">{lead.scoreBreakdown.fit}%</span>
                 </div>
                  <div className="flex justify-between items-center text-base">
                   <span className="text-slate-500 dark:text-slate-400">Engagement</span>
                   <span className="font-semibold text-primary-600 dark:text-primary-400">{lead.scoreBreakdown.engagement}%</span>
                 </div>
                  <div className="flex justify-between items-center text-base">
                   <span className="text-slate-500 dark:text-slate-400">Budget</span>
                   <span className="font-semibold text-blue-600 dark:text-blue-400">{lead.scoreBreakdown.budget}%</span>
                 </div>
               </div>
            </div>
             <div className="p-6 bg-slate-50 dark:bg-slate-800/50 rounded-lg border border-slate-200 dark:border-slate-800">
              <h3 className="text-xl font-semibold text-slate-900 dark:text-white mb-4">Notes</h3>
              <p className="text-base text-slate-600 dark:text-slate-300 italic">
                {lead.notes || "No notes available for this lead."}
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LeadDetail;

import React, { useState, useMemo, useEffect } from 'react';
import { Lead, EmailTemplate, NurtureEmail, LeadStatus } from '../types';
import { MOCK_TEMPLATES } from '../constants';
import LeadForm from './LeadForm'; 
import LeadDetail from './LeadDetail';
import { 
  IconSearch, 
  IconChevronDown, 
  IconChevronRight, 
  IconSparkles, 
  IconMail,
  IconSend,
  IconX,
  IconTrash,
  IconBot,
  IconClock,
  IconArrowUp,
  IconArrowDown,
  IconFunnel
} from './Icons';
import { generateSmartFilterCriteria, batchAnalyzeLeads, generateAIBulkEmail, generateNurtureSequence } from '../services/geminiService';

interface LeadsProps {
  leads: Lead[];
  onAddLead: (leadData: Omit<Lead, 'id'>) => void;
  onUpdateLead: (lead: Lead) => void;
  onDeleteLeads: (leadIds: string[]) => void;
}

type ViewMode = 'list' | 'create' | 'edit' | 'detail';
type SortKey = keyof Lead;
type SortDirection = 'asc' | 'desc';

const FilterCheckbox: React.FC<{ label: string; count?: number; filterKey?: string; checked: boolean; onChange: (checked: boolean) => void; }> = ({ label, count, filterKey, checked, onChange }) => {
  const checkboxId = `filter-${filterKey || label}`;
  return (
    <div className="flex items-center group cursor-pointer py-1">
      <input type="checkbox" id={checkboxId} className="w-4 h-4 rounded border-slate-300 text-primary-600 focus:ring-primary-500 bg-white dark:bg-slate-800 dark:border-slate-700 cursor-pointer" onChange={(e) => onChange(e.target.checked)} checked={checked} />
      <label htmlFor={checkboxId} className="ml-2 text-sm text-slate-600 dark:text-slate-300 group-hover:text-primary-600 dark:group-hover:text-primary-400 transition-colors cursor-pointer flex-1 truncate">{label}</label>
      {count !== undefined && <span className="ml-auto text-xs text-slate-400 bg-slate-100 dark:bg-slate-800 px-1.5 py-0.5 rounded-full">{count}</span>}
    </div>
  );
};

const Leads: React.FC<LeadsProps> = ({ leads, onAddLead, onUpdateLead, onDeleteLeads }) => {
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [selectedLead, setSelectedLead] = useState<Lead | null>(null);
  const [expandedSections, setExpandedSections] = useState<Record<string, boolean>>({'source': true, 'status': true});

  // Filtering, Sorting, and Pagination State
  const [searchQuery, setSearchQuery] = useState('');
  const [smartFilterQuery, setSmartFilterQuery] = useState('');
  const [isProcessingAI, setIsProcessingAI] = useState(false);
  const [selectedFilters, setSelectedFilters] = useState<Record<string, boolean>>({});
  const [aiFilters, setAiFilters] = useState<any[]>([]);
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: SortDirection } | null>({ key: 'score', direction: 'desc' });
  const [currentPage, setCurrentPage] = useState(1);
  const [recordsPerPage, setRecordsPerPage] = useState(10);

  const [selectedLeadIds, setSelectedLeadIds] = useState<Set<string>>(new Set());
  const [batchAnalysisResult, setBatchAnalysisResult] = useState<string | null>(null);
  const [isEmailModalOpen, setIsEmailModalOpen] = useState(false);
  const [emailSubject, setEmailSubject] = useState('');
  const [emailBody, setEmailBody] = useState('');
  const [emailTone, setEmailTone] = useState<'formal' | 'casual' | 'persuasive'>('persuasive');
  const [isDraftingAI, setIsDraftingAI] = useState(false);
  const [previewLeadName, setPreviewLeadName] = useState<string | null>(null);
  const [isSchedulingEmail, setIsSchedulingEmail] = useState(false);
  const [scheduleDateTime, setScheduleDateTime] = useState('');
  const [isNurtureModalOpen, setIsNurtureModalOpen] = useState(false);
  const [nurtureSequence, setNurtureSequence] = useState<NurtureEmail[] | null>(null);
  const [isNurturing, setIsNurturing] = useState(false);
  const [activeNurtureAccordion, setActiveNurtureAccordion] = useState<number | null>(0);

  // Move useMemo hooks to the top level, before any conditional returns
  const uniqueLeadSources = useMemo(() => Array.from(new Set(leads.map(l => l.leadSource).filter(Boolean))).sort(), [leads]);
  const uniqueStatuses = useMemo(() => Object.values(LeadStatus), []);
  const uniqueIndustries = useMemo(() => Array.from(new Set(leads.map(l => l.industry).filter(Boolean))).sort(), [leads]);
  const uniqueRatings = useMemo(() => Array.from(new Set(leads.map(l => l.rating).filter(Boolean))).sort(), [leads]);

  const applyAIFilters = (lead: Lead, filters: any[]) => {
      if (!filters || filters.length === 0) return true;
      return filters.every(filter => {
          const leadValue = lead[filter.field as keyof Lead] as any;
          if (leadValue === undefined) return false;
          const filterValue = isNaN(Number(filter.value)) ? filter.value : Number(filter.value);
          const leadValueNormalized = typeof leadValue === 'string' ? leadValue.toLowerCase() : leadValue;
          const filterValueNormalized = typeof filterValue === 'string' ? filterValue.toLowerCase() : filterValue;

          switch (filter.operator) {
              case '$gt': return leadValueNormalized > filterValueNormalized;
              case '$lt': return leadValueNormalized < filterValueNormalized;
              case '$eq': return leadValueNormalized == filterValueNormalized;
              case '$contains': return typeof leadValueNormalized === 'string' && leadValueNormalized.includes(filterValueNormalized as string);
              default: return true;
          }
      });
  };

  const filteredLeads = useMemo(() => {
    const query = searchQuery.toLowerCase();
    const activeSourceFilters = uniqueLeadSources.filter(source => selectedFilters[`Source: ${source}`]);
    const activeStatusFilters = uniqueStatuses.filter(status => selectedFilters[`Status: ${status}`]);
    const activeIndustryFilters = uniqueIndustries.filter(industry => selectedFilters[`Industry: ${industry}`]);
    const activeRatingFilters = uniqueRatings.filter(rating => selectedFilters[`Rating: ${rating}`]);

    return leads.filter(lead => {
      const matchesSearch = !query || ['name', 'company', 'email', 'leadSource', 'city'].some(field => lead[field as keyof Lead]?.toString().toLowerCase().includes(query));

      const matchesSource = activeSourceFilters.length === 0 || (lead.leadSource && activeSourceFilters.includes(lead.leadSource));
      const matchesStatus = activeStatusFilters.length === 0 || (lead.status && activeStatusFilters.includes(lead.status));
      const matchesIndustry = activeIndustryFilters.length === 0 || (lead.industry && activeIndustryFilters.includes(lead.industry));
      const matchesRating = activeRatingFilters.length === 0 || (lead.rating && activeRatingFilters.includes(lead.rating));

      const matchesAI = applyAIFilters(lead, aiFilters);

      return matchesSearch && matchesSource && matchesStatus && matchesIndustry && matchesRating && matchesAI;
    });
  }, [leads, searchQuery, selectedFilters, uniqueLeadSources, uniqueStatuses, uniqueIndustries, uniqueRatings, aiFilters]);


  const sortedLeads = useMemo(() => {
    let sortableItems = [...filteredLeads];
    if (sortConfig !== null) {
      sortableItems.sort((a, b) => {
        const aValue = a[sortConfig.key];
        const bValue = b[sortConfig.key];
        if (aValue === undefined || aValue < bValue) return sortConfig.direction === 'asc' ? -1 : 1;
        if (bValue === undefined || aValue > bValue) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
      });
    }
    return sortableItems;
  }, [filteredLeads, sortConfig]);

  const handleViewLeadDetail = (lead: Lead) => { setSelectedLead(lead); setViewMode('detail'); };
  const handleCreateNewLead = () => { setSelectedLead(null); setViewMode('create'); };
  const handleEditLead = (lead: Lead) => { setSelectedLead(lead); setViewMode('edit'); };
  const handleCancelForm = () => { setSelectedLead(null); setViewMode('list'); };
  const handleBackToList = () => { setSelectedLead(null); setViewMode('list'); };

  useEffect(() => {
    setSelectedLeadIds(new Set()); // Reset selection when filters or page change
  }, [searchQuery, selectedFilters, aiFilters, currentPage, recordsPerPage]);


  const handleSaveLead = (leadData: Lead) => {
    if (viewMode === 'edit' && selectedLead) {
      onUpdateLead({ ...selectedLead, ...leadData });
    } else {
      onAddLead(leadData);
    }
    setViewMode('list');
    setSelectedLead(null);
  };

  const handleDeleteSelected = () => {
    if (selectedLeadIds.size === 0) return;
    if (window.confirm(`Are you sure you want to delete ${selectedLeadIds.size} selected lead(s)?`)) {
      onDeleteLeads(Array.from(selectedLeadIds));
      setSelectedLeadIds(new Set());
    }
  };

  const handleDeleteFromDetail = (leadId: string) => {
     if (window.confirm(`Are you sure you want to delete this lead?`)) {
      onDeleteLeads([leadId]);
      setViewMode('list');
      setSelectedLead(null);
    }
  };

  const handleNurtureLead = async (lead: Lead) => {
    setIsNurturing(true);
    setNurtureSequence(null);
    setActiveNurtureAccordion(0);
    setIsNurtureModalOpen(true);
    const sequence = await generateNurtureSequence(lead);
    setNurtureSequence(sequence);
    setIsNurturing(false);
  };

  const closeNurtureModal = () => {
    setIsNurtureModalOpen(false);
    setNurtureSequence(null);
  };

  const toggleSection = (section: string) => setExpandedSections(prev => ({ ...prev, [section]: !prev[section] }));
  const toggleSelection = (id: string) => {
    const newSelected = new Set(selectedLeadIds);
    newSelected.has(id) ? newSelected.delete(id) : newSelected.add(id);
    setSelectedLeadIds(newSelected);
  };

  const handleSmartFilter = async () => {
    if (!smartFilterQuery.trim()) { setAiFilters([]); return; }
    setIsProcessingAI(true);
    setSearchQuery('');
    const criteria = await generateSmartFilterCriteria(smartFilterQuery);
    setAiFilters(criteria.filters || []);
    setIsProcessingAI(false);
    setCurrentPage(1);
  };

  const handleBatchAnalyze = async () => {
    if (selectedLeadIds.size === 0) return;
    setIsProcessingAI(true);
    const selectedLeads = leads.filter(l => selectedLeadIds.has(l.id));
    const result = await batchAnalyzeLeads(selectedLeads);
    setBatchAnalysisResult(result);
    setIsProcessingAI(false);
  };

  const handleOpenEmailModal = () => { if (selectedLeadIds.size > 0) setIsEmailModalOpen(true); };
  const closeEmailModal = () => { setIsEmailModalOpen(false); setEmailSubject(''); setEmailBody(''); setPreviewLeadName(null); setIsSchedulingEmail(false); setScheduleDateTime(''); };

  // Trigger from LeadDetail to open email modal with specific content
  const handleDirectEmail = (lead: Lead, content: string) => {
    setSelectedLeadIds(new Set([lead.id]));
    // Pre-resolve merge tags for direct send
    const resolvedBody = content
        .replace(/{{name}}/g, lead.name)
        .replace(/{{company}}/g, lead.company);

    setEmailBody(resolvedBody);
    setEmailSubject(`Follow-up: ${lead.company}`);
    setPreviewLeadName(lead.name);
    setIsEmailModalOpen(true);
  };

  const handleTemplateChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const templateId = e.target.value;
    if (!templateId) { setEmailSubject(''); setEmailBody(''); setPreviewLeadName(null); return; }
    const template = MOCK_TEMPLATES.find(t => t.id === templateId);
    if (!template) return;
    const previewLead = leads.find(l => l.id === Array.from(selectedLeadIds)[0]);
    if (previewLead) {
      setPreviewLeadName(previewLead.name);
      setEmailSubject(template.subject.replace(/{{name}}/g, previewLead.name).replace(/{{company}}/g, previewLead.company));
      setEmailBody(template.body.replace(/{{name}}/g, previewLead.name).replace(/{{company}}/g, previewLead.company));
    } else {
      setPreviewLeadName(null);
      setEmailSubject(template.subject.replace(/{{.+?}}/g, '[Variable]'));
      setEmailBody(template.body.replace(/{{name}}/g, '[Lead Name]').replace(/{{company}}/g, '[Company Name]'));
    }
  };

  const handleAIDraft = async () => {
    if (selectedLeadIds.size === 0) return;
    setIsDraftingAI(true);
    const selectedLeads = leads.filter(l => selectedLeadIds.has(l.id));
    const result = await generateAIBulkEmail(selectedLeads, emailTone, emailBody);
    setEmailBody(result);
    setIsDraftingAI(false);
  };

  const handleSendEmail = () => {
    const message = isSchedulingEmail ? `Email scheduled for ${new Date(scheduleDateTime).toLocaleString()}` : `Email successfully sent`;
    alert(`${message} to ${selectedLeadIds.size} selected leads!`);
    closeEmailModal();
  };

  const paginatedLeads = sortedLeads.slice((currentPage - 1) * recordsPerPage, currentPage * recordsPerPage);
  const totalPages = Math.ceil(sortedLeads.length / recordsPerPage);

  const toggleSelectAll = () => {
    if (selectedLeadIds.size === paginatedLeads.length) setSelectedLeadIds(new Set());
    else setSelectedLeadIds(new Set(paginatedLeads.map(l => l.id)));
  };

  const requestSort = (key: SortKey) => {
    let direction: SortDirection = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') direction = 'desc';
    setSortConfig({ key, direction });
  };

  const getSortIcon = (key: SortKey) => {
    if (!sortConfig || sortConfig.key !== key) return <span className="w-3 h-3 opacity-0 group-hover:opacity-50 transition-opacity">↕️</span>;
    if (sortConfig.direction === 'asc') return <IconArrowUp className="w-3 h-3 text-primary-500" />;
    return <IconArrowDown className="w-3 h-3 text-primary-500" />;
  };

  // Helper for Status Badge Color
  const getStatusStyle = (status: string) => {
    switch(status) {
        case LeadStatus.NEW: return 'bg-blue-50 text-blue-700 border-blue-200 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-800/30';
        case LeadStatus.CONTACTED: return 'bg-primary-50 text-primary-700 border-primary-200 dark:bg-primary-900/20 dark:text-primary-400 dark:border-primary-800/30';
        case LeadStatus.QUALIFIED: return 'bg-indigo-50 text-indigo-700 border-indigo-200 dark:bg-indigo-900/20 dark:text-indigo-400 dark:border-indigo-800/30';
        case LeadStatus.PROPOSAL: return 'bg-amber-50 text-amber-700 border-amber-200 dark:bg-amber-900/20 dark:text-amber-400 dark:border-amber-800/30';
        case LeadStatus.NEGOTIATION: return 'bg-orange-50 text-orange-700 border-orange-200 dark:bg-orange-900/20 dark:text-orange-400 dark:border-orange-800/30';
        case LeadStatus.CLOSED: return 'bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-900/20 dark:text-emerald-400 dark:border-emerald-800/30';
        case LeadStatus.LOST: return 'bg-slate-50 text-slate-600 border-slate-200 dark:bg-slate-800 dark:text-slate-400 dark:border-slate-700';
        default: return 'bg-slate-50 text-slate-600 border-slate-200';
    }
  };

  const getInitials = (name: string) => {
    return name.split(' ').map(n => n[0]).join('').substring(0, 2).toUpperCase();
  };

  const getScoreColor = (score: number) => {
      if (score >= 80) return 'text-emerald-500';
      if (score >= 50) return 'text-yellow-500';
      return 'text-red-500';
  };

  const renderView = () => {
    if (viewMode === 'create' || viewMode === 'edit') {
        return <LeadForm onCancel={handleCancelForm} onSave={handleSaveLead} initialData={selectedLead} />;
    }
    if (viewMode === 'detail' && selectedLead) {
        return <LeadDetail lead={selectedLead} onBack={handleBackToList} onEdit={() => handleEditLead(selectedLead)} onDelete={() => handleDeleteFromDetail(selectedLead.id)} onNurture={() => handleNurtureLead(selectedLead)} isNurturing={isNurturing} leads={leads} onComposeEmail={handleDirectEmail} />;
    }
    return (
        <div className="flex flex-col md:flex-row h-full gap-4 md:gap-6">
            {/* Filters Sidebar */}
            <div className="w-full md:w-64 flex-shrink-0 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden flex flex-col h-full animate-fade-in">
            <div className="p-4 border-b border-slate-100 dark:border-slate-800 flex items-center gap-2 bg-slate-50/50 dark:bg-slate-800/30">
                <IconFunnel className="w-4 h-4 text-primary-500" />
                <h2 className="text-sm font-bold text-slate-800 dark:text-slate-200 uppercase tracking-wide">Smart Filters</h2>
            </div>
            <div className="flex-1 overflow-y-auto p-3 custom-scrollbar space-y-3">
                {/* Lead Source Section */}
                <div className="bg-slate-50/50 dark:bg-slate-800/30 rounded-lg p-2">
                <button onClick={() => toggleSection('source')} className="flex items-center justify-between w-full text-left mb-2 group">
                    <span className="text-sm font-semibold text-slate-700 dark:text-slate-300 group-hover:text-primary-600 transition-colors">Lead Source</span>
                    {expandedSections['source'] ? <IconChevronDown className="w-3.5 h-3.5 text-slate-400" /> : <IconChevronRight className="w-3.5 h-3.5 text-slate-400" />}
                </button>
                {expandedSections['source'] && <div className="space-y-0.5 animate-fade-in">{uniqueLeadSources.map(source => <FilterCheckbox key={source} label={source || 'Unknown'} filterKey={`Source: ${source}`} checked={!!selectedFilters[`Source: ${source}`]} onChange={(checked) => setSelectedFilters(prev => ({ ...prev, [`Source: ${source}`]: checked }))} count={leads.filter(l => l.leadSource === source).length} />)}</div>}
                </div>

                {/* Status Section */}
                <div className="bg-slate-50/50 dark:bg-slate-800/30 rounded-lg p-2">
                <button onClick={() => toggleSection('status')} className="flex items-center justify-between w-full text-left mb-2 group">
                    <span className="text-sm font-semibold text-slate-700 dark:text-slate-300 group-hover:text-primary-600 transition-colors">Status</span>
                    {expandedSections['status'] ? <IconChevronDown className="w-3.5 h-3.5 text-slate-400" /> : <IconChevronRight className="w-3.5 h-3.5 text-slate-400" />}
                </button>
                {expandedSections['status'] && <div className="space-y-0.5 animate-fade-in">{uniqueStatuses.map(status => <FilterCheckbox key={status} label={status} filterKey={`Status: ${status}`} checked={!!selectedFilters[`Status: ${status}`]} onChange={(checked) => setSelectedFilters(prev => ({ ...prev, [`Status: ${status}`]: checked }))} count={leads.filter(l => l.status === status).length} />)}</div>}
                </div>

                {/* Industry Section */}
                <div className="bg-slate-50/50 dark:bg-slate-800/30 rounded-lg p-2">
                <button onClick={() => toggleSection('industry')} className="flex items-center justify-between w-full text-left mb-2 group">
                    <span className="text-sm font-semibold text-slate-700 dark:text-slate-300 group-hover:text-primary-600 transition-colors">Industry</span>
                    {expandedSections['industry'] ? <IconChevronDown className="w-3.5 h-3.5 text-slate-400" /> : <IconChevronRight className="w-3.5 h-3.5 text-slate-400" />}
                </button>
                {expandedSections['industry'] && <div className="space-y-0.5 animate-fade-in">{uniqueIndustries.map(industry => <FilterCheckbox key={industry} label={industry} filterKey={`Industry: ${industry}`} checked={!!selectedFilters[`Industry: ${industry}`]} onChange={(checked) => setSelectedFilters(prev => ({ ...prev, [`Industry: ${industry}`]: checked }))} count={leads.filter(l => l.industry === industry).length} />)}</div>}
                </div>
            </div>
            </div>

            {/* Main Content */}
            <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden h-full">
            <div className="p-4 md:p-6 pb-2">
                <div className="flex flex-col md:flex-row md:justify-between md:items-center gap-4 mb-4">
                <div className="flex items-center gap-4">
                    <h1 className="text-2xl font-bold text-slate-800 dark:text-slate-100">Leads <span className="text-lg text-slate-400 font-medium ml-1">({sortedLeads.length})</span></h1>
                    <button onClick={handleCreateNewLead} className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-all transform hover:-translate-y-0.5">+ New Lead</button>
                </div>
                <div className="flex items-center space-x-3"><div className="relative group"><IconSearch className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 group-focus-within:text-primary-500 transition-colors" /><input type="text" placeholder="Search leads..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="w-full md:w-64 pl-9 pr-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500/50 transition-all" /></div></div>
                </div>

                <div className="flex items-center gap-2 p-1.5 rounded-xl border border-primary-200 dark:border-primary-500/30 bg-primary-50 dark:bg-primary-900/10 mb-4 shadow-sm">
                <div className="relative flex-1"><IconSparkles className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-primary-600 dark:text-primary-400" /><input type="text" value={smartFilterQuery} onChange={(e) => setSmartFilterQuery(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSmartFilter()} placeholder="Ask AI to filter (e.g., 'hot tech leads in New York')..." className="w-full pl-9 pr-3 py-2 text-sm bg-white dark:bg-slate-800 border border-primary-100 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500/50 text-slate-900 dark:text-white placeholder-slate-400" /></div>
                <button onClick={handleSmartFilter} disabled={isProcessingAI} className="px-4 py-2 bg-primary-600 text-white text-sm font-medium rounded-lg hover:bg-primary-500 transition-colors disabled:opacity-50 shadow-sm">{isProcessingAI ? 'Thinking...' : 'Filter'}</button>
                    {aiFilters.length > 0 && (
                    <button onClick={() => { setAiFilters([]); setSmartFilterQuery(''); }} className="px-3 py-2 bg-slate-200 text-slate-700 text-xs font-medium rounded-lg hover:bg-slate-300 transition-colors dark:bg-slate-700 dark:text-slate-200 dark:hover:bg-slate-600">
                        Clear
                    </button>
                    )}
                {selectedLeadIds.size > 0 && (<div className="h-6 w-px bg-slate-300 dark:bg-slate-700 mx-1"></div>)}
                {selectedLeadIds.size > 0 && (<><button onClick={handleBatchAnalyze} className="px-4 py-2 bg-indigo-600 text-white text-sm font-medium rounded-lg hover:bg-indigo-500 transition-colors flex items-center shadow-sm"><IconSparkles className="w-4 h-4 mr-1.5" />Analyze</button><button onClick={handleOpenEmailModal} className="px-4 py-2 bg-emerald-600 text-white text-sm font-medium rounded-lg hover:bg-emerald-500 transition-colors flex items-center shadow-sm"><IconMail className="w-4 h-4 mr-1.5" />Email</button><button onClick={handleDeleteSelected} className="px-4 py-2 bg-red-600 text-white text-sm font-medium rounded-lg hover:bg-red-500 transition-colors flex items-center shadow-sm"><IconTrash className="w-4 h-4 mr-1.5" />Delete</button></>)}
                </div>

                {batchAnalysisResult && (<div className="mb-4 p-4 bg-indigo-50 dark:bg-slate-800 border border-indigo-200 dark:border-slate-700 rounded-lg animate-slide-up relative"><button onClick={() => setBatchAnalysisResult(null)} className="absolute top-2 right-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200"><IconX className="w-4 h-4" /></button><h3 className="text-sm font-bold text-indigo-700 dark:text-indigo-400 mb-2 flex items-center"><IconSparkles className="w-4 h-4 mr-2" /> AI Bulk Analysis</h3><div className="prose prose-sm dark:prose-invert max-w-none text-slate-700 dark:text-slate-300">{batchAnalysisResult.split('\n').map((line, i) => <p key={i} className="my-1">{line}</p>)}</div></div>)}
            </div>

            <div className="flex-1 overflow-auto bg-white dark:bg-slate-900 custom-scrollbar relative">
                <table className="w-full text-left text-sm border-collapse">
                <thead className="bg-slate-50/90 dark:bg-slate-950/90 backdrop-blur-sm sticky top-0 z-10 border-b border-slate-200 dark:border-slate-800 shadow-sm">
                    <tr>
                    <th className="px-4 py-3 w-12 text-center"><input type="checkbox" checked={selectedLeadIds.size === paginatedLeads.length && paginatedLeads.length > 0} onChange={toggleSelectAll} className="w-4 h-4 rounded border-slate-300 text-primary-600 focus:ring-primary-500 bg-white dark:bg-slate-800 cursor-pointer" /></th>
                    <th className="px-4 py-3"><button onClick={() => requestSort('name')} className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider whitespace-nowrap group flex items-center gap-2 hover:text-primary-600 transition-colors">Lead Name {getSortIcon('name')}</button></th>
                    <th className="px-4 py-3"><button onClick={() => requestSort('company')} className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider whitespace-nowrap group flex items-center gap-2 hover:text-primary-600 transition-colors">Company {getSortIcon('company')}</button></th>
                    <th className="px-4 py-3"><button onClick={() => requestSort('score')} className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider whitespace-nowrap group flex items-center gap-2 hover:text-primary-600 transition-colors">Score {getSortIcon('score')}</button></th>
                    <th className="px-4 py-3"><button onClick={() => requestSort('status')} className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider whitespace-nowrap group flex items-center gap-2 hover:text-primary-600 transition-colors">Status {getSortIcon('status')}</button></th>
                    <th className="px-4 py-3"><button onClick={() => requestSort('lastContact')} className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider whitespace-nowrap group flex items-center gap-2 hover:text-primary-600 transition-colors">Last Contact {getSortIcon('lastContact')}</button></th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 dark:divide-slate-800/50">
                    {paginatedLeads.map((lead) => (
                    <tr key={lead.id} className="hover:bg-primary-50/50 dark:hover:bg-slate-800/60 transition-colors group cursor-default">
                        <td className="px-4 py-4 text-center"><input type="checkbox" checked={selectedLeadIds.has(lead.id)} onChange={() => toggleSelection(lead.id)} className="w-4 h-4 rounded border-slate-300 text-primary-600 focus:ring-primary-500 bg-white dark:bg-slate-800 cursor-pointer" /></td>
                        <td className="px-4 py-4">
                            <div className="flex items-center gap-3">
                                <div className="w-8 h-8 rounded-full bg-slate-200 dark:bg-slate-700 flex items-center justify-center text-xs font-bold text-slate-600 dark:text-slate-300 border border-slate-300 dark:border-slate-600">
                                    {getInitials(lead.name)}
                                </div>
                                <div>
                                    <span onClick={() => handleViewLeadDetail(lead)} className="text-sm font-semibold text-slate-900 dark:text-slate-100 hover:text-primary-600 dark:hover:text-primary-400 cursor-pointer block">{lead.name}</span>
                                    <span className="text-xs text-slate-500 dark:text-slate-400">{lead.title}</span>
                                </div>
                            </div>
                        </td>
                        <td className="px-4 py-4 text-sm text-slate-600 dark:text-slate-300 font-medium">{lead.company}</td>
                        <td className="px-4 py-4">
                            <div className="flex items-center gap-3">
                                <div className="flex-1 w-16 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden">
                                    <div className={`h-full rounded-full ${lead.score >= 80 ? 'bg-emerald-500' : lead.score >= 50 ? 'bg-yellow-500' : 'bg-red-500'}`} style={{ width: `${lead.score}%` }}></div>
                                </div>
                                <span className={`text-xs font-bold ${getScoreColor(lead.score)}`}>{lead.score}</span>
                            </div>
                        </td>
                        <td className="px-4 py-4">
                            <span className={`px-2.5 py-1 text-xs font-semibold rounded-full border ${getStatusStyle(lead.status)}`}>
                                {lead.status}
                            </span>
                        </td>
                        <td className="px-4 py-4 text-sm text-slate-500 dark:text-slate-400">{lead.lastContact}</td>
                    </tr>
                    ))}
                    {paginatedLeads.length === 0 && (
                        <tr>
                            <td colSpan={6}>
                                <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                                    <IconSearch className="w-12 h-12 mb-4 opacity-20" />
                                    <p className="text-lg font-medium">No leads found</p>
                                    <p className="text-sm">Try adjusting your filters or search terms.</p>
                                </div>
                            </td>
                        </tr>
                    )}
                </tbody>
                </table>
            </div>
            {totalPages > 1 && (<div className="p-4 border-t border-slate-200 dark:border-slate-800 flex justify-between items-center text-sm bg-slate-50 dark:bg-slate-900/50"><div className="text-slate-600 dark:text-slate-400">Showing <span className="font-semibold">{paginatedLeads.length}</span> of {sortedLeads.length} results</div><div className="flex items-center gap-2"><button disabled={currentPage === 1} onClick={() => setCurrentPage(c => c - 1)} className="px-3 py-1.5 border border-slate-200 dark:border-slate-700 rounded-lg hover:bg-white dark:hover:bg-slate-800 disabled:opacity-50 transition-colors">Prev</button><span className="text-slate-500 dark:text-slate-400">Page {currentPage} of {totalPages}</span><button disabled={currentPage === totalPages} onClick={() => setCurrentPage(c => c + 1)} className="px-3 py-1.5 border border-slate-200 dark:border-slate-700 rounded-lg hover:bg-white dark:hover:bg-slate-800 disabled:opacity-50 transition-colors">Next</button></div></div>)}
            </div>
        </div>
    );
  };

  return (
    <>
      {renderView()}
      {/* Modals are now rendered regardless of the view mode */}
      {isEmailModalOpen && <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm"><div className="w-full max-w-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-scale-in"><div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50"><h2 className="text-2xl font-bold text-slate-900 dark:text-white flex items-center"><IconMail className="w-5 h-5 mr-3 text-primary-500" />Compose Email</h2><button onClick={closeEmailModal} className="text-slate-400 hover:text-slate-600 dark:hover:text-white"><IconX className="w-6 h-6" /></button></div><div className="p-6 overflow-y-auto space-y-4"><div><label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">To</label><div className="p-2 bg-slate-100 dark:bg-slate-800 rounded-lg text-sm text-slate-600 dark:text-slate-400">{selectedLeadIds.size} selected leads</div></div><div><label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Template</label><select onChange={handleTemplateChange} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white"><option value="">-- No Template --</option>{MOCK_TEMPLATES.map(template => (<option key={template.id} value={template.id}>{template.name}</option>))}</select>{previewLeadName && (<p className="text-sm text-slate-500 dark:text-slate-400 mt-1">Showing a preview using data from <span className="font-semibold">{previewLeadName}</span>.</p>)}</div><div><label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Subject</label><input type="text" value={emailSubject} onChange={(e) => setEmailSubject(e.target.value)} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white" /></div><div><label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-2">AI Actions</label><div className="flex items-center gap-2"><div className="flex items-center p-1 bg-slate-100 dark:bg-slate-800 rounded-lg">{(['formal', 'casual', 'persuasive'] as const).map(t => (<button key={t} type="button" onClick={() => setEmailTone(t)} className={`px-3 py-1 text-sm font-medium rounded-md transition-colors ${emailTone === t ? 'bg-white dark:bg-slate-700 text-primary-600 dark:text-white shadow-sm' : 'text-slate-500 hover:bg-slate-200/50 dark:hover:bg-slate-700/50'}`}>{t.charAt(0).toUpperCase() + t.slice(1)}</button>))}</div><button type="button" onClick={handleAIDraft} disabled={isDraftingAI} className="flex items-center px-4 py-1.5 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-sm transition-colors disabled:opacity-50"><IconSparkles className="w-4 h-4 mr-2" />{isDraftingAI ? 'Drafting...' : 'Draft with AI'}</button></div></div><div><label className="block text-base font-medium text-slate-700 dark:text-slate-300 mb-1">Body</label><textarea value={emailBody} onChange={(e) => setEmailBody(e.target.value)} rows={10} placeholder={isDraftingAI ? "Nova is thinking..." : "Your email body will appear here..."} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white font-mono text-base" /></div><div className="pt-2"><div className="flex items-center"><input type="checkbox" id="schedule-email" checked={isSchedulingEmail} onChange={(e) => setIsSchedulingEmail(e.target.checked)} className="w-4 h-4 text-primary-600 bg-slate-100 border-slate-300 rounded focus:ring-primary-500 dark:focus:ring-primary-600 dark:ring-offset-slate-800 focus:ring-2 dark:bg-slate-700 dark:border-slate-600" /><label htmlFor="schedule-email" className="ml-2 text-sm font-medium text-slate-700 dark:text-slate-300">Schedule for later</label></div>{isSchedulingEmail && (<div className="mt-2 animate-fade-in"><input type="datetime-local" value={scheduleDateTime} onChange={(e) => setScheduleDateTime(e.target.value)} className="w-full md:w-1/2 px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white" /></div>)}</div></div><div className="p-6 border-t border-slate-200 dark:border-slate-800 flex justify-end gap-3 bg-slate-50 dark:bg-slate-800/50"><button type="button" onClick={closeEmailModal} className="px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">Cancel</button><button onClick={handleSendEmail} className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-colors flex items-center">{isSchedulingEmail ? <IconClock className="w-4 h-4 mr-2" /> : <IconSend className="w-4 h-4 mr-2" />}{isSchedulingEmail ? 'Schedule Email' : 'Send Email'}</button></div></div></div>}
      {isNurtureModalOpen && <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm"><div className="w-full max-w-3xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-scale-in"><div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50"><h2 className="text-xl font-bold text-slate-900 dark:text-white flex items-center"><IconBot className="w-5 h-5 mr-3 text-primary-500" />AI Nurture Sequence</h2><button onClick={closeNurtureModal} className="text-slate-400 hover:text-slate-600 dark:hover:text-white"><IconX className="w-6 h-6" /></button></div><div className="p-6 overflow-y-auto">{isNurturing ? (<div className="flex flex-col items-center justify-center h-64 text-center"><IconSparkles className="w-12 h-12 text-primary-500 animate-pulse" /><p className="mt-4 text-slate-600 dark:text-slate-300">Generating personalized sequence for {selectedLead?.name}...</p></div>) : nurtureSequence ? (<div className="space-y-4">{nurtureSequence.map((email, index) => (<div key={index} className="border border-slate-200 dark:border-slate-800 rounded-lg overflow-hidden"><button onClick={() => setActiveNurtureAccordion(activeNurtureAccordion === index ? null : index)} className="w-full flex justify-between items-center p-4 bg-slate-50 dark:bg-slate-800/50 hover:bg-slate-100 dark:hover:bg-slate-800"><div className="font-medium text-slate-900 dark:text-white"><span className="text-primary-600 dark:text-primary-400">Step {index + 1}:</span> {email.delay} - {email.subject}</div><IconChevronDown className={`w-5 h-5 text-slate-500 transition-transform ${activeNurtureAccordion === index ? 'rotate-180' : ''}`} /></button>{activeNurtureAccordion === index && (<div className="p-4 border-t border-slate-200 dark:border-slate-800 animate-fade-in"><p className="text-sm text-slate-600 dark:text-slate-400 whitespace-pre-wrap font-mono">{email.body}</p></div>)}</div>))}</div>) : null}</div><div className="p-6 border-t border-slate-200 dark:border-slate-800 flex justify-end gap-3 bg-slate-50 dark:bg-slate-800/50"><button type="button" onClick={closeNurtureModal} className="px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">Close</button><button className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-colors flex items-center"><IconSend className="w-4 h-4 mr-2" />Start Sequence</button></div></div></div>}
    </>
  );
};

export default Leads;

export interface Call {
  id: string;
  subject: string;
  relatedTo: string; // Name of Lead/Contact
  relatedToId: string; // ID of Lead/Contact
  type: 'Inbound' | 'Outbound';
  outcome: 'Connected' | 'Left Voicemail' | 'No Answer' | 'Scheduled Follow-up';
  date: string; // ISO string
  notes: string;
  summary?: string;
}

export enum LeadStatus {
  NEW = 'New',
  CONTACTED = 'Contacted',
  QUALIFIED = 'Qualified',
  PROPOSAL = 'Proposal Sent',
  NEGOTIATION = 'Negotiation',
  CLOSED = 'Closed Won',
  LOST = 'Closed Lost'
}

export interface Lead {
  id: string;
  name: string;
  company: string;
  email: string;
  phone: string;
  status: LeadStatus;
  value: number;
  lastContact: string;
  score: number; // 0-100 AI Score
  scoreBreakdown: {
    fit: number;
    engagement: number;
    budget: number;
  };
  notes: string;
  activities?: Activity[];
  // New fields for enhanced view
  source?: string;
  city?: string;
  industry?: string;
  createdTime?: string;
  lastActivity?: string;
  leadSource?: string; // Specific field for the column

  // Fields for Create Lead form
  firstName?: string;
  lastName?: string;
  title?: string;
  mobile?: string;
  fax?: string;
  website?: string;
  noOfEmployees?: number;
  annualRevenue?: number;
  rating?: 'Acquired' | 'Active' | 'Market Failed' | 'Project Cancelled' | 'Shutdown';
  owner?: string;
}

export interface Activity {
  id: string;
  type: 'stage_change' | 'value_change' | 'probability_change' | 'update' | 'created' | 'email_sent' | 'meeting_scheduled' | 'follow_up' | 'status_change';
  description: string;
  timestamp: string;
}

export interface Deal {
  id: string;
  title: string;
  company: string;
  stage: 'Qualification' | 'Needs Analysis' | 'Value Proposition' | 'Decision Makers' | 'Proposal/Price Quote' | 'Negotiation/Review' | 'Closed Won' | 'Closed Lost';
