  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M21.21 15.89A10 10 0 1 1 8 2.83"/><path d="M22 12A10 10 0 0 0 12 2v10z"/></svg>
);

export const IconActivity = ({ className }: { className?: string }) => (
  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M22 12h-4l-3 9L9 3l-3 9H2"/></svg>
);

export const IconTrendingUp = ({ className }: { className?: string }) => (
  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><polyline points="23 6 13.5 15.5 8.5 10.5 1 18"/><polyline points="17 6 23 6 23 12"/></svg>
);

export const IconWallet = ({ className }: { className?: string }) => (
  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M21 12V7H5a2 2 0 0 1 0-4h14v4"/><path d="M3 5v14a2 2 0 0 0 2 2h16v-5"/><path d="M18 12a2 2 0 0 0 0 4h4v-4Z"/></svg>
);

import React, { useState, useMemo } from 'react';
import { Meeting } from '../types';
import { 
  IconCalendar, IconFilter, IconClock, IconMapPin, IconGlobe, 
  IconPlus, IconSearch, IconX, IconEdit, IconTrash, 
  IconArrowUp, IconArrowDown, IconList, IconChevronLeft, IconChevronRight 
} from './Icons';

interface MeetingsProps {
  meetings: Meeting[];
  onAddMeeting: (meeting: Meeting) => void;
  onUpdateMeeting: (meeting: Meeting) => void;
  onDeleteMeeting: (id: string) => void;
}

type SortKey = keyof Meeting;
type SortDirection = 'asc' | 'desc';

const Meetings: React.FC<MeetingsProps> = ({ meetings, onAddMeeting, onUpdateMeeting, onDeleteMeeting }) => {
  const [viewMode, setViewMode] = useState<'list' | 'calendar'>('list');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedMeeting, setSelectedMeeting] = useState<Meeting | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [typeFilter, setTypeFilter] = useState<string>('All');
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: SortDirection } | null>({ key: 'date', direction: 'asc' });

  // Calendar State
  const [currentDate, setCurrentDate] = useState(new Date());

  // Form State
  const [formData, setFormData] = useState<Omit<Meeting, 'id'>>({
    title: '',
    date: new Date().toISOString().split('T')[0],
    startTime: '09:00',
    endTime: '10:00',
    type: 'Online',
    relatedTo: ''
  });

  const filteredMeetings = useMemo(() => {
    return meetings.filter(meeting => {
      const matchesSearch = meeting.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            meeting.relatedTo.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesType = typeFilter === 'All' || meeting.type === typeFilter;
      return matchesSearch && matchesType;
    });
  }, [meetings, searchQuery, typeFilter]);

  const sortedMeetings = useMemo(() => {
    let sortableItems = [...filteredMeetings];
    if (sortConfig !== null) {
      sortableItems.sort((a, b) => {
        const aValue = a[sortConfig.key];
        const bValue = b[sortConfig.key];
        if (aValue < bValue) return sortConfig.direction === 'asc' ? -1 : 1;
        if (aValue > bValue) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
      });
    }
    return sortableItems;
  }, [filteredMeetings, sortConfig]);

  const requestSort = (key: SortKey) => {
    let direction: SortDirection = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const getSortIcon = (key: SortKey) => {
    if (!sortConfig || sortConfig.key !== key) return <span className="w-3 h-3 opacity-0 group-hover:opacity-50 transition-opacity">↕️</span>;
    if (sortConfig.direction === 'asc') return <IconArrowUp className="w-3 h-3 text-primary-500" />;
    return <IconArrowDown className="w-3 h-3 text-primary-500" />;
  };

  const handleOpenModal = (meeting?: Meeting, dateOverride?: string) => {
    if (meeting) {
      setSelectedMeeting(meeting);
      setFormData({
        title: meeting.title,
        date: meeting.date,
        startTime: meeting.startTime,
        endTime: meeting.endTime,
        type: meeting.type,
        relatedTo: meeting.relatedTo
      });
    } else {
      setSelectedMeeting(null);
      setFormData({
        title: '',
        date: dateOverride || new Date().toISOString().split('T')[0],
        startTime: '09:00',
        endTime: '10:00',
        type: 'Online',
        relatedTo: ''
      });
    }
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setSelectedMeeting(null);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.title || !formData.date || !formData.startTime || !formData.endTime) {
      alert("Please fill in all required fields.");
      return;
    }

    if (selectedMeeting) {
      onUpdateMeeting({ ...formData, id: selectedMeeting.id });
    } else {
      onAddMeeting({ ...formData, id: `M-${Date.now()}` });
    }
    handleCloseModal();
  };

  const handleDelete = () => {
    if (selectedMeeting && window.confirm("Are you sure you want to delete this meeting?")) {
      onDeleteMeeting(selectedMeeting.id);
      handleCloseModal();
    }
  };

  // Calendar Helpers
  const getDaysInMonth = (date: Date) => {
    return new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
  };

  const getFirstDayOfMonth = (date: Date) => {
    return new Date(date.getFullYear(), date.getMonth(), 1).getDay();
  };

  const changeMonth = (offset: number) => {
    const newDate = new Date(currentDate);
    newDate.setMonth(newDate.getMonth() + offset);
    setCurrentDate(newDate);
  };

  const isToday = (dateString: string) => {
    const today = new Date();
    return dateString === today.toISOString().split('T')[0];
  };

  const renderCalendar = () => {
    const daysInMonth = getDaysInMonth(currentDate);
    const firstDay = getFirstDayOfMonth(currentDate);
    const days = [];
    const monthYear = currentDate.toLocaleString('default', { month: 'long', year: 'numeric' });

    // Empty cells for padding
    for (let i = 0; i < firstDay; i++) {
        days.push(<div key={`empty-${i}`} className="min-h-[100px] bg-slate-50/30 dark:bg-slate-900/30 border-r border-b border-slate-100 dark:border-slate-800" />);
    }

    // Day cells
    for (let d = 1; d <= daysInMonth; d++) {
        const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayMeetings = meetings.filter(m => m.date === dateStr);

        days.push(
            <div 
                key={d} 
                onClick={() => handleOpenModal(undefined, dateStr)}
                className="min-h-[100px] bg-white dark:bg-slate-900 border-r border-b border-slate-200 dark:border-slate-800 p-2 hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors cursor-pointer group flex flex-col"
            >
                <div className="flex justify-between items-start mb-1">
                    <span className={`text-sm font-semibold w-7 h-7 flex items-center justify-center rounded-full ${isToday(dateStr) ? 'bg-primary-600 text-white shadow-md shadow-primary-500/30' : 'text-slate-700 dark:text-slate-300'}`}>
                        {d}
                    </span>
                    <button className="opacity-0 group-hover:opacity-100 text-slate-400 hover:text-primary-500 transition-opacity">
                        <IconPlus className="w-3 h-3" />
                    </button>
                </div>
                <div className="space-y-1 overflow-y-auto max-h-[80px] custom-scrollbar">
                    {dayMeetings.map(m => (
                        <div 
                            key={m.id} 
                            onClick={(e) => { e.stopPropagation(); handleOpenModal(m); }} 
                            className={`px-2 py-1 text-xs rounded border border-l-2 truncate transition-all hover:shadow-sm ${
                                m.type === 'Online' 
                                ? 'bg-blue-50 text-blue-700 border-blue-100 border-l-blue-500 dark:bg-blue-900/20 dark:text-blue-300 dark:border-blue-800' 
                                : 'bg-orange-50 text-orange-700 border-orange-100 border-l-orange-500 dark:bg-orange-900/20 dark:text-orange-300 dark:border-orange-800'
                            }`}
                            title={`${m.startTime} - ${m.title}`}
                        >
                            <span className="font-bold mr-1">{m.startTime}</span>
                            {m.title}
                        </div>
                    ))}
                </div>
            </div>
        );
    }

    return (
        <div className="flex-1 flex flex-col overflow-hidden bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm">
            <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50/50 dark:bg-slate-900/50">
                <div className="flex items-center gap-4">
                    <button onClick={() => changeMonth(-1)} className="p-1 hover:bg-slate-200 dark:hover:bg-slate-800 rounded-full transition-colors text-slate-600 dark:text-slate-400">
                        <IconChevronLeft className="w-5 h-5" />
                    </button>
                    <h2 className="text-lg font-bold text-slate-900 dark:text-white min-w-[140px] text-center">{monthYear}</h2>
                    <button onClick={() => changeMonth(1)} className="p-1 hover:bg-slate-200 dark:hover:bg-slate-800 rounded-full transition-colors text-slate-600 dark:text-slate-400">
                        <IconChevronRight className="w-5 h-5" />
                    </button>
                </div>
                <button onClick={() => setCurrentDate(new Date())} className="text-sm font-medium text-primary-600 hover:text-primary-700 dark:text-primary-400 dark:hover:text-primary-300">
                    Today
                </button>
            </div>

            <div className="grid grid-cols-7 border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-950/50">
                {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(day => (
                    <div key={day} className="py-2 text-center text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider">
                        {day}
                    </div>
                ))}
            </div>

            <div className="flex-1 overflow-y-auto custom-scrollbar">
                <div className="grid grid-cols-7 auto-rows-fr min-h-full">
                    {days}
                </div>
            </div>
        </div>
    );
  };

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex justify-between items-center flex-shrink-0">
        <div className="flex items-center gap-4">
            <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Meetings</h1>
            <div className="flex bg-slate-100 dark:bg-slate-800/50 p-1 rounded-xl border border-slate-200 dark:border-slate-700/50">
                <button onClick={() => setViewMode('list')} className={`p-2 rounded-lg transition-all duration-200 ${viewMode === 'list' ? 'bg-white dark:bg-slate-700 shadow-sm text-primary-600 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200'}`}><IconList className="w-4 h-4" /></button>
                <button onClick={() => setViewMode('calendar')} className={`p-2 rounded-lg transition-all duration-200 ${viewMode === 'calendar' ? 'bg-white dark:bg-slate-700 shadow-sm text-primary-600 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200'}`}><IconCalendar className="w-4 h-4" /></button>
            </div>
        </div>
        <button 
          onClick={() => handleOpenModal()}
          className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-all flex items-center"
        >
          <IconPlus className="w-4 h-4 mr-2" /> New Meeting
        </button>
      </div>

      {viewMode === 'list' ? (
        <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm dark:shadow-none overflow-hidden flex flex-col flex-1">
            {/* Toolbar */}
            <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-slate-50/50 dark:bg-slate-900/50">
            <div className="flex items-center space-x-4">
                <div className="relative group">
                    <IconSearch className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 group-focus-within:text-primary-500 transition-colors" />
                    <input 
                    type="text" 
                    placeholder="Search meetings..." 
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="pl-9 pr-4 py-2 text-sm bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 w-full sm:w-64 transition-all"
                    />
                </div>

                <div className="flex items-center space-x-2">
                <IconFilter className="w-4 h-4 text-slate-400" />
                <select 
                    value={typeFilter}
                    onChange={(e) => setTypeFilter(e.target.value)}
                    className="bg-transparent text-sm font-medium text-slate-700 dark:text-slate-300 focus:outline-none cursor-pointer"
                >
                    <option value="All">All Types</option>
                    <option value="Online">Online</option>
                    <option value="Offline">Offline</option>
                </select>
                </div>
            </div>
            </div>

            {/* Table */}
            <div className="overflow-auto flex-1 custom-scrollbar">
            <table className="w-full text-left text-sm">
                <thead className="bg-slate-50 dark:bg-slate-950/90 backdrop-blur-sm text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-800 sticky top-0 z-10">
                <tr>
                    <th className="px-6 py-4 font-medium"><button onClick={() => requestSort('title')} className="flex items-center gap-2 hover:text-primary-600 transition-colors">Title {getSortIcon('title')}</button></th>
                    <th className="px-6 py-4 font-medium"><button onClick={() => requestSort('date')} className="flex items-center gap-2 hover:text-primary-600 transition-colors">Date & Time {getSortIcon('date')}</button></th>
                    <th className="px-6 py-4 font-medium"><button onClick={() => requestSort('type')} className="flex items-center gap-2 hover:text-primary-600 transition-colors">Type {getSortIcon('type')}</button></th>
                    <th className="px-6 py-4 font-medium"><button onClick={() => requestSort('relatedTo')} className="flex items-center gap-2 hover:text-primary-600 transition-colors">Related To {getSortIcon('relatedTo')}</button></th>
                    <th className="px-6 py-4 font-medium text-right">Actions</th>
                </tr>
                </thead>
                <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
                {sortedMeetings.map((meeting) => (
                    <tr 
                    key={meeting.id} 
                    className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors cursor-pointer group"
                    onClick={() => handleOpenModal(meeting)}
                    >
                    <td className="px-6 py-4">
                        <div className="flex items-center text-base font-medium text-slate-900 dark:text-white">
                        <div className={`p-2 rounded-lg mr-3 ${meeting.type === 'Online' ? 'bg-blue-50 text-blue-600 dark:bg-blue-900/20 dark:text-blue-400' : 'bg-orange-50 text-orange-600 dark:bg-orange-900/20 dark:text-orange-400'}`}>
                            {meeting.type === 'Online' ? <IconGlobe className="w-4 h-4" /> : <IconMapPin className="w-4 h-4" />}
                        </div>
                        {meeting.title}
                        </div>
                    </td>
                    <td className="px-6 py-4">
                        <div className="flex flex-col">
                        <div className="flex items-center text-sm text-slate-900 dark:text-white font-medium">
                            <IconCalendar className="w-3.5 h-3.5 mr-2 text-slate-400" />
                            {meeting.date}
                        </div>
                        <div className="flex items-center text-xs text-slate-500 mt-1">
                            <IconClock className="w-3.5 h-3.5 mr-2 text-slate-400" />
                            {meeting.startTime} - {meeting.endTime}
                        </div>
                        </div>
                    </td>
                    <td className="px-6 py-4">
                        <span className={`px-2.5 py-1 text-xs font-bold rounded-full border ${
                        meeting.type === 'Online' 
                            ? 'bg-blue-50 text-blue-700 border-blue-200 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-800' 
                            : 'bg-orange-50 text-orange-700 border-orange-200 dark:bg-orange-900/20 dark:text-orange-400 dark:border-orange-800'
                        }`}>
                        {meeting.type}
                        </span>
                    </td>
                    <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300">
                        {meeting.relatedTo ? (
                            <div className="flex items-center">
                                <span className="w-6 h-6 rounded-full bg-slate-200 dark:bg-slate-700 flex items-center justify-center text-[10px] font-bold mr-2 text-slate-600 dark:text-slate-300">
                                    {meeting.relatedTo.charAt(0)}
                                </span>
                                {meeting.relatedTo}
                            </div>
                        ) : (
                            <span className="text-slate-400 italic">None</span>
                        )}
                    </td>
                    <td className="px-6 py-4 text-right">
                        <button 
                        onClick={(e) => { e.stopPropagation(); handleOpenModal(meeting); }}
                        className="p-2 text-slate-400 hover:text-primary-600 dark:hover:text-primary-400 opacity-0 group-hover:opacity-100 transition-all"
                        >
                        <IconEdit className="w-4 h-4" />
                        </button>
                    </td>
                    </tr>
                ))}
                {sortedMeetings.length === 0 && (
                    <tr>
                    <td colSpan={5} className="px-6 py-12 text-center text-slate-500 dark:text-slate-400">
                        <div className="flex flex-col items-center justify-center">
                        <IconCalendar className="w-12 h-12 text-slate-300 dark:text-slate-700 mb-3" />
                        <p className="text-lg font-medium">No meetings found</p>
                        <p className="text-sm">Try adjusting your filters or create a new meeting.</p>
                        </div>
                    </td>
                    </tr>
                )}
                </tbody>
            </table>
            </div>
        </div>
      ) : (
        renderCalendar()
      )}

      {/* Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="w-full max-w-lg bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-scale-in">
            <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50">
              <h2 className="text-xl font-bold text-slate-900 dark:text-white flex items-center">
                 <IconCalendar className="w-5 h-5 mr-3 text-primary-500" />
                 {selectedMeeting ? 'Edit Meeting' : 'Schedule Meeting'}
              </h2>
              <button 
                onClick={handleCloseModal} 
                className="text-slate-400 hover:text-slate-600 dark:hover:text-white transition-colors"
              >
                <IconX className="w-6 h-6" />
              </button>
            </div>

            <div className="p-6 overflow-y-auto">
              <form onSubmit={handleSubmit} className="space-y-5">
                 <div>
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Meeting Title <span className="text-red-500">*</span></label>
                    <input 
                       type="text" 
                       name="title" 
                       value={formData.title} 
                       onChange={handleInputChange} 
                       required
                       placeholder="e.g. Weekly Sync"
                       className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 text-slate-900 dark:text-white"
                    />
                 </div>

                 <div className="grid grid-cols-2 gap-5">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Date <span className="text-red-500">*</span></label>
                        <input 
                            type="date" 
                            name="date" 
                            value={formData.date} 
                            onChange={handleInputChange} 
                            required
                            className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 text-slate-900 dark:text-white"
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Type</label>
                        <select 
                            name="type" 
                            value={formData.type} 
                            onChange={handleInputChange}
                            className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 text-slate-900 dark:text-white appearance-none cursor-pointer"
                        >
                            <option value="Online">Online</option>
                            <option value="Offline">Offline</option>
                        </select>
                    </div>
                 </div>

                 <div className="grid grid-cols-2 gap-5">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Start Time <span className="text-red-500">*</span></label>
                        <input 
                            type="time" 
                            name="startTime" 
                            value={formData.startTime} 
                            onChange={handleInputChange}
                            required
                            className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 text-slate-900 dark:text-white"
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">End Time <span className="text-red-500">*</span></label>
                        <input 
                            type="time" 
                            name="endTime" 
                            value={formData.endTime} 
                            onChange={handleInputChange} 
                            required
                            className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 text-slate-900 dark:text-white"
                        />
                    </div>
                 </div>

                 <div>
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Related To</label>
                    <input 
                       type="text" 
                       name="relatedTo" 
                       value={formData.relatedTo} 
                       onChange={handleInputChange} 
                       placeholder="e.g. Acme Corp or John Doe"
                       className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 text-slate-900 dark:text-white"
                    />
                 </div>

                 <div className="pt-4 flex gap-3 justify-end border-t border-slate-100 dark:border-slate-800">
                    {selectedMeeting && (
                        <button 
                            type="button"
                            onClick={handleDelete}
                            className="mr-auto px-4 py-2.5 text-sm font-medium text-red-600 bg-red-50 dark:bg-red-500/10 rounded-xl hover:bg-red-100 dark:hover:bg-red-500/20 transition-colors flex items-center"
                        >
                            <IconTrash className="w-4 h-4 mr-2" /> Delete
                        </button>
                    )}
                    <button 
                        type="button"
                        onClick={handleCloseModal}
                        className="px-5 py-2.5 text-sm font-medium text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 rounded-xl hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors"
                    >
                        Cancel
                    </button>
                    <button 
                        type="submit"
                        className="px-6 py-2.5 text-sm font-medium text-white bg-primary-600 rounded-xl hover:bg-primary-500 shadow-lg shadow-primary-500/25 transition-colors"
                    >
                        {selectedMeeting ? 'Save Changes' : 'Schedule Meeting'}
                    </button>
                 </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Meetings;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Leads from './components/Leads';
import Pipeline from './components/Pipeline';
import Tasks from './components/Tasks';
import Meetings from './components/Meetings';
import Contacts from './components/Contacts';
import Accounts from './components/Accounts';
import Calls from './components/Calls';
import Settings from './components/Settings';
import PlaceholderModule from './components/PlaceholderModule';
import AIChat from './components/AIChat';
import { MOCK_LEADS, MOCK_DEALS, MOCK_TASKS, MOCK_MEETINGS, MOCK_CONTACTS, MOCK_ACCOUNTS, MOCK_CALLS } from './constants';
import { IconMenu } from './components/Icons';
import { Lead, Deal, Activity, Task, Meeting, Contact, Account, Call } from './types';
import Notifications from './components/Notifications';

// RGB values for themes (for Tailwind opacity support)
// Updated mapping to match new "Theme Engine" names
const THEMES: Record<string, Record<number, string>> = {
  indigo: { 50: '238 242 255', 100: '224 231 255', 200: '199 210 254', 300: '165 180 252', 400: '129 140 248', 500: '99 102 241', 600: '79 70 229', 700: '67 56 202', 800: '55 48 163', 900: '49 46 129', 950: '30 27 75' }, // Corporate Indigo
  slate: { 50: '248 250 252', 100: '241 245 249', 200: '226 232 240', 300: '203 213 225', 400: '148 163 184', 500: '100 116 139', 600: '71 85 105', 700: '51 65 85', 800: '30 41 59', 900: '15 23 42', 950: '2 6 23' }, // Midnight Charcoal / Slate Professional
  emerald: { 50: '236 253 245', 100: '209 250 229', 200: '167 243 208', 300: '110 231 183', 400: '52 211 153', 500: '16 185 129', 600: '5 150 105', 700: '4 120 87', 800: '6 95 70', 900: '6 78 59', 950: '2 44 34' }, // Emerald Forest
  purple: { 50: '250 245 255', 100: '243 232 255', 200: '233 213 255', 300: '216 180 254', 400: '192 132 252', 500: '168 85 247', 600: '147 51 234', 700: '126 34 206', 800: '107 33 168', 900: '88 28 135', 950: '59 7 100' }, // Royal Amethyst
  orange: { 50: '255 247 237', 100: '255 237 213', 200: '254 215 170', 300: '253 186 116', 400: '251 146 60', 500: '249 115 22', 600: '234 88 12', 700: '194 65 12', 800: '154 52 18', 900: '124 45 18', 950: '67 20 7' }, // Sunset Horizon
  rose: { 50: '255 241 242', 100: '255 228 230', 200: '254 205 211', 300: '253 164 175', 400: '251 113 133', 500: '244 63 94', 600: '225 29 72', 700: '190 18 60', 800: '159 18 57', 900: '136 19 55', 950: '76 5 25' }, // Ruby Crimson
  cyan: { 50: '236 254 255', 100: '207 250 254', 200: '165 243 252', 300: '103 232 249', 400: '34 211 238', 500: '6 182 212', 600: '8 145 178', 700: '14 116 144', 800: '21 94 117', 900: '22 78 99', 950: '8 51 68' }, // Oceanic Teal
};

function App() {
  const [currentView, setCurrentView] = useState('dashboard');
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isDark, setIsDark] = useState(true);

  // Theme Settings
  const [primaryColor, setPrimaryColor] = useState('indigo');
  const [fontFamily, setFontFamily] = useState('Plus Jakarta Sans');
  const [density, setDensity] = useState('Medium'); // Mapped to Typography Scale (Small, Medium, Large, XL)
  const [weekStart, setWeekStart] = useState('Sunday');
  const [dateFormat, setDateFormat] = useState('DD/MM/YYYY');
  const [timeZone, setTimeZone] = useState('UTC');
  const [timeFormat, setTimeFormat] = useState<'12h' | '24h'>('12h');
  const [workingDays, setWorkingDays] = useState<string[]>(['Mon', 'Tue', 'Wed', 'Thu', 'Fri']);
  const [fiscalYearStart, setFiscalYearStart] = useState('January');

  // State for data
  const [leads, setLeads] = useState<Lead[]>(MOCK_LEADS);
  const [deals, setDeals] = useState<Deal[]>(MOCK_DEALS);
  const [tasks, setTasks] = useState<Task[]>(MOCK_TASKS);
  const [meetings, setMeetings] = useState<Meeting[]>(MOCK_MEETINGS);
  const [contacts, setContacts] = useState<Contact[]>(MOCK_CONTACTS);
  const [accounts, setAccounts] = useState<Account[]>(MOCK_ACCOUNTS);
  const [calls, setCalls] = useState<Call[]>(MOCK_CALLS);

  // Pipeline Goal State
  const [pipelineGoal, setPipelineGoal] = useState<number>(() => {
    const saved = localStorage.getItem('nova_pipeline_goal');
    return saved ? Number(saved) : 5000000;
  });

  const handleSetPipelineGoal = (goal: number) => {
    setPipelineGoal(goal);
    localStorage.setItem('nova_pipeline_goal', goal.toString());
  };

  const handleNavigateToTasks = () => {
    setCurrentView('tasks');
  };

  // Toggle Dark Mode
  useEffect(() => {
    if (isDark) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDark]);

  // Apply Theme Colors and Font via CSS Variables
  useEffect(() => {
    const root = document.documentElement;
    const themeColors = THEMES[primaryColor] || THEMES.indigo;

    // Apply Colors
    Object.keys(themeColors).forEach((key) => {
      root.style.setProperty(`--color-primary-${key}`, themeColors[Number(key)]);
    });

    // Apply Font
    const fontMap: Record<string, string> = {
      'Plus Jakarta Sans': "'Plus Jakarta Sans', sans-serif",
      'Inter UI': "'Inter', sans-serif",
      'Montserrat': "'Montserrat', sans-serif",
      'Outfit': "'Outfit', sans-serif",
      'Lexend': "'Lexend', sans-serif",
      'Playfair': "'Playfair Display', serif",
    };
    root.style.setProperty('--font-family', fontMap[fontFamily] || "'Inter', sans-serif");

    // Apply Density (Typography Scale)
    const sizeMap: Record<string, string> = {
      'Small': '14px',
      'Medium': '16px',
      'Large': '17px',
      'XL': '18px'
    };
    // Setting a base font size variable if your CSS uses rem/em relative to something dynamic, 
    // or you could set it on the html tag. Tailwind uses rems based on root.
    root.style.fontSize = sizeMap[density] || '16px';

  }, [primaryColor, fontFamily, density]);

  const toggleTheme = () => setIsDark(!isDark);

  const handleAddLead = (newLeadData: Omit<Lead, 'id'>) => {
    const leadToAdd: Lead = {
      ...newLeadData,
      id: `L${Date.now()}`,
      score: 50,
      scoreBreakdown: { fit: 50, engagement: 50, budget: 50 },
      notes: 'Newly created lead.',
      lastContact: new Date().toISOString().split('T')[0],
      name: `${newLeadData.firstName || ''} ${newLeadData.lastName || ''}`.trim(),
      owner: 'Bayas Ahamed',
    };
    setLeads(prevLeads => [leadToAdd, ...prevLeads]);
  };

  const handleUpdateLead = (updatedLead: Lead) => {
    setLeads(prevLeads => prevLeads.map(lead => 
      lead.id === updatedLead.id ? { ...lead, ...updatedLead, name: `${updatedLead.firstName || ''} ${updatedLead.lastName || ''}`.trim() } : lead
    ));
  };

  const handleDeleteLeads = (leadIdsToDelete: string[]) => {
    setLeads(prevLeads => prevLeads.filter(lead => !leadIdsToDelete.includes(lead.id)));
  };

  const handleAddContact = (contactData: Omit<Contact, 'id' | 'lastActivity'>) => {
    const newContact: Contact = {
      ...contactData,
      id: `C${Date.now()}`,
      lastActivity: 'Just now',
    } as Contact;
    setContacts(prevContacts => [newContact, ...prevContacts]);
  };

  const handleUpdateContact = (updatedContact: Contact) => {
    setContacts(prevContacts => prevContacts.map(c => 
      c.id === updatedContact.id ? updatedContact : c
    ));
  };

  const handleAddAccount = (newAccount: Account) => {
    setAccounts(prevAccounts => [...prevAccounts, newAccount]);
  };

  const handleUpdateAccount = (updatedAccount: Account) => {
    setAccounts(prevAccounts => prevAccounts.map(a => 
      a.id === updatedAccount.id ? updatedAccount : a
    ));
  };

  const handleDeleteAccount = (accountId: string) => {
    setAccounts(prevAccounts => prevAccounts.filter(a => a.id !== accountId));
  };

  const handleAddCall = (callData: Omit<Call, 'id'>) => {
    const newCall: Call = {
      ...callData,
      id: `CALL-${Date.now()}`,
    };
    setCalls(prevCalls => [newCall, ...prevCalls]);
  };

  const handleAddMeeting = (newMeeting: Meeting) => {
    setMeetings(prev => [...prev, newMeeting]);
  };

  const handleUpdateMeeting = (updatedMeeting: Meeting) => {
    setMeetings(prev => prev.map(m => m.id === updatedMeeting.id ? updatedMeeting : m));
  };

  const handleDeleteMeeting = (meetingId: string) => {
    setMeetings(prev => prev.filter(m => m.id !== meetingId));
  };

  const handleAddDeal = (newDeal: Deal) => {
    const dealWithActivity = {
      ...newDeal,
      activities: [
        {
          id: Date.now().toString(),
          type: 'created' as const,
          description: 'Deal created',
          timestamp: new Date().toISOString()
        }
      ]
    };
    setDeals(prevDeals => [...prevDeals, dealWithActivity]);
  };

  const handleUpdateDeal = (updatedDeal: Deal) => {
    setDeals(prevDeals => {
      const oldDeal = prevDeals.find(d => d.id === updatedDeal.id);
      if (!oldDeal) return prevDeals;

      const newActivities: Activity[] = [];
      const timestamp = new Date().toISOString();

      if (oldDeal.stage !== updatedDeal.stage) {
        newActivities.push({ id: Date.now().toString() + 's', type: 'stage_change', description: `Stage updated to ${updatedDeal.stage}`, timestamp });
      }
      if (oldDeal.value !== updatedDeal.value) {
        newActivities.push({ id: Date.now().toString() + 'v', type: 'value_change', description: `Value updated from $${oldDeal.value.toLocaleString()} to $${updatedDeal.value.toLocaleString()}`, timestamp });
      }
      if (oldDeal.probability !== updatedDeal.probability) {
        newActivities.push({ id: Date.now().toString() + 'p', type: 'probability_change', description: `Probability updated from ${oldDeal.probability}% to ${updatedDeal.probability}%`, timestamp });
      }

      const hasManualActivity = updatedDeal.activities && updatedDeal.activities.length > (oldDeal.activities?.length || 0);
      if (newActivities.length === 0 && !hasManualActivity && JSON.stringify(oldDeal) !== JSON.stringify(updatedDeal)) {
         newActivities.push({ id: Date.now().toString() + 'u', type: 'update', description: `Deal details updated`, timestamp });
      }

      const baseActivities = updatedDeal.activities && updatedDeal.activities.length >= (oldDeal.activities?.length || 0) 
        ? updatedDeal.activities 
        : (oldDeal.activities || []);

      const finalDeal = {
        ...updatedDeal,
        activities: [...baseActivities, ...newActivities]
      };

      return prevDeals.map(d => d.id === updatedDeal.id ? finalDeal : d);
    });
  };

  const handleAddTask = (newTask: Task) => {
    setTasks(prev => [newTask, ...prev]);
  };

  const handleUpdateTask = (updatedTask: Task) => {
    setTasks(prev => prev.map(t => t.id === updatedTask.id ? updatedTask : t));
  };

  const handleDeleteTask = (taskId: string) => {
    setTasks(prev => prev.filter(t => t.id !== taskId));
  };

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return <Dashboard leads={leads} deals={deals} tasks={tasks} meetings={meetings} isDark={isDark} pipelineGoal={pipelineGoal} />;
      case 'leads':
        return <Leads leads={leads} onAddLead={handleAddLead} onUpdateLead={handleUpdateLead} onDeleteLeads={handleDeleteLeads} />;
      case 'pipeline':
        return <Pipeline deals={deals} onAddDeal={handleAddDeal} onUpdateDeal={handleUpdateDeal} pipelineGoal={pipelineGoal} onSetGoal={handleSetPipelineGoal} />;
      case 'tasks':
        return <Tasks tasks={tasks} onAddTask={handleAddTask} onUpdateTask={handleUpdateTask} onDeleteTask={handleDeleteTask} />;
      case 'meetings':
        return <Meetings 
          meetings={meetings} 
          contacts={contacts}
          accounts={accounts}
          onAddMeeting={handleAddMeeting} 
          onUpdateMeeting={handleUpdateMeeting} 
          onDeleteMeeting={handleDeleteMeeting}
        />;
      case 'contacts':
        return <Contacts contacts={contacts} onAddContact={handleAddContact} onUpdateContact={handleUpdateContact} />;
      case 'accounts':
        return <Accounts 
          accounts={accounts} 
          contacts={contacts} 
          deals={deals}
          leads={leads}
          meetings={meetings}
          onAddAccount={handleAddAccount} 
          onUpdateAccount={handleUpdateAccount}
          onDeleteAccount={handleDeleteAccount}
          onAddContact={handleAddContact}
        />;
      case 'calls':
        return <Calls calls={calls} leads={leads} contacts={contacts} onAddCall={handleAddCall} />;
      case 'settings':
        return <Settings 
          isDark={isDark} 
          toggleTheme={toggleTheme} 
          primaryColor={primaryColor} 
          setPrimaryColor={setPrimaryColor} 
          pipelineGoal={pipelineGoal}
          setPipelineGoal={handleSetPipelineGoal}
          // Theme Props
          fontFamily={fontFamily}
          setFontFamily={setFontFamily}
          density={density}
          setDensity={setDensity}
          // Regional Props
          weekStart={weekStart}
          setWeekStart={setWeekStart}
          dateFormat={dateFormat}
          setDateFormat={setDateFormat}
          timeZone={timeZone}
          setTimeZone={setTimeZone}
          timeFormat={timeFormat}
          setTimeFormat={setTimeFormat}
          workingDays={workingDays}
          setWorkingDays={setWorkingDays}
          fiscalYearStart={fiscalYearStart}
          setFiscalYearStart={setFiscalYearStart}
        />;
      case 'campaigns': return <PlaceholderModule title="Campaigns" />;
      case 'documents': return <PlaceholderModule title="Documents" />;
      case 'visits': return <PlaceholderModule title="Visits" />;
      case 'projects': return <PlaceholderModule title="Projects" />;
      default: return <Dashboard leads={leads} deals={deals} tasks={tasks} meetings={meetings} isDark={isDark} pipelineGoal={pipelineGoal} />;
    }
  };

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-slate-950 overflow-hidden text-slate-900 dark:text-slate-100 font-sans selection:bg-primary-500/30 transition-colors duration-300">
      {sidebarOpen && (
        <div className="fixed inset-0 bg-black/50 z-20 md:hidden" onClick={() => setSidebarOpen(false)} />
      )}
      <Sidebar 
        currentView={currentView} 
        setView={(view) => { setCurrentView(view); setSidebarOpen(false); }} 
        isOpen={sidebarOpen}
        isDark={isDark}
        toggleTheme={toggleTheme}
      />
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        {/* Background Grid Pattern */}
        <div className="absolute inset-0 z-0 pointer-events-none bg-grid-pattern dark:bg-grid-pattern-dark bg-grid opacity-[0.03] dark:opacity-[0.05]"></div>

        <header className="md:hidden flex items-center justify-between px-4 py-3 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 transition-colors duration-300 z-10">
          <div className="flex items-center">
            <button onClick={() => setSidebarOpen(true)} className="p-2 -ml-2 text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white">
              <IconMenu className="w-6 h-6" />
            </button>
            <span className="ml-2 font-bold text-slate-900 dark:text-white">NovaCRM</span>
          </div>
          <Notifications tasks={tasks} onNavigateToTasks={handleNavigateToTasks} />
        </header>
        {currentView !== 'settings' && (
            <div className="hidden md:block absolute top-6 right-8 z-20">
            <Notifications tasks={tasks} onNavigateToTasks={handleNavigateToTasks} />
            </div>
        )}
        <main className={`flex-1 overflow-y-auto ${currentView === 'settings' ? 'p-0' : 'p-4 md:p-8'} scroll-smooth z-10`}>
          <div className={`${currentView === 'settings' ? 'h-full' : 'max-w-7xl mx-auto h-full'}`}>
            {renderContent()}
          </div>
        </main>
      </div>
      <AIChat leads={leads} deals={deals} />
    </div>
  );
}

export default App;

import React, { useState, useMemo } from 'react';
import { Account, Contact, Deal, Lead, Meeting } from '../types';
import { IconBuilding, IconFilter, IconPhone, IconX, IconGlobe, IconUser, IconArrowUp, IconArrowDown } from './Icons';
import AccountDetail from './AccountDetail';

interface AccountsProps {
  accounts: Account[];
  contacts?: Contact[];
  deals?: Deal[];
  leads?: Lead[];
  meetings?: Meeting[];
  onAddAccount: (account: Account) => void;
  onUpdateAccount?: (account: Account) => void;
  onDeleteAccount?: (accountId: string) => void;
  onAddContact: (contact: Omit<Contact, 'id' | 'lastActivity'>) => void;
}

type SortKey = keyof Account;

const Accounts: React.FC<AccountsProps> = ({ 
    accounts, 
    contacts = [], 
    deals = [], 
    leads = [],
    meetings = [],
    onAddAccount,
    onUpdateAccount,
    onDeleteAccount,
    onAddContact
}) => {
  const [viewMode, setViewMode] = useState<'list' | 'detail'>('list');
  const [selectedAccount, setSelectedAccount] = useState<Account | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  // Default sort by lastActivity descending
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: 'asc' | 'desc' } | null>({ key: 'lastActivity', direction: 'desc' });

  const [formData, setFormData] = useState<Partial<Account>>({
      name: '',
      industry: '',
      website: '',
      phone: '',
      owner: 'Alex Chen'
  });

  const sortedAccounts = useMemo(() => {
    let sortableItems = [...accounts];
    if (sortConfig !== null) {
      sortableItems.sort((a, b) => {
        const aValue = a[sortConfig.key] || '';
        const bValue = b[sortConfig.key] || '';
        if (aValue < bValue) return sortConfig.direction === 'asc' ? -1 : 1;
        if (aValue > bValue) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
      });
    }
    return sortableItems;
  }, [accounts, sortConfig]);

  const requestSort = (key: SortKey) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const getSortIcon = (key: SortKey) => {
    if (!sortConfig || sortConfig.key !== key) return <span className="w-3 h-3 opacity-0 group-hover:opacity-50 transition-opacity">↕️</span>;
    if (sortConfig.direction === 'asc') return <IconArrowUp className="w-3 h-3 text-primary-500" />;
    return <IconArrowDown className="w-3 h-3 text-primary-500" />;
  };

  const handleOpenDetail = (account: Account) => {
      setSelectedAccount(account);
      setViewMode('detail');
  };

  const handleBackToList = () => {
      setSelectedAccount(null);
      setViewMode('list');
  };

  const handleEditAccount = () => {
      if (selectedAccount) {
          setFormData(selectedAccount);
          setIsModalOpen(true);
      }
  };

  const handleDeleteAccountAction = () => {
      if (selectedAccount && onDeleteAccount) {
          if (window.confirm(`Are you sure you want to delete ${selectedAccount.name}?`)) {
              onDeleteAccount(selectedAccount.id);
              handleBackToList();
          }
      }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
      const { name, value } = e.target;
      setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if (!formData.name) {
          alert("Account Name is required");
          return;
      }

      const accountData: Account = {
          id: selectedAccount && viewMode === 'detail' ? selectedAccount.id : `A-${Date.now()}`,
          name: formData.name || '',
          industry: formData.industry || 'Technology',
          website: formData.website || '',
          phone: formData.phone || '',
          owner: formData.owner || 'Alex Chen',
          primaryContact: selectedAccount?.primaryContact, // Preserve existing
          lastActivity: selectedAccount?.lastActivity || new Date().toISOString().split('T')[0] // Default to today
      };

      if (selectedAccount && viewMode === 'detail' && onUpdateAccount) {
          onUpdateAccount(accountData);
          setSelectedAccount(accountData); // Update local view
      } else {
          onAddAccount(accountData);
      }

      setFormData({ name: '', industry: '', website: '', phone: '', owner: 'Alex Chen' });
      setIsModalOpen(false);
  };

  if (viewMode === 'detail' && selectedAccount) {
      return (
          <AccountDetail 
            account={selectedAccount} 
            onBack={handleBackToList}
            onEdit={handleEditAccount}
            onDelete={handleDeleteAccountAction}
            contacts={contacts}
            deals={deals}
            leads={leads}
            meetings={meetings}
            onAddContact={onAddContact}
          />
      );
  }

  return (
    <div className="space-y-6 animate-fade-in h-full flex flex-col">
      <div className="flex justify-between items-center flex-shrink-0">
        <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Accounts</h1>
        <button 
            onClick={() => {
                setSelectedAccount(null);
                setFormData({ name: '', industry: '', website: '', phone: '', owner: 'Alex Chen' });
                setIsModalOpen(true);
            }}
            className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-all transform hover:-translate-y-0.5"
        >
          + New Account
        </button>
      </div>

      <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm dark:shadow-none overflow-hidden flex flex-col flex-1">
        <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between bg-slate-50/50 dark:bg-slate-900/50">
           <div className="flex items-center space-x-2">
             <IconFilter className="w-4 h-4 text-slate-400" />
             <select className="bg-transparent text-sm font-medium text-slate-700 dark:text-slate-300 focus:outline-none cursor-pointer">
               <option>All Accounts</option>
               <option>My Accounts</option>
             </select>
           </div>
        </div>
        <div className="overflow-auto flex-1 custom-scrollbar">
            <table className="w-full text-left text-sm">
            <thead className="sticky top-0 z-10 bg-slate-50 dark:bg-slate-950/90 backdrop-blur-sm shadow-sm">
                <tr className="text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-800">
                <th className="px-6 py-4 text-sm font-medium"><button onClick={() => requestSort('name')} className="flex items-center gap-2 hover:text-primary-600 transition-colors">Account Name {getSortIcon('name')}</button></th>
                <th className="px-6 py-4 text-sm font-medium"><button onClick={() => requestSort('industry')} className="flex items-center gap-2 hover:text-primary-600 transition-colors">Industry {getSortIcon('industry')}</button></th>
                <th className="px-6 py-4 text-sm font-medium"><button onClick={() => requestSort('phone')} className="flex items-center gap-2 hover:text-primary-600 transition-colors">Phone {getSortIcon('phone')}</button></th>
                <th className="px-6 py-4 text-sm font-medium"><button onClick={() => requestSort('website')} className="flex items-center gap-2 hover:text-primary-600 transition-colors">Website {getSortIcon('website')}</button></th>
                <th className="px-6 py-4 text-sm font-medium"><button onClick={() => requestSort('primaryContact')} className="flex items-center gap-2 hover:text-primary-600 transition-colors">Primary Contact {getSortIcon('primaryContact')}</button></th>
