                    <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300">{account.industry}</td>
                    <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300">
                        {account.phone && (
                            <div className="flex items-center">
