                            <IconCalendar className="w-12 h-12 mb-3 text-slate-300 dark:text-slate-600" />
                            <p className="text-lg font-medium">No meetings found</p>
                            <p className="text-sm">Schedule a meeting to discuss business opportunities.</p>
                        </div>
