  onUpdateAccount?: (account: Account) => void;
  onDeleteAccount?: (accountId: string) => void;
  onAddContact: (contact: Omit<Contact, 'id' | 'lastActivity'>) => void;
  onAddCall?: (call: Omit<Call, 'id'>) => void;
}

type SortKey = keyof Account;

const Accounts: React.FC<AccountsProps> = ({ 
    accounts, 
    contacts = [], 
    deals = [], 
    leads = [],
    meetings = [],
    calls = [],
    onAddAccount,
    onUpdateAccount,
    onDeleteAccount,
    onAddContact,
    onAddCall
}) => {
  const [viewMode, setViewMode] = useState<'list' | 'detail'>('list');
  const [selectedAccount, setSelectedAccount] = useState<Account | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  // Default sort by lastActivity descending
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: 'asc' | 'desc' } | null>({ key: 'lastActivity', direction: 'desc' });

  const [formData, setFormData] = useState<Partial<Account>>({
      name: '',
      industry: '',
      website: '',
      phone: '',
      owner: 'Alex Chen'
  });

  const sortedAccounts = useMemo(() => {
    let sortableItems = [...accounts];
    if (sortConfig !== null) {
      sortableItems.sort((a, b) => {
        const aValue = a[sortConfig.key] || '';
        const bValue = b[sortConfig.key] || '';
        if (aValue < bValue) return sortConfig.direction === 'asc' ? -1 : 1;
        if (aValue > bValue) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
      });
    }
    return sortableItems;
  }, [accounts, sortConfig]);

  const requestSort = (key: SortKey) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const getSortIcon = (key: SortKey) => {
    if (!sortConfig || sortConfig.key !== key) return <span className="w-3 h-3 opacity-0 group-hover:opacity-50 transition-opacity">↕️</span>;
    if (sortConfig.direction === 'asc') return <IconArrowUp className="w-3 h-3 text-primary-500" />;
    return <IconArrowDown className="w-3 h-3 text-primary-500" />;
  };

  const handleOpenDetail = (account: Account) => {
      setSelectedAccount(account);
      setViewMode('detail');
  };

  const handleBackToList = () => {
      setSelectedAccount(null);
      setViewMode('list');
  };

  const handleEditAccount = () => {
      if (selectedAccount) {
          setFormData(selectedAccount);
          setIsModalOpen(true);
      }
  };

  const handleDeleteAccountAction = () => {
      if (selectedAccount && onDeleteAccount) {
          if (window.confirm(`Are you sure you want to delete ${selectedAccount.name}?`)) {
              onDeleteAccount(selectedAccount.id);
              handleBackToList();
          }
      }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
      const { name, value } = e.target;
      setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if (!formData.name) {
          alert("Account Name is required");
          return;
      }

      const accountData: Account = {
          id: selectedAccount && viewMode === 'detail' ? selectedAccount.id : `A-${Date.now()}`,
          name: formData.name || '',
          industry: formData.industry || 'Technology',
          website: formData.website || '',
          phone: formData.phone || '',
          owner: formData.owner || 'Alex Chen',
          primaryContact: selectedAccount?.primaryContact, // Preserve existing
          lastActivity: selectedAccount?.lastActivity || new Date().toISOString().split('T')[0] // Default to today
      };

      if (selectedAccount && viewMode === 'detail' && onUpdateAccount) {
          onUpdateAccount(accountData);
          setSelectedAccount(accountData); // Update local view
      } else {
          onAddAccount(accountData);
      }

      setFormData({ name: '', industry: '', website: '', phone: '', owner: 'Alex Chen' });
      setIsModalOpen(false);
  };

  if (viewMode === 'detail' && selectedAccount) {
      return (
          <AccountDetail 
            account={selectedAccount} 
            onBack={handleBackToList}
            onEdit={handleEditAccount}
            onDelete={handleDeleteAccountAction}
            contacts={contacts}
            deals={deals}
            leads={leads}
            meetings={meetings}
            calls={calls}
            onAddContact={onAddContact}
            onAddCall={onAddCall}
            onUpdateAccount={(updatedAccount) => {
                if (onUpdateAccount) {
                    onUpdateAccount(updatedAccount);
                    setSelectedAccount(updatedAccount); // Update local state for immediate reflect
                }
            }}
          />
      );
  }

  return (
    <div className="space-y-6 animate-fade-in h-full flex flex-col">
      <div className="flex justify-between items-center flex-shrink-0">
        <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Accounts</h1>
        <button 
            onClick={() => {
                setSelectedAccount(null);
                setFormData({ name: '', industry: '', website: '', phone: '', owner: 'Alex Chen' });
                setIsModalOpen(true);
            }}
            className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-all transform hover:-translate-y-0.5"
        >
          + New Account
        </button>
      </div>

      <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm dark:shadow-none overflow-hidden flex flex-col flex-1">
        <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between bg-slate-50/50 dark:bg-slate-900/50">
           <div className="flex items-center space-x-2">
             <IconFilter className="w-4 h-4 text-slate-400" />
             <select className="bg-transparent text-sm font-medium text-slate-700 dark:text-slate-300 focus:outline-none cursor-pointer">
               <option>All Accounts</option>
               <option>My Accounts</option>
             </select>
           </div>
        </div>
        <div className="overflow-auto flex-1 custom-scrollbar">
            <table className="w-full text-left text-sm">
            <thead className="sticky top-0 z-10 bg-slate-50 dark:bg-slate-950/90 backdrop-blur-sm shadow-sm">
                <tr className="text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-800">
                <th className="px-6 py-4 text-sm font-medium"><button onClick={() => requestSort('name')} className="flex items-center gap-2 hover:text-primary-600 transition-colors">Account Name {getSortIcon('name')}</button></th>
                <th className="px-6 py-4 text-sm font-medium"><button onClick={() => requestSort('industry')} className="flex items-center gap-2 hover:text-primary-600 transition-colors">Industry {getSortIcon('industry')}</button></th>
                <th className="px-6 py-4 text-sm font-medium"><button onClick={() => requestSort('phone')} className="flex items-center gap-2 hover:text-primary-600 transition-colors">Phone {getSortIcon('phone')}</button></th>
                <th className="px-6 py-4 text-sm font-medium"><button onClick={() => requestSort('website')} className="flex items-center gap-2 hover:text-primary-600 transition-colors">Website {getSortIcon('website')}</button></th>
                <th className="px-6 py-4 text-sm font-medium"><button onClick={() => requestSort('primaryContact')} className="flex items-center gap-2 hover:text-primary-600 transition-colors">Primary Contact {getSortIcon('primaryContact')}</button></th>
                <th className="px-6 py-4 text-sm font-medium"><button onClick={() => requestSort('owner')} className="flex items-center gap-2 hover:text-primary-600 transition-colors">Owner {getSortIcon('owner')}</button></th>
                <th className="px-6 py-4 text-sm font-medium"><button onClick={() => requestSort('lastActivity')} className="flex items-center gap-2 hover:text-primary-600 transition-colors">Last Activity {getSortIcon('lastActivity')}</button></th>
                </tr>
            </thead>
            <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
                {sortedAccounts.map((account) => (
                <tr 
                    key={account.id} 
                    onClick={() => handleOpenDetail(account)}
                    className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors group cursor-pointer"
                >
                    <td className="px-6 py-4 text-base font-medium text-slate-900 dark:text-white flex items-center">
                        <div className="p-2 bg-primary-50 dark:bg-primary-900/20 rounded-lg mr-3 group-hover:bg-primary-100 dark:group-hover:bg-primary-800/30 transition-colors">
                            <IconBuilding className="w-4 h-4 text-primary-600 dark:text-primary-400" />
                        </div>
                        <span className="group-hover:text-primary-600 dark:group-hover:text-primary-400 transition-colors">{account.name}</span>
                    </td>
                    <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300">{account.industry}</td>
                    <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300">
                        {account.phone && (
                            <div className="flex items-center">
                                <IconPhone className="w-3 h-3 mr-1.5 opacity-50" />
                                {account.phone}
                            </div>
                        )}
                    </td>
                    <td className="px-6 py-4 text-sm">
                        {account.website && (
                             <span className="text-blue-600 dark:text-blue-400 hover:underline flex items-center truncate max-w-[200px]">
                                 {account.website}
                             </span>
                        )}
                    </td>
                    <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300">
                        {account.primaryContact || '-'}
                    </td>
                    <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300 flex items-center">
                         <div className="w-6 h-6 rounded-full bg-slate-200 dark:bg-slate-700 flex items-center justify-center text-xs font-bold mr-2 text-slate-600 dark:text-slate-300">
                             {account.owner.charAt(0)}
                         </div>
                        {account.owner}
                    </td>
                    <td className="px-6 py-4 text-sm text-slate-500 dark:text-slate-400">
                        {account.lastActivity || '-'}
                    </td>
                </tr>
                ))}
            </tbody>
            </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="w-full max-w-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-scale-in">
            <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50">
              <h2 className="text-2xl font-bold text-slate-900 dark:text-white flex items-center">
                 <IconBuilding className="w-6 h-6 mr-3 text-primary-600" />
                 {selectedAccount && viewMode === 'detail' ? 'Edit Account' : 'Create New Account'}
              </h2>
              <button 
                onClick={() => setIsModalOpen(false)} 
                className="text-slate-400 hover:text-slate-600 dark:hover:text-white transition-colors"
              >
                <IconX className="w-6 h-6" />
              </button>
            </div>

            <div className="p-8 overflow-y-auto custom-scrollbar">
              <form onSubmit={handleSubmit} className="space-y-6">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Account Name <span className="text-red-500">*</span></label>
                        <div className="relative">
                             <input 
                                type="text" 
                                name="name" 
                                value={formData.name} 
                                onChange={handleInputChange} 
                                required
                                className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 text-slate-900 dark:text-white" 
                                placeholder="e.g. Acme Corp"
                             />
                             <IconBuilding className="absolute right-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400 pointer-events-none" />
                        </div>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Industry</label>
                        <select 
                            name="industry" 
                            value={formData.industry} 
                            onChange={handleInputChange}
                            className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 text-slate-900 dark:text-white appearance-none cursor-pointer"
                        >
                            <option value="">- Select Industry -</option>
                            <option value="Technology">Technology</option>
                            <option value="Retail">Retail</option>
                            <option value="Manufacturing">Manufacturing</option>
                            <option value="Finance">Finance</option>
                            <option value="Healthcare">Healthcare</option>
                            <option value="Defense">Defense</option>
                            <option value="Consulting">Consulting</option>
                        </select>
                    </div>
                 </div>

                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Phone</label>
                        <div className="relative">
                            <input 
                                type="tel" 
                                name="phone" 
                                value={formData.phone} 
                                onChange={handleInputChange} 
                                className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 text-slate-900 dark:text-white" 
                                placeholder="(555) 000-0000"
                            />
                            <IconPhone className="absolute right-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400 pointer-events-none" />
                        </div>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Website</label>
                        <div className="relative">
                            <input 
                                type="text" 
                                name="website" 
                                value={formData.website} 
                                onChange={handleInputChange} 
                                className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 text-slate-900 dark:text-white" 
                                placeholder="www.example.com"
                            />
                            <IconGlobe className="absolute right-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400 pointer-events-none" />
                        </div>
                    </div>
                 </div>

                 <div>
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Owner</label>
                    <div className="relative">
                        <input 
                            type="text" 
                            name="owner" 
                            value={formData.owner} 
                            readOnly
                            className="w-full px-4 py-2.5 bg-slate-100 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-500 dark:text-slate-400 cursor-not-allowed" 
                        />
                        <IconUser className="absolute right-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400 pointer-events-none" />
                    </div>
                 </div>

                 <div className="pt-4 flex gap-3 justify-end">
                    <button 
                        type="button"
                        onClick={() => setIsModalOpen(false)}
                        className="px-5 py-2.5 text-sm font-medium text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 rounded-xl hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors"
                    >
                        Cancel
                    </button>
                    <button 
                        type="submit"
                        className="px-6 py-2.5 text-sm font-medium text-white bg-primary-600 rounded-xl hover:bg-primary-500 shadow-lg shadow-primary-500/25 transition-colors"
                    >
                        {selectedAccount && viewMode === 'detail' ? 'Save Changes' : 'Create Account'}
                    </button>
                 </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Accounts;

import React, { useState } from 'react';
import { Account, Contact, Deal, Lead, Meeting, Call } from '../types';
import { 
  IconArrowLeft, 
  IconEdit, 
  IconTrash, 
  IconBuilding, 
  IconGlobe, 
  IconPhone, 
  IconUser, 
  IconUsers, 
  IconKanban,
  IconSparkles,
  IconMail,
  IconPlus,
  IconX,
  IconTarget,
  IconCalendar,
  IconClock,
  IconActivity
} from './Icons';
import { generateAccountInsights } from '../services/geminiService';

interface AccountDetailProps {
  account: Account;
  onBack: () => void;
  onEdit: () => void;
  onDelete: () => void;
  contacts: Contact[];
  deals: Deal[];
  leads: Lead[];
  meetings?: Meeting[];
  calls?: Call[];
  onAddContact: (contact: Omit<Contact, 'id' | 'lastActivity'>) => void;
  onAddCall?: (call: Omit<Call, 'id'>) => void;
  onUpdateAccount?: (account: Account) => void;
}

const DetailRow: React.FC<{ label: string; value?: string | number | null; icon?: React.ElementType; isLink?: boolean }> = ({ label, value, icon: Icon, isLink }) => {
  if (!value) return null;
  return (
    <div>
      <label className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">{label}</label>
      <p className="text-base font-medium text-slate-900 dark:text-slate-100 flex items-center mt-1">
        {Icon && <Icon className="w-4 h-4 mr-2 text-slate-400" />}
        {isLink ? (
            <a href={value.toString().startsWith('http') ? value.toString() : `https://${value}`} target="_blank" rel="noopener noreferrer" className="text-primary-600 hover:underline">
                {value}
            </a>
        ) : value}
      </p>
    </div>
  );
};

const AccountDetail: React.FC<AccountDetailProps> = ({ account, onBack, onEdit, onDelete, contacts, deals, leads, meetings = [], calls = [], onAddContact, onAddCall, onUpdateAccount }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'contacts' | 'leads' | 'deals' | 'meetings' | 'calls'>('overview');
  const [insights, setInsights] = useState<string>('');
  const [isLoadingInsights, setIsLoadingInsights] = useState(false);

  // Contact Modal State
  const [isContactModalOpen, setIsContactModalOpen] = useState(false);
  const [newContact, setNewContact] = useState({ firstName: '', lastName: '', title: '', email: '', phone: '' });
  const [isAddingPrimary, setIsAddingPrimary] = useState(false);

  // Call Modal State
  const [isCallModalOpen, setIsCallModalOpen] = useState(false);
  const [newCall, setNewCall] = useState<{subject: string; relatedToId: string; type: string; outcome: string; notes: string}>({
      subject: '',
      relatedToId: account.id, // Default to account ID if logging against account directly
      type: 'Outbound',
      outcome: 'Connected',
      notes: ''
  });

  const relatedContacts = contacts.filter(c => c.company === account.name);
  const relatedDeals = deals.filter(d => d.company === account.name);
  const relatedLeads = leads.filter(l => l.company === account.name);
  // Simple matching by name or if the meeting relates to a contact of this account
  const relatedMeetings = meetings.filter(m => 
      m.relatedTo === account.name || 
      relatedContacts.some(c => c.name === m.relatedTo)
  );

  const relatedCalls = calls.filter(c => 
      c.relatedTo === account.name ||
      relatedContacts.some(contact => contact.name === c.relatedTo)
  );

  const primaryContactDetails = contacts.find(c => c.name === account.primaryContact);

  const handleGenerateInsights = async () => {
    setIsLoadingInsights(true);
    const result = await generateAccountInsights(account);
    setInsights(result);
    setIsLoadingInsights(false);
  };

  const handleContactSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      const contactName = `${newContact.firstName} ${newContact.lastName}`.trim();
      onAddContact({
          name: contactName,
          firstName: newContact.firstName,
          lastName: newContact.lastName,
          title: newContact.title,
          email: newContact.email,
          phone: newContact.phone,
          company: account.name, // Auto-link to this account
          status: 'New'
      });

      if (isAddingPrimary && onUpdateAccount) {
          onUpdateAccount({
              ...account,
              primaryContact: contactName
          });
      }

      setIsContactModalOpen(false);
      setIsAddingPrimary(false);
      setNewContact({ firstName: '', lastName: '', title: '', email: '', phone: '' });
  };

  const handleContactChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      setNewContact({ ...newContact, [e.target.name]: e.target.value });
  };

  const handleCallSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if (onAddCall) {
          // Resolve relatedTo name
          let relatedName = account.name;
          // Check if relatedToId matches a contact
          const contact = relatedContacts.find(c => c.id === newCall.relatedToId);
          if (contact) {
              relatedName = contact.name;
          }

          onAddCall({
              subject: newCall.subject,
              relatedTo: relatedName,
              relatedToId: newCall.relatedToId,
              type: newCall.type as any,
              outcome: newCall.outcome as any,
              notes: newCall.notes,
              date: new Date().toISOString()
          });
      }
      setIsCallModalOpen(false);
      setNewCall({ subject: '', relatedToId: account.id, type: 'Outbound', outcome: 'Connected', notes: '' });
  };

  const openAddContactModal = (asPrimary = false) => {
      setIsAddingPrimary(asPrimary);
      setIsContactModalOpen(true);
  };

  const getAllActivities = () => {
    const activities: { id: string; type: string; description: string; timestamp: string; icon: any; color: string }[] = [];

    // Meetings
    relatedMeetings.forEach(m => {
      activities.push({
        id: m.id,
        type: 'Meeting',
        description: `Scheduled: ${m.title} (${m.type})`,
        timestamp: m.date, 
        icon: IconCalendar,
        color: 'text-purple-600 bg-purple-100 dark:text-purple-400 dark:bg-purple-900/20'
      });
    });

    // Calls
    relatedCalls.forEach(c => {
        activities.push({
            id: c.id,
            type: 'Call',
            description: `${c.type}: ${c.subject} - ${c.outcome}`,
            timestamp: c.date,
            icon: IconPhone,
            color: 'text-cyan-600 bg-cyan-100 dark:text-cyan-400 dark:bg-cyan-900/20'
        });
    });

    // Deal Activities
    relatedDeals.forEach(d => {
      d.activities.forEach(a => {
        activities.push({
          id: a.id,
          type: 'Deal',
          description: `${d.title}: ${a.description}`,
          timestamp: a.timestamp,
          icon: IconKanban,
          color: 'text-blue-600 bg-blue-100 dark:text-blue-400 dark:bg-blue-900/20'
        });
      });
    });

    // Lead Activities
    relatedLeads.forEach(l => {
      if (l.activities) {
        l.activities.forEach(a => {
          activities.push({
            id: a.id,
            type: 'Lead',
            description: `${l.name}: ${a.description}`,
            timestamp: a.timestamp,
            icon: IconTarget,
            color: 'text-emerald-600 bg-emerald-100 dark:text-emerald-400 dark:bg-emerald-900/20'
          });
        });
      }
    });

    return activities.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()).slice(0, 10);
  };

  const accountActivities = getAllActivities();

  return (
    <div className="bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm h-full flex flex-col animate-fade-in">
      {/* Header */}
      <div className="flex-shrink-0">
        <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-950/50 rounded-t-xl">
            <div className="flex items-center gap-4">
            <button onClick={onBack} className="p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800 transition-colors group">
                <IconArrowLeft className="w-5 h-5 text-slate-600 dark:text-slate-300 group-hover:-translate-x-1 transition-transform" />
            </button>
            <div>
                <h1 className="text-2xl font-bold text-slate-900 dark:text-white flex items-center gap-2">
                    <IconBuilding className="w-6 h-6 text-primary-600 dark:text-primary-400" />
