                                <option>Inbound</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Outcome</label>
                            <select 
                                value={newCall.outcome} 
                                onChange={(e) => setNewCall({...newCall, outcome: e.target.value})}
