                    <Legend 
                        layout="horizontal" 
                        verticalAlign="bottom" 
                        align="center"
                        iconType="circle"
                        wrapperStyle={{ paddingTop: '20px', fontSize: '12px' }}
                    />
                </PieChart>
             </ResponsiveContainer>
          </ChartWidget>
      </div>

      {/* Row 3: Secondary Charts & Lists */}
      <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">

          {/* Deal Stage Funnel */}
          <ChartWidget title="Opportunities by Stage">
             <ResponsiveContainer width="100%" height={250}>
                <BarChart data={barData} layout="vertical" margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
                    <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke={isDark ? "#334155" : "#e2e8f0"} opacity={0.3} />
                    <XAxis type="number" hide />
                    <YAxis dataKey="name" type="category" width={80} tick={{ fill: isDark ? '#94a3b8' : '#64748b', fontSize: 11 }} axisLine={false} tickLine={false} />
                    <Tooltip cursor={{fill: 'transparent'}} contentStyle={{ borderRadius: '8px', backgroundColor: isDark ? '#1e293b' : '#fff' }} />
                    <Bar dataKey="count" fill="#10b981" radius={[0, 4, 4, 0]} barSize={20} />
                </BarChart>
             </ResponsiveContainer>
          </ChartWidget>

          {/* Top Opportunities List */}
          <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 shadow-sm hover:shadow-md transition-shadow">
              <div className="flex items-center justify-between mb-6">
                  <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100">Top Opportunities</h3>
                  <IconTrendingUp className="w-5 h-5 text-emerald-500" />
              </div>
              <div className="space-y-4">
                  {topDeals.length > 0 ? topDeals.map((deal, idx) => (
                      <div key={deal.id} className="flex items-center justify-between p-3 rounded-xl bg-slate-50 dark:bg-slate-800/50 border border-slate-100 dark:border-slate-700/50 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors">
                          <div className="flex items-center gap-3">
                              <span className="font-bold text-slate-400 text-sm">#{idx + 1}</span>
                              <div>
                                  <p className="font-semibold text-sm text-slate-900 dark:text-white">{deal.title}</p>
                                  <p className="text-xs text-slate-500">{deal.company}</p>
                              </div>
                          </div>
                          <div className="text-right">
                              <p className="font-bold text-slate-900 dark:text-white text-sm">${deal.value.toLocaleString()}</p>
                              <span className="text-[10px] uppercase font-bold text-indigo-500 bg-indigo-50 dark:bg-indigo-900/20 px-1.5 py-0.5 rounded">{deal.probability}%</span>
                          </div>
                      </div>
                  )) : (
                      <div className="text-center text-slate-500 text-sm py-8">No open opportunities found.</div>
                  )}
              </div>
          </div>

          {/* Recent Activity */}
          <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 shadow-sm hover:shadow-md transition-shadow flex flex-col">
              <div className="flex items-center justify-between mb-6">
                  <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100">Activity Feed</h3>
                  <IconActivity className="w-5 h-5 text-blue-500" />
              </div>
              <div className="overflow-y-auto flex-1 custom-scrollbar -mr-2 pr-2">
                  {allActivities.length > 0 ? allActivities.map((act, index) => (
                      <ActivityItem 
                          key={act.id} 
                          activity={act} 
                          isLast={index === allActivities.length - 1}
                      />
                  )) : (
                      <div className="flex flex-col items-center justify-center h-40 text-slate-500">
                          <IconSparkles className="w-8 h-8 mb-2 opacity-20" />
                          <p className="text-sm">No recent activity.</p>
                      </div>
                  )}
              </div>
          </div>

      </div>
    </div>
  );
};

