                                className={`flex-1 py-1.5 text-xs font-bold rounded-md transition-all ${aiTab === 'location' ? 'bg-indigo-600 text-white shadow-sm' : 'text-slate-600 dark:text-slate-400 hover:bg-white/50 dark:hover:bg-slate-700'}`}
                            >
                                Location
