import React, { useState, useEffect } from 'react';
import { Lead, LeadStatus, Deal } from '../types';
import { 
  IconArrowLeft, 
  IconEdit, 
  IconTrash, 
  IconMail, 
  IconPhone, 
  IconBuilding, 
  IconSparkles, 
  IconInfo, 
  IconGlobe, 
  IconUsers, 
  IconBot, 
  IconUser,
  IconMessageSquare,
  IconCopy,
  IconKanban,
  IconChevronRight
} from './Icons';
import { generateFollowUpSuggestions } from '../services/geminiService';

interface LeadDetailProps {
  lead: Lead;
  onBack: () => void;
  onEdit: () => void;
  onDelete: () => void;
  onNurture: () => void;
  isNurturing: boolean;
  leads: Lead[];
  onComposeEmail: (lead: Lead, initialContent: string) => void;
  onAddDeal?: (deal: Deal) => void;
  onUpdateLead: (lead: Lead) => void;
  onSelectLead?: (lead: Lead) => void;
}

const DetailRow: React.FC<{ label: string; value?: string | number | null; icon?: React.ElementType }> = ({ label, value, icon: Icon }) => {
  if (!value && value !== 0) return null;
  return (
    <div>
      <label className="text-sm text-slate-500 dark:text-slate-400 uppercase tracking-wider">{label}</label>
      <p className="text-lg text-slate-900 dark:text-slate-100 flex items-center mt-1">
        {Icon && <Icon className="w-4 h-4 mr-2 text-slate-400" />}
        {value}
      </p>
    </div>
  );
};

const LeadDetail: React.FC<LeadDetailProps> = ({ lead, onBack, onEdit, onDelete, onNurture, isNurturing, leads, onComposeEmail, onAddDeal, onUpdateLead, onSelectLead }) => {
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [isLoadingSuggestions, setIsLoadingSuggestions] = useState(true);

  useEffect(() => {
    let isMounted = true;
    const fetchSuggestions = async () => {
      setIsLoadingSuggestions(true);
      const result = await generateFollowUpSuggestions(lead);
      if (isMounted) {
        setSuggestions(result);
        setIsLoadingSuggestions(false);
      }
    };

    fetchSuggestions();

    return () => {
      isMounted = false;
    };
  }, [lead]);

  const handleConvertToOpportunity = () => {
      if (confirm(`Convert ${lead.name} to an Opportunity? This will create a new opportunity and update the lead status to Qualified.`)) {
          if (onAddDeal) {
              const newDeal: Deal = {
                  id: `D-${Date.now()}`,
                  title: `${lead.company || lead.name} - Opportunity`,
                  company: lead.company,
                  value: lead.value || 0,
                  stage: 'Qualification',
                  probability: 20,
                  closeDate: new Date(new Date().setMonth(new Date().getMonth() + 1)).toISOString().split('T')[0], // Default 1 month out
                  email: lead.email,
                  phone: lead.phone,
                  activities: [{
                      id: `DA-${Date.now()}`,
                      type: 'created',
                      description: `Opportunity created from Lead: ${lead.name}`,
                      timestamp: new Date().toISOString()
                  }]
              };
              onAddDeal(newDeal);
              onUpdateLead({ ...lead, status: LeadStatus.QUALIFIED, rating: 'Active' });
              alert("Opportunity created successfully!");
          }
      }
  };

  const similarLeads = leads.filter(l => 
    l.id !== lead.id &&
    (l.industry === lead.industry || l.company === lead.company) &&
    l.score > 70
  ).sort((a, b) => b.score - a.score).slice(0, 3);

  return (
    <div className="bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm h-full flex flex-col animate-fade-in">
      {/* Header */}
      <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-950/50 rounded-t-xl flex-shrink-0">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800 transition-colors">
            <IconArrowLeft className="w-5 h-5 text-slate-600 dark:text-slate-300" />
          </button>
          <div>
            <h1 className="text-3xl font-bold text-slate-900 dark:text-white">{lead.name}</h1>
            <p className="text-lg text-slate-500 dark:text-slate-400">{lead.company}</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {lead.status !== LeadStatus.QUALIFIED && lead.status !== LeadStatus.CLOSED && (
              <button 
                onClick={handleConvertToOpportunity}
                className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-white bg-emerald-600 rounded-md hover:bg-emerald-500 shadow-lg shadow-emerald-500/20 transition-colors mr-2"
              >
                <IconKanban className="w-4 h-4" /> 
                Convert to Opportunity
              </button>
          )}
          <button 
            onClick={onNurture}
            disabled={isNurturing}
            className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-md hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-colors disabled:opacity-70 disabled:cursor-not-allowed"
          >
            <IconBot className="w-4 h-4" /> 
            {isNurturing ? 'Generating...' : 'Nurture'}
          </button>
          <button onClick={onEdit} className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-md hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">
            <IconEdit className="w-4 h-4" /> Edit
          </button>
          <button onClick={onDelete} className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-red-600 bg-red-50 dark:bg-red-500/10 border border-red-200 dark:border-red-500/20 rounded-md hover:bg-red-100 dark:hover:bg-red-500/20 transition-colors">
            <IconTrash className="w-4 h-4" /> Delete
          </button>
        </div>
      </div>

      {/* Body */}
      <div className="flex-1 overflow-y-auto p-8">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Main Details Column */}
          <div className="lg:col-span-2 space-y-8">
            <div className="p-6 bg-slate-50 dark:bg-slate-800/50 rounded-lg border border-slate-200 dark:border-slate-800">
              <h3 className="text-xl font-semibold text-slate-900 dark:text-white mb-6">Lead Information</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <DetailRow label="Lead Owner" value={lead.owner} icon={IconUser} />
                <DetailRow label="First Name" value={lead.firstName || lead.name.split(' ')[0]} />
                <DetailRow label="Last Name" value={lead.lastName || lead.name.split(' ').slice(1).join(' ')} />
                <DetailRow label="Company" value={lead.company} icon={IconBuilding} />
                <DetailRow label="Title" value={lead.title} />
                <DetailRow label="Lead Source" value={lead.leadSource} />
                <DetailRow label="Industry" value={lead.industry} />
                <DetailRow label="Annual Revenue" value={lead.annualRevenue ? `$${lead.annualRevenue.toLocaleString()}`: null} />
                <DetailRow label="Status" value={lead.status} />
              </div>
            </div>

            <div className="p-6 bg-slate-50 dark:bg-slate-800/50 rounded-lg border border-slate-200 dark:border-slate-800">
              <h3 className="text-xl font-semibold text-slate-900 dark:text-white mb-6">Contact Details</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <DetailRow label="Email" value={lead.email} icon={IconMail} />
                <DetailRow label="Phone" value={lead.phone} icon={IconPhone} />
                <DetailRow label="Mobile" value={lead.mobile} />
                <DetailRow label="Website" value={lead.website} icon={IconGlobe} />
                <DetailRow label="City" value={lead.city} />
              </div>
            </div>

            {/* AI Follow-up Suggestions */}
            <div className="p-6 bg-slate-50 dark:bg-slate-800/50 rounded-lg border border-slate-200 dark:border-slate-800">
              <h3 className="text-xl font-semibold text-slate-900 dark:text-white mb-6 flex items-center">
                <IconSparkles className="w-5 h-5 mr-2 text-primary-500" />
                AI Follow-up Suggestions
              </h3>
              {isLoadingSuggestions ? (
                <div className="space-y-4 animate-pulse">
                  <div className="h-4 bg-slate-200 dark:bg-slate-700 rounded w-5/6"></div>
                  <div className="h-4 bg-slate-200 dark:bg-slate-700 rounded w-full"></div>
                  <div className="h-4 bg-slate-200 dark:bg-slate-700 rounded w-4/6"></div>
                </div>
              ) : (
                <div className="space-y-4">
                  {suggestions.map((suggestion, index) => (
                    <div key={index} className="flex items-start gap-3 group">
                      <IconMessageSquare className="w-4 h-4 text-slate-400 mt-1 flex-shrink-0" />
                      <p className="flex-1 text-base text-slate-700 dark:text-slate-300">
                        {suggestion}
                      </p>
                      <div className="flex flex-col gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button 
                            onClick={() => onComposeEmail(lead, suggestion)}
                            className="p-1.5 rounded-md text-primary-600 bg-primary-50 hover:bg-primary-100 dark:text-primary-400 dark:bg-primary-900/30 dark:hover:bg-primary-900/50 transition-colors"
                            title="Draft Email"
                        >
                            <IconMail className="w-4 h-4" />
                        </button>
                        <button 
                            onClick={() => navigator.clipboard.writeText(suggestion)}
                            className="p-1.5 rounded-md text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors"
                            title="Copy suggestion"
                        >
                            <IconCopy className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

             {similarLeads.length > 0 && (
              <div className="p-6 bg-slate-50 dark:bg-slate-800/50 rounded-lg border border-slate-200 dark:border-slate-800">
                <h3 className="text-xl font-semibold text-slate-900 dark:text-white mb-6">Similar High-Potential Leads</h3>
                <div className="space-y-4">
                  {similarLeads.map(similarLead => (
                    <div 
                        key={similarLead.id} 
                        onClick={() => onSelectLead && onSelectLead(similarLead)}
                        className="flex justify-between items-center p-3 bg-white dark:bg-slate-800 rounded-md border border-slate-200 dark:border-slate-700 cursor-pointer hover:border-primary-500 dark:hover:border-primary-500 transition-colors group"
                    >
                      <div>
                        <p className="font-medium text-slate-800 dark:text-slate-100 group-hover:text-primary-600 dark:group-hover:text-primary-400 transition-colors">{similarLead.name}</p>
                        <p className="text-sm text-slate-500 dark:text-slate-400">{similarLead.company}</p>
                      </div>
                      <div className="flex items-center gap-4">
                        <div className="flex items-center gap-2">
                            <div className="w-12 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden">
                            <div className="h-full bg-emerald-500" style={{width: `${similarLead.score}%`}}></div>
                            </div>
                            <span className="text-sm font-bold text-emerald-600 dark:text-emerald-400">{similarLead.score}</span>
                        </div>
                        <IconChevronRight className="w-4 h-4 text-slate-300 dark:text-slate-600" />
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* AI Score Column */}
          <div className="space-y-6">
            <div className="p-6 bg-gradient-to-br from-primary-50 to-blue-50 dark:from-slate-800 dark:to-slate-800/50 rounded-lg border border-slate-200 dark:border-slate-800">
               <h3 className="text-xl font-semibold text-slate-900 dark:text-white mb-4 flex items-center">
                 <IconSparkles className="w-5 h-5 mr-2 text-primary-500" />
                 AI Scoring
               </h3>
               <div className="flex items-center justify-between mb-2">
                 <span className="text-base text-slate-600 dark:text-slate-300">Overall Score</span>
                 <span className="text-5xl font-bold text-primary-600 dark:text-primary-400">{lead.score}</span>
               </div>
               <div className="w-full bg-slate-200 dark:bg-slate-700 rounded-full h-2.5 mb-6">
                  <div className={`h-2.5 rounded-full ${
                      lead.score > 75 ? 'bg-emerald-500' :
                      lead.score > 40 ? 'bg-yellow-500' :
                      'bg-slate-400'
                  }`} style={{ width: `${lead.score}%` }}></div>
               </div>

               <div className="space-y-4">
                 <div className="flex justify-between items-center text-base">
                   <span className="text-slate-500 dark:text-slate-400">Profile Fit</span>
                   <span className="font-semibold text-emerald-600 dark:text-emerald-400">{lead.scoreBreakdown.fit}%</span>
                 </div>
                  <div className="flex justify-between items-center text-base">
                   <span className="text-slate-500 dark:text-slate-400">Engagement</span>
                   <span className="font-semibold text-primary-600 dark:text-primary-400">{lead.scoreBreakdown.engagement}%</span>
                 </div>
                  <div className="flex justify-between items-center text-base">
                   <span className="text-slate-500 dark:text-slate-400">Budget</span>
                   <span className="font-semibold text-blue-600 dark:text-blue-400">{lead.scoreBreakdown.budget}%</span>
                 </div>
               </div>
            </div>
             <div className="p-6 bg-slate-50 dark:bg-slate-800/50 rounded-lg border border-slate-200 dark:border-slate-800">
              <h3 className="text-xl font-semibold text-slate-900 dark:text-white mb-4">Notes</h3>
              <p className="text-base text-slate-600 dark:text-slate-300 italic">
                {lead.notes || "No notes available for this lead."}
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LeadDetail;

import React, { useState, useMemo } from 'react';
import { Lead, Deal } from '../types';
import { 
  IconSearch, 
  IconPlus, 
  IconFilter, 
  IconArrowUp, 
  IconArrowDown, 
  IconMail, 
  IconTrash, 
  IconSparkles,
  IconUser,
  IconCheckSquare,
  IconX
} from './Icons';
import LeadDetail from './LeadDetail';
import LeadForm from './LeadForm';
import { 
  generateSmartFilterCriteria, 
  batchAnalyzeLeads, 
  generateAIBulkEmail, 
  generateNurtureSequence 
} from '../services/geminiService';

interface LeadsProps {
  leads: Lead[];
  onAddLead: (lead: Omit<Lead, 'id'>) => void;
  onUpdateLead: (lead: Lead) => void;
  onDeleteLeads: (ids: string[]) => void;
  onAddDeal: (deal: Deal) => void;
}

type ViewMode = 'list' | 'detail' | 'create' | 'edit';
type SortKey = keyof Lead;

const Leads: React.FC<LeadsProps> = ({ leads, onAddLead, onUpdateLead, onDeleteLeads, onAddDeal }) => {
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [selectedLead, setSelectedLead] = useState<Lead | null>(null);
  const [selectedLeadIds, setSelectedLeadIds] = useState<Set<string>>(new Set());

  // Filtering & Sorting
  const [searchQuery, setSearchQuery] = useState('');
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: 'asc' | 'desc' } | null>(null);
  const [isSmartFiltering, setIsSmartFiltering] = useState(false);
  const [activeFilters, setActiveFilters] = useState<any[]>([]);
  const [smartFilterDescription, setSmartFilterDescription] = useState('');

  // AI Actions State
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiAnalysisResult, setAiAnalysisResult] = useState('');
  const [isDraftingEmail, setIsDraftingEmail] = useState(false);
  const [emailDraft, setEmailDraft] = useState('');
  const [isNurturing, setIsNurturing] = useState(false);

  // Email Modal
  const [isEmailModalOpen, setIsEmailModalOpen] = useState(false);

  const handleSmartFilter = async () => {
    if (!searchQuery) return;
    setIsSmartFiltering(true);
    const result = await generateSmartFilterCriteria(searchQuery);
    if (result.filters && result.filters.length > 0) {
      setActiveFilters(result.filters);
      setSmartFilterDescription(`Filtered by AI: ${searchQuery}`);
    } else {
      alert("AI couldn't interpret filters from your query. Showing text search results.");
      setActiveFilters([]);
      setSmartFilterDescription('');
    }
    setIsSmartFiltering(false);
  };

  const clearFilters = () => {
    setSearchQuery('');
    setActiveFilters([]);
    setSmartFilterDescription('');
  };

  const filteredLeads = useMemo(() => {
    let result = leads;

    // Apply AI Smart Filters if active
    if (activeFilters.length > 0) {
      result = result.filter(lead => {
        return activeFilters.every(filter => {
          const leadValue = (lead as any)[filter.field];
          if (leadValue === undefined) return false;

          switch (filter.operator) {
            case '$eq': return String(leadValue).toLowerCase() === String(filter.value).toLowerCase();
            case '$contains': return String(leadValue).toLowerCase().includes(String(filter.value).toLowerCase());
            case '$gt': return leadValue > filter.value;
            case '$lt': return leadValue < filter.value;
            default: return true;
          }
        });
      });
    } 
    // Fallback to simple text search if no AI filters but query exists (or explicit text search)
    else if (searchQuery) {
      const lowerQuery = searchQuery.toLowerCase();
      result = result.filter(lead => 
        lead.name.toLowerCase().includes(lowerQuery) || 
        lead.company.toLowerCase().includes(lowerQuery) ||
        lead.email.toLowerCase().includes(lowerQuery)
      );
    }

    // Apply Sorting
    if (sortConfig) {
      result = [...result].sort((a, b) => {
        const aVal = a[sortConfig.key] || '';
        const bVal = b[sortConfig.key] || '';

        if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
        if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
      });
    }

    return result;
  }, [leads, activeFilters, searchQuery, sortConfig]);

  const toggleSort = (key: SortKey) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const toggleSelectLead = (id: string) => {
    const newSelected = new Set(selectedLeadIds);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedLeadIds(newSelected);
  };

  const toggleSelectAll = () => {
    if (selectedLeadIds.size === filteredLeads.length) {
      setSelectedLeadIds(new Set());
    } else {
      setSelectedLeadIds(new Set(filteredLeads.map(l => l.id)));
    }
  };

  const handleBulkAnalyze = async () => {
    if (selectedLeadIds.size === 0) return;
    setIsAnalyzing(true);
    const selectedLeadsList = leads.filter(l => selectedLeadIds.has(l.id));
    const analysis = await batchAnalyzeLeads(selectedLeadsList);
    setAiAnalysisResult(analysis);
    setIsAnalyzing(false);
  };

  const handleBulkEmail = async () => {
    if (selectedLeadIds.size === 0) return;
    setIsDraftingEmail(true);
    const selectedLeadsList = leads.filter(l => selectedLeadIds.has(l.id));
    const draft = await generateAIBulkEmail(selectedLeadsList, 'formal');
    setEmailDraft(draft);
    setIsDraftingEmail(false);
    setIsEmailModalOpen(true);
  };

  const handleBulkDelete = () => {
    if (selectedLeadIds.size === 0) return;
    if (window.confirm(`Are you sure you want to delete ${selectedLeadIds.size} leads?`)) {
      onDeleteLeads(Array.from(selectedLeadIds));
      setSelectedLeadIds(new Set());
    }
  };

  const handleNurtureLead = async (lead: Lead) => {
    setIsNurturing(true);
    const sequence = await generateNurtureSequence(lead);
    console.log("Generated Sequence:", sequence);
    // In a real app, this would save to the DB. For now we just alert or log.
    alert(`Nurture sequence generated for ${lead.name} with ${sequence.length} emails.`);
    setIsNurturing(false);
  };

  // View Navigation Handlers
  const handleViewLeadDetail = (lead: Lead) => {
    setSelectedLead(lead);
    setViewMode('detail');
  };

  const handleEditLead = (lead: Lead) => {
    setSelectedLead(lead);
    setViewMode('edit');
  };

  const handleCreateLead = () => {
    setSelectedLead(null);
    setViewMode('create');
  };

  const handleBackToList = () => {
    setViewMode('list');
    setSelectedLead(null);
  };

  const handleSaveLead = (leadData: Lead) => {
    if (viewMode === 'create') {
        onAddLead(leadData);
    } else if (viewMode === 'edit') {
        onUpdateLead(leadData);
    }
    setViewMode('list');
  };

  const handleDirectEmail = (lead: Lead, initialContent: string = '') => {
    // Open email modal pre-filled
    setEmailDraft(initialContent);
    setIsEmailModalOpen(true);
  };

  // Render Logic
  if (viewMode === 'detail' && selectedLead) {
    return (
        <LeadDetail 
            lead={selectedLead} 
            onBack={handleBackToList} 
            onEdit={() => handleEditLead(selectedLead)} 
            onDelete={() => {
                onDeleteLeads([selectedLead.id]);
                handleBackToList();
            }} 
            onNurture={() => handleNurtureLead(selectedLead)} 
            isNurturing={isNurturing} 
            leads={leads} 
            onComposeEmail={handleDirectEmail} 
            onAddDeal={onAddDeal}
            onUpdateLead={onUpdateLead}
            onSelectLead={handleViewLeadDetail}
        />
    );
  }

  if (viewMode === 'create' || (viewMode === 'edit' && selectedLead)) {
      return (
          <LeadForm 
            onCancel={handleBackToList}
            onSave={handleSaveLead}
            initialData={viewMode === 'edit' ? selectedLead : undefined}
          />
      );
  }

  return (
    <div className="space-y-6 animate-fade-in h-full flex flex-col">
      {/* Header & Toolbar */}
      <div className="flex flex-col gap-4 flex-shrink-0">
        <div className="flex justify-between items-center">
            <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Leads</h1>
            <button 
                onClick={handleCreateLead}
                className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-all flex items-center"
            >
                <IconPlus className="w-4 h-4 mr-2" /> New Lead
            </button>
        </div>

        <div className="bg-white dark:bg-slate-900 p-4 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col md:flex-row gap-4 items-center justify-between">
            {/* Smart Search */}
            <div className="relative flex-1 w-full md:w-auto">
                <div className="relative">
                    <input 
                        type="text" 
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleSmartFilter()}
                        placeholder="Search or ask AI (e.g., 'High value tech leads in NY')" 
                        className="w-full pl-10 pr-12 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white transition-all shadow-sm"
                    />
                    <IconSearch className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                    <button 
                        onClick={handleSmartFilter}
                        disabled={!searchQuery || isSmartFiltering}
                        className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 bg-primary-100 dark:bg-primary-900/30 text-primary-600 dark:text-primary-400 rounded-lg hover:bg-primary-200 dark:hover:bg-primary-900/50 transition-colors disabled:opacity-50"
                        title="AI Smart Filter"
                    >
                        {isSmartFiltering ? <span className="animate-spin">⟳</span> : <IconSparkles className="w-4 h-4" />}
                    </button>
                </div>
            </div>

            {/* Actions for Selection */}
            {selectedLeadIds.size > 0 && (
                <div className="flex items-center gap-2 animate-fade-in">
                    <span className="text-sm font-medium text-slate-500 dark:text-slate-400 mr-2">{selectedLeadIds.size} selected</span>
                    <button onClick={handleBulkAnalyze} disabled={isAnalyzing} className="px-3 py-2 text-sm font-medium text-indigo-600 bg-indigo-50 dark:bg-indigo-900/20 rounded-lg hover:bg-indigo-100 dark:hover:bg-indigo-900/40 transition-colors flex items-center">
                        {isAnalyzing ? 'Analyzing...' : <><IconSparkles className="w-4 h-4 mr-2" /> Analyze</>}
                    </button>
                    <button onClick={handleBulkEmail} disabled={isDraftingEmail} className="px-3 py-2 text-sm font-medium text-blue-600 bg-blue-50 dark:bg-blue-900/20 rounded-lg hover:bg-blue-100 dark:hover:bg-blue-900/40 transition-colors flex items-center">
                        <IconMail className="w-4 h-4 mr-2" /> Email
                    </button>
                    <button onClick={handleBulkDelete} className="px-3 py-2 text-sm font-medium text-red-600 bg-red-50 dark:bg-red-900/20 rounded-lg hover:bg-red-100 dark:hover:bg-red-900/40 transition-colors flex items-center">
                        <IconTrash className="w-4 h-4 mr-2" /> Delete
                    </button>
                </div>
            )}
        </div>

        {/* Active Filter Chips */}
        {smartFilterDescription && (
            <div className="flex items-center gap-2">
                <span className="text-xs font-bold text-slate-500 uppercase">Active Filter:</span>
                <div className="flex items-center bg-primary-50 dark:bg-primary-900/20 text-primary-700 dark:text-primary-300 px-3 py-1 rounded-full text-sm border border-primary-100 dark:border-primary-800">
                    <IconSparkles className="w-3 h-3 mr-2" />
                    {smartFilterDescription}
                    <button onClick={clearFilters} className="ml-2 hover:text-primary-900"><IconX className="w-3 h-3" /></button>
                </div>
            </div>
        )}

        {/* AI Analysis Result Panel */}
        {aiAnalysisResult && (
             <div className="bg-indigo-50 dark:bg-indigo-900/10 p-4 rounded-xl border border-indigo-100 dark:border-indigo-800/30 flex items-start gap-4 animate-fade-in relative">
                 <div className="p-2 bg-white dark:bg-slate-800 rounded-lg shadow-sm">
                    <IconSparkles className="w-5 h-5 text-indigo-500" />
                 </div>
                 <div className="flex-1">
                     <h4 className="font-bold text-indigo-900 dark:text-indigo-100 text-sm mb-1">AI Batch Analysis</h4>
                     <div className="text-sm text-indigo-800 dark:text-indigo-200 whitespace-pre-line leading-relaxed">
                         {aiAnalysisResult}
                     </div>
                 </div>
                 <button onClick={() => setAiAnalysisResult('')} className="absolute top-2 right-2 text-indigo-400 hover:text-indigo-600"><IconX className="w-4 h-4" /></button>
             </div>
        )}
      </div>

      {/* Table List */}
      <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden flex flex-col flex-1">
         <div className="overflow-auto flex-1 custom-scrollbar">
            <table className="w-full text-left text-sm">
                <thead className="bg-slate-50 dark:bg-slate-950/90 text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-800 sticky top-0 z-10 backdrop-blur-sm">
                    <tr>
                        <th className="px-4 py-4 w-10">
                            <div 
                                onClick={toggleSelectAll} 
                                className={`w-5 h-5 rounded border flex items-center justify-center cursor-pointer transition-colors ${selectedLeadIds.size > 0 && selectedLeadIds.size === filteredLeads.length ? 'bg-primary-600 border-primary-600 text-white' : 'border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-800'}`}
                            >
                                {selectedLeadIds.size > 0 && selectedLeadIds.size === filteredLeads.length && <IconCheckSquare className="w-3.5 h-3.5" />}
                            </div>
                        </th>
                        <th className="px-6 py-4 font-medium cursor-pointer hover:text-primary-600" onClick={() => toggleSort('name')}>
                            <div className="flex items-center gap-1">Name {sortConfig?.key === 'name' ? (sortConfig.direction === 'asc' ? <IconArrowUp className="w-3 h-3" /> : <IconArrowDown className="w-3 h-3" />) : null}</div>
                        </th>
                        <th className="px-6 py-4 font-medium cursor-pointer hover:text-primary-600" onClick={() => toggleSort('company')}>
                             <div className="flex items-center gap-1">Company {sortConfig?.key === 'company' ? (sortConfig.direction === 'asc' ? <IconArrowUp className="w-3 h-3" /> : <IconArrowDown className="w-3 h-3" />) : null}</div>
                        </th>
                        <th className="px-6 py-4 font-medium cursor-pointer hover:text-primary-600" onClick={() => toggleSort('status')}>
                             <div className="flex items-center gap-1">Status {sortConfig?.key === 'status' ? (sortConfig.direction === 'asc' ? <IconArrowUp className="w-3 h-3" /> : <IconArrowDown className="w-3 h-3" />) : null}</div>
                        </th>
                        <th className="px-6 py-4 font-medium cursor-pointer hover:text-primary-600" onClick={() => toggleSort('score')}>
                             <div className="flex items-center gap-1">Score {sortConfig?.key === 'score' ? (sortConfig.direction === 'asc' ? <IconArrowUp className="w-3 h-3" /> : <IconArrowDown className="w-3 h-3" />) : null}</div>
                        </th>
                        <th className="px-6 py-4 font-medium">Owner</th>
                        <th className="px-6 py-4 font-medium text-right">Actions</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
                    {filteredLeads.map(lead => (
                        <tr 
                            key={lead.id} 
                            className={`hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors cursor-pointer group ${selectedLeadIds.has(lead.id) ? 'bg-slate-50 dark:bg-slate-800/80' : ''}`}
                            onClick={() => handleViewLeadDetail(lead)}
                        >
                            <td className="px-4 py-4" onClick={(e) => { e.stopPropagation(); toggleSelectLead(lead.id); }}>
                                <div className={`w-5 h-5 rounded border flex items-center justify-center cursor-pointer transition-colors ${selectedLeadIds.has(lead.id) ? 'bg-primary-600 border-primary-600 text-white' : 'border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-800'}`}>
                                    {selectedLeadIds.has(lead.id) && <IconCheckSquare className="w-3.5 h-3.5" />}
                                </div>
                            </td>
                            <td className="px-6 py-4">
                                <div className="flex items-center">
                                    <div className="w-8 h-8 rounded-full bg-slate-200 dark:bg-slate-700 flex items-center justify-center text-xs font-bold text-slate-600 dark:text-slate-300 mr-3">
                                        {lead.name.charAt(0)}
                                    </div>
                                    <div className="font-medium text-slate-900 dark:text-white group-hover:text-primary-600 dark:group-hover:text-primary-400 transition-colors">{lead.name}</div>
                                </div>
                            </td>
                            <td className="px-6 py-4 text-slate-600 dark:text-slate-300">{lead.company}</td>
                            <td className="px-6 py-4">
                                <span className={`px-2.5 py-1 text-xs font-medium rounded-full ${
                                    lead.status === 'New' ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400' :
                                    lead.status === 'Contacted' ? 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400' :
                                    lead.status === 'Qualified' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400' :
                                    'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400'
                                }`}>
                                    {lead.status}
                                </span>
                            </td>
                            <td className="px-6 py-4">
                                <div className="flex items-center gap-2">
                                    <span className={`font-bold ${lead.score > 70 ? 'text-emerald-600 dark:text-emerald-400' : lead.score < 40 ? 'text-red-500' : 'text-amber-500'}`}>{lead.score}</span>
                                    {lead.score > 80 && <IconSparkles className="w-3 h-3 text-amber-400" />}
                                </div>
                            </td>
                            <td className="px-6 py-4 text-slate-500 dark:text-slate-400 text-xs flex items-center gap-2">
                                <IconUser className="w-3 h-3" /> {lead.owner || 'Unassigned'}
                            </td>
                            <td className="px-6 py-4 text-right">
                                <button 
                                    onClick={(e) => { e.stopPropagation(); handleViewLeadDetail(lead); }} 
                                    className="p-2 text-slate-400 hover:text-primary-600 dark:hover:text-primary-400 opacity-0 group-hover:opacity-100 transition-opacity"
                                >
                                    Details
                                </button>
                            </td>
                        </tr>
                    ))}
                    {filteredLeads.length === 0 && (
                        <tr>
                            <td colSpan={7} className="px-6 py-12 text-center text-slate-500 dark:text-slate-400">
                                <div className="flex flex-col items-center justify-center">
                                    <IconSearch className="w-12 h-12 mb-3 text-slate-300 dark:text-slate-600" />
                                    <p className="text-lg font-medium">No leads found</p>
                                    <p className="text-sm">Try adjusting your filters or ask AI for help.</p>
                                </div>
                            </td>
                        </tr>
                    )}
                </tbody>
            </table>
         </div>
      </div>

      {/* Email Modal */}
      {isEmailModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
            <div className="w-full max-w-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden animate-scale-in">
                <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50">
                    <h3 className="font-bold text-lg text-slate-900 dark:text-white flex items-center">
                        <IconMail className="w-5 h-5 mr-2 text-primary-500" />
                        Compose Email
                    </h3>
                    <button onClick={() => setIsEmailModalOpen(false)} className="text-slate-400 hover:text-slate-600 dark:hover:text-white"><IconX className="w-5 h-5" /></button>
                </div>
                <div className="p-6">
                    <div className="mb-4">
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">To</label>
                        <div className="p-2 bg-slate-100 dark:bg-slate-800 rounded-lg text-sm text-slate-600 dark:text-slate-300">
                            {selectedLeadIds.size > 0 ? `${selectedLeadIds.size} Recipients selected` : selectedLead ? selectedLead.email : 'No recipient'}
                        </div>
                    </div>
                    <div className="mb-4">
                         <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Subject</label>
                         <input type="text" className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white" placeholder="Enter subject..." />
                    </div>
                    <div className="mb-4">
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Message</label>
                        <textarea 
                            value={emailDraft}
                            onChange={(e) => setEmailDraft(e.target.value)}
                            rows={10}
                            className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white font-mono text-sm"
                        ></textarea>
                    </div>
                    <div className="flex justify-end gap-3">
                         <button onClick={() => setIsEmailModalOpen(false)} className="px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">Cancel</button>
                         <button onClick={() => { alert('Email Sent!'); setIsEmailModalOpen(false); }} className="px-6 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-colors">Send Email</button>
                    </div>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

export default Leads;

import React, { useState, useMemo, useEffect } from 'react';
import { Lead, Deal } from '../types';
import { 
  IconSearch, 
  IconPlus, 
  IconFilter, 
  IconArrowUp, 
  IconArrowDown, 
  IconMail, 
  IconTrash, 
  IconSparkles,
  IconUser,
  IconCheckSquare,
  IconX
} from './Icons';
import LeadDetail from './LeadDetail';
import LeadForm from './LeadForm';
import { 
  generateSmartFilterCriteria, 
  batchAnalyzeLeads, 
  generateAIBulkEmail, 
  generateNurtureSequence 
} from '../services/geminiService';

interface LeadsProps {
  leads: Lead[];
  onAddLead: (lead: Omit<Lead, 'id'>) => void;
  onUpdateLead: (lead: Lead) => void;
  onDeleteLeads: (ids: string[]) => void;
  onAddDeal: (deal: Deal) => void;
}

type ViewMode = 'list' | 'detail' | 'create' | 'edit';
type SortKey = keyof Lead;

const Leads: React.FC<LeadsProps> = ({ leads, onAddLead, onUpdateLead, onDeleteLeads, onAddDeal }) => {
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [selectedLead, setSelectedLead] = useState<Lead | null>(null);
  const [selectedLeadIds, setSelectedLeadIds] = useState<Set<string>>(new Set());

  // Filtering & Sorting
  const [searchQuery, setSearchQuery] = useState('');
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: 'asc' | 'desc' } | null>(null);
  const [isSmartFiltering, setIsSmartFiltering] = useState(false);
  const [activeFilters, setActiveFilters] = useState<any[]>([]);
  const [smartFilterDescription, setSmartFilterDescription] = useState('');

  // AI Actions State
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiAnalysisResult, setAiAnalysisResult] = useState('');
  const [isDraftingEmail, setIsDraftingEmail] = useState(false);
  const [emailDraft, setEmailDraft] = useState('');
  const [isNurturing, setIsNurturing] = useState(false);

  // Email Modal
  const [isEmailModalOpen, setIsEmailModalOpen] = useState(false);

  // Sync selectedLead with leads prop to ensure updates (like status changes) are reflected immediately
  useEffect(() => {
    if (selectedLead) {
      const updatedLead = leads.find(l => l.id === selectedLead.id);
      if (updatedLead) {
        setSelectedLead(updatedLead);
      }
    }
  }, [leads, selectedLead?.id]); // Only re-run if leads change or the ID of selected lead changes

  const handleSmartFilter = async () => {
    if (!searchQuery) return;
    setIsSmartFiltering(true);
    const result = await generateSmartFilterCriteria(searchQuery);
    if (result.filters && result.filters.length > 0) {
      setActiveFilters(result.filters);
      setSmartFilterDescription(`Filtered by AI: ${searchQuery}`);
    } else {
      alert("AI couldn't interpret filters from your query. Showing text search results.");
      setActiveFilters([]);
      setSmartFilterDescription('');
    }
    setIsSmartFiltering(false);
  };

  const clearFilters = () => {
    setSearchQuery('');
    setActiveFilters([]);
    setSmartFilterDescription('');
  };

  const filteredLeads = useMemo(() => {
    let result = leads;

    // Apply AI Smart Filters if active
    if (activeFilters.length > 0) {
      result = result.filter(lead => {
        return activeFilters.every(filter => {
          const leadValue = (lead as any)[filter.field];
          if (leadValue === undefined) return false;

          switch (filter.operator) {
            case '$eq': return String(leadValue).toLowerCase() === String(filter.value).toLowerCase();
            case '$contains': return String(leadValue).toLowerCase().includes(String(filter.value).toLowerCase());
            case '$gt': return leadValue > filter.value;
            case '$lt': return leadValue < filter.value;
            default: return true;
          }
        });
      });
    } 
    // Fallback to simple text search if no AI filters but query exists (or explicit text search)
    else if (searchQuery) {
      const lowerQuery = searchQuery.toLowerCase();
      result = result.filter(lead => 
        lead.name.toLowerCase().includes(lowerQuery) || 
        lead.company.toLowerCase().includes(lowerQuery) ||
        lead.email.toLowerCase().includes(lowerQuery)
      );
    }

    // Apply Sorting
    if (sortConfig) {
      result = [...result].sort((a, b) => {
        const aVal = a[sortConfig.key] || '';
        const bVal = b[sortConfig.key] || '';

        if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
        if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
      });
    }

    return result;
  }, [leads, activeFilters, searchQuery, sortConfig]);

  const toggleSort = (key: SortKey) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const toggleSelectLead = (id: string) => {
    const newSelected = new Set(selectedLeadIds);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedLeadIds(newSelected);
  };

  const toggleSelectAll = () => {
    if (selectedLeadIds.size === filteredLeads.length) {
      setSelectedLeadIds(new Set());
    } else {
      setSelectedLeadIds(new Set(filteredLeads.map(l => l.id)));
    }
  };

  const handleBulkAnalyze = async () => {
    if (selectedLeadIds.size === 0) return;
    setIsAnalyzing(true);
    const selectedLeadsList = leads.filter(l => selectedLeadIds.has(l.id));
    const analysis = await batchAnalyzeLeads(selectedLeadsList);
    setAiAnalysisResult(analysis);
    setIsAnalyzing(false);
  };

  const handleBulkEmail = async () => {
    if (selectedLeadIds.size === 0) return;
    setIsDraftingEmail(true);
    const selectedLeadsList = leads.filter(l => selectedLeadIds.has(l.id));
    const draft = await generateAIBulkEmail(selectedLeadsList, 'formal');
    setEmailDraft(draft);
    setIsDraftingEmail(false);
    setIsEmailModalOpen(true);
  };

  const handleBulkDelete = () => {
    if (selectedLeadIds.size === 0) return;
    if (window.confirm(`Are you sure you want to delete ${selectedLeadIds.size} leads?`)) {
      onDeleteLeads(Array.from(selectedLeadIds));
      setSelectedLeadIds(new Set());
    }
  };

  const handleNurtureLead = async (lead: Lead) => {
    setIsNurturing(true);
    try {
      const sequence = await generateNurtureSequence(lead);
      if (sequence && sequence.length > 0) {
        // Open the email modal with the first email in the sequence
        setEmailDraft(`Subject: ${sequence[0].subject}\n\n${sequence[0].body}`);
        setIsEmailModalOpen(true);
      } else {
        alert("Could not generate a nurture sequence at this time.");
      }
    } catch (e) {
      console.error(e);
      alert("An error occurred while generating the sequence.");
    } finally {
      setIsNurturing(false);
    }
  };

  // View Navigation Handlers
  const handleViewLeadDetail = (lead: Lead) => {
    setSelectedLead(lead);
    setViewMode('detail');
  };

  const handleEditLead = (lead: Lead) => {
    setSelectedLead(lead);
    setViewMode('edit');
  };

  const handleCreateLead = () => {
    setSelectedLead(null);
    setViewMode('create');
  };

  const handleBackToList = () => {
    setViewMode('list');
    setSelectedLead(null);
  };

  const handleSaveLead = (leadData: Lead) => {
    if (viewMode === 'create') {
        onAddLead(leadData);
    } else if (viewMode === 'edit') {
        onUpdateLead(leadData);
    }
    setViewMode('list');
  };

  const handleDirectEmail = (lead: Lead, initialContent: string = '') => {
    // Open email modal pre-filled
    setEmailDraft(initialContent);
    setIsEmailModalOpen(true);
  };

  // Render Logic
  if (viewMode === 'detail' && selectedLead) {
    return (
        <LeadDetail 
            lead={selectedLead} 
            onBack={handleBackToList} 
            onEdit={() => handleEditLead(selectedLead)} 
            onDelete={() => {
                onDeleteLeads([selectedLead.id]);
                handleBackToList();
            }} 
            onNurture={() => handleNurtureLead(selectedLead)} 
            isNurturing={isNurturing} 
            leads={leads} 
            onComposeEmail={handleDirectEmail} 
            onAddDeal={onAddDeal}
            onUpdateLead={onUpdateLead}
            onSelectLead={handleViewLeadDetail}
        />
    );
  }

  if (viewMode === 'create' || (viewMode === 'edit' && selectedLead)) {
      return (
          <LeadForm 
            onCancel={handleBackToList}
            onSave={handleSaveLead}
            initialData={viewMode === 'edit' ? selectedLead : undefined}
          />
      );
  }

  return (
    <div className="space-y-6 animate-fade-in h-full flex flex-col">
      {/* Header & Toolbar */}
      <div className="flex flex-col gap-4 flex-shrink-0">
        <div className="flex justify-between items-center">
            <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Leads</h1>
            <button 
                onClick={handleCreateLead}
                className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-all flex items-center"
            >
                <IconPlus className="w-4 h-4 mr-2" /> New Lead
            </button>
        </div>

        <div className="bg-white dark:bg-slate-900 p-4 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col md:flex-row gap-4 items-center justify-between">
            {/* Smart Search */}
            <div className="relative flex-1 w-full md:w-auto">
                <div className="relative">
                    <input 
                        type="text" 
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleSmartFilter()}
                        placeholder="Search or ask AI (e.g., 'High value tech leads in NY')" 
                        className="w-full pl-10 pr-12 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white transition-all shadow-sm"
                    />
                    <IconSearch className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                    <button 
                        onClick={handleSmartFilter}
                        disabled={!searchQuery || isSmartFiltering}
                        className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 bg-primary-100 dark:bg-primary-900/30 text-primary-600 dark:text-primary-400 rounded-lg hover:bg-primary-200 dark:hover:bg-primary-900/50 transition-colors disabled:opacity-50"
                        title="AI Smart Filter"
                    >
                        {isSmartFiltering ? <span className="animate-spin">⟳</span> : <IconSparkles className="w-4 h-4" />}
                    </button>
                </div>
            </div>

            {/* Actions for Selection */}
            {selectedLeadIds.size > 0 && (
                <div className="flex items-center gap-2 animate-fade-in">
                    <span className="text-sm font-medium text-slate-500 dark:text-slate-400 mr-2">{selectedLeadIds.size} selected</span>
                    <button onClick={handleBulkAnalyze} disabled={isAnalyzing} className="px-3 py-2 text-sm font-medium text-indigo-600 bg-indigo-50 dark:bg-indigo-900/20 rounded-lg hover:bg-indigo-100 dark:hover:bg-indigo-900/40 transition-colors flex items-center">
                        {isAnalyzing ? 'Analyzing...' : <><IconSparkles className="w-4 h-4 mr-2" /> Analyze</>}
                    </button>
                    <button onClick={handleBulkEmail} disabled={isDraftingEmail} className="px-3 py-2 text-sm font-medium text-blue-600 bg-blue-50 dark:bg-blue-900/20 rounded-lg hover:bg-blue-100 dark:hover:bg-blue-900/40 transition-colors flex items-center">
                        <IconMail className="w-4 h-4 mr-2" /> Email
                    </button>
                    <button onClick={handleBulkDelete} className="px-3 py-2 text-sm font-medium text-red-600 bg-red-50 dark:bg-red-900/20 rounded-lg hover:bg-red-100 dark:hover:bg-red-900/40 transition-colors flex items-center">
                        <IconTrash className="w-4 h-4 mr-2" /> Delete
                    </button>
                </div>
            )}
        </div>

        {/* Active Filter Chips */}
        {smartFilterDescription && (
            <div className="flex items-center gap-2">
                <span className="text-xs font-bold text-slate-500 uppercase">Active Filter:</span>
                <div className="flex items-center bg-primary-50 dark:bg-primary-900/20 text-primary-700 dark:text-primary-300 px-3 py-1 rounded-full text-sm border border-primary-100 dark:border-primary-800">
                    <IconSparkles className="w-3 h-3 mr-2" />
                    {smartFilterDescription}
                    <button onClick={clearFilters} className="ml-2 hover:text-primary-900"><IconX className="w-3 h-3" /></button>
                </div>
            </div>
        )}

        {/* AI Analysis Result Panel */}
        {aiAnalysisResult && (
             <div className="bg-indigo-50 dark:bg-indigo-900/10 p-4 rounded-xl border border-indigo-100 dark:border-indigo-800/30 flex items-start gap-4 animate-fade-in relative">
                 <div className="p-2 bg-white dark:bg-slate-800 rounded-lg shadow-sm">
                    <IconSparkles className="w-5 h-5 text-indigo-500" />
                 </div>
                 <div className="flex-1">
                     <h4 className="font-bold text-indigo-900 dark:text-indigo-100 text-sm mb-1">AI Batch Analysis</h4>
                     <div className="text-sm text-indigo-800 dark:text-indigo-200 whitespace-pre-line leading-relaxed">
                         {aiAnalysisResult}
                     </div>
                 </div>
                 <button onClick={() => setAiAnalysisResult('')} className="absolute top-2 right-2 text-indigo-400 hover:text-indigo-600"><IconX className="w-4 h-4" /></button>
             </div>
        )}
      </div>

      {/* Table List */}
      <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden flex flex-col flex-1">
         <div className="overflow-auto flex-1 custom-scrollbar">
            <table className="w-full text-left text-sm">
                <thead className="bg-slate-50 dark:bg-slate-950/90 text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-800 sticky top-0 z-10 backdrop-blur-sm">
                    <tr>
                        <th className="px-4 py-4 w-10">
                            <div 
                                onClick={toggleSelectAll} 
                                className={`w-5 h-5 rounded border flex items-center justify-center cursor-pointer transition-colors ${selectedLeadIds.size > 0 && selectedLeadIds.size === filteredLeads.length ? 'bg-primary-600 border-primary-600 text-white' : 'border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-800'}`}
                            >
                                {selectedLeadIds.size > 0 && selectedLeadIds.size === filteredLeads.length && <IconCheckSquare className="w-3.5 h-3.5" />}
                            </div>
                        </th>
                        <th className="px-6 py-4 font-medium cursor-pointer hover:text-primary-600" onClick={() => toggleSort('name')}>
                            <div className="flex items-center gap-1">Name {sortConfig?.key === 'name' ? (sortConfig.direction === 'asc' ? <IconArrowUp className="w-3 h-3" /> : <IconArrowDown className="w-3 h-3" />) : null}</div>
                        </th>
                        <th className="px-6 py-4 font-medium cursor-pointer hover:text-primary-600" onClick={() => toggleSort('company')}>
                             <div className="flex items-center gap-1">Company {sortConfig?.key === 'company' ? (sortConfig.direction === 'asc' ? <IconArrowUp className="w-3 h-3" /> : <IconArrowDown className="w-3 h-3" />) : null}</div>
                        </th>
                        <th className="px-6 py-4 font-medium cursor-pointer hover:text-primary-600" onClick={() => toggleSort('status')}>
                             <div className="flex items-center gap-1">Status {sortConfig?.key === 'status' ? (sortConfig.direction === 'asc' ? <IconArrowUp className="w-3 h-3" /> : <IconArrowDown className="w-3 h-3" />) : null}</div>
                        </th>
                        <th className="px-6 py-4 font-medium cursor-pointer hover:text-primary-600" onClick={() => toggleSort('score')}>
                             <div className="flex items-center gap-1">Score {sortConfig?.key === 'score' ? (sortConfig.direction === 'asc' ? <IconArrowUp className="w-3 h-3" /> : <IconArrowDown className="w-3 h-3" />) : null}</div>
                        </th>
                        <th className="px-6 py-4 font-medium">Owner</th>
                        <th className="px-6 py-4 font-medium text-right">Actions</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
                    {filteredLeads.map(lead => (
                        <tr 
                            key={lead.id} 
                            className={`hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors cursor-pointer group ${selectedLeadIds.has(lead.id) ? 'bg-slate-50 dark:bg-slate-800/80' : ''}`}
                            onClick={() => handleViewLeadDetail(lead)}
                        >
                            <td className="px-4 py-4" onClick={(e) => { e.stopPropagation(); toggleSelectLead(lead.id); }}>
                                <div className={`w-5 h-5 rounded border flex items-center justify-center cursor-pointer transition-colors ${selectedLeadIds.has(lead.id) ? 'bg-primary-600 border-primary-600 text-white' : 'border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-800'}`}>
                                    {selectedLeadIds.has(lead.id) && <IconCheckSquare className="w-3.5 h-3.5" />}
                                </div>
                            </td>
                            <td className="px-6 py-4">
                                <div className="flex items-center">
                                    <div className="w-8 h-8 rounded-full bg-slate-200 dark:bg-slate-700 flex items-center justify-center text-xs font-bold text-slate-600 dark:text-slate-300 mr-3">
                                        {lead.name.charAt(0)}
                                    </div>
                                    <div className="font-medium text-slate-900 dark:text-white group-hover:text-primary-600 dark:group-hover:text-primary-400 transition-colors">{lead.name}</div>
                                </div>
                            </td>
                            <td className="px-6 py-4 text-slate-600 dark:text-slate-300">{lead.company}</td>
                            <td className="px-6 py-4">
                                <span className={`px-2.5 py-1 text-xs font-medium rounded-full ${
                                    lead.status === 'New' ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400' :
                                    lead.status === 'Contacted' ? 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400' :
                                    lead.status === 'Qualified' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400' :
                                    'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400'
                                }`}>
                                    {lead.status}
                                </span>
                            </td>
                            <td className="px-6 py-4">
                                <div className="flex items-center gap-2">
                                    <span className={`font-bold ${lead.score > 70 ? 'text-emerald-600 dark:text-emerald-400' : lead.score < 40 ? 'text-red-500' : 'text-amber-500'}`}>{lead.score}</span>
                                    {lead.score > 80 && <IconSparkles className="w-3 h-3 text-amber-400" />}
                                </div>
                            </td>
                            <td className="px-6 py-4 text-slate-500 dark:text-slate-400 text-xs flex items-center gap-2">
                                <IconUser className="w-3 h-3" /> {lead.owner || 'Unassigned'}
                            </td>
                            <td className="px-6 py-4 text-right">
                                <button 
                                    onClick={(e) => { e.stopPropagation(); handleViewLeadDetail(lead); }} 
                                    className="p-2 text-slate-400 hover:text-primary-600 dark:hover:text-primary-400 opacity-0 group-hover:opacity-100 transition-opacity"
                                >
                                    Details
                                </button>
                            </td>
                        </tr>
                    ))}
                    {filteredLeads.length === 0 && (
                        <tr>
                            <td colSpan={7} className="px-6 py-12 text-center text-slate-500 dark:text-slate-400">
                                <div className="flex flex-col items-center justify-center">
                                    <IconSearch className="w-12 h-12 mb-3 text-slate-300 dark:text-slate-600" />
