import React, { useState, useMemo, useEffect } from 'react';
import { Lead, Deal } from '../types';
import { 
  IconSearch, 
  IconPlus, 
  IconFilter, 
  IconArrowUp, 
  IconArrowDown, 
  IconMail, 
  IconTrash, 
  IconSparkles, 
  IconUser, 
  IconCheckSquare, 
  IconX
} from './Icons';
import LeadDetail from './LeadDetail';
import LeadForm from './LeadForm';
import { 
  generateSmartFilterCriteria, 
  batchAnalyzeLeads, 
  generateAIBulkEmail, 
  generateNurtureSequence 
} from '../services/geminiService';

interface LeadsProps {
  leads: Lead[];
  onAddLead: (lead: Omit<Lead, 'id'>) => void;
  onUpdateLead: (lead: Lead) => void;
  onDeleteLeads: (ids: string[]) => void;
  onAddDeal: (deal: Deal) => void;
  onViewOpportunities?: () => void;
}

type ViewMode = 'list' | 'detail' | 'create' | 'edit';
type SortKey = keyof Lead;

const Leads: React.FC<LeadsProps> = ({ leads, onAddLead, onUpdateLead, onDeleteLeads, onAddDeal, onViewOpportunities }) => {
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [selectedLead, setSelectedLead] = useState<Lead | null>(null);
  const [selectedLeadIds, setSelectedLeadIds] = useState<Set<string>>(new Set());

  // Filtering & Sorting
  const [searchQuery, setSearchQuery] = useState('');
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: 'asc' | 'desc' } | null>(null);
  const [isSmartFiltering, setIsSmartFiltering] = useState(false);
  const [activeFilters, setActiveFilters] = useState<any[]>([]);
  const [smartFilterDescription, setSmartFilterDescription] = useState('');

  // AI Actions State
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiAnalysisResult, setAiAnalysisResult] = useState('');
  const [isDraftingEmail, setIsDraftingEmail] = useState(false);
  const [emailDraft, setEmailDraft] = useState('');
  const [isNurturing, setIsNurturing] = useState(false);

  // Email Modal
  const [isEmailModalOpen, setIsEmailModalOpen] = useState(false);

  // Sync selectedLead with leads prop to ensure updates (like status changes) are reflected immediately
  useEffect(() => {
    if (selectedLead) {
      const updatedLead = leads.find(l => l.id === selectedLead.id);
      if (updatedLead) {
        setSelectedLead(updatedLead);
      }
    }
  }, [leads, selectedLead?.id]); // Only re-run if leads change or the ID of selected lead changes

  const handleSmartFilter = async () => {
    if (!searchQuery) return;
    setIsSmartFiltering(true);
    const result = await generateSmartFilterCriteria(searchQuery);
    if (result.filters && result.filters.length > 0) {
      setActiveFilters(result.filters);
      setSmartFilterDescription(`Filtered by AI: ${searchQuery}`);
    } else {
      alert("AI couldn't interpret filters from your query. Showing text search results.");
      setActiveFilters([]);
      setSmartFilterDescription('');
    }
    setIsSmartFiltering(false);
  };

  const clearFilters = () => {
    setSearchQuery('');
    setActiveFilters([]);
    setSmartFilterDescription('');
  };

  const filteredLeads = useMemo(() => {
    let result = leads;

    // Apply AI Smart Filters if active
    if (activeFilters.length > 0) {
      result = result.filter(lead => {
        return activeFilters.every(filter => {
          const leadValue = (lead as any)[filter.field];
          if (leadValue === undefined) return false;

          switch (filter.operator) {
            case '$eq': return String(leadValue).toLowerCase() === String(filter.value).toLowerCase();
            case '$contains': return String(leadValue).toLowerCase().includes(String(filter.value).toLowerCase());
            case '$gt': return leadValue > filter.value;
            case '$lt': return leadValue < filter.value;
            default: return true;
          }
        });
      });
    } 
    // Fallback to simple text search if no AI filters but query exists (or explicit text search)
    else if (searchQuery) {
      const lowerQuery = searchQuery.toLowerCase();
      result = result.filter(lead => 
        lead.name.toLowerCase().includes(lowerQuery) || 
        lead.company.toLowerCase().includes(lowerQuery) ||
        lead.email.toLowerCase().includes(lowerQuery)
      );
    }

    // Apply Sorting
    if (sortConfig) {
      result = [...result].sort((a, b) => {
        const aVal = a[sortConfig.key] || '';
        const bVal = b[sortConfig.key] || '';

        if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
        if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
      });
    }

    return result;
  }, [leads, activeFilters, searchQuery, sortConfig]);

  const toggleSort = (key: SortKey) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const toggleSelectLead = (id: string) => {
    const newSelected = new Set(selectedLeadIds);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedLeadIds(newSelected);
  };

  const toggleSelectAll = () => {
    if (selectedLeadIds.size === filteredLeads.length) {
      setSelectedLeadIds(new Set());
    } else {
      setSelectedLeadIds(new Set(filteredLeads.map(l => l.id)));
    }
  };

  const handleBulkAnalyze = async () => {
    if (selectedLeadIds.size === 0) return;
    setIsAnalyzing(true);
    const selectedLeadsList = leads.filter(l => selectedLeadIds.has(l.id));
    const analysis = await batchAnalyzeLeads(selectedLeadsList);
    setAiAnalysisResult(analysis);
    setIsAnalyzing(false);
  };

  const handleBulkEmail = async () => {
    if (selectedLeadIds.size === 0) return;
    setIsDraftingEmail(true);
    const selectedLeadsList = leads.filter(l => selectedLeadIds.has(l.id));
    const draft = await generateAIBulkEmail(selectedLeadsList, 'formal');
    setEmailDraft(draft);
    setIsDraftingEmail(false);
    setIsEmailModalOpen(true);
  };

  const handleBulkDelete = () => {
    if (selectedLeadIds.size === 0) return;
    if (window.confirm(`Are you sure you want to delete ${selectedLeadIds.size} leads?`)) {
      onDeleteLeads(Array.from(selectedLeadIds));
      setSelectedLeadIds(new Set());
    }
  };

  const handleNurtureLead = async (lead: Lead) => {
    setIsNurturing(true);
    try {
      const sequence = await generateNurtureSequence(lead);
      if (sequence && sequence.length > 0) {
        // Open the email modal with the first email in the sequence
        setEmailDraft(`Subject: ${sequence[0].subject}\n\n${sequence[0].body}`);
        setIsEmailModalOpen(true);
      } else {
        alert("Could not generate a nurture sequence at this time.");
      }
    } catch (e) {
      console.error(e);
      alert("An error occurred while generating the sequence.");
    } finally {
      setIsNurturing(false);
    }
