  };

  const handleDeleteAccount = (accountId: string) => {
    setAccounts(prevAccounts => prevAccounts.filter(a => a.id !== accountId));
  };

  const handleAddCall = (callData: Omit<Call, 'id'>) => {
    const newCall: Call = {
      ...callData,
      id: `CALL-${Date.now()}`,
    };
    setCalls(prevCalls => [newCall, ...prevCalls]);
  };

  const handleAddMeeting = (newMeeting: Meeting) => {
    setMeetings(prev => [...prev, newMeeting]);
  };

  const handleUpdateMeeting = (updatedMeeting: Meeting) => {
    setMeetings(prev => prev.map(m => m.id === updatedMeeting.id ? updatedMeeting : m));
  };

  const handleDeleteMeeting = (meetingId: string) => {
    setMeetings(prev => prev.filter(m => m.id !== meetingId));
  };

  const handleAddDeal = (newDeal: Deal) => {
    // If activities are already provided (e.g. from Convert Lead), use them, otherwise add default created activity
    const activities = newDeal.activities && newDeal.activities.length > 0 
      ? newDeal.activities 
      : [{
          id: Date.now().toString(),
          type: 'created' as const,
          description: 'Deal created',
          timestamp: new Date().toISOString()
        }];

    const dealWithActivity = {
      ...newDeal,
      activities
    };
    setDeals(prevDeals => [...prevDeals, dealWithActivity]);
  };

  const handleUpdateDeal = (updatedDeal: Deal) => {
    setDeals(prevDeals => {
      const oldDeal = prevDeals.find(d => d.id === updatedDeal.id);
      if (!oldDeal) return prevDeals;

      const newActivities: Activity[] = [];
      const timestamp = new Date().toISOString();

      if (oldDeal.stage !== updatedDeal.stage) {
        newActivities.push({ id: Date.now().toString() + 's', type: 'stage_change', description: `Stage updated to ${updatedDeal.stage}`, timestamp });
      }
      if (oldDeal.value !== updatedDeal.value) {
        newActivities.push({ id: Date.now().toString() + 'v', type: 'value_change', description: `Value updated from $${oldDeal.value.toLocaleString()} to $${updatedDeal.value.toLocaleString()}`, timestamp });
      }
      if (oldDeal.probability !== updatedDeal.probability) {
        newActivities.push({ id: Date.now().toString() + 'p', type: 'probability_change', description: `Probability updated from ${oldDeal.probability}% to ${updatedDeal.probability}%`, timestamp });
      }

      const hasManualActivity = updatedDeal.activities && updatedDeal.activities.length > (oldDeal.activities?.length || 0);
      if (newActivities.length === 0 && !hasManualActivity && JSON.stringify(oldDeal) !== JSON.stringify(updatedDeal)) {
         newActivities.push({ id: Date.now().toString() + 'u', type: 'update', description: `Deal details updated`, timestamp });
      }

      const baseActivities = updatedDeal.activities && updatedDeal.activities.length >= (oldDeal.activities?.length || 0) 
        ? updatedDeal.activities 
        : (oldDeal.activities || []);

      const finalDeal = {
        ...updatedDeal,
        activities: [...baseActivities, ...newActivities]
      };

      return prevDeals.map(d => d.id === updatedDeal.id ? finalDeal : d);
    });
  };

  const handleAddTask = (newTask: Task) => {
    setTasks(prev => [newTask, ...prev]);
  };

  const handleUpdateTask = (updatedTask: Task) => {
    setTasks(prev => prev.map(t => t.id === updatedTask.id ? updatedTask : t));
  };

  const handleDeleteTask = (taskId: string) => {
    setTasks(prev => prev.filter(t => t.id !== taskId));
  };

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return <Dashboard leads={leads} deals={deals} tasks={tasks} meetings={meetings} isDark={isDark} pipelineGoal={pipelineGoal} />;
      case 'leads':
        return <Leads 
            leads={leads} 
            onAddLead={handleAddLead} 
            onUpdateLead={handleUpdateLead} 
            onDeleteLeads={handleDeleteLeads} 
            onAddDeal={handleAddDeal} 
            onViewOpportunities={() => setCurrentView('pipeline')}
        />;
      case 'pipeline':
        return <Pipeline deals={deals} onAddDeal={handleAddDeal} onUpdateDeal={handleUpdateDeal} pipelineGoal={pipelineGoal} onSetGoal={handleSetPipelineGoal} />;
      case 'tasks':
        return <Tasks tasks={tasks} onAddTask={handleAddTask} onUpdateTask={handleUpdateTask} onDeleteTask={handleDeleteTask} />;
      case 'meetings':
        return <Meetings 
          meetings={meetings} 
          contacts={contacts}
          accounts={accounts}
          onAddMeeting={handleAddMeeting} 
          onUpdateMeeting={handleUpdateMeeting} 
          onDeleteMeeting={handleDeleteMeeting}
        />;
      case 'contacts':
        return <Contacts contacts={contacts} onAddContact={handleAddContact} onUpdateContact={handleUpdateContact} />;
      case 'accounts':
        return <Accounts 
          accounts={accounts} 
          contacts={contacts} 
          deals={deals}
          leads={leads}
          meetings={meetings}
          calls={calls}
          onAddAccount={handleAddAccount} 
          onUpdateAccount={handleUpdateAccount}
          onDeleteAccount={handleDeleteAccount}
          onAddContact={handleAddContact}
          onAddCall={handleAddCall}
        />;
      case 'calls':
        return <Calls calls={calls} leads={leads} contacts={contacts} accounts={accounts} onAddCall={handleAddCall} />;
      case 'settings':
        return <Settings 
          isDark={isDark} 
          toggleTheme={toggleTheme} 
          primaryColor={primaryColor} 
          setPrimaryColor={setPrimaryColor} 
          pipelineGoal={pipelineGoal}
          setPipelineGoal={handleSetPipelineGoal}
          // Theme Props
          fontFamily={fontFamily}
          setFontFamily={setFontFamily}
          density={density}
          setDensity={setDensity}
          // Regional Props
          weekStart={weekStart}
          setWeekStart={setWeekStart}
          dateFormat={dateFormat}
          setDateFormat={setDateFormat}
          timeZone={timeZone}
          setTimeZone={setTimeZone}
          timeFormat={timeFormat}
          setTimeFormat={setTimeFormat}
          workingDays={workingDays}
          setWorkingDays={setWorkingDays}
          fiscalYearStart={fiscalYearStart}
          setFiscalYearStart={setFiscalYearStart}
        />;
      case 'campaigns': return <PlaceholderModule title="Campaigns" />;
      case 'documents': return <PlaceholderModule title="Documents" />;
      case 'visits': return <PlaceholderModule title="Visits" />;
      case 'projects': return <PlaceholderModule title="Projects" />;
      default: return <Dashboard leads={leads} deals={deals} tasks={tasks} meetings={meetings} isDark={isDark} pipelineGoal={pipelineGoal} />;
    }
  };

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-slate-950 overflow-hidden text-slate-900 dark:text-slate-100 font-sans selection:bg-primary-500/30 transition-colors duration-300">
      {sidebarOpen && (
        <div className="fixed inset-0 bg-black/50 z-20 md:hidden" onClick={() => setSidebarOpen(false)} />
      )}
      <Sidebar 
        currentView={currentView} 
        setView={(view) => { setCurrentView(view); setSidebarOpen(false); }} 
        isOpen={sidebarOpen}
        isDark={isDark}
        toggleTheme={toggleTheme}
      />
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        {/* Background Grid Pattern */}
        <div className="absolute inset-0 z-0 pointer-events-none bg-grid-pattern dark:bg-grid-pattern-dark bg-grid opacity-[0.03] dark:opacity-[0.05]"></div>

        <header className="md:hidden flex items-center justify-between px-4 py-3 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 transition-colors duration-300 z-10">
          <div className="flex items-center">
            <button onClick={() => setSidebarOpen(true)} className="p-2 -ml-2 text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white">
              <IconMenu className="w-6 h-6" />
            </button>
            <span className="ml-2 font-bold text-slate-900 dark:text-white">NovaCRM</span>
          </div>
          <Notifications tasks={tasks} onNavigateToTasks={handleNavigateToTasks} />
        </header>
        {currentView !== 'settings' && (
            <div className="hidden md:block absolute top-6 right-8 z-20">
            <Notifications tasks={tasks} onNavigateToTasks={handleNavigateToTasks} />
            </div>
        )}
        <main className={`flex-1 overflow-y-auto ${currentView === 'settings' ? 'p-0' : 'p-4 md:p-8'} scroll-smooth z-10`}>
          <div className={`${currentView === 'settings' ? 'h-full' : 'max-w-7xl mx-auto h-full'}`}>
            {renderContent()}
          </div>
        </main>
      </div>
      <AIChat leads={leads} deals={deals} />
    </div>
  );
}

export default App;

