  const [tasks, setTasks] = useState<Task[]>(MOCK_TASKS);
  const [meetings, setMeetings] = useState<Meeting[]>(MOCK_MEETINGS);
  const [contacts, setContacts] = useState<Contact[]>(MOCK_CONTACTS);
  const [accounts, setAccounts] = useState<Account[]>(MOCK_ACCOUNTS);
  const [calls, setCalls] = useState<Call[]>(MOCK_CALLS);

  // Pipeline Goal State
  const [pipelineGoal, setPipelineGoal] = useState<number>(() => {
    const saved = localStorage.getItem('nova_pipeline_goal');
    return saved ? Number(saved) : 5000000;
  });

  const handleSetPipelineGoal = (goal: number) => {
    setPipelineGoal(goal);
    localStorage.setItem('nova_pipeline_goal', goal.toString());
  };

  const handleNavigateToTasks = () => {
    setCurrentView('tasks');
  };

  // Toggle Dark Mode
  useEffect(() => {
    if (isDark) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDark]);

  // Apply Theme Colors and Font via CSS Variables
  useEffect(() => {
    const root = document.documentElement;
    const themeColors = THEMES[primaryColor] || THEMES.indigo;

    // Apply Colors
    Object.keys(themeColors).forEach((key) => {
      root.style.setProperty(`--color-primary-${key}`, themeColors[Number(key)]);
    });

    // Apply Font
    const fontMap: Record<string, string> = {
      'Plus Jakarta Sans': "'Plus Jakarta Sans', sans-serif",
      'Inter UI': "'Inter', sans-serif",
      'Montserrat': "'Montserrat', sans-serif",
      'Outfit': "'Outfit', sans-serif",
      'Lexend': "'Lexend', sans-serif",
      'Playfair': "'Playfair Display', serif",
    };
    root.style.setProperty('--font-family', fontMap[fontFamily] || "'Inter', sans-serif");

    // Apply Density (Typography Scale)
    const sizeMap: Record<string, string> = {
      'Small': '14px',
      'Medium': '16px',
      'Large': '17px',
      'XL': '18px'
    };
    // Setting a base font size variable if your CSS uses rem/em relative to something dynamic, 
    // or you could set it on the html tag. Tailwind uses rems based on root.
    root.style.fontSize = sizeMap[density] || '16px';

  }, [primaryColor, fontFamily, density]);

  const toggleTheme = () => setIsDark(!isDark);

  const handleAddLead = (newLeadData: Omit<Lead, 'id'>) => {
    const leadToAdd: Lead = {
      ...newLeadData,
      id: `L${Date.now()}`,
      score: 50,
      scoreBreakdown: { fit: 50, engagement: 50, budget: 50 },
      notes: 'Newly created lead.',
      lastContact: new Date().toISOString().split('T')[0],
      name: `${newLeadData.firstName || ''} ${newLeadData.lastName || ''}`.trim(),
      owner: 'Bayas Ahamed',
    };
    setLeads(prevLeads => [leadToAdd, ...prevLeads]);
  };

  const handleUpdateLead = (updatedLead: Lead) => {
    setLeads(prevLeads => prevLeads.map(lead => 
      lead.id === updatedLead.id ? { ...lead, ...updatedLead, name: `${updatedLead.firstName || ''} ${updatedLead.lastName || ''}`.trim() } : lead
    ));
  };

  const handleDeleteLeads = (leadIdsToDelete: string[]) => {
    setLeads(prevLeads => prevLeads.filter(lead => !leadIdsToDelete.includes(lead.id)));
  };

  const handleAddContact = (contactData: Omit<Contact, 'id' | 'lastActivity'>) => {
    const newContact: Contact = {
      ...contactData,
      id: `C${Date.now()}`,
      lastActivity: 'Just now',
    } as Contact;
    setContacts(prevContacts => [newContact, ...prevContacts]);
  };

  const handleUpdateContact = (updatedContact: Contact) => {
    setContacts(prevContacts => prevContacts.map(c => 
      c.id === updatedContact.id ? updatedContact : c
    ));
  };

  const handleAddAccount = (newAccount: Account) => {
    setAccounts(prevAccounts => [...prevAccounts, newAccount]);
  };

  const handleUpdateAccount = (updatedAccount: Account) => {
    setAccounts(prevAccounts => prevAccounts.map(a => 
      a.id === updatedAccount.id ? updatedAccount : a
    ));
  };

  const handleDeleteAccount = (accountId: string) => {
    setAccounts(prevAccounts => prevAccounts.filter(a => a.id !== accountId));
  };

  const handleAddCall = (callData: Omit<Call, 'id'>) => {
    const newCall: Call = {
      ...callData,
      id: `CALL-${Date.now()}`,
    };
    setCalls(prevCalls => [newCall, ...prevCalls]);
  };

  const handleAddMeeting = (newMeeting: Meeting) => {
    setMeetings(prev => [...prev, newMeeting]);
  };

  const handleUpdateMeeting = (updatedMeeting: Meeting) => {
    setMeetings(prev => prev.map(m => m.id === updatedMeeting.id ? updatedMeeting : m));
  };

  const handleDeleteMeeting = (meetingId: string) => {
    setMeetings(prev => prev.filter(m => m.id !== meetingId));
  };

  const handleAddDeal = (newDeal: Deal) => {
    // If activities are already provided (e.g. from Convert Lead), use them, otherwise add default created activity
    const activities = newDeal.activities && newDeal.activities.length > 0 
      ? newDeal.activities 
      : [{
          id: Date.now().toString(),
          type: 'created' as const,
          description: 'Deal created',
          timestamp: new Date().toISOString()
        }];

    const dealWithActivity = {
      ...newDeal,
      activities
    };
    setDeals(prevDeals => [...prevDeals, dealWithActivity]);
  };

  const handleUpdateDeal = (updatedDeal: Deal) => {
    setDeals(prevDeals => {
      const oldDeal = prevDeals.find(d => d.id === updatedDeal.id);
      if (!oldDeal) return prevDeals;

      const newActivities: Activity[] = [];
      const timestamp = new Date().toISOString();

      if (oldDeal.stage !== updatedDeal.stage) {
        newActivities.push({ id: Date.now().toString() + 's', type: 'stage_change', description: `Stage updated to ${updatedDeal.stage}`, timestamp });
      }
      if (oldDeal.value !== updatedDeal.value) {
        newActivities.push({ id: Date.now().toString() + 'v', type: 'value_change', description: `Value updated from $${oldDeal.value.toLocaleString()} to $${updatedDeal.value.toLocaleString()}`, timestamp });
      }
      if (oldDeal.probability !== updatedDeal.probability) {
        newActivities.push({ id: Date.now().toString() + 'p', type: 'probability_change', description: `Probability updated from ${oldDeal.probability}% to ${updatedDeal.probability}%`, timestamp });
      }

      const hasManualActivity = updatedDeal.activities && updatedDeal.activities.length > (oldDeal.activities?.length || 0);
      if (newActivities.length === 0 && !hasManualActivity && JSON.stringify(oldDeal) !== JSON.stringify(updatedDeal)) {
         newActivities.push({ id: Date.now().toString() + 'u', type: 'update', description: `Deal details updated`, timestamp });
      }

      const baseActivities = updatedDeal.activities && updatedDeal.activities.length >= (oldDeal.activities?.length || 0) 
        ? updatedDeal.activities 
        : (oldDeal.activities || []);

      const finalDeal = {
        ...updatedDeal,
        activities: [...baseActivities, ...newActivities]
      };

      return prevDeals.map(d => d.id === updatedDeal.id ? finalDeal : d);
    });
  };

  const handleAddTask = (newTask: Task) => {
    setTasks(prev => [newTask, ...prev]);
  };

  const handleUpdateTask = (updatedTask: Task) => {
    setTasks(prev => prev.map(t => t.id === updatedTask.id ? updatedTask : t));
  };

  const handleDeleteTask = (taskId: string) => {
    setTasks(prev => prev.filter(t => t.id !== taskId));
  };

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return <Dashboard leads={leads} deals={deals} tasks={tasks} meetings={meetings} isDark={isDark} pipelineGoal={pipelineGoal} />;
      case 'leads':
        return <Leads 
            leads={leads}
            accounts={accounts} 
            onAddLead={handleAddLead} 
            onUpdateLead={handleUpdateLead} 
            onDeleteLeads={handleDeleteLeads} 
            onAddDeal={handleAddDeal} 
            onViewOpportunities={() => setCurrentView('pipeline')}
        />;
      case 'pipeline':
        return <Pipeline 
            deals={deals}
            accounts={accounts}
            contacts={contacts}
            onAddDeal={handleAddDeal} 
            onUpdateDeal={handleUpdateDeal} 
            pipelineGoal={pipelineGoal} 
            onSetGoal={handleSetPipelineGoal} 
        />;
      case 'tasks':
        return <Tasks tasks={tasks} onAddTask={handleAddTask} onUpdateTask={handleUpdateTask} onDeleteTask={handleDeleteTask} />;
      case 'meetings':
        return <Meetings 
          meetings={meetings} 
          contacts={contacts}
          accounts={accounts}
          onAddMeeting={handleAddMeeting} 
          onUpdateMeeting={handleUpdateMeeting} 
          onDeleteMeeting={handleDeleteMeeting}
        />;
      case 'contacts':
        return <Contacts 
          contacts={contacts} 
          accounts={accounts}
          onAddContact={handleAddContact} 
          onUpdateContact={handleUpdateContact} 
        />;
      case 'accounts':
        return <Accounts 
          accounts={accounts} 
          contacts={contacts} 
          deals={deals}
          leads={leads}
          meetings={meetings}
          calls={calls}
          onAddAccount={handleAddAccount} 
          onUpdateAccount={handleUpdateAccount} 
          onDeleteAccount={handleDeleteAccount}
          onAddContact={handleAddContact}
          onAddCall={handleAddCall}
        />;
      case 'calls':
        return <Calls calls={calls} leads={leads} contacts={contacts} accounts={accounts} onAddCall={handleAddCall} />;
      case 'settings':
        return <Settings 
          isDark={isDark} 
          toggleTheme={toggleTheme} 
          primaryColor={primaryColor} 
          setPrimaryColor={setPrimaryColor} 
          pipelineGoal={pipelineGoal}
          setPipelineGoal={handleSetPipelineGoal}
          // Theme Props
          fontFamily={fontFamily}
          setFontFamily={setFontFamily}
          density={density}
          setDensity={setDensity}
          // Regional Props
          weekStart={weekStart}
          setWeekStart={setWeekStart}
          dateFormat={dateFormat}
          setDateFormat={setDateFormat}
          timeZone={timeZone}
          setTimeZone={setTimeZone}
          timeFormat={timeFormat}
          setTimeFormat={setTimeFormat}
          workingDays={workingDays}
          setWorkingDays={setWorkingDays}
          fiscalYearStart={fiscalYearStart}
          setFiscalYearStart={setFiscalYearStart}
        />;
      case 'campaigns': return <PlaceholderModule title="Campaigns" />;
      case 'documents': return <PlaceholderModule title="Documents" />;
      case 'visits': return <PlaceholderModule title="Visits" />;
      case 'projects': return <PlaceholderModule title="Projects" />;
      default: return <Dashboard leads={leads} deals={deals} tasks={tasks} meetings={meetings} isDark={isDark} pipelineGoal={pipelineGoal} />;
    }
  };

  return (
    <div className="flex h-screen bg-slate-50 dark:bg-slate-950 overflow-hidden text-slate-900 dark:text-slate-100 font-sans selection:bg-primary-500/30 transition-colors duration-300">
      {sidebarOpen && (
        <div className="fixed inset-0 bg-black/50 z-20 md:hidden" onClick={() => setSidebarOpen(false)} />
      )}
      <Sidebar 
        currentView={currentView} 
        setView={(view) => { setCurrentView(view); setSidebarOpen(false); }} 
        isOpen={sidebarOpen}
        isDark={isDark}
        toggleTheme={toggleTheme}
      />
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        {/* Background Grid Pattern */}
        <div className="absolute inset-0 z-0 pointer-events-none bg-grid-pattern dark:bg-grid-pattern-dark bg-grid opacity-[0.03] dark:opacity-[0.05]"></div>

        <header className="md:hidden flex items-center justify-between px-4 py-3 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 transition-colors duration-300 z-10">
          <div className="flex items-center">
            <button onClick={() => setSidebarOpen(true)} className="p-2 -ml-2 text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white">
              <IconMenu className="w-6 h-6" />
            </button>
            <span className="ml-2 font-bold text-slate-900 dark:text-white">NovaCRM</span>
          </div>
          <Notifications tasks={tasks} onNavigateToTasks={handleNavigateToTasks} />
        </header>
        {currentView !== 'settings' && (
            <div className="hidden md:block absolute top-6 right-8 z-20">
            <Notifications tasks={tasks} onNavigateToTasks={handleNavigateToTasks} />
            </div>
        )}
        <main className={`flex-1 overflow-y-auto ${currentView === 'settings' ? 'p-0' : 'p-4 md:p-8'} scroll-smooth z-10`}>
          <div className={`${currentView === 'settings' ? 'h-full' : 'max-w-7xl mx-auto h-full'}`}>
            {renderContent()}
          </div>
        </main>
      </div>
      <AIChat leads={leads} deals={deals} />
    </div>
  );
}

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Contact, ContactStatus, Account } from '../types';
import { 
  IconSearch, IconPlus, IconArrowUp, IconArrowDown, 
  IconEdit, IconTrash, IconX, IconUser, IconList, IconKanban,
  IconBuilding, IconMail, IconPhone
} from './Icons';

interface ContactsProps {
  contacts: Contact[];
  accounts?: Account[];
  onAddContact: (contact: Omit<Contact, 'id' | 'lastActivity'>) => void;
  onUpdateContact: (contact: Contact) => void;
}

const CONTACT_STATUSES: ContactStatus[] = ['New', 'Active', 'Inactive'];

const Contacts: React.FC<ContactsProps> = ({ contacts, accounts = [], onAddContact, onUpdateContact }) => {
  const [viewMode, setViewMode] = useState<'list' | 'kanban'>('list');
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [sortConfig, setSortConfig] = useState<{ key: keyof Contact; direction: 'asc' | 'desc' } | null>(null);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedContact, setSelectedContact] = useState<Contact | null>(null);
  const [formData, setFormData] = useState<Partial<Contact>>({});

  const [draggedContactId, setDraggedContactId] = useState<string | null>(null);

  // Autocomplete State for Company
  const [filteredAccounts, setFilteredAccounts] = useState<Account[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const wrapperRef = useRef<HTMLDivElement>(null);

  // Click outside to close suggestions
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
        setShowSuggestions(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [wrapperRef]);

  const filteredContacts = useMemo(() => {
    return contacts.filter(contact => {
      const matchesSearch = contact.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            contact.email.toLowerCase().includes(searchQuery.toLowerCase()) ||
                            contact.company.toLowerCase().includes(searchQuery.toLowerCase());

      const matchesStatus = statusFilter === 'All' || contact.status === statusFilter;

      return matchesSearch && matchesStatus;
    });
  }, [contacts, searchQuery, statusFilter]);

  const sortedContacts = useMemo(() => {
    let items = [...filteredContacts];
    if (sortConfig) {
      items.sort((a, b) => {
        const aVal = a[sortConfig.key] || '';
        const bVal = b[sortConfig.key] || '';
        if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
        if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
      });
    }
    return items;
  }, [filteredContacts, sortConfig]);

  const handleSort = (key: keyof Contact) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') direction = 'desc';
    setSortConfig({ key, direction });
  };

  const getSortIcon = (key: keyof Contact) => {
    if (!sortConfig || sortConfig.key !== key) return <span className="w-3 h-3 opacity-0 group-hover:opacity-50 transition-opacity">↕️</span>;
    if (sortConfig.direction === 'asc') return <IconArrowUp className="w-3 h-3 text-primary-500" />;
    return <IconArrowDown className="w-3 h-3 text-primary-500" />;
  };

  const handleOpenModal = (contact?: Contact) => {
    if (contact) {
      setSelectedContact(contact);
      setFormData(contact);
    } else {
      setSelectedContact(null);
      setFormData({ status: 'New' });
    }
    setIsModalOpen(true);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.firstName || !formData.lastName || !formData.email) {
        alert("First Name, Last Name, and Email are required");
        return;
    }

    const contactData = {
        ...formData,
        name: `${formData.firstName} ${formData.lastName}`.trim(),
    } as any;

    if (selectedContact) {
        onUpdateContact({ ...selectedContact, ...contactData });
    } else {
        onAddContact(contactData);
    }
    setIsModalOpen(false);
  };

  const handleInputChange = (key: string, value: string) => {
      setFormData(prev => ({ ...prev, [key]: value }));

      if (key === 'company') {
          if (value && accounts.length > 0) {
              const matches = accounts.filter(a => a.name.toLowerCase().includes(value.toLowerCase()));
              setFilteredAccounts(matches);
              setShowSuggestions(matches.length > 0);
          } else {
              setShowSuggestions(false);
          }
      }
  };

  const selectAccount = (account: Account) => {
      setFormData(prev => ({
          ...prev,
          company: account.name,
      }));
      setShowSuggestions(false);
  };

  // Drag and Drop Handlers
  const handleDragStart = (e: React.DragEvent, contactId: string) => {
    setDraggedContactId(contactId);
    e.dataTransfer.setData('contactId', contactId);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  };

  const handleDrop = (e: React.DragEvent, newStatus: ContactStatus) => {
    e.preventDefault();
    const contactId = e.dataTransfer.getData('contactId');
    const contact = contacts.find(c => c.id === contactId);

    if (contact && contact.status !== newStatus) {
        onUpdateContact({ ...contact, status: newStatus });
    }
    setDraggedContactId(null);
  };

  return (
    <div className="space-y-6 animate-fade-in h-full flex flex-col">
      <div className="flex justify-between items-center flex-shrink-0">
        <div className="flex items-center gap-4">
            <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Contacts</h1>
            <div className="flex bg-slate-100 dark:bg-slate-800/50 p-1 rounded-xl border border-slate-200 dark:border-slate-700/50">
                <button 
                    onClick={() => setViewMode('list')} 
                    className={`p-2 rounded-lg transition-all ${viewMode === 'list' ? 'bg-white dark:bg-slate-700 shadow-sm text-primary-600 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-300'}`} 
                    title="List View"
                >
                    <IconList className="w-4 h-4" />
                </button>
                <button 
                    onClick={() => setViewMode('kanban')} 
                    className={`p-2 rounded-lg transition-all ${viewMode === 'kanban' ? 'bg-white dark:bg-slate-700 shadow-sm text-primary-600 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-300'}`} 
                    title="Kanban View"
                >
                    <IconKanban className="w-4 h-4" />
                </button>
            </div>
        </div>
        <button onClick={() => handleOpenModal()} className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-all flex items-center">
          <IconPlus className="w-4 h-4 mr-2" /> New Contact
        </button>
      </div>

      <div className={`bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden flex flex-col flex-1 ${viewMode === 'kanban' ? 'bg-transparent border-none shadow-none overflow-visible' : ''}`}>
        <div className={`p-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between gap-4 bg-slate-50/50 dark:bg-slate-900/50 ${viewMode === 'kanban' ? 'hidden' : ''}`}>
           <div className="relative flex-1 max-w-md">
             <IconSearch className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
             <input 
               type="text" 
               placeholder="Search contacts..." 
               value={searchQuery}
               onChange={(e) => setSearchQuery(e.target.value)}
               className="w-full pl-9 pr-4 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white"
             />
           </div>
           <select 
             value={statusFilter} 
             onChange={(e) => setStatusFilter(e.target.value)}
             className="px-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-700 dark:text-slate-200"
           >
             <option value="All">All Status</option>
             {CONTACT_STATUSES.map(s => <option key={s} value={s}>{s}</option>)}
           </select>
        </div>

        {/* View Content */}
        {viewMode === 'list' ? (
            <div className="overflow-x-auto flex-1">
            <table className="w-full text-left text-sm">
                <thead className="bg-slate-50 dark:bg-slate-950/90 text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-800 backdrop-blur-sm sticky top-0">
                    <tr>
                    <th className="px-6 py-4 font-medium cursor-pointer group hover:text-primary-600 transition-colors" onClick={() => handleSort('name')}>
                        <div className="flex items-center gap-1">Name {getSortIcon('name')}</div>
                    </th>
                    <th className="px-6 py-4 font-medium cursor-pointer group hover:text-primary-600 transition-colors" onClick={() => handleSort('title')}>
                        <div className="flex items-center gap-1">Title {getSortIcon('title')}</div>
                    </th>
                    <th className="px-6 py-4 font-medium cursor-pointer group hover:text-primary-600 transition-colors" onClick={() => handleSort('company')}>
                        <div className="flex items-center gap-1">Company {getSortIcon('company')}</div>
                    </th>
                    <th className="px-6 py-4 font-medium cursor-pointer group hover:text-primary-600 transition-colors" onClick={() => handleSort('email')}>
                        <div className="flex items-center gap-1">Email {getSortIcon('email')}</div>
                    </th>
                    <th className="px-6 py-4 font-medium cursor-pointer group hover:text-primary-600 transition-colors" onClick={() => handleSort('phone')}>
                        <div className="flex items-center gap-1">Phone {getSortIcon('phone')}</div>
                    </th>
                    <th className="px-6 py-4 font-medium">Status</th>
                    <th className="px-6 py-4 font-medium text-right">Actions</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
                {sortedContacts.map(contact => (
                    <tr key={contact.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                    <td className="px-6 py-4 text-slate-900 dark:text-white font-medium flex items-center">
                        <div className="w-8 h-8 rounded-full bg-primary-100 dark:bg-primary-900/30 text-primary-600 dark:text-primary-400 flex items-center justify-center mr-3 text-xs font-bold">
                        {contact.name.charAt(0)}
                        </div>
                        {contact.name}
                    </td>
                    <td className="px-6 py-4 text-slate-600 dark:text-slate-300">{contact.title}</td>
                    <td className="px-6 py-4 text-slate-600 dark:text-slate-300">{contact.company}</td>
                    <td className="px-6 py-4 text-slate-600 dark:text-slate-300">{contact.email}</td>
                    <td className="px-6 py-4 text-slate-600 dark:text-slate-300">{contact.phone}</td>
                    <td className="px-6 py-4">
                        <span className={`px-2 py-1 text-xs font-medium rounded-full ${
                        contact.status === 'Active' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400' :
                        contact.status === 'New' ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400' :
                        'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400'
                        }`}>
                        {contact.status || 'New'}
                        </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                        <button onClick={() => handleOpenModal(contact)} className="text-slate-400 hover:text-primary-600 dark:hover:text-primary-400 mr-2"><IconEdit className="w-4 h-4" /></button>
                    </td>
                    </tr>
                ))}
                {sortedContacts.length === 0 && (
                    <tr>
                        <td colSpan={7} className="px-6 py-12 text-center text-slate-500 dark:text-slate-400">
                            <div className="flex flex-col items-center justify-center">
                                <IconUser className="w-12 h-12 text-slate-300 dark:text-slate-600 mb-3" />
                                <p className="text-lg font-medium">No contacts found</p>
                                <p className="text-sm">Add a new contact to get started.</p>
                            </div>
                        </td>
                    </tr>
                )}
                </tbody>
            </table>
            </div>
        ) : (
            <div className="flex-1 overflow-x-auto overflow-y-hidden">
                <div className="h-full flex gap-6 min-w-full pb-4">
                    {CONTACT_STATUSES.map(status => (
                        <div
                            key={status}
                            onDragOver={handleDragOver}
                            onDrop={(e) => handleDrop(e, status)}
                            className={`flex flex-col w-80 bg-slate-50 dark:bg-slate-900/50 border border-slate-200 dark:border-slate-800 rounded-xl flex-shrink-0 transition-colors ${draggedContactId ? 'border-dashed border-slate-300 dark:border-slate-700' : ''}`}
                        >
                            {/* Column Header */}
                            <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-100/50 dark:bg-slate-900/50 rounded-t-xl">
                                <div className="flex items-center gap-2">
                                    <div className={`w-2 h-2 rounded-full ${
                                        status === 'New' ? 'bg-blue-500' : 
                                        status === 'Active' ? 'bg-emerald-500' : 
                                        'bg-slate-400'
                                    }`}></div>
                                    <span className="font-bold text-slate-700 dark:text-slate-200">{status}</span>
                                </div>
                                <span className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-400 text-xs font-bold px-2 py-0.5 rounded-full">
                                    {filteredContacts.filter(c => (c.status || 'New') === status).length}
                                </span>
                            </div>

                            {/* Cards */}
                            <div className="flex-1 p-3 space-y-3 overflow-y-auto custom-scrollbar">
                                {filteredContacts.filter(c => (c.status || 'New') === status).map(contact => (
                                    <div
                                        key={contact.id}
                                        draggable
                                        onDragStart={(e) => handleDragStart(e, contact.id)}
                                        onClick={() => handleOpenModal(contact)}
                                        className="bg-white dark:bg-slate-800 p-4 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm hover:shadow-md cursor-move group transition-all active:scale-95 active:shadow-lg"
                                    >
                                        <div className="flex justify-between items-start mb-2">
                                            <div className="flex items-center gap-3">
                                                <div className="w-8 h-8 rounded-full bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 flex items-center justify-center text-xs font-bold border border-slate-200 dark:border-slate-600">
                                                    {contact.name.charAt(0)}
                                                </div>
                                                <div>
                                                    <h4 className="font-semibold text-slate-900 dark:text-white text-sm hover:text-primary-600 dark:hover:text-primary-400 transition-colors">{contact.name}</h4>
                                                    <p className="text-xs text-slate-500 dark:text-slate-400 truncate max-w-[140px]">{contact.title}</p>
                                                </div>
                                            </div>
                                        </div>

                                        <div className="space-y-1.5 mt-3 pt-3 border-t border-slate-50 dark:border-slate-700/50">
                                            {contact.company && <div className="text-xs text-slate-600 dark:text-slate-300 flex items-center gap-2"><IconBuilding className="w-3 h-3 text-slate-400"/> {contact.company}</div>}
                                            {contact.email && <div className="text-xs text-slate-500 dark:text-slate-400 flex items-center gap-2 truncate" title={contact.email}><IconMail className="w-3 h-3 text-slate-400"/> {contact.email}</div>}
                                            {contact.phone && <div className="text-xs text-slate-500 dark:text-slate-400 flex items-center gap-2"><IconPhone className="w-3 h-3 text-slate-400"/> {contact.phone}</div>}
                                        </div>
                                    </div>
                                ))}
                                {filteredContacts.filter(c => (c.status || 'New') === status).length === 0 && (
                                    <div className="flex flex-col items-center justify-center h-24 border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-lg text-slate-400 dark:text-slate-600 text-xs">
                                        <span>No contacts</span>
                                    </div>
                                )}
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
           <div className="w-full max-w-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden animate-scale-in">
              <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50">
                 <h2 className="text-xl font-bold text-slate-900 dark:text-white flex items-center">
                    <IconUser className="w-5 h-5 mr-3 text-primary-500" />
                    {selectedContact ? 'Edit Contact' : 'New Contact'}
                 </h2>
                 <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600 dark:hover:text-white"><IconX className="w-6 h-6" /></button>
              </div>
              <form onSubmit={handleSave} className="p-6 overflow-y-auto max-h-[80vh]">
                 <div className="grid grid-cols-2 gap-4 mb-4">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">First Name *</label>
                        <input type="text" value={formData.firstName || ''} onChange={(e) => handleInputChange('firstName', e.target.value)} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white" required />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Last Name *</label>
                        <input type="text" value={formData.lastName || ''} onChange={(e) => handleInputChange('lastName', e.target.value)} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white" required />
                    </div>
                 </div>
                 <div className="grid grid-cols-2 gap-4 mb-4">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Email *</label>
                        <input type="email" value={formData.email || ''} onChange={(e) => handleInputChange('email', e.target.value)} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white" required />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Phone</label>
                        <input type="tel" value={formData.phone || ''} onChange={(e) => handleInputChange('phone', e.target.value)} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white" />
                    </div>
                 </div>
                 <div className="grid grid-cols-2 gap-4 mb-4">
                    <div className="relative" ref={wrapperRef}>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Company</label>
                        <div className="relative">
                            <input 
                                type="text" 
                                value={formData.company || ''} 
                                onChange={(e) => handleInputChange('company', e.target.value)} 
                                onFocus={() => { if(formData.company && accounts.length) setShowSuggestions(true); }}
                                className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white" 
                                autoComplete="off"
                            />
                            {showSuggestions && (
                                <div className="absolute z-50 w-full mt-1 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl shadow-2xl max-h-48 overflow-y-auto custom-scrollbar">
                                    {filteredAccounts.map(account => (
                                        <div 
                                            key={account.id}
                                            onClick={() => selectAccount(account)}
                                            className="px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-700 cursor-pointer flex items-center justify-between border-b border-slate-100 dark:border-slate-700 last:border-0 transition-colors"
                                        >
                                            <span className="text-sm font-medium text-slate-900 dark:text-white">{account.name}</span>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Title</label>
                        <input type="text" value={formData.title || ''} onChange={(e) => handleInputChange('title', e.target.value)} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white" />
                    </div>
                 </div>
                 <div className="mb-4">
                     <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Status</label>
                     <select value={formData.status || 'New'} onChange={(e) => setFormData({...formData, status: e.target.value as ContactStatus})} className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 dark:text-white cursor-pointer">
                        {CONTACT_STATUSES.map(s => <option key={s} value={s}>{s}</option>)}
                     </select>
                 </div>
                 <div className="flex justify-end pt-4 gap-3">
                    <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 rounded-lg hover:bg-slate-200 transition-colors">Cancel</button>
                    <button type="submit" className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 transition-colors">Save Contact</button>
                 </div>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default Contacts;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Deal, Activity, Account, Contact } from '../types';
import { IconX, IconMail, IconPhone, IconFilter, IconHistory, IconClock, IconCalendar, IconCheckCircle, IconTarget, IconBuilding, IconUser } from './Icons';

interface PipelineProps {
  deals: Deal[];
  accounts?: Account[];
  contacts?: Contact[];
  onAddDeal: (deal: Deal) => void;
  onUpdateDeal: (deal: Deal) => void;
  pipelineGoal: number;
  onSetGoal: (goal: number) => void;
}

const Pipeline: React.FC<PipelineProps> = ({ deals, accounts = [], contacts = [], onAddDeal, onUpdateDeal, pipelineGoal, onSetGoal }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isGoalModalOpen, setIsGoalModalOpen] = useState(false);
  const [tempGoal, setTempGoal] = useState(pipelineGoal.toString());

  const [draggedDealId, setDraggedDealId] = useState<string | null>(null);
  const [selectedDeal, setSelectedDeal] = useState<Deal | null>(null);

  const initialFormState = {
    title: '',
    company: '',
    value: '',
    closeDate: '',
    stage: 'Qualification' as Deal['stage'],
    email: '',
    phone: '',
    probability: 50,
    contactName: ''
  };

  const [formData, setFormData] = useState(initialFormState);

  // Autocomplete State
  const [filteredAccounts, setFilteredAccounts] = useState<Account[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);

  const [filteredContacts, setFilteredContacts] = useState<Contact[]>([]);
  const [showContactSuggestions, setShowContactSuggestions] = useState(false);

  const wrapperRef = useRef<HTMLDivElement>(null);
  const contactWrapperRef = useRef<HTMLDivElement>(null);

  // Sync selectedDeal with deals prop when modal is open to reflect updates immediately
  useEffect(() => {
    if (selectedDeal && isModalOpen) {
      const freshDeal = deals.find(d => d.id === selectedDeal.id);
      if (freshDeal) {
        setSelectedDeal(freshDeal);
      }
    }
  }, [deals, isModalOpen]);

  // Click outside to close suggestions
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
        setShowSuggestions(false);
      }
      if (contactWrapperRef.current && !contactWrapperRef.current.contains(event.target as Node)) {
        setShowContactSuggestions(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [wrapperRef, contactWrapperRef]);

  // Reset form or populate when modal opens/closes or selection changes
  useEffect(() => {
    if (selectedDeal) {
      setFormData({
        title: selectedDeal.title,
        company: selectedDeal.company,
        value: selectedDeal.value.toString(),
        closeDate: selectedDeal.closeDate,
        stage: selectedDeal.stage,
        email: selectedDeal.email || '',
        phone: selectedDeal.phone || '',
        probability: selectedDeal.probability,
        contactName: '' // Can't easily backfill this without storing contactId on deal
      });
    } else {
      setFormData(initialFormState);
    }
  }, [selectedDeal]);

  const handleOpenNewDeal = () => {
    setSelectedDeal(null);
    setIsModalOpen(true);
  };

  const handleOpenEditDeal = (deal: Deal) => {
    setSelectedDeal(deal);
    setIsModalOpen(true);
  };

  const handleLogActivity = (type: 'email_sent' | 'meeting_scheduled' | 'follow_up', description: string) => {
    if (!selectedDeal) return;

    const newActivity: Activity = {
      id: Date.now().toString(),
      type,
      description,
      timestamp: new Date().toISOString()
    };

    const updatedDeal: Deal = {
      ...selectedDeal,
      activities: [...(selectedDeal.activities || []), newActivity]
    };

    // Optimistic update for smoother UI
    setSelectedDeal(updatedDeal);
    onUpdateDeal(updatedDeal);
  };

  // Filter States
  const [filterCompany, setFilterCompany] = useState('');
  const [filterDate, setFilterDate] = useState('');

  // Derived Options for Dropdowns
  const uniqueCompanies = useMemo(() => Array.from(new Set(deals.map(d => d.company))).sort(), [deals]);
  const uniqueDates = useMemo(() => Array.from(new Set(deals.map(d => d.closeDate))).sort(), [deals]);

  // Filter Logic
  const filteredDeals = useMemo(() => {
    return deals.filter(deal => {
      const matchesCompany = filterCompany ? deal.company === filterCompany : true;
      const matchesDate = filterDate ? deal.closeDate === filterDate : true;
      return matchesCompany && matchesDate;
    });
  }, [deals, filterCompany, filterDate]);

  const columns = [
    { id: 'Qualification', label: 'Qualification', color: 'bg-slate-500' },
    { id: 'Needs Analysis', label: 'Needs Analysis', color: 'bg-blue-500' },
    { id: 'Value Proposition', label: 'Value Proposition', color: 'bg-indigo-500' },
    { id: 'Decision Makers', label: 'Decision Makers', color: 'bg-purple-500' },
    { id: 'Proposal/Price Quote', label: 'Proposal/Price Quote', color: 'bg-yellow-500' },
    { id: 'Negotiation/Review', label: 'Negotiation/Review', color: 'bg-orange-500' },
    { id: 'Closed Won', label: 'Closed Won', color: 'bg-emerald-500' },
    { id: 'Closed Lost', label: 'Closed Lost', color: 'bg-red-500' },
  ];

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));

    if (name === 'company') {
        if (value && accounts.length > 0) {
            const matches = accounts.filter(a => a.name.toLowerCase().includes(value.toLowerCase()));
            setFilteredAccounts(matches);
            setShowSuggestions(matches.length > 0);
        } else {
            setShowSuggestions(false);
        }
    }

    if (name === 'contactName') {
        if (value && contacts.length > 0) {
            // If company is selected, filter contacts by company
            let availableContacts = contacts;
            if (formData.company) {
                availableContacts = contacts.filter(c => c.company.toLowerCase() === formData.company.toLowerCase());
                // If no direct matches, maybe fall back to all contacts? Let's stick to strict if company is set.
                if (availableContacts.length === 0) availableContacts = contacts;
            }
            const matches = availableContacts.filter(c => c.name.toLowerCase().includes(value.toLowerCase()));
            setFilteredContacts(matches);
            setShowContactSuggestions(matches.length > 0);
        } else {
            setShowContactSuggestions(false);
        }
    }
  };

  const selectAccount = (account: Account) => {
      setFormData(prev => ({
          ...prev,
          company: account.name,
          phone: account.phone || prev.phone // Optional: keep existing phone if manually entered? Overwriting is usually safer for "auto-fill".
      }));
      setShowSuggestions(false);
  };

  const selectContact = (contact: Contact) => {
      setFormData(prev => ({
          ...prev,
          contactName: contact.name,
          email: contact.email || prev.email,
          phone: contact.phone || prev.phone,
          company: contact.company || prev.company // Auto-switch company if contact belongs to one
      }));
      setShowContactSuggestions(false);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (selectedDeal) {
      // Edit Mode
      const updatedDeal: Deal = {
        ...selectedDeal,
        title: formData.title,
        company: formData.company,
        value: Number(formData.value),
        stage: formData.stage,
        closeDate: formData.closeDate,
        probability: Number(formData.probability),
        email: formData.email,
        phone: formData.phone
      };
      onUpdateDeal(updatedDeal);
    } else {
      // Create Mode
      const newDeal: Deal = {
        id: Date.now().toString(),
        title: formData.title,
        company: formData.company,
        value: Number(formData.value),
        stage: formData.stage,
        closeDate: formData.closeDate || new Date().toISOString().split('T')[0],
        probability: Number(formData.probability),
        email: formData.email,
        phone: formData.phone,
        activities: []
      };
      onAddDeal(newDeal);
    }

    setIsModalOpen(false);
    setSelectedDeal(null);
  };

  const handleSaveGoal = () => {
    const goal = parseFloat(tempGoal);
    if (!isNaN(goal) && goal > 0) {
      onSetGoal(goal);
      setIsGoalModalOpen(false);
    }
  };

  // Drag and Drop Handlers
  const handleDragStart = (e: React.DragEvent, dealId: string) => {
    setDraggedDealId(dealId);
    e.dataTransfer.setData('dealId', dealId);
    e.dataTransfer.effectAllowed = 'move';
    const target = e.target as HTMLElement;
    target.style.opacity = '0.5';
  };

  const handleDragEnd = (e: React.DragEvent) => {
    setDraggedDealId(null);
    const target = e.target as HTMLElement;
    target.style.opacity = '1';
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  };

  const handleDrop = (e: React.DragEvent, stageId: string) => {
    e.preventDefault();
    const dealId = e.dataTransfer.getData('dealId');
    const deal = deals.find(d => d.id === dealId);

    if (deal && deal.stage !== stageId) {
      onUpdateDeal({ ...deal, stage: stageId as Deal['stage'] });
    }
  };

  // Helper functions for Activity Log styling
  const getActivityTypeStyle = (type: Activity['type']) => {
    switch (type) {
      case 'created':
        return 'bg-emerald-100 text-emerald-700 border-emerald-200 dark:bg-emerald-500/10 dark:text-emerald-400 dark:border-emerald-500/20';
      case 'stage_change':
        return 'bg-blue-100 text-blue-700 border-blue-200 dark:bg-blue-500/10 dark:text-blue-400 dark:border-blue-500/20';
      case 'value_change':
        return 'bg-amber-100 text-amber-700 border-amber-200 dark:bg-amber-500/10 dark:text-amber-400 dark:border-amber-500/20';
      case 'probability_change':
        return 'bg-purple-100 text-purple-700 border-purple-200 dark:bg-purple-500/10 dark:text-purple-400 dark:border-purple-500/20';
      case 'email_sent':
        return 'bg-indigo-100 text-indigo-700 border-indigo-200 dark:bg-indigo-500/10 dark:text-indigo-400 dark:border-indigo-500/20';
      case 'meeting_scheduled':
        return 'bg-pink-100 text-pink-700 border-pink-200 dark:bg-pink-500/10 dark:text-pink-400 dark:border-pink-500/20';
      case 'follow_up':
        return 'bg-cyan-100 text-cyan-700 border-cyan-200 dark:bg-cyan-500/10 dark:text-cyan-400 dark:border-cyan-500/20';
      default:
        return 'bg-slate-100 text-slate-700 border-slate-200 dark:bg-slate-800 dark:text-slate-400 dark:border-slate-700';
    }
  };

  const formatActivityType = (type: string) => {
    return type.split('_').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
  };

  return (
    <div className="h-full flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold text-slate-900 dark:text-white">Opportunity Pipeline</h1>
        <div className="flex gap-3">
          <button
            onClick={() => { setTempGoal(pipelineGoal.toString()); setIsGoalModalOpen(true); }}
            className="flex items-center px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-all"
          >
            <IconTarget className="w-4 h-4 mr-2 text-emerald-500" />
            Set Goal
          </button>
          <button 
            onClick={handleOpenNewDeal}
            className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-all"
          >
            + New Opportunity
          </button>
        </div>
      </div>

      {/* Filter Bar */}
      <div className="flex flex-wrap items-center gap-4 mb-6 p-4 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm dark:shadow-none transition-colors">
        <div className="flex items-center text-sm font-medium text-slate-500 dark:text-slate-400">
          <IconFilter className="w-4 h-4 mr-2" />
          Filter by:
        </div>

        <select
          value={filterCompany}
          onChange={(e) => setFilterCompany(e.target.value)}
          className="px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm text-slate-700 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-primary-500 transition-colors cursor-pointer"
        >
          <option value="">All Companies</option>
          {uniqueCompanies.map(c => <option key={c} value={c}>{c}</option>)}
        </select>

        <select
          value={filterDate}
          onChange={(e) => setFilterDate(e.target.value)}
          className="px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm text-slate-700 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-primary-500 transition-colors cursor-pointer"
        >
          <option value="">All Dates</option>
          {uniqueDates.map(d => <option key={d} value={d}>{d}</option>)}
        </select>

        {(filterCompany || filterDate) && (
          <button
            onClick={() => { setFilterCompany(''); setFilterDate(''); }}
            className="px-3 py-2 text-sm font-medium text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-500/10 rounded-lg transition-colors"
          >
            Clear Filters
          </button>
        )}
      </div>

      <div className="flex-1 grid grid-cols-1 md:grid-cols-[repeat(8,minmax(300px,1fr))] gap-6 overflow-x-auto pb-4">
        {columns.map((col) => (
          <div 
            key={col.id} 
            onDragOver={handleDragOver}
            onDrop={(e) => handleDrop(e, col.id)}
            className={`flex flex-col h-full min-w-[300px] bg-slate-50 dark:bg-slate-900/50 border border-slate-200 dark:border-slate-800 rounded-xl transition-all duration-300 ${draggedDealId ? 'border-dashed border-slate-300 dark:border-slate-700' : ''}`}
          >
            <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between">
              <h3 className="text-base font-semibold text-slate-900 dark:text-white truncate pr-2">{col.label}</h3>
              <span className="px-2 py-0.5 text-xs font-bold text-slate-700 dark:text-slate-900 bg-slate-200 dark:bg-slate-200 rounded-full flex-shrink-0">
                {filteredDeals.filter(d => d.stage === col.id).length}
              </span>
            </div>
            <div className="p-4 space-y-4 flex-1 overflow-y-auto">
              {filteredDeals.filter(d => d.stage === col.id).map((deal) => (
                <div 
                  key={deal.id} 
                  draggable
                  onDragStart={(e) => handleDragStart(e, deal.id)}
                  onDragEnd={handleDragEnd}
                  onClick={() => handleOpenEditDeal(deal)}
                  className="p-4 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg shadow-sm hover:shadow-md hover:border-primary-300 dark:hover:border-slate-600 transition-all cursor-move group select-none active:cursor-grabbing"
                >
                  <div className="flex justify-between items-start mb-2">
                    <span className="text-sm font-medium text-slate-500 dark:text-slate-400">{deal.company}</span>
                    <div className={`w-2 h-2 rounded-full ${col.color}`}></div>
                  </div>
                  <h4 className="text-base font-semibold text-slate-900 dark:text-white mb-3 group-hover:text-primary-600 dark:group-hover:text-primary-400 transition-colors">{deal.title}</h4>

                  {/* Contact Info */}
                  {(deal.email || deal.phone) && (
                    <div className="mb-3 space-y-1">
                      {deal.email && (
                        <div className="flex items-center text-sm text-slate-500 dark:text-slate-400">
                          <IconMail className="w-3 h-3 mr-1.5 opacity-70" />
                          <span className="truncate max-w-[180px]">{deal.email}</span>
                        </div>
                      )}
                      {deal.phone && (
                        <div className="flex items-center text-sm text-slate-500 dark:text-slate-400">
                          <IconPhone className="w-3 h-3 mr-1.5 opacity-70" />
                          <span>{deal.phone}</span>
                        </div>
                      )}
                    </div>
                  )}

                  <div className="flex justify-between items-center pt-3 border-t border-slate-100 dark:border-slate-700/50">
                    <span className="text-lg font-bold text-slate-700 dark:text-slate-200">${deal.value.toLocaleString()}</span>
                    <div className="flex items-center">
                        <div className="w-16 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full mr-2 overflow-hidden">
