                 </div>

                 {/* Company Field with Account Autocomplete */}
                 <div className="relative" ref={accountWrapperRef}>
                    <label className={labelClasses}>Company <span className="text-red-500">*</span></label>
                    <div className="relative">
                        <input 
                            name="company" 
