                            onFocus={() => { if(formData.company && accounts.length) setShowAccountSuggestions(true); }}
                            placeholder="Company Name" 
                            className={inputClasses} 
                            autoComplete="off"
                        />
                        <IconBuilding className={iconWrapperClasses} />
                        {showAccountSuggestions && (
