                <div>
                    <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-1 uppercase tracking-wider">Notifications & Alerts</h3>
                    <p className="text-sm text-slate-500 dark:text-slate-400">Control when and how you receive system updates.</p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="p-6 bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm">
                        <div className="flex items-center gap-3 mb-6">
                            <IconMail className="w-5 h-5 text-slate-400" />
                            <h4 className="font-bold text-slate-900 dark:text-white">Triggers</h4>
