                                <span className="text-sm text-slate-700 dark:text-slate-300">New Lead Assigned</span>
                            </label>
                            <label className="flex items-center space-x-3 cursor-pointer">
                                <input type="checkbox" checked={dealWonAlert} onChange={(e) => setDealWonAlert(e.target.checked)} className="w-5 h-5 text-primary-600 rounded border-slate-300 focus:ring-primary-500 dark:bg-slate-700 dark:border-slate-600" />
                                <span className="text-sm text-slate-700 dark:text-slate-300">Deal Closed Won</span>
