import React, { useState, useMemo } from 'react';
import { Document, DocumentType, DocumentStatus } from '../types';
import { 
  IconFileText, IconSearch, IconFilter, IconPlus, IconDownload, IconTrash, 
  IconArrowUp, IconArrowDown, IconX, IconUpload, IconFile 
} from './Icons';

interface DocumentsProps {
  documents: Document[];
  onAddDocument: (doc: Document) => void;
  onDeleteDocument: (id: string) => void;
}

const DOCUMENT_TYPES: DocumentType[] = ['Contract', 'Proposal', 'Invoice', 'Brief', 'Report', 'Other'];
const DOCUMENT_STATUSES: DocumentStatus[] = ['Draft', 'Final', 'Signed', 'Pending Review'];

const Documents: React.FC<DocumentsProps> = ({ documents, onAddDocument, onDeleteDocument }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [typeFilter, setTypeFilter] = useState<string>('All');
  const [sortConfig, setSortConfig] = useState<{ key: keyof Document; direction: 'asc' | 'desc' } | null>({ key: 'uploadedAt', direction: 'desc' });

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Document>>({
    type: 'Contract',
    status: 'Draft',
    relatedTo: ''
  });

  const filteredDocuments = useMemo(() => {
    return documents.filter(doc => {
      const matchesSearch = doc.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            doc.relatedTo.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesType = typeFilter === 'All' || doc.type === typeFilter;
      return matchesSearch && matchesType;
    });
  }, [documents, searchQuery, typeFilter]);

  const sortedDocuments = useMemo(() => {
    let items = [...filteredDocuments];
    if (sortConfig) {
      items.sort((a, b) => {
        const aVal = a[sortConfig.key] || '';
        const bVal = b[sortConfig.key] || '';
        if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
        if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
      });
    }
    return items;
  }, [filteredDocuments, sortConfig]);

  const handleSort = (key: keyof Document) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') direction = 'desc';
    setSortConfig({ key, direction });
  };

  const getSortIcon = (key: keyof Document) => {
    if (!sortConfig || sortConfig.key !== key) return <span className="w-3 h-3 opacity-0 group-hover:opacity-50 transition-opacity">↕️</span>;
    if (sortConfig.direction === 'asc') return <IconArrowUp className="w-3 h-3 text-primary-500" />;
    return <IconArrowDown className="w-3 h-3 text-primary-500" />;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) {
      alert("File Name is required");
      return;
    }

    const newDoc: Document = {
      id: `DOC-${Date.now()}`,
      name: formData.name,
      type: formData.type as DocumentType,
      status: formData.status as DocumentStatus,
      relatedTo: formData.relatedTo || 'General',
      size: `${(Math.random() * 5 + 0.5).toFixed(1)} MB`, // Mock size
      uploadedBy: 'Alex Chen',
      uploadedAt: new Date().toISOString().split('T')[0]
    };

    onAddDocument(newDoc);
    setIsModalOpen(false);
    setFormData({ type: 'Contract', status: 'Draft', relatedTo: '', name: '' });
  };

  return (
    <div className="space-y-6 h-full flex flex-col animate-fade-in">
      {/* Header */}
      <div className="flex justify-between items-center flex-shrink-0">
        <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Documents</h1>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-all flex items-center"
        >
          <IconUpload className="w-4 h-4 mr-2" /> Upload Document
        </button>
      </div>

      <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden flex flex-col flex-1">
        {/* Toolbar */}
        <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50/50 dark:bg-slate-900/50">
           <div className="relative max-w-md w-full">
             <IconSearch className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
             <input 
               type="text" 
               placeholder="Search documents..." 
               value={searchQuery}
               onChange={(e) => setSearchQuery(e.target.value)}
               className="w-full pl-9 pr-4 py-2 text-sm bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white"
             />
           </div>

           <div className="flex items-center space-x-2">
             <IconFilter className="w-4 h-4 text-slate-400" />
             <select 
               value={typeFilter}
               onChange={(e) => setTypeFilter(e.target.value)}
               className="bg-transparent text-sm font-medium text-slate-700 dark:text-slate-300 focus:outline-none cursor-pointer"
             >
               <option value="All">All Types</option>
               {DOCUMENT_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
             </select>
           </div>
        </div>

        {/* Table */}
        <div className="overflow-auto flex-1 custom-scrollbar">
          <table className="w-full text-left text-sm">
            <thead className="bg-slate-50 dark:bg-slate-950/90 text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-800 sticky top-0 z-10 backdrop-blur-sm">
              <tr>
                <th className="px-6 py-4 font-medium cursor-pointer hover:text-primary-600" onClick={() => handleSort('name')}>
                    <div className="flex items-center gap-1">Name {getSortIcon('name')}</div>
                </th>
                <th className="px-6 py-4 font-medium cursor-pointer hover:text-primary-600" onClick={() => handleSort('relatedTo')}>
                    <div className="flex items-center gap-1">Related To {getSortIcon('relatedTo')}</div>
                </th>
                <th className="px-6 py-4 font-medium cursor-pointer hover:text-primary-600" onClick={() => handleSort('type')}>
                    <div className="flex items-center gap-1">Type {getSortIcon('type')}</div>
                </th>
                <th className="px-6 py-4 font-medium cursor-pointer hover:text-primary-600" onClick={() => handleSort('status')}>
                    <div className="flex items-center gap-1">Status {getSortIcon('status')}</div>
                </th>
                <th className="px-6 py-4 font-medium cursor-pointer hover:text-primary-600" onClick={() => handleSort('uploadedAt')}>
                    <div className="flex items-center gap-1">Date {getSortIcon('uploadedAt')}</div>
                </th>
                <th className="px-6 py-4 font-medium text-right cursor-pointer hover:text-primary-600" onClick={() => handleSort('size')}>
                    <div className="flex items-center justify-end gap-1">Size {getSortIcon('size')}</div>
                </th>
                <th className="px-6 py-4 font-medium text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
              {sortedDocuments.map(doc => (
                <tr key={doc.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors group">
                  <td className="px-6 py-4">
                    <div className="flex items-center">
                        <div className="p-2 rounded-lg bg-blue-50 text-blue-600 dark:bg-blue-900/20 dark:text-blue-400 mr-3">
                            <IconFileText className="w-4 h-4" />
                        </div>
                        <span className="font-medium text-slate-900 dark:text-white">{doc.name}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-slate-600 dark:text-slate-300">{doc.relatedTo}</td>
                  <td className="px-6 py-4">
                      <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-slate-100 text-slate-800 dark:bg-slate-800 dark:text-slate-200 border border-slate-200 dark:border-slate-700">
                          {doc.type}
                      </span>
                  </td>
                  <td className="px-6 py-4">
                    <span className={`px-2 py-1 text-xs font-bold rounded-full ${
                      doc.status === 'Final' || doc.status === 'Signed' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-500/20 dark:text-emerald-400' :
                      doc.status === 'Pending Review' ? 'bg-amber-100 text-amber-700 dark:bg-amber-500/20 dark:text-amber-400' :
                      'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400'
                    }`}>
                      {doc.status}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-slate-600 dark:text-slate-300 text-sm">{doc.uploadedAt}</td>
                  <td className="px-6 py-4 text-slate-500 dark:text-slate-400 text-sm text-right">{doc.size}</td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex items-center justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button className="p-2 text-slate-400 hover:text-primary-600 dark:hover:text-primary-400 transition-colors" title="Download">
                            <IconDownload className="w-4 h-4" />
                        </button>
                        <button 
                            onClick={() => { if(window.confirm('Delete this document?')) onDeleteDocument(doc.id); }}
                            className="p-2 text-slate-400 hover:text-red-600 dark:hover:text-red-400 transition-colors" 
                            title="Delete"
                        >
                            <IconTrash className="w-4 h-4" />
                        </button>
                    </div>
                  </td>
                </tr>
              ))}
              {sortedDocuments.length === 0 && (
                  <tr>
                      <td colSpan={7} className="px-6 py-12 text-center text-slate-500 dark:text-slate-400">
                          <div className="flex flex-col items-center justify-center">
                              <IconFile className="w-12 h-12 text-slate-300 dark:text-slate-600 mb-3" />
                              <p className="text-lg font-medium">No documents found</p>
                              <p className="text-sm">Upload a new document to get started.</p>
                          </div>
                      </td>
                  </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Upload Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="w-full max-w-lg bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden animate-scale-in">
            <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50">
              <h2 className="text-xl font-bold text-slate-900 dark:text-white flex items-center">
                 <IconUpload className="w-5 h-5 mr-3 text-primary-500" />
                 Upload Document
              </h2>
              <button 
                onClick={() => setIsModalOpen(false)} 
                className="text-slate-400 hover:text-slate-600 dark:hover:text-white transition-colors"
              >
                <IconX className="w-6 h-6" />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-6 space-y-5">
               <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">Document Name <span className="text-red-500">*</span></label>
                  <input 
                     type="text" 
