               <div className="border-2 border-dashed border-slate-300 dark:border-slate-700 rounded-xl p-8 flex flex-col items-center justify-center text-center hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-colors cursor-pointer group">
                   <IconUpload className="w-10 h-10 text-slate-400 group-hover:text-primary-500 mb-2 transition-colors" />
                   <p className="text-sm font-medium text-slate-700 dark:text-slate-300">Click to upload or drag and drop</p>
                   <p className="text-xs text-slate-500 dark:text-slate-500 mt-1">PDF, DOCX, JPG up to 10MB</p>
               </div>

               <div className="pt-4 flex gap-3 justify-end border-t border-slate-100 dark:border-slate-800">
                  <button 
                      type="button"
                      onClick={() => setIsModalOpen(false)}
                      className="px-5 py-2.5 text-sm font-medium text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-slate-800 rounded-xl hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors"
                  >
                      Cancel
                  </button>
                  <button 
                      type="submit"
                      className="px-6 py-2.5 text-sm font-medium text-white bg-primary-600 rounded-xl hover:bg-primary-500 shadow-lg shadow-primary-500/25 transition-colors"
                  >
                      Upload
                  </button>
               </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

