                     className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 text-slate-900 dark:text-white"
                  />
               </div>

               <div className="border-2 border-dashed border-slate-300 dark:border-slate-700 rounded-xl p-8 flex flex-col items-center justify-center text-center hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-colors cursor-pointer group">
                   <IconUpload className="w-10 h-10 text-slate-400 group-hover:text-primary-500 mb-2 transition-colors" />
                   <p className="text-sm font-medium text-slate-700 dark:text-slate-300">Click to upload or drag and drop</p>
