                          <button 
                              onClick={() => { if(window.confirm('Delete this document permanently?')) { onDeleteDocument(selectedDocument.id); setIsQuickViewOpen(false); } }}
                              className="p-2 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
                              title="Delete"
                          >
                              <IconTrash className="w-5 h-5" />
                          </button>
                          <button onClick={() => setIsQuickViewOpen(false)} className="p-2 text-slate-400 hover:text-slate-600 dark:hover:text-white">
                              <IconX className="w-6 h-6" />
                          </button>
                      </div>
                  </div>

                  <div className="flex flex-1 overflow-hidden">
                      {/* Preview Area */}
                      <div className="flex-1 bg-slate-100 dark:bg-slate-950 flex flex-col items-center justify-center border-r border-slate-200 dark:border-slate-800 p-8">
                          <div className="w-32 h-40 bg-white dark:bg-slate-800 shadow-xl flex items-center justify-center mb-6 rounded-lg border border-slate-200 dark:border-slate-700">
                              <IconFileText className="w-16 h-16 text-slate-300 dark:text-slate-600" />
                          </div>
                          <p className="text-slate-500 dark:text-slate-400 text-sm font-medium">Preview not available for this file type.</p>
                          <button className="mt-4 px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm font-medium hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors shadow-sm flex items-center">
                              <IconDownload className="w-4 h-4 mr-2" /> Download File
                          </button>
                      </div>

                      {/* Details Sidebar */}
                      <div className="w-80 bg-white dark:bg-slate-900 p-6 overflow-y-auto">
                          <h3 className="text-sm font-bold text-slate-900 dark:text-white uppercase tracking-wider mb-4 border-b border-slate-100 dark:border-slate-800 pb-2">Details</h3>
                          <div className="space-y-4">
                              <div>
                                  <label className="text-xs text-slate-500 dark:text-slate-400 block mb-1">Status</label>
                                  <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                                      selectedDocument.status === 'Final' ? 'bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-400' :
                                      selectedDocument.status === 'Draft' ? 'bg-slate-100 text-slate-800 dark:bg-slate-800 dark:text-slate-300' :
                                      'bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-400'
                                  }`}>
                                      {selectedDocument.status}
                                  </span>
                              </div>
                              <div>
                                  <label className="text-xs text-slate-500 dark:text-slate-400 block mb-1">Type</label>
                                  <p className="text-sm font-medium text-slate-900 dark:text-white">{selectedDocument.type}</p>
                              </div>
                              <div>
                                  <label className="text-xs text-slate-500 dark:text-slate-400 block mb-1">Related To</label>
                                  <p className="text-sm font-medium text-slate-900 dark:text-white">{selectedDocument.relatedTo}</p>
                              </div>
                              <div>
                                  <label className="text-xs text-slate-500 dark:text-slate-400 block mb-1">File Size</label>
                                  <p className="text-sm font-medium text-slate-900 dark:text-white">{selectedDocument.size}</p>
                              </div>
                              <div>
                                  <label className="text-xs text-slate-500 dark:text-slate-400 block mb-1">Uploaded By</label>
                                  <p className="text-sm font-medium text-slate-900 dark:text-white">{selectedDocument.uploadedBy}</p>
                              </div>
                          </div>
                      </div>
                  </div>
              </div>
          </div>
      )}

      {/* Parsing Result Modal */}
      {(isParsing || parseResult) && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
              <div className="w-full max-w-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden animate-scale-in">
                  <div className="p-6 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50">
                      <h2 className="text-xl font-bold text-slate-900 dark:text-white flex items-center">
                          <IconSparkles className="w-5 h-5 mr-3 text-indigo-500" />
                          Document Analysis
                      </h2>
                      <button 
                          onClick={() => { setParseResult(null); setIsParsing(false); }} 
                          className="text-slate-400 hover:text-slate-600 dark:hover:text-white transition-colors"
                      >
                          <IconX className="w-6 h-6" />
                      </button>
                  </div>
                  <div className="p-8">
                      {isParsing ? (
                          <div className="flex flex-col items-center justify-center py-8">
                              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600 mb-4"></div>
                              <p className="text-slate-600 dark:text-slate-300 font-medium">Analyzing selected documents...</p>
                              <p className="text-xs text-slate-500 mt-2">This may take a few seconds.</p>
                          </div>
                      ) : (
                          <div className="prose prose-sm dark:prose-invert max-w-none text-slate-700 dark:text-slate-300 leading-relaxed">
                              <div dangerouslySetInnerHTML={{ __html: parseResult ? parseResult.replace(/\n/g, '<br />') : '' }} />
                          </div>
                      )}
                  </div>
                  {!isParsing && (
                      <div className="p-4 border-t border-slate-200 dark:border-slate-800 flex justify-end bg-slate-50 dark:bg-slate-800/50">
                          <button 
                              onClick={() => { setParseResult(null); setIsParsing(false); }} 
                              className="px-5 py-2.5 text-sm font-medium text-white bg-indigo-600 rounded-xl hover:bg-indigo-500 transition-colors"
                          >
                              Close
                          </button>
                      </div>
                  )}
              </div>
          </div>
      )}
    </div>
  );
};

export default Documents;

import React, { useState, useMemo } from 'react';
import { Document, DocumentType, DocumentStatus } from '../types';
import { 
  IconFileText, IconSearch, IconFilter, IconPlus, IconDownload, IconTrash, 
  IconArrowUp, IconArrowDown, IconX, IconUpload, IconFile, IconArchive, 
  IconRefresh, IconSparkles, IconCheckSquare, IconCalendar, IconEye
} from './Icons';
import { batchParseDocuments } from '../services/geminiService';

interface DocumentsProps {
  documents: Document[];
  onAddDocument: (doc: Document) => void;
  onDeleteDocument: (id: string) => void;
  onUpdateDocument: (doc: Document) => void;
}

const DOCUMENT_TYPES: DocumentType[] = ['Contract', 'Proposal', 'Invoice', 'Brief', 'Report', 'Other'];
const DOCUMENT_STATUSES: DocumentStatus[] = ['Draft', 'Final', 'Signed', 'Pending Review'];
const DATE_FILTERS = ['All Time', 'This Week', 'This Month', 'This Quarter', 'This Year'];

const Documents: React.FC<DocumentsProps> = ({ documents, onAddDocument, onDeleteDocument, onUpdateDocument }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [typeFilter, setTypeFilter] = useState<string>('All');
  const [dateFilter, setDateFilter] = useState<string>('All Time');
  const [sortConfig, setSortConfig] = useState<{ key: keyof Document; direction: 'asc' | 'desc' } | null>({ key: 'uploadedAt', direction: 'desc' });
  const [activeTab, setActiveTab] = useState<'active' | 'archived'>('active');
  const [selectedDocIds, setSelectedDocIds] = useState<Set<string>>(new Set());

  // Modal States
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isQuickViewOpen, setIsQuickViewOpen] = useState(false);
  const [selectedDocument, setSelectedDocument] = useState<Document | null>(null);

  const [formData, setFormData] = useState<Partial<Document>>({
    type: 'Contract',
    status: 'Draft',
    relatedTo: ''
  });

  // AI Parsing State
  const [isParsing, setIsParsing] = useState(false);
  const [parseResult, setParseResult] = useState<string | null>(null);

  const filteredDocuments = useMemo(() => {
    return documents.filter(doc => {
      const isArchived = !!doc.archived;
      const showInTab = activeTab === 'archived' ? isArchived : !isArchived;

      if (!showInTab) return false;

      // 1. Text Search
      const matchesSearch = doc.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            doc.relatedTo.toLowerCase().includes(searchQuery.toLowerCase());

      // 2. Type Filter
      const matchesType = typeFilter === 'All' || doc.type === typeFilter;

      // 3. Date Filter
      let matchesDate = true;
      if (dateFilter !== 'All Time') {
          const docDate = new Date(doc.uploadedAt);
          const now = new Date();

          if (dateFilter === 'This Week') {
              const startOfWeek = new Date(now);
              startOfWeek.setDate(now.getDate() - now.getDay()); // Sunday
              startOfWeek.setHours(0, 0, 0, 0);
              matchesDate = docDate >= startOfWeek;
          } else if (dateFilter === 'This Month') {
              matchesDate = docDate.getMonth() === now.getMonth() && docDate.getFullYear() === now.getFullYear();
          } else if (dateFilter === 'This Quarter') {
              const currentQuarter = Math.floor(now.getMonth() / 3);
              const docQuarter = Math.floor(docDate.getMonth() / 3);
              matchesDate = currentQuarter === docQuarter && docDate.getFullYear() === now.getFullYear();
          } else if (dateFilter === 'This Year') {
              matchesDate = docDate.getFullYear() === now.getFullYear();
          }
      }

      return matchesSearch && matchesType && matchesDate;
    });
  }, [documents, searchQuery, typeFilter, activeTab, dateFilter]);

  const sortedDocuments = useMemo(() => {
    let items = [...filteredDocuments];
    if (sortConfig) {
      items.sort((a, b) => {
        const aVal = a[sortConfig.key] || '';
        const bVal = b[sortConfig.key] || '';
        if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
        if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
      });
    }
    return items;
  }, [filteredDocuments, sortConfig]);

  const handleSort = (key: keyof Document) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') direction = 'desc';
    setSortConfig({ key, direction });
  };

  const getSortIcon = (key: keyof Document) => {
    if (!sortConfig || sortConfig.key !== key) return <span className="w-3 h-3 opacity-0 group-hover:opacity-50 transition-opacity">↕️</span>;
    if (sortConfig.direction === 'asc') return <IconArrowUp className="w-3 h-3 text-primary-500" />;
    return <IconArrowDown className="w-3 h-3 text-primary-500" />;
  };

  const toggleSelectDoc = (id: string) => {
    const newSelected = new Set(selectedDocIds);
    if (newSelected.has(id)) newSelected.delete(id);
    else newSelected.add(id);
    setSelectedDocIds(newSelected);
  };

  const toggleSelectAll = () => {
    if (selectedDocIds.size === sortedDocuments.length && sortedDocuments.length > 0) {
      setSelectedDocIds(new Set());
    } else {
      setSelectedDocIds(new Set(sortedDocuments.map(d => d.id)));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) {
      alert("File Name is required");
      return;
    }

    const newDoc: Document = {
      id: `DOC-${Date.now()}`,
      name: formData.name,
      type: formData.type as DocumentType,
      status: formData.status as DocumentStatus,
      relatedTo: formData.relatedTo || 'General',
      size: `${(Math.random() * 5 + 0.5).toFixed(1)} MB`, // Mock size
      uploadedBy: 'Alex Chen',
      uploadedAt: new Date().toISOString().split('T')[0],
      archived: false
    };

    onAddDocument(newDoc);
    setIsModalOpen(false);
    setFormData({ type: 'Contract', status: 'Draft', relatedTo: '', name: '' });
  };

  const handleBulkArchive = () => {
      const selectedIds = Array.from(selectedDocIds);
      if (confirm(`Archive ${selectedIds.length} documents?`)) {
          selectedIds.forEach(id => {
              const doc = documents.find(d => d.id === id);
              if (doc) onUpdateDocument({ ...doc, archived: true });
          });
          setSelectedDocIds(new Set());
      }
  };

  const handleBulkRestore = () => {
      const selectedIds = Array.from(selectedDocIds);
      selectedIds.forEach(id => {
          const doc = documents.find(d => d.id === id);
          if (doc) onUpdateDocument({ ...doc, archived: false });
      });
      setSelectedDocIds(new Set());
  };

  const handleArchive = (doc: Document) => {
      onUpdateDocument({ ...doc, archived: true });
  };

  const handleRestore = (doc: Document) => {
      onUpdateDocument({ ...doc, archived: false });
  };

  const handleQuickView = (doc: Document) => {
      setSelectedDocument(doc);
      setIsQuickViewOpen(true);
  };

  const handleBulkParse = async () => {
      const selectedDocs = documents.filter(d => selectedDocIds.has(d.id));
      if (selectedDocs.length === 0) return;

      setIsParsing(true);
      const result = await batchParseDocuments(selectedDocs);
      setParseResult(result);
      setIsParsing(false);
  };

  // Helper to open Quick View for the single selected item in bulk mode
  const handleBulkQuickView = () => {
      if (selectedDocIds.size === 1) {
          const docId = Array.from(selectedDocIds)[0];
          const doc = documents.find(d => d.id === docId);
          if (doc) handleQuickView(doc);
      }
  };

  return (
    <div className="space-y-6 h-full flex flex-col animate-fade-in">
      {/* Header */}
      <div className="flex justify-between items-center flex-shrink-0">
        <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Documents</h1>

        <div className="flex gap-3">
            {/* View Toggle */}
            <div className="flex bg-slate-100 dark:bg-slate-800/50 p-1 rounded-xl border border-slate-200 dark:border-slate-700/50">
                <button 
                    onClick={() => { setActiveTab('active'); setSelectedDocIds(new Set()); }}
                    className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-all ${activeTab === 'active' ? 'bg-white dark:bg-slate-700 shadow-sm text-primary-600 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200'}`}
                >
                    Active
                </button>
                <button 
                    onClick={() => { setActiveTab('archived'); setSelectedDocIds(new Set()); }}
                    className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-all ${activeTab === 'archived' ? 'bg-white dark:bg-slate-700 shadow-sm text-primary-600 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200'}`}
                >
                    Archived
                </button>
            </div>

            <button 
            onClick={() => setIsModalOpen(true)}
            className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-all flex items-center"
            >
            <IconUpload className="w-4 h-4 mr-2" /> Upload Document
            </button>
        </div>
      </div>

      <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden flex flex-col flex-1">
