                          </div>
                      </div>
                      <div className="w-80 bg-white dark:bg-slate-900 p-6 overflow-y-auto border-l border-slate-200 dark:border-slate-800">
                          <h3 className="text-sm font-bold text-slate-900 dark:text-white uppercase tracking-wider mb-4 border-b border-slate-100 dark:border-slate-800 pb-2">Details</h3>
                          <div className="space-y-4">
                              <div><label className="text-xs text-slate-500 dark:text-slate-400 block mb-1">Type</label><p className="text-sm font-medium text-slate-900 dark:text-white">{selectedDocument.type}</p></div>
                              <div><label className="text-xs text-slate-500 dark:text-slate-400 block mb-1">Related To</label><p className="text-sm font-medium text-slate-900 dark:text-white">{selectedDocument.relatedTo}</p></div>
                              <div><label className="text-xs text-slate-500 dark:text-slate-400 block mb-1">Status</label><p className="text-sm font-medium text-slate-900 dark:text-white">{selectedDocument.status}</p></div>
                          </div>
                      </div>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Documents;

import React, { useState, useMemo, useEffect } from 'react';
import { Lead, Deal, Account, Contact, Document } from '../types';
import { 
  IconSearch, IconPlus, IconArrowUp, IconArrowDown, IconTrash, IconUser
} from './Icons';
import LeadDetail from './LeadDetail';
import LeadForm from './LeadForm';

interface LeadsProps {
  leads: Lead[];
  accounts?: Account[];
  contacts?: Contact[];
  onAddLead: (lead: Omit<Lead, 'id'>) => void;
  onUpdateLead: (lead: Lead) => void;
  onDeleteLeads: (ids: string[]) => void;
  onAddDeal: (deal: Deal) => void;
  onViewOpportunities?: () => void;
  onAddDocument: (doc: Document) => void;
}

type ViewMode = 'list' | 'detail' | 'create' | 'edit';
type SortKey = keyof Lead;

const Leads: React.FC<LeadsProps> = ({ leads, accounts = [], contacts = [], onAddLead, onUpdateLead, onDeleteLeads, onAddDeal, onViewOpportunities, onAddDocument }) => {
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [selectedLead, setSelectedLead] = useState<Lead | null>(null);
  const [selectedLeadIds, setSelectedLeadIds] = useState<Set<string>>(new Set());

  const [searchQuery, setSearchQuery] = useState('');
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: 'asc' | 'desc' } | null>(null);

  useEffect(() => {
    if (selectedLead) {
      const updatedLead = leads.find(l => l.id === selectedLead.id);
      if (updatedLead) setSelectedLead(updatedLead);
    }
  }, [leads, selectedLead]);

  const filteredLeads = useMemo(() => {
    return leads.filter(lead => {
      const matchesSearch = 
        lead.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
        lead.company.toLowerCase().includes(searchQuery.toLowerCase()) ||
        lead.email.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesSearch;
    });
  }, [leads, searchQuery]);

  const sortedLeads = useMemo(() => {
    let items = [...filteredLeads];
    if (sortConfig) {
      items.sort((a, b) => {
        // @ts-ignore
        const aVal = a[sortConfig.key] || '';
        // @ts-ignore
        const bVal = b[sortConfig.key] || '';
        if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
        if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
      });
    }
    return items;
  }, [filteredLeads, sortConfig]);

  const handleSort = (key: SortKey) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const getSortIcon = (key: SortKey) => {
    if (!sortConfig || sortConfig.key !== key) return <span className="w-3 h-3 opacity-0 group-hover:opacity-50 transition-opacity">↕️</span>;
    if (sortConfig.direction === 'asc') return <IconArrowUp className="w-3 h-3 text-primary-500" />;
    return <IconArrowDown className="w-3 h-3 text-primary-500" />;
  };

  const toggleSelectLead = (id: string) => {
    const newSelected = new Set(selectedLeadIds);
    if (newSelected.has(id)) newSelected.delete(id);
    else newSelected.add(id);
    setSelectedLeadIds(newSelected);
  };

  const toggleSelectAll = () => {
    if (selectedLeadIds.size === sortedLeads.length) {
      setSelectedLeadIds(new Set());
    } else {
      setSelectedLeadIds(new Set(sortedLeads.map(l => l.id)));
    }
  };

  const handleDeleteSelected = () => {
    if (window.confirm(`Are you sure you want to delete ${selectedLeadIds.size} leads?`)) {
      onDeleteLeads(Array.from(selectedLeadIds));
      setSelectedLeadIds(new Set());
    }
  };

  if (viewMode === 'create' || (viewMode === 'edit' && selectedLead)) {
    return (
      <LeadForm 
        onCancel={() => { setViewMode('list'); setSelectedLead(null); }}
        onSave={(lead) => { 
            if (viewMode === 'create') onAddLead(lead);
            else if (selectedLead) onUpdateLead({ ...lead, id: selectedLead.id });
            setViewMode('list'); 
            setSelectedLead(null);
        }}
        initialData={viewMode === 'edit' ? selectedLead : null}
        accounts={accounts}
        contacts={contacts}
      />
    );
  }

  if (viewMode === 'detail' && selectedLead) {
    return (
      <LeadDetail 
        lead={selectedLead} 
        onBack={() => { setViewMode('list'); setSelectedLead(null); }}
        onEdit={() => setViewMode('edit')}
        onDelete={() => { onDeleteLeads([selectedLead.id]); setViewMode('list'); setSelectedLead(null); }}
        onNurture={() => {}}
        isNurturing={false}
        leads={leads}
        onComposeEmail={() => {}}
        onAddDeal={onAddDeal}
        onUpdateLead={onUpdateLead}
        onViewOpportunities={onViewOpportunities}
        onAddDocument={onAddDocument}
      />
    );
  }

  return (
    <div className="space-y-6 h-full flex flex-col animate-fade-in">
      <div className="flex justify-between items-center flex-shrink-0">
        <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Leads</h1>
        <div className="flex items-center gap-3">
          {selectedLeadIds.size > 0 && (
            <button onClick={handleDeleteSelected} className="px-4 py-2 text-sm font-medium text-red-600 bg-red-50 dark:bg-red-500/10 border border-red-200 dark:border-red-500/20 rounded-lg hover:bg-red-100 dark:hover:bg-red-500/20 transition-colors flex items-center">
              <IconTrash className="w-4 h-4 mr-2" /> Delete ({selectedLeadIds.size})
            </button>
          )}
          <button onClick={() => setViewMode('create')} className="px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-all flex items-center">
            <IconPlus className="w-4 h-4 mr-2" /> New Lead
          </button>
        </div>
      </div>

      <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden flex flex-col flex-1">
        <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50/50 dark:bg-slate-900/50">
           <div className="relative max-w-md w-full">
             <IconSearch className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
             <input type="text" placeholder="Search leads..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="w-full pl-9 pr-4 py-2 text-sm bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-900 dark:text-white" />
           </div>
        </div>

        <div className="overflow-auto flex-1">
          <table className="w-full text-left text-sm border-collapse">
            <thead className="bg-slate-50 dark:bg-slate-950/90 text-slate-500 dark:text-slate-400 font-semibold border-b border-slate-200 dark:border-slate-800 sticky top-0 z-10 backdrop-blur-sm">
              <tr>
                <th className="px-6 py-4 w-12">
                  <input type="checkbox" checked={selectedLeadIds.size === sortedLeads.length && sortedLeads.length > 0} onChange={toggleSelectAll} className="rounded border-slate-300 text-primary-600 focus:ring-primary-500 cursor-pointer w-4 h-4" />
                </th>
                <th className="px-6 py-4 cursor-pointer group hover:text-primary-600 transition-colors" onClick={() => handleSort('name')}><div className="flex items-center gap-1 uppercase tracking-wider text-xs">Name {getSortIcon('name')}</div></th>
                <th className="px-6 py-4 cursor-pointer group hover:text-primary-600 transition-colors" onClick={() => handleSort('company')}><div className="flex items-center gap-1 uppercase tracking-wider text-xs">Company {getSortIcon('company')}</div></th>
                <th className="px-6 py-4 cursor-pointer group hover:text-primary-600 transition-colors" onClick={() => handleSort('email')}><div className="flex items-center gap-1 uppercase tracking-wider text-xs">Email {getSortIcon('email')}</div></th>
                <th className="px-6 py-4 cursor-pointer group hover:text-primary-600 transition-colors" onClick={() => handleSort('status')}><div className="flex items-center gap-1 uppercase tracking-wider text-xs">Status {getSortIcon('status')}</div></th>
                <th className="px-6 py-4 cursor-pointer group hover:text-primary-600 transition-colors" onClick={() => handleSort('score')}><div className="flex items-center gap-1 uppercase tracking-wider text-xs">Score {getSortIcon('score')}</div></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-200 dark:divide-slate-800">
              {sortedLeads.map((lead, index) => (
                <tr 
                    key={lead.id} 
                    className={`group transition-all duration-200 cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-800/60 ${index % 2 === 0 ? 'bg-white dark:bg-slate-900' : 'bg-slate-50/50 dark:bg-slate-900/40'}`}
                    onClick={() => { setSelectedLead(lead); setViewMode('detail'); }}
                >
                  <td className="px-6 py-4" onClick={(e) => e.stopPropagation()}>
                    <input type="checkbox" checked={selectedLeadIds.has(lead.id)} onChange={() => toggleSelectLead(lead.id)} className="rounded border-slate-300 text-primary-600 focus:ring-primary-500 cursor-pointer w-4 h-4" />
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center">
                        <div className="w-9 h-9 rounded-full bg-gradient-to-br from-slate-100 to-slate-200 dark:from-slate-800 dark:to-slate-700 text-slate-600 dark:text-slate-300 flex items-center justify-center mr-3 text-sm font-bold border border-slate-200 dark:border-slate-700 shadow-sm">{lead.name.charAt(0)}</div>
                        <div><span className="font-semibold text-slate-900 dark:text-white block">{lead.name}</span><span className="text-xs text-slate-500 dark:text-slate-400 md:hidden">{lead.title}</span></div>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-slate-600 dark:text-slate-300 font-medium">{lead.company}</td>
                  <td className="px-6 py-4 text-slate-500 dark:text-slate-400">{lead.email}</td>
                  <td className="px-6 py-4">
                    <span className={`px-3 py-1 text-xs font-semibold rounded-full border ${lead.status === 'New' ? 'bg-blue-50 text-blue-700 border-blue-200 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-800' : lead.status === 'Contacted' ? 'bg-purple-50 text-purple-700 border-purple-200 dark:bg-purple-900/20 dark:text-purple-400 dark:border-purple-800' : lead.status === 'Qualified' ? 'bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-900/20 dark:text-emerald-400 dark:border-emerald-800' : 'bg-slate-50 text-slate-600 border-slate-200 dark:bg-slate-800 dark:text-slate-400 dark:border-slate-700'}`}>{lead.status}</span>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-3">
                        <div className="w-16 h-2 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                            <div className={`h-full rounded-full ${lead.score > 70 ? 'bg-emerald-500' : lead.score > 40 ? 'bg-amber-500' : 'bg-red-500'}`} style={{ width: `${lead.score}%` }}></div>
                        </div>
                        <span className={`text-sm font-bold ${lead.score > 70 ? 'text-emerald-600 dark:text-emerald-400' : lead.score > 40 ? 'text-amber-600 dark:text-amber-400' : 'text-red-600 dark:text-red-400'}`}>{lead.score}</span>
                    </div>
                  </td>
                </tr>
              ))}
              {sortedLeads.length === 0 && (
                  <tr>
                      <td colSpan={6} className="px-6 py-16 text-center text-slate-500 dark:text-slate-400">
                          <div className="flex flex-col items-center justify-center">
                              <div className="p-4 bg-slate-50 dark:bg-slate-800/50 rounded-full mb-3"><IconUser className="w-8 h-8 text-slate-300 dark:text-slate-600" /></div>
                              <p className="text-lg font-semibold text-slate-900 dark:text-white">No leads found</p>
                              <p className="text-sm mt-1">Try adjusting your search filters or add a new lead.</p>
                          </div>
                      </td>
                  </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Leads;

import React, { useState, useEffect } from 'react';
import { Lead, Deal, Document } from '../types';
import { 
  IconArrowLeft, IconEdit, IconTrash, IconMail, IconPhone, IconBuilding, 
  IconSparkles, IconGlobe, IconUser, IconBot, IconMessageSquare, IconCopy, 
  IconKanban, IconChevronRight, IconFileText, IconPlus
} from './Icons';
import { generateFollowUpSuggestions } from '../services/geminiService';

interface LeadDetailProps {
  lead: Lead;
  onBack: () => void;
  onEdit: () => void;
  onDelete: () => void;
  onNurture: () => void;
  isNurturing: boolean;
  leads: Lead[];
  onComposeEmail: (lead: Lead, initialContent: string) => void;
  onAddDeal?: (deal: Deal) => void;
  onUpdateLead: (lead: Lead) => void;
  onSelectLead?: (lead: Lead) => void;
  onViewOpportunities?: () => void;
  onAddDocument: (doc: Document) => void;
}

const DetailRow: React.FC<{ label: string; value?: string | number | null; icon?: React.ElementType }> = ({ label, value, icon: Icon }) => {
  if (!value && value !== 0) return null;
  return (
    <div>
      <label className="text-sm text-slate-500 dark:text-slate-400 uppercase tracking-wider">{label}</label>
      <p className="text-lg text-slate-900 dark:text-slate-100 flex items-center mt-1">
        {Icon && <Icon className="w-4 h-4 mr-2 text-slate-400" />}
        {value}
      </p>
    </div>
  );
};

const LeadDetail: React.FC<LeadDetailProps> = ({ lead, onBack, onEdit, onDelete, onNurture, isNurturing, leads, onComposeEmail, onAddDeal, onUpdateLead, onSelectLead, onViewOpportunities, onAddDocument }) => {
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [isLoadingSuggestions, setIsLoadingSuggestions] = useState(true);
  const [showDocMenu, setShowDocMenu] = useState(false);

  useEffect(() => {
    let isMounted = true;
    const fetchSuggestions = async () => {
      setIsLoadingSuggestions(true);
      const result = await generateFollowUpSuggestions(lead);
      if (isMounted) {
        setSuggestions(result);
        setIsLoadingSuggestions(false);
      }
    };
    fetchSuggestions();
    return () => { isMounted = false; };
  }, [lead]);

  const handleConvertToOpportunity = () => {
      if (confirm(`Convert ${lead.name} to an Opportunity? This will create a new opportunity and update the lead status to Qualified.`)) {
          if (onAddDeal) {
              const newDeal: Deal = {
                  id: `D-${Date.now()}`,
                  title: `${lead.company || lead.name} - Opportunity`,
                  company: lead.company,
                  value: lead.value || 0,
                  stage: 'Qualification',
                  probability: 20,
                  closeDate: new Date(new Date().setMonth(new Date().getMonth() + 1)).toISOString().split('T')[0],
                  email: lead.email,
                  phone: lead.phone,
                  activities: [{
                      id: `DA-${Date.now()}`,
                      type: 'created',
                      description: `Opportunity created from Lead: ${lead.name}`,
                      timestamp: new Date().toISOString()
                  }]
              };
              onAddDeal(newDeal);
              onUpdateLead({ ...lead, status: 'Qualified', rating: 'Active' });

              if (onViewOpportunities) {
                  onViewOpportunities();
              } else {
                  alert("Opportunity created successfully!");
              }
          }
      }
  };

  const handleGenerateDocument = (type: 'Proposal' | 'Quotation') => {
      const newDoc: Document = {
          id: `DOC-${Date.now()}`,
          name: `${type} for ${lead.company}.pdf`,
          type: type,
          status: 'Draft',
          relatedTo: lead.company,
          size: '1.2 MB', // Mock size
          uploadedBy: lead.owner || 'System',
          uploadedAt: new Date().toISOString().split('T')[0],
          archived: false
      };
      onAddDocument(newDoc);
      setShowDocMenu(false);
      alert(`${type} generated successfully! Check the Documents tab.`);
  };

  const similarLeads = leads.filter(l => 
    l.id !== lead.id &&
    (l.industry === lead.industry || l.company === lead.company) &&
    l.score > 70
  ).sort((a, b) => b.score - a.score).slice(0, 3);

  return (
    <div className="bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm h-full flex flex-col animate-fade-in">
      {/* Header */}
      <div className="p-4 border-b border-slate-200 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-950/50 rounded-t-xl flex-shrink-0">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800 transition-colors">
            <IconArrowLeft className="w-5 h-5 text-slate-600 dark:text-slate-300" />
          </button>
          <div>
            <h1 className="text-3xl font-bold text-slate-900 dark:text-white">{lead.name}</h1>
            <p className="text-lg text-slate-500 dark:text-slate-400">{lead.company}</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {/* Document Generation Dropdown */}
          <div className="relative">
              <button 
                onClick={() => setShowDocMenu(!showDocMenu)}
                className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-slate-700 dark:text-slate-300 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-md hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors"
              >
                  <IconFileText className="w-4 h-4" /> Create Doc
              </button>
              {showDocMenu && (
                  <div className="absolute right-0 mt-2 w-48 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl shadow-lg z-50 overflow-hidden">
                      <button onClick={() => handleGenerateDocument('Proposal')} className="w-full text-left px-4 py-2 text-sm text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-700">Proposal</button>
                      <button onClick={() => handleGenerateDocument('Quotation')} className="w-full text-left px-4 py-2 text-sm text-slate-700 dark:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-700">Quotation</button>
                  </div>
              )}
          </div>

          {lead.status !== 'Qualified' && lead.status !== 'Closed Won' && lead.status !== 'Closed Lost' && (
              <button 
                onClick={handleConvertToOpportunity}
                className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-white bg-emerald-600 rounded-md hover:bg-emerald-500 shadow-lg shadow-emerald-500/20 transition-colors mr-2"
              >
                <IconKanban className="w-4 h-4" /> 
                Convert
              </button>
          )}
          <button 
            onClick={onNurture}
            disabled={isNurturing}
            className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-white bg-primary-600 rounded-md hover:bg-primary-500 shadow-lg shadow-primary-500/20 transition-colors disabled:opacity-70 disabled:cursor-not-allowed"
          >
            <IconBot className="w-4 h-4" /> 
            {isNurturing ? '...' : 'Nurture'}
          </button>
          <button onClick={onEdit} className="p-2 text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-colors">
            <IconEdit className="w-5 h-5" />
          </button>
          <button onClick={onDelete} className="p-2 text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-full transition-colors">
            <IconTrash className="w-5 h-5" />
          </button>
        </div>
      </div>

      {/* Body */}
      <div className="flex-1 overflow-y-auto p-8">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Main Details Column */}
          <div className="lg:col-span-2 space-y-8">
            <div className="p-6 bg-slate-50 dark:bg-slate-800/50 rounded-lg border border-slate-200 dark:border-slate-800">
              <h3 className="text-xl font-semibold text-slate-900 dark:text-white mb-6">Lead Information</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <DetailRow label="Lead Owner" value={lead.owner} icon={IconUser} />
                <DetailRow label="Name" value={`${lead.firstName || ''} ${lead.lastName || ''}`} />
                <DetailRow label="Company" value={lead.company} icon={IconBuilding} />
                <DetailRow label="Title" value={lead.title} />
                <DetailRow label="Source" value={lead.leadSource} />
                <DetailRow label="Status" value={lead.status} />
              </div>
            </div>

            <div className="p-6 bg-slate-50 dark:bg-slate-800/50 rounded-lg border border-slate-200 dark:border-slate-800">
              <h3 className="text-xl font-semibold text-slate-900 dark:text-white mb-6">Contact</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <DetailRow label="Email" value={lead.email} icon={IconMail} />
                <DetailRow label="Phone" value={lead.phone} icon={IconPhone} />
                <DetailRow label="Website" value={lead.website} icon={IconGlobe} />
                <DetailRow label="Address" value={lead.city} />
              </div>
            </div>

            {/* AI Follow-up Suggestions */}
            <div className="p-6 bg-slate-50 dark:bg-slate-800/50 rounded-lg border border-slate-200 dark:border-slate-800">
              <h3 className="text-xl font-semibold text-slate-900 dark:text-white mb-6 flex items-center">
                <IconSparkles className="w-5 h-5 mr-2 text-primary-500" />
                AI Suggested Actions
              </h3>
              {isLoadingSuggestions ? (
                <div className="space-y-4 animate-pulse">
                  <div className="h-4 bg-slate-200 dark:bg-slate-700 rounded w-5/6"></div>
                  <div className="h-4 bg-slate-200 dark:bg-slate-700 rounded w-full"></div>
                </div>
              ) : (
                <div className="space-y-4">
                  {suggestions.map((suggestion, index) => (
                    <div key={index} className="flex items-start gap-3 group">
                      <IconMessageSquare className="w-4 h-4 text-slate-400 mt-1 flex-shrink-0" />
                      <p className="flex-1 text-base text-slate-700 dark:text-slate-300">
                        {suggestion}
                      </p>
                      <div className="flex flex-col gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button onClick={() => onComposeEmail(lead, suggestion)} className="p-1.5 rounded-md text-primary-600 bg-primary-50 hover:bg-primary-100 dark:text-primary-400 dark:bg-primary-900/30 dark:hover:bg-primary-900/50 transition-colors"><IconMail className="w-4 h-4" /></button>
                        <button onClick={() => navigator.clipboard.writeText(suggestion)} className="p-1.5 rounded-md text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors"><IconCopy className="w-4 h-4" /></button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
