/**
 * Finds account location and suggests nearby competitors using Google Maps Grounding.
 */
export const findAccountLocationAndNearby = async (companyName: string, website: string, industry: string): Promise<{ address: string, competitors: string }> => {
  try {
    const prompt = `Locate the headquarters of ${companyName} (${website}) using Google Maps. 
    1. Provide the full street address.
    2. Using Google Maps, find 3-4 nearby companies that are in the "${industry}" sector/industry segment.

    Format the output exactly as follows:
    Address: [Full Address]

    Nearby Opportunities:
    - [Company Name]: [Distance/Brief details]
    - [Company Name]: [Distance/Brief details]
    `;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        tools: [{ googleMaps: {} }],
      },
    });

    const text = response.text || "";

    // Simple parsing to extract address and list
    const addressMatch = text.match(/Address:\s*(.*?)(\n|$)/i);
    const address = addressMatch ? addressMatch[1].trim() : "";

    // Extract everything after "Nearby Opportunities:"
    const competitorsMatch = text.match(/Nearby Opportunities:([\s\S]*)/i);
    const competitors = competitorsMatch ? competitorsMatch[1].trim() : "";

    return { 
      address: address || "Location not found.", 
      competitors: competitors || "No nearby data found." 
    };

  } catch (error) {
    console.error("Gemini Maps Location Error:", error);
    return { address: "", competitors: "Unable to fetch location data." };
  }
};

/**
 * Parses multiple documents to extract key information using AI.
 */
export const batchParseDocuments = async (docs: Document[]): Promise<string> => {
  try {
    const docList = docs.map(d => `- ${d.name} (${d.type}) related to ${d.relatedTo}`).join('\n');
    const prompt = `Analyze the metadata of these documents and provide a consolidated summary.

    Documents:
    ${docList}

    Please identify:
    1. The mix of document types (e.g. 2 Contracts, 1 Proposal).
    2. Key accounts involved based on the filenames and 'related to' field.
    3. Any potential missing documents typically needed for a deal (e.g. if a Proposal exists but no Contract).

    Keep the summary concise and formatted as a bulleted list.`;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
    });

    return response.text || "Document parsing failed.";
  } catch (error) {
    console.error("Gemini Doc Parse Error:", error);
    return "Unable to parse documents at this moment.";
  }
};

/**
 * Generates proposal content based on lead details.
 */
export const generateProposalContent = async (lead: Lead) => {
  try {
    const prompt = `Draft a professional project proposal for a potential client based on the following details.

    **Client Details:**
    - Name: ${lead.name}
    - Company: ${lead.company}
    - Industry: ${lead.industry}
    - Potential Deal Value: $${lead.value || 50000}
    - Notes: ${lead.notes || 'No specific notes.'}

    **Requirements:**
    1. **Executive Summary**: A compelling paragraph summarizing why our solution is a good fit for ${lead.company}.
    2. **Scope of Work**: A list of 4-6 bullet points outlining standard services for a ${lead.industry || 'Business'} client (e.g., implementation, training, migration).
    3. **Investment Items**: A breakdown of costs that sum up to roughly the potential deal value ($${lead.value || 50000}). Return as an array of objects with 'description' and 'cost'.

    Return the output as a valid JSON object with the following keys:
    {
      "executiveSummary": "string",
      "scopeOfWork": ["string", "string"],
      "investmentItems": [
        {"description": "string", "cost": number}
      ]
    }
    `;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            executiveSummary: { type: Type.STRING },
            scopeOfWork: { 
              type: Type.ARRAY, 
              items: { type: Type.STRING } 
            },
            investmentItems: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  description: { type: Type.STRING },
                  cost: { type: Type.NUMBER }
                },
                required: ['description', 'cost']
              }
            }
          },
          required: ['executiveSummary', 'scopeOfWork', 'investmentItems']
        }
      }
    });

    const text = response.text?.trim();
    if (!text) throw new Error("Empty response");
    const jsonStr = text.startsWith("```json") ? text.replace(/```json\n|```/g, "") : text;
    return JSON.parse(jsonStr);

  } catch (error) {
    console.error("Gemini Proposal Gen Error:", error);
    return null;
  }
};

