                {value}
            </a>
        ) : value}
      </p>
    </div>
  );
};

const AccountDetail: React.FC<AccountDetailProps> = ({ account, onBack, onEdit, onDelete, contacts, deals, leads, meetings = [], calls = [], onAddContact, onAddCall, onUpdateAccount, onAddDocument }) => {
