                            {selectedTemplate ? (
                                <div className="max-w-[800px] mx-auto bg-white shadow-2xl min-h-[1000px] rounded-sm transform transition-all origin-top duration-300 relative">
                                    {/* Overlay for editor mode to simulate structure changes without re-writing entire components */}
                                    {isEditorMode && (
                                        <div className="absolute inset-0 pointer-events-none z-10 p-10 flex flex-col gap-4">
                                            {!editorConfig.sections.header && <div className="absolute top-0 left-0 right-0 h-32 bg-slate-100/90 backdrop-blur-sm flex items-center justify-center border-b border-red-200 text-red-500 font-bold uppercase tracking-widest text-xs">Header Hidden</div>}

                                            {/* Just visual indicators for sections in editor mode */}
                                            <div className={`border-2 border-dashed border-blue-200 rounded-lg p-2 absolute top-10 right-10 ${editorConfig.showLogo ? 'opacity-100' : 'opacity-20'}`}>Logo Area</div>
