                                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Base Type</label>
                                    <select 
                                        value={newTemplateData.type}
                                        onChange={(e) => setNewTemplateData({...newTemplateData, type: e.target.value})}
